window.CLINICAL_DB["guidelines"] = [{"name":"中国高血压防治指南（2024年版）","category":"心血管内科","scope":"18岁以上成人高血压筛查、诊断、评估、治疗和管理。","diagnosis":["诊室血压：非同日3次≥140/90mmHg","家庭自测：≥135/85mmHg","24h动态：24h平均≥130/80，白天≥135/85，夜间≥120/70","初诊查：血常规、尿常规、生化、心电图、眼底","疑继发性：肾动脉超声、肾上腺CT、儿茶酚胺、醛固酮/肾素"],"staging":["正常高值120-139/80-89","1级140-159/90-99","2级160-179/100-109","3级≥180/110","单纯收缩期：收缩≥140且舒张<90","危险分层：低/中/高/很高危"],"key_points":["目标：一般<140/90，能耐受<130/80；老年<140/90","高危立即用药，中危观察4周，低危观察3个月","生活方式干预是基础","2级以上初始联合，优选SPC","优先长效制剂","同时干预血脂血糖吸烟"],"drug_recommendations":["CCB：氨氯地平5mg qd起(最大10)、硝苯地平控释30mg qd","ACEI：依那普利5-10mg bid、贝那普利10-20mg qd","ARB：缬沙坦80-160mg qd、厄贝沙坦150-300mg qd","利尿剂：氢氯噻嗪12.5-25mg qd、吲达帕胺1.5-2.5mg qd","β阻滞剂：美托洛尔47.5-95mg qd、比索洛尔2.5-10mg qd","SPC：缬沙坦氨氯地平、培哚普利氨氯地平","难治性：加螺内酯20-40mg qd(eGFR≥45,K<4.5)"],"non_pharmacological":["限盐<5g/d","减重BMI<24，腰围男<90女<85","每周≥150分钟中等强度有氧运动","限酒男<25g女<15g酒精/d","戒烟包括二手烟","心理平衡，保证睡眠"],"complications":["高血压急症(≥180/120+靶器官损害)：静脉降压，1h降25%，2-6h至160/100","亚急症：口服降压，24-48h逐步降压","合并卒中：急性期不急于降压，>220/120或溶栓>185/110才降","合并冠心病：β阻滞剂+ACEI/ARB，目标<130/80","合并心衰：β阻滞剂+ACEI/ARB+MRA+SGLT2i","合并糖尿病/CKD：ACEI/ARB首选"],"monitoring":["初诊/调药期：每周测2-3天早晚各1次","稳定期：每周1-2天","每次随访：血压、心率、体重、电解质、肾功能","每年：心电图、心超、尿微量白蛋白、眼底"],"special_populations":["老年：小剂量起始，缓慢加量，防体位性低血压","妊娠：甲基多巴、拉贝洛尔、硝苯地平；禁用ACEI/ARB/利尿剂","儿童青少年：优先生活方式，药物选CCB/ACEI/ARB","继发性：针对病因治疗"],"references":"中国高血压防治指南修订委员会. 中国高血压防治指南(2024). 中华心血管病杂志"},{"name":"慢性冠脉综合征诊断和治疗指南（2024）","category":"心血管内科","scope":"冠心病稳定期(CCS)诊断、危险分层、药物治疗和血运重建决策。","diagnosis":["典型心绞痛：胸骨后压榨感，劳力诱发，休息/硝酸甘油缓解<15min","不典型：女性/糖尿病/老人可胸闷气短上腹痛","静息心电图可正常，发作时ST-T改变","负荷试验：运动平板、负荷超声、负荷心肌灌注","冠脉CTA：中低危首选无创","冠脉造影：金标准，高危或无创阳性者"],"staging":["CCS心绞痛分级：I一般活动无症状/II轻度受限/III明显受限/IV静息发作","高危：左主干>50%、前降支近段>70%、LVEF<35%、多支病变","SYNTAX评分：评估病变复杂度指导血运重建"],"key_points":["药物治疗是基石，所有患者GDMT","高危推荐PCI/CABG，中危可考虑，低危优先药物","二级预防：抗血小板、调脂、降压、降糖、生活方式","完全血运重建优于部分","左主干/三支：SYNTAX≤22可选PCI，>22推荐CABG","康复运动改善预后"],"drug_recommendations":["抗血小板：阿司匹林75-100mg qd长期；PCI术后DAPT 6-12个月(氯吡格雷75mg qd/替格瑞洛90mg bid)","调脂：LDL-C<1.4且降幅≥50%；阿托伐他汀20-80mg qn；不达标加依折麦布10mg；仍不达标加PCSK9i","β阻滞剂：美托洛尔47.5-190mg qd，目标静息心率55-60","ACEI/ARB：合并高血压/心衰/糖尿病/CKD时用","硝酸酯：硝酸异山梨酯10mg tid(缓解症状不改善预后)","SGLT2i：合并心衰/CKD/糖尿病时推荐","曲美他嗪20mg tid辅助"],"non_pharmacological":["戒烟限酒，控制体重BMI<24","地中海饮食：多蔬果全谷物鱼类坚果，少红肉饱和脂肪","心脏康复：每周≥150分钟中等强度有氧","控制血压<130/80、HbA1c<7%、LDL达标","心理调节，避免过劳情绪激动","流感肺炎球菌疫苗"],"complications":["急性冠脉综合征：按STEMI/NSTEMI处理，急诊PCI","心力衰竭：按心衰GDMT","心律失常：房颤抗凝+心率/节律控制，室性评估猝死风险","缺血性心肌病：LVEF<35%+完全血运重建后仍低评估ICD","支架内血栓：DAPT依从性评估"],"monitoring":["术后1/3/6/12个月随访，之后每年","每次：症状、血压、心率、血脂、肝肾功能、血糖","每年：心电图、心超、运动负荷","非侵入检查不推荐常规频繁复查，有症状变化时查"],"special_populations":["糖尿病：目标更严，LDL<1.4，血压<130/80","CKD：ACEI/ARB护肾，造影前水化","老年：注意出血风险，DAPT疗程个体化","女性：症状不典型诊断延迟，同等治疗"],"references":"中华医学会心血管病学分会. 慢性冠脉综合征诊断和治疗指南(2024). 中华心血管病杂志"},{"name":"中国心力衰竭诊断和治疗指南（2024）","category":"心血管内科","scope":"成人急慢性心衰诊断、分型评估、药物和非药物治疗。","diagnosis":["症状：呼吸困难、乏力、水肿、端坐呼吸、夜间阵发呼吸困难","体征：颈静脉怒张、肺部啰音、心脏扩大、S3奔马律、肝大腹水","BNP<35或NT-proBNP<125可排除慢性心衰；急性<300可排除","心超：LVEF、心脏结构、瓣膜、舒张功能","胸片：肺淤血、心影增大、胸腔积液"],"staging":["A期：高危因素无结构异常","B期：结构异常无症状","C期：结构异常有/曾有症状","D期：难治性终末期","按LVEF：HFrEF≤40%、HFmrEF41-49%、HFpEF≥50%","NYHA I-IV级"],"key_points":["急性：利尿、扩血管、正性肌力，稳定后启动GDMT","慢性HFrEF：四联(ARNI/ACEI+β阻滞剂+MRA+SGLT2i)均达目标量","HFpEF：SGLT2i推荐，利尿剂缓解症状，治合并症","非药物：限钠限水、体重监测、运动康复","器械：CRT(LBBB+QRS>130+LVEF<35)、ICD","终末期：LVAD、心脏移植、姑息"],"drug_recommendations":["ARNI：沙库巴曲缬沙坦50mg bid起，每2-4周加倍，目标200mg bid","β阻滞剂：比索洛尔/美托洛尔/卡维地洛，小剂量起每2-4周加倍","MRA：螺内酯10-25mg qd(eGFR≥30,K<5.0)，起始后2-3天和1周查血钾肌酐","SGLT2i：达格列净10mg qd或恩格列净10mg qd，所有HFrEF均推荐","利尿剂：呋塞米20-40mg qd起，按体重水肿调整","地高辛0.125-0.25mg qd：房颤室率快或症状仍明显","血管扩张剂：肼苯哒嗪+硝酸异山梨酯(ACEI不耐受或非洲裔)"],"non_pharmacological":["限钠：轻度<3g/d，中重度<2g/d","限水：严重低钠(<130)或顽固水肿<1.5L/d","每日体重：3天增>2kg提示液体潴留，加利尿剂","运动康复：稳定期循序渐进，从床边活动开始","戒烟限酒，肥胖者减重","流感肺炎球菌疫苗，避免感染"],"complications":["急性左心衰：端坐位、吸氧、吗啡2.5-5mg iv、呋塞米20-40mg iv、硝酸甘油静滴","心源性休克：正性肌力(多巴酚丁胺/米力农)、血管活性药(去甲肾)、IABP/ECMO","心律失常：房颤抗凝+控制室率，室速/室颤按ACLS","肾功恶化：调整利尿剂和RAASi，避免肾毒性药","电解质紊乱：低钾补钾，低钠限水"],"monitoring":["稳定期每1-3个月：症状、体重、血压、心率、电解质、肾功能","BNP/NT-proBNP评估疗效预后","心超每6-12个月复查","6分钟步行、生活质量评估","药物滴定期间密切监测血压心率血钾肌酐"],"special_populations":["老年：小剂量起始缓慢滴定，注意体位性低血压和肾功能","妊娠：禁用ACEI/ARB/ARNI/SGLT2i，用β阻滞剂(拉贝洛尔)、利尿剂、地高辛","CKD：eGFR<30慎用MRA，SGLT2i在eGFR≥20可用","房颤合并心衰：优先β阻滞剂控制室率，必要时地高辛"],"references":"中华医学会心血管病学分会. 中国心力衰竭诊断和治疗指南(2024). 中华心血管病杂志"},{"name":"心房颤动诊断和治疗中国指南（2024）","category":"心血管内科","scope":"成人房颤筛查、诊断、卒中预防、节律/心率控制和综合管理。","diagnosis":["心电图/监测记录到房颤(RR绝对不齐、无P波、f波)≥30秒","阵发性<7天自行终止；持续性>7天；长程持续性>1年拟转复；永久性不再转复","瓣膜性：中重度二尖瓣狭窄或机械瓣术后","非瓣膜性：其他所有","评估：经胸心超、甲功、肾功、血常规","隐匿性：长程监测7天-3年"],"staging":["CHA2DS2-VASc：心衰1、高血压1、年龄≥75=2、糖尿病1、卒中/TIA=2、血管病1、年龄65-74=1、女性1","卒中风险：≥2(男)/≥3(女)需抗凝；1(男)/2(女)考虑抗凝","HAS-BLED：高血压1、肝肾异常1-2、卒中1、出血1、INR不稳1、老年>65=1、药/酒1-2；≥3积极纠正可逆因素"],"key_points":["非瓣膜性NOAC优先；瓣膜性必须华法林","早期节律控制改善预后，导管消融一线","心率控制：静息<80运动<110；宽松静息<110","ABC路径：A抗凝避卒中、B更好症状控制、C合并症管理","≥65岁常规心电图筛查，高危可穿戴设备","左心耳封堵：抗凝禁忌或出血高危"],"drug_recommendations":["NOAC：达比加群150mg bid(肌酐清除30-49用75)、利伐沙班20mg qd(15-49用15)、阿哌沙班5mg bid(≥80/体重≤60/肌酐≥133用2.5)、艾多沙班60mg qd","华法林：2.5-3mg qd起，按INR调，目标2.0-3.0，每周至稳定后每月","节律控制：胺碘酮0.2g tid×1周→bid×1周→qd维持；普罗帕酮150-300mg tid(无结构性心脏病)；索他洛尔80-160mg bid","心率控制：美托洛尔47.5-190mg qd、地尔硫卓90-360mg/d分3次、地高辛0.125-0.25mg qd","预激合并房颤：禁用腺苷/β阻滞剂/CCB/地高辛，首选电复律或普鲁卡因胺/伊布利特","围术期桥接：NOAC一般不需；华法林高血栓风险(机械瓣/近期卒中)用低分子肝素桥接"],"non_pharmacological":["导管消融：肺静脉隔离为基石，阵发性一线，持续性可考虑","电复律：血流动力学不稳定立即；择期复律前抗凝≥3周或经食道超声排除血栓","左心耳封堵：Watchman等，抗凝禁忌或出血高危","外科迷宫：合并心脏手术时","生活方式：减重、戒酒、避免咖啡因、治疗睡眠呼吸暂停(CPAP)、控制血压"],"complications":["缺血性卒中：抗凝预防，急性期按卒中指南","心动过速性心肌病：控制心率/节律后心功能可恢复","血栓栓塞：肾/肠系膜/肢体系统性栓塞","出血：抗凝相关出血，评估HAS-BLED纠正可逆因素，严重出血用拮抗剂(达比加群用依达赛珠单抗，Xa抑制剂用安德沙奈α)"],"monitoring":["抗凝初期：每周查血常规肝肾功电解质","华法林：INR每周至稳定后每月","NOAC：肾功每6-12个月，eGFR<50每3个月","心率/节律：心电图、动态心电图定期","心超：每年评估心房大小心功能"],"special_populations":["老年：NOAC优先，注意肾功和出血风险","妊娠：瓣膜性用华法林，非瓣膜性用低分子肝素；禁用NOAC","肥厚型心肌病：华法林抗凝(不论CHA2DS2-VASc)","甲亢：β阻滞剂控制室率，治疗甲亢后多可转复"],"references":"中华医学会心血管病学分会. 心房颤动诊断和治疗中国指南(2024). 中华心血管病杂志"},{"name":"中国肺动脉高压诊断和治疗指南（2024）","category":"心血管内科","scope":"成人肺动脉高压(PH)诊断分类、危险分层和靶向治疗。","diagnosis":["右心导管：mPAP≥25mmHg(海平面静息)金标准；PAH还需PAWP≤15+PVR≥3WU","心超筛查：三尖瓣反流速度>3.4或>2.9+其他PH征象","病因筛查：自身抗体、HIV、肝功、甲功、BMPR2基因","6MWD评估功能预后","右心功能：BNP/NT-proBNP、心超(MRI更精确)","CTEPH：V/Q扫描首选筛查，肺动脉造影确诊"],"staging":["WHO功能分级：I无活动受限/II轻度受限/III明显受限/IV静息症状","PAH危险分层：低危(<5%年死亡，6MWD>440、BNP<50、无心包积液、WHO I-II)、中危、高危(>10%)","PH分类：1型动脉性(PAH)、2型左心疾病、3型肺病/缺氧、4型CTEPH、5型不明原因"],"key_points":["一般治疗：氧疗、利尿、抗凝(特发性PAH)、避免妊娠/剧烈运动/高海拔","PAH靶向：按危险分层选单药/联合","低危单药口服；中危双药联合；高危三药+肠外前列环素","CTEPH：肺动脉内膜剥脱术首选；不能手术者BPA或利奥西呱","2型/3型：治原发病为主，靶向不常规推荐","终末期：肺移植评估"],"drug_recommendations":["内皮素受体拮抗剂：波生坦62.5mg bid×4周→125mg bid(监测肝功)、安立生坦5mg qd、马昔腾坦10mg qd","PDE5抑制剂：西地那非20mg tid、他达拉非40mg qd、伐地那非5mg bid","sGC激动剂：利奥西呱2.5mg tid起→最大2.5mg tid(PAH和CTEPH均可用)","前列环素类：依前列醇2-16ng/kg/min持续静滴(高危)、曲前列尼尔(皮下/静滴/吸入)、伊洛前列素吸入5-20μg 6-9次/d、司来帕格0.2mg bid起→最大1.6mg bid","利尿剂：呋塞米20-40mg qd按水肿调整","氧疗：SpO2<91%时吸氧","抗凝：特发性/遗传性PAH用华法林INR2.0-3.0"],"non_pharmacological":["氧疗维持SpO2≥92%","康复运动：专业指导下进行，避免过度劳累","避免：妊娠(避孕)、高海拔、剧烈运动、感冒、吸烟","心理支持：焦虑抑郁常见","疫苗接种：流感、肺炎球菌","营养支持避免营养不良"],"complications":["右心衰：利尿、氧疗、靶向药，正性肌力(米力农/左西孟旦)","心律失常：房扑房颤常见，控制室率+抗凝","咯血：支气管动脉栓塞，防大咯血窒息","晕厥：避免突然体位变化，评估靶向药调整"],"monitoring":["每3-6个月：WHO分级、6MWD、BNP、心超","右心导管：每1-2年或病情变化时","肝功(波生坦)、血常规、肾功定期","评估治疗反应和危险分层变化"],"special_populations":["妊娠：PH妊娠死亡率高，严格避孕，意外妊娠多学科管理","儿童：按体重调剂量，波生坦/西地那非可用","结缔组织病相关PAH：同时治原发病"],"references":"中华医学会呼吸病学分会肺栓塞与肺血管病学组. 中国肺动脉高压诊断和治疗指南(2024). 中华结核和呼吸杂志"},{"name":"慢性阻塞性肺疾病诊治指南（2024年修订版）","category":"呼吸内科","scope":"成人COPD诊断、评估、稳定期管理和急性加重处理。","diagnosis":["危险因素：吸烟(最主要)、职业粉尘/化学物、室内外空气污染、生物燃料","持续症状：慢性咳嗽、咳痰、气短/呼吸困难","肺功能：吸入支扩剂后FEV1/FVC<0.70为持续气流受限","支扩试验：排除哮喘(改善>12%且>200ml提示哮喘)","胸部CT：排除其他病，评估肺气肿类型","评估合并症：心血管病、骨质疏松、抑郁、肺癌、代谢综合征"],"staging":["GOLD肺功能：1级FEV1≥80%、2级50-79%、3级30-49%、4级<30%","症状：CAT≥10或mMRC≥2为症状多","急性加重：≥2次/年或≥1次住院为加重多","分组：A(症状少加重少)、B(症状多加重少)、E(加重多不论症状)","BODE指数：BMI、气流阻塞、呼吸困难、运动耐力评估预后"],"key_points":["戒烟最有效，可延缓肺功能下降","稳定期核心：支扩剂+肺康复+疫苗","B组和E组基础用LABA+LAMA双支扩","血嗜酸≥300或合并哮喘：加ICS三联","急性加重：加支扩剂、全身激素、抗生素(有感染征象)、氧疗","长期氧疗：静息SpO2≤88或PaO2≤55，>15h/d改善生存"],"drug_recommendations":["A组：SABA(沙丁胺醇)按需，或LABA/LAMA维持","B组：LABA+LAMA双支扩(茚达特罗/格隆溴铵、维兰特罗/乌美溴铵)","E组：LABA+LAMA；嗜酸高加ICS三联(布地奈德/福莫特罗/格隆溴铵)","急性加重：泼尼松龙40mg qd×5天；抗生素阿莫西林克拉维酸/大环内酯/呼吸喹诺酮5-7天","雾化：沙丁胺醇2.5mg+异丙托溴铵0.5mg q4-6h","氧疗：鼻导管1-2L/min，目标SpO2 88-92%(避免高氧致CO2潴留)","祛痰：氨溴索30mg tid、乙酰半胱氨酸600mg bid"],"non_pharmacological":["戒烟：药物(尼古丁替代/安非他酮/伐尼克兰)+行为干预","肺康复：运动训练(下肢耐力+力量)、呼吸训练(缩唇/腹式)、教育、心理支持，6-8周","营养支持：BMI<21增加蛋白热量","疫苗：每年流感、肺炎球菌、新冠","避免空气污染职业暴露，室内通风","长期家庭氧疗和无创通气(CO2潴留者)"],"complications":["急性加重：最常见，感染为主要诱因","呼吸衰竭：II型呼衰，无创通气BiPAP，必要时插管","肺心病/右心衰：利尿、氧疗，避免过度利尿","气胸：肺大疱破裂，胸腔闭式引流","骨质疏松：长期激素活动少，补钙维D，双膦酸盐"],"monitoring":["稳定期每3-6个月：症状、急性加重、肺功能","每年肺功能1次","急性加重后4-6周复查评估恢复和治疗调整","CAT/mMRC定期评估","药物吸入技术检查纠正"],"special_populations":["哮喘-COPD重叠(ACO)：ICS+LABA基础按哮喘管理","老年：注意吸入装置选择(干粉需吸气流速)，简化方案","合并心血管病：β阻滞剂心脏选择性可用，非选择性禁用","肺癌筛查：长期吸烟者低剂量CT每年"],"references":"中华医学会呼吸病学分会. 慢性阻塞性肺疾病诊治指南(2024修订版). 中华结核和呼吸杂志"},{"name":"支气管哮喘防治指南（2024年版）","category":"呼吸内科","scope":"成人和儿童哮喘诊断、评估和长期管理。","diagnosis":["反复发作喘息/气急/胸闷/咳嗽，夜间/凌晨多发，可变呼气气流受限","支扩试验阳性(FEV1改善>12%且>200ml)或PEF变异率>10%","激发试验阳性(乙酰甲胆碱/组胺)","呼出气一氧化氮(FeNO)升高提示嗜酸粒细胞性炎症","过敏原检测：皮肤点刺或血清sIgE","排除其他原因(COPD、心衰、气道异物)"],"staging":["控制水平：良好控制/部分控制/未控制","GINA阶梯：1-5级，按控制水平升/降级","严重程度：治疗后控制水平反映(轻度/中度/重度)","急性发作严重度：轻度/中度/重度/危重","未来风险：急性加重、肺功能下降、药物不良反应","表型：嗜酸粒细胞型、中性粒细胞型、少炎症型、肥胖相关型"],"key_points":["GINA推荐所有成人/青少年首选含ICS的治疗方案","5级阶梯治疗，根据控制水平升/降级","急性发作：评估严重度，反复吸入SABA，全身激素，氧疗，必要时机械通气","治疗目标：良好症状控制，维持正常活动，减少未来风险","识别并避免诱因和过敏原","患者教育和吸入技术是关键"],"drug_recommendations":["第1-2级：低剂量ICS-福莫特罗按需(GINA推荐)，或低剂量ICS每天+SABA按需","第3级：低剂量ICS-LABA维持+SABA按需，或低剂量ICS-福莫特罗维持+缓解","第4级：中/高剂量ICS-LABA维持+SABA按需","第5级：高剂量ICS-LABA+LAMA；评估生物制剂(抗IgE奥马珠单抗、抗IL-5美泊利单抗/瑞利珠单抗、抗IL-4Rα度普利尤单抗)","急性发作：沙丁胺醇雾化q20min×3次；甲泼尼龙40mg iv/口服；重症加硫酸镁2g iv 20min","重度发作：PaCO2升高、意识改变、呼吸衰竭→气管插管机械通气"],"non_pharmacological":["避免过敏原：尘螨(防螨床罩、热水洗)、花粉(季节防护)、宠物、霉菌","避免触发：烟雾、冷空气、剧烈运动(运动前吸入SABA)、阿司匹林/NSAIDs(阿司匹林哮喘)","呼吸训练：缩唇呼吸、腹式呼吸","适度运动：游泳、散步，避免剧烈运动","体重管理：肥胖哮喘减重改善控制","疫苗：流感、肺炎球菌"],"complications":["哮喘持续状态：雾化SABA+激素+氧疗，无效插管","气胸/纵隔气肿：严重发作，胸腔闭式引流","呼吸衰竭：II型呼衰，无创或有创通气","慢阻肺重叠(ACO)：按更积极的哮喘方案治疗","药物不良反应：ICS口腔念珠菌(漱口)、声音嘶哑；SABA心悸手抖；生物制剂注射反应"],"monitoring":["控制良好每3-6个月随访，未控制每2-4周","每次：症状、急性加重、吸入技术、峰流速(PEF)","FeNO、血嗜酸粒细胞评估表型和治疗反应","肺功能每年1-2次","评估治疗依从性和环境控制"],"special_populations":["妊娠：ICS(布地奈德首选)+SABA，避免白三烯调节剂，控制不佳危害大于药物","儿童：5岁以下用吸入储雾罐，ICS剂量按年龄","老年：注意吸入技术和合并症，简化方案","职业性哮喘：避免职业暴露是关键，早期脱离改善预后","阿司匹林哮喘：白三烯调节剂效果好，禁用阿司匹林和NSAIDs"],"references":"中华医学会呼吸病学分会哮喘学组. 支气管哮喘防治指南(2024). 中华结核和呼吸杂志"},{"name":"中国成人社区获得性肺炎诊断和治疗指南（2024）","category":"呼吸内科","scope":"成人社区获得性肺炎(CAP)诊断、严重程度评估和抗感染治疗。","diagnosis":["新发肺部浸润影(胸片/CT)+咳嗽咳痰/发热/胸痛/呼吸困难","白细胞异常(>10或<4×10⁹/L)，伴或不伴核左移","排除其他原因(肺结核、肺癌、肺水肿、肺栓塞、非感染性间质性肺病)","病原学：痰培养、血培养、尿抗原(肺炎链球菌/军团菌)、呼吸道病毒核酸、非典型病原体抗体/核酸","重症评估：CURB-65(意识/尿素>7/呼吸≥30/血压<90/60/年龄≥65)、PSI评分","影像学：CT比胸片敏感，尤其老年和免疫低下者"],"staging":["CURB-65：0-1分门诊，2分住院，≥3分考虑ICU","PSI：I-II级门诊，III-IV级住院，V级ICU","重症肺炎标准(任一)：需要有创机械通气；感染性休克需血管活性药","次要标准(≥3条考虑重症)：呼吸≥30、氧合指数≤250、多肺叶浸润、意识障碍、BUN≥7、WBC<4、PLT<10、体温<36、低血压需液体复苏"],"key_points":["尽早经验性抗感染：首剂4小时内(重症1小时内)","根据治疗场所和危险因素选择抗生素","疗程：一般5-7天，非典型10-14天，金葡/铜绿14-21天","预防：流感疫苗、肺炎球菌疫苗","支持治疗：氧疗、补液、营养、化痰","疗效评估：用药48-72小时评估，72小时无改善考虑换药或进一步检查"],"drug_recommendations":["门诊无基础病：阿莫西林0.5g tid或多西环素0.1g bid或大环内酯(当地耐药低时)","门诊有基础病/近3月用抗生素：阿莫西林克拉维酸0.625g tid或呼吸喹诺酮(左氧氟沙星0.5g qd/莫西沙星0.4g qd)，或头孢+大环内酯","住院非ICU：β内酰胺类(头孢曲松2g qd/头孢噻肟)+大环内酯(阿奇霉素0.5g qd)，或呼吸喹诺酮单药","ICU：β内酰胺类+大环内酯/呼吸喹诺酮；怀疑铜绿用抗假单胞菌β内酰胺(哌拉西林他唑巴坦4.5g q6h/头孢吡肟2g q8h/亚胺培南)","重症：联合治疗覆盖非典型，必要时覆盖MRSA(万古霉素/利奈唑胺)","流感季节怀疑流感病毒性肺炎：奥司他韦75mg bid×5天(48h内最佳，重症超过48h仍用)"],"non_pharmacological":["氧疗：鼻导管/面罩，目标SpO2 90-94%(COPD 88-92%)","补液：脱水者静脉补液，心功能不全者限制","化痰排痰：体位引流、拍背、雾化吸入","营养支持：肠内营养优先，重症不能进食者肠外","休息，多饮水，清淡饮食","物理降温(高热时)"],"complications":["胸腔积液/脓胸：抗感染+胸腔穿刺引流，脓胸需充分引流+胸膜剥脱","肺脓肿：延长抗生素疗程，体位引流，必要时手术","呼吸衰竭：I型/II型呼衰，无创或有创通气","感染性休克：液体复苏+血管活性药+广谱抗生素，ICU","多器官功能衰竭：ICU综合支持"],"monitoring":["用药48-72小时评估：体温、呼吸、心率、血压、血氧、白细胞、影像学","治疗有效：体温下降、症状改善、白细胞下降","72小时无改善：复查CT、考虑耐药/特殊病原/并发症，调整抗生素","疗程结束评估临床治愈，不推荐常规复查胸片","血培养阳性者复查至阴性"],"special_populations":["老年：症状不典型(可无发热，仅表现意识改变/食欲差)，CURB-65年龄加分，注意肾功调剂量","孕妇：青霉素/头孢类安全，避免四环素/喹诺酮，重症需住院","免疫低下(激素/肿瘤/移植)：覆盖特殊病原(真菌、肺孢子菌、巨细胞病毒)，尽早支气管镜检查","吸入风险(卒中/痴呆)：覆盖厌氧菌，阿莫西林克拉维酸或克林霉素"],"references":"中华医学会呼吸病学分会. 中国成人社区获得性肺炎诊断和治疗指南(2024). 中华结核和呼吸杂志"},{"name":"肺血栓栓塞症诊治与预防指南（2024）","category":"呼吸内科","scope":"成人急性肺血栓栓塞症(PTE)诊断、危险分层和治疗。","diagnosis":["疑诊：Wells评分/Geneva评分评估临床可能性；D-二聚体排除低危(年龄校正值)","确诊：CT肺动脉造影(CTPA)首选；通气灌注扫描(V/Q)；肺动脉造影","危险分层：高危(休克/低血压)、中危(右心功能不全+心肌损伤)、低危","右心功能：心超(右室扩大/运动减弱)、CT(右室/左室直径比>0.9)","心肌损伤：肌钙蛋白升高、BNP/NT-proBNP升高","下肢静脉超声：寻找DVT证据"],"staging":["高危：休克或低血压(收缩压<90或下降≥40持续>15min)，需立即再灌注","中危：无休克低血压，但右心功能不全+心肌损伤；中高危(两者都有)需密切监测，中低危(其一)","低危：无休克低血压，无右心功能不全和心肌损伤","PESI/sPESI评分评估30天死亡风险","抗凝疗程：3个月基础，根据诱因和复发风险决定延长"],"key_points":["高危：立即再灌注(溶栓/取栓)+抗凝","中低危：抗凝治疗，住院观察","低危：可门诊抗凝治疗","NOAC优先于华法林(除非瓣膜病/妊娠)","下腔静脉滤器：抗凝禁忌或抗凝中复发","慢性血栓栓塞性肺动脉高压(CTEPH)：肺动脉内膜剥脱术/BPA/靶向药"],"drug_recommendations":["初始抗凝：低分子肝素(依诺肝素1mg/kg q12h)或磺达肝癸钠(体重<50:5mg,50-100:7.5mg,>100:10mg qd)或普通肝素(APTT调整)","NOAC：利伐沙班15mg bid×21天→20mg qd；阿哌沙班10mg bid×7天→5mg bid；达比加群150mg bid(先胃肠外抗凝5天)；艾多沙班60mg qd(先胃肠外5天)","华法林：与胃肠外重叠≥5天，INR 2.0-3.0，瓣膜性房颤/妊娠用","溶栓：阿替普酶50-100mg 2h静滴，或尿激酶2万U/kg 2h静滴(高危)","介入：导管碎栓/取栓/溶栓(溶栓禁忌或失败)","疗程：可逆诱因3个月；特发性/持续危险因素≥6个月评估长期；肿瘤用低分子肝素或NOAC长期"],"non_pharmacological":["卧床休息(急性期)，避免用力排便，患肢抬高(DVT)","吸氧：低氧血症者","下肢DVT：避免按摩挤压患肢，防止血栓脱落","梯度压力弹力袜：DVT后预防血栓后综合征(PTS)","早期活动：抗凝充分后可早期下床，不增加PE风险","预防：术后早期活动、低分子肝素预防、间歇充气加压"],"complications":["出血：抗凝相关，评估HAS-BLED，纠正可逆因素，严重出血用拮抗剂/输血","肺动脉高压(CTEPH)：抗凝+评估手术/BPA/靶向药","右心衰竭：利尿、氧疗、正性肌力药","复发：评估抗凝依从性、恶性肿瘤、易栓症，延长/加强抗凝","血栓后综合征(PTS)：下肢肿胀疼痛色素沉着，弹力袜+运动"],"monitoring":["抗凝初期：每周查血常规、肝肾功能、电解质、大便潜血","华法林：INR每周至稳定后每月","NOAC：肾功每6-12个月，eGFR<50每3个月","抗凝3个月评估：复发风险、出血风险、是否延长","心超/CTPA：评估右心恢复和CTEPH"],"special_populations":["妊娠：低分子肝素抗凝(不通过胎盘)，禁用华法林和NOAC，产后可换华法林(哺乳安全)","恶性肿瘤：低分子肝素或NOAC长期抗凝，直至肿瘤缓解","老年：注意肾功能和出血风险，NOAC按肌酐清除率调剂量","严重肾功能不全(eGFR<30)：普通肝素或低分子肝素(监测抗Xa)，慎用NOAC"],"references":"中华医学会呼吸病学分会. 肺血栓栓塞症诊治与预防指南(2024). 中华结核和呼吸杂志"},{"name":"中国支气管扩张症诊断和治疗指南（2024）","category":"呼吸内科","scope":"成人支气管扩张症诊断、病因评估和治疗。","diagnosis":["慢性咳嗽、大量脓痰、反复咯血","胸部HRCT：印戒征(支气管直径>伴行肺动脉)、双轨征、囊状扩张","病因评估：既往感染(结核/百日咳/麻疹)、免疫缺陷(IgG/IgA/IgM)、囊性纤维化(汗液氯试验/基因)、纤毛运动障碍(鼻纤毛活检)、变应性支气管肺曲霉病(ABPA)、类风湿等结缔组织病","痰培养：常规细菌+真菌+分枝杆菌，铜绿假单胞菌定植重要","肺功能：阻塞性通气功能障碍常见","严重程度：BSI评分、FACED评分"],"staging":["严重程度评估：BSI评分(年龄、FEV1、BMI、既往住院、铜绿定植、大咯血、影像学累及范围)","急性加重：痰量增加/脓性痰/呼吸困难加重，持续≥48小时","稳定期：症状稳定","铜绿假单胞菌定植：连续2次痰培养阳性(间隔>3个月)，提示预后差","ABPA：哮喘+嗜酸高+曲霉sIgE/总IgE高+中心性支气管扩张+黏液栓"],"key_points":["气道廓清是基础，每天1-2次","长期抗生素：铜绿定植用大环内酯类或吸入抗生素","急性加重：根据痰培养和既往用药选抗生素","手术：局限病变+反复感染/咯血可手术切除","咯血处理：少量止血药，大咯血介入栓塞或手术","预防加重：疫苗、戒烟、避免感染"],"drug_recommendations":["气道廓清：体位引流、拍背、主动循环呼吸技术(ACBT)、振荡呼气正压装置(Flutter/Acapella)","急性加重抗生素：无铜绿风险阿莫西林克拉维酸0.625g tid或头孢曲松2g qd；有铜绿风险环丙沙星0.5-0.75g bid口服或头孢他啶2g q8h/哌拉西林他唑巴坦4.5g q6h iv","长期口服抗生素：铜绿定植用阿奇霉素250mg 每周3次或红霉素500mg bid(注意耐药和听力)","吸入抗生素：妥布霉素吸入溶液300mg bid(每月交替)或多黏菌素吸入(铜绿定植反复加重)","祛痰：氨溴索30mg tid、乙酰半胱氨酸600mg bid、羧甲司坦0.5g tid","支气管扩张剂：合并气道阻塞用LABA/LAMA","咯血：氨甲环酸0.5g iv/口服；大咯血垂体后叶素5-10U+5%GS 250ml静滴，或支气管动脉栓塞"],"non_pharmacological":["气道廓清技术：每天1-2次，每次20-30分钟","运动锻炼：有氧+力量训练，改善运动耐力和生活质量","营养支持：消瘦者增加蛋白热量","戒烟，避免烟雾和空气污染","疫苗：每年流感、肺炎球菌、新冠","避免呼吸道感染，勤洗手，感染期隔离"],"complications":["反复感染急性加重：最常见，铜绿定植者更频繁","咯血：常见，大咯血可窒息死亡，需紧急处理","呼吸衰竭：晚期II型呼衰，无创通气","肺心病/右心衰：长期缺氧肺动脉高压所致","继发真菌感染(曲霉球)：咯血常见，抗真菌或手术"],"monitoring":["稳定期每3-6个月：症状、急性加重次数、痰培养、肺功能","每年肺功能1次","急性加重后4-6周复查","痰培养：每年1-2次或急性加重时","评估气道廓清技术掌握情况"],"special_populations":["儿童：囊性纤维化和原发性纤毛运动障碍需排查，长期随访","ABPA：口服激素(泼尼松0.5mg/kg/d渐减)+抗真菌(伊曲康唑200mg bid)，目标总IgE下降35-50%","免疫缺陷：IVIG替代治疗，积极抗感染","老年：注意吸入装置和排痰能力，简化方案"],"references":"中华医学会呼吸病学分会. 中国支气管扩张症诊断和治疗指南(2024). 中华结核和呼吸杂志"},{"name":"中国急性胰腺炎诊治指南（2024）","category":"消化内科","scope":"成人急性胰腺炎诊断、严重程度分级和治疗。","diagnosis":["急性、持续中上腹痛(可向背部放射)","血清淀粉酶/脂肪酶>正常上限3倍","影像学(CT/MRI/超声)典型改变(胰腺肿大、胰周渗出)","满足2项即可诊断","病因：胆石症(最常见)、酒精、高甘油三酯(>11.3mmol/L)、药物、ERCP术后、自身免疫","增强CT：发病72小时后评估胰腺坏死"],"staging":["轻症(MAP)：无器官衰竭，无局部/全身并发症，占80-85%","中重症(MSAP)：一过性器官衰竭(≤48h)或局部/全身并发症","重症(SAP)：持续性器官衰竭(>48h)，占10-20%，死亡率高","器官衰竭：改良Marshall评分≥2分(呼吸/循环/肾)","局部并发症：急性胰周液体积聚(APFC)、急性坏死物积聚(ANC)、胰腺假性囊肿、包裹性坏死(WON)","全身并发症：SIRS、脓毒症、腹腔间隔室综合征"],"key_points":["轻症：禁食、补液、止痛，早期肠内营养(48h内)","重症：ICU监护，器官功能支持，抗感染(感染性坏死)","胆源性胰腺炎：有胆管炎/梗阻时急诊ERCP，无梗阻保守治疗后择期胆囊切除","高甘油三酯性：胰岛素+肝素/血液净化降甘油三酯","不推荐预防性使用抗生素","手术：感染性坏死经皮/内镜引流失败后微创清创"],"drug_recommendations":["补液：乳酸林格液或生理盐水，前24h 250-500ml/h，目标BUN下降、Hct正常","止痛：哌替啶50-100mg im(避免吗啡Oddi括约肌痉挛)，或芬太尼","止吐：甲氧氯普胺10mg iv、昂丹司琼8mg iv","PPI：奥美拉唑40mg iv q12h(减少胃酸刺激胰液分泌)","生长抑素：奥曲肽0.1mg iv后25μg/h持续泵入(重症)","抗感染(感染性坏死)：碳青霉烯(亚胺培南0.5g q6h)或喹诺酮+甲硝唑，覆盖革兰阴性和厌氧菌","高甘油三酯：胰岛素0.1-0.3U/kg/h+葡萄糖，或低分子肝素5000U q12h，目标TG<5.65"],"non_pharmacological":["禁食：轻症可短期禁食，症状缓解后尽早开放饮食(清流→低脂半流)","肠内营养：48h内经鼻空肠管开始，优于肠外营养","补液：早期积极静脉补液是关键","监测：生命体征、尿量、血氧、电解质、血糖","腹腔高压：胃肠减压、肛管排气、血液滤过","血液净化：重症伴肾衰/高甘油三酯/炎症反应综合征"],"complications":["器官衰竭：呼吸(ARDS机械通气)、循环(休克血管活性药)、肾(血液滤过)","感染性胰腺坏死：发热、白细胞升高、CT气泡征，抗生素+引流/清创","假性囊肿：>6cm或有症状可内镜/经皮引流","腹腔间隔室综合征：腹压>25mmHg+器官衰竭，减压","胰瘘：生长抑素+引流，多可自愈"],"monitoring":["入院24h内：每4-6h生命体征、尿量、血氧","实验室：血常规、生化、淀粉酶、脂肪酶、凝血、血气","增强CT：72h后评估坏死，2-3周复查评估并发症","BISAP/Ranson评分评估严重度","营养状态评估，白蛋白"],"special_populations":["老年：症状不典型，并发症多，预后差，积极补液注意心功能","妊娠：胆源性常见，保守治疗为主，避免CT，必要时ERCP(铅衣保护)","免疫低下：感染风险高，早期抗生素，积极引流","儿童：多为病毒/创伤/药物，治疗原则相同，剂量按体重"],"references":"中华医学会消化病学分会. 中国急性胰腺炎诊治指南(2024). 中华消化杂志"},{"name":"中国胃食管反流病诊疗指南（2024）","category":"消化内科","scope":"成人胃食管反流病(GERD)诊断和治疗，包括反流性食管炎(RE)、非糜烂性反流病(NERD)和Barrett食管。","diagnosis":["典型症状：烧心、反酸(每周≥2次)","不典型：胸痛、吞咽困难、慢性咳嗽、喉炎、哮喘、牙蚀","PPI试验：标准剂量PPI bid×1-2周，症状改善≥50%支持诊断","胃镜：RE分级(LA-A/B/C/D)，排除溃疡/肿瘤/Barrett","24h食管pH-阻抗监测：金标准，评估酸/非酸反流","食管测压：排除贲门失弛缓，评估LES压力，术前评估"],"staging":["RE洛杉矶分级：A(≥1处黏膜破损≤5mm)、B(>5mm不融合)、C(融合<75%周径)、D(融合≥75%周径)","NERD：有症状但胃镜正常，pH监测异常","功能性烧心：症状但pH监测正常，PPI无效","Barrett食管：鳞状上皮被柱状上皮取代，伴/不伴肠化生，癌变风险","并发症：出血、狭窄、Barrett食管、腺癌"],"key_points":["PPI是首选药物，早餐前30分钟服用","NERD：PPI 8周，按需维持","RE：PPI 8周，C/D级或并发症需长期维持","生活方式干预是基础","难治性GERD：优化PPI→加H2RA/促动力药→评估手术","Barrett食管：PPI+内镜监测，低级别异型增生可消融"],"drug_recommendations":["PPI：奥美拉唑20mg、兰索拉唑30mg、泮托拉唑40mg、雷贝拉唑10-20mg、艾司奥美拉唑20-40mg，早餐前30min qd，重症bid","H2受体拮抗剂：法莫替丁20mg bid(夜间酸突破，PPI睡前加用)","促动力药：莫沙必利5mg tid、多潘立酮10mg tid(餐前15-30min)","黏膜保护剂：铝碳酸镁1g tid(咀嚼，餐后1h)、硫糖铝1g qid","维持治疗：PPI最低有效剂量按需或间歇，RE C/D级长期维持","难治性：艾司奥美拉唑40mg bid，加巴氯芬10mg tid(减少TLESR)，评估手术"],"non_pharmacological":["减重：BMI>25者减重可改善","饮食：避免高脂、巧克力、咖啡、浓茶、辛辣、酸性食物，睡前3h不进食","抬高床头15-20cm(不是垫高枕头)","戒烟限酒","避免紧身衣、弯腰、腹压增高","右侧卧位睡眠(减少反流)"],"complications":["反流性食管炎出血：PPI大剂量，内镜止血","食管狭窄：扩张+PPI长期维持","Barrett食管：PPI+内镜监测(每3-5年，低级别异型增生每6-12月，高级别内镜消融/手术)","食管腺癌：Barrett+高级别异型增生风险，早期内镜治疗","喉炎/哮喘/慢性咳嗽：PPI试验性治疗，有效则维持"],"monitoring":["PPI治疗4-8周评估疗效","RE治疗8周后复查胃镜(尤其C/D级)","Barrett食管定期内镜监测+活检","长期PPI：监测骨密度、维生素B12、镁、肾功能","症状复发评估依从性和诱因"],"special_populations":["老年：注意PPI长期使用风险(骨折、感染、肾损伤)，最低有效剂量","妊娠：生活方式为主，必要时铝碳酸镁/硫糖铝，PPI(奥美拉唑)相对安全但尽量避免前3月","儿童：多为生理性反流，病理性需评估，PPI按体重","肥胖：减重是关键，手术可考虑胃底折叠+减重"],"references":"中华医学会消化病学分会. 中国胃食管反流病诊疗指南(2024). 中华消化杂志"},{"name":"炎症性肠病诊断与治疗的共识意见（2024）","category":"消化内科","scope":"成人溃疡性结肠炎(UC)和克罗恩病(CD)的诊断和治疗。","diagnosis":["UC：持续或反复发作腹泻、黏液脓血便、腹痛，里急后重","CD：腹痛、腹泻、体重下降、瘘管、肛周病变","结肠镜+活检：UC连续弥漫性黏膜炎症从直肠向近端延伸；CD节段性、纵行溃疡、鹅卵石样、非干酪样肉芽肿","小肠评估：CTE/MRE(CD)、胶囊内镜、小肠镜","粪便钙卫蛋白：鉴别IBD和IBS，评估活动度","排除感染(艰难梭菌、阿米巴、结核)、缺血性肠炎、肠结核"],"staging":["UC活动度：改良Mayo评分(排便次数、便血、内镜、医师评估)，轻度≤2、中度3-5、重度6-10、暴发性>10","UC范围：E1直肠、E2左半结肠、E3广泛结肠","CD活动度：CDAI评分(<150缓解、150-220轻度、220-450中度、>450重度)","CD部位：L1回肠末段、L2结肠、L3回结肠、L4上消化道；行为：B1非狭窄非穿透、B2狭窄、B3穿透、肛周P","高危因素：CD年轻发病、广泛病变、深溃疡、肛周病变、吸烟"],"key_points":["UC：5-ASA是轻中度基础，激素用于中重度急性发作，免疫抑制剂/生物制剂用于激素依赖/抵抗","CD：早期使用免疫抑制剂/生物制剂(降阶梯)，激素不用于维持","营养支持：CD尤其重要，肠内营养可诱导缓解","手术：UC全结肠切除可治愈；CD手术切除病变但复发率高","定期监测：UC病程>8年需结肠镜筛查癌变","患者教育：戒烟(CD)、饮食、依从性"],"drug_recommendations":["UC轻中度：美沙拉嗪2-4g/d分3-4次口服+栓剂1g qn(直肠炎)，8周评估","UC中重度急性：甲泼尼龙40-60mg iv qd或泼尼松40-60mg po qd，5-7天评估，有效渐减","UC激素抵抗：环孢素2mg/kg/d iv或英夫利昔单抗5mg/kg(0/2/6周)","UC维持：美沙拉嗪2g/d长期，硫唑嘌呤50-100mg qd(激素依赖)，生物制剂维持","CD诱导：全肠内营养(EEN)或激素(泼尼松40mg qd)，中重度首选生物制剂(英夫利昔5mg/kg或阿达木单抗160/80mg)","CD维持：硫唑嘌呤1.5-2.5mg/kg/d或甲氨蝶呤15-25mg/w或生物制剂，激素不维持","生物制剂：抗TNF(英夫利昔/阿达木)、抗整合素(维得利珠单抗)、抗IL-12/23(乌司奴单抗)、JAK抑制剂(托法替布)"],"non_pharmacological":["营养：CD活动期全肠内营养(EEN)可诱导缓解，尤其儿童；缓解期高营养饮食","戒烟：CD必须戒烟(加重病情和复发)，UC吸烟可能有保护但不推荐","饮食：个体化，避免不耐受食物，活动期低渣饮食，缓解期均衡","心理支持：焦虑抑郁常见，影响依从性和预后","疫苗接种：免疫抑制前接种乙肝、HPV、流感、肺炎球菌，避免活疫苗","康复：适度运动，维持体重"],"complications":["UC中毒性巨结肠：禁食、胃肠减压、激素、抗感染，无效急诊手术","CD瘘管/脓肿：脓肿先引流，生物制剂治疗瘘管","CD狭窄：内镜扩张或手术","肠穿孔：急诊手术","癌变：UC病程>8年每年结肠镜+活检，CD结肠广泛病变同样筛查","营养不良：定期评估，补充铁、维生素B12、维生素D、锌"],"monitoring":["活动期每2-4周评估症状、粪便钙卫蛋白","缓解期每3-6个月随访","结肠镜：UC治疗8-12周复查评估黏膜愈合，之后按风险定期筛查","硫唑嘌呤：监测血常规、肝功能(前8周每2周，之后每3月)","生物制剂：治疗前筛查结核、乙肝，定期评估疗效和抗药抗体","营养指标：白蛋白、铁蛋白、维生素B12、维生素D"],"special_populations":["儿童青少年：EEN是CD一线诱导，影响生长发育需积极治疗，生物制剂可用","妊娠：缓解期受孕风险低，5-ASA/硫唑嘌呤/抗TNF孕期可继续，甲氨蝶呤禁用","老年：注意感染风险，生物制剂和免疫抑制剂谨慎，合并症多","肛周CD：抗生素(甲硝唑/环丙沙星)+生物制剂+外科引流，多学科"],"references":"中华医学会消化病学分会炎症性肠病学组. 炎症性肠病诊断与治疗的共识意见(2024). 中华消化杂志"},{"name":"中国2型糖尿病防治指南（2024年版）","category":"内分泌科","scope":"成人2型糖尿病筛查、诊断、治疗和并发症管理。","diagnosis":["糖尿病症状(多饮多尿多食体重下降)+随机血糖≥11.1","空腹血糖≥7.0mmol/L(空腹≥8h)","OGTT 2h血糖≥11.1mmol/L","HbA1c≥6.5%","无典型症状需改日复查确认","分型：1型(自身免疫、胰岛素绝对缺乏)、2型(胰岛素抵抗+分泌不足)、特殊类型、妊娠糖尿病"],"staging":["HbA1c目标：一般<7%，年轻/无并发症<6.5%，老年/并发症多<7.5-8%","糖尿病前期：IFG(空腹6.1-6.9)、IGT(OGTT 2h 7.8-11.0)、HbA1c 5.7-6.4%","并发症分期：糖尿病肾病(G1-G5/A1-A3)、视网膜病变(I-VI期)、神经病变、下肢动脉病变、足病(0-5级Wagner)","心血管风险分层：极高危(ASCVD/CKD/靶器官损害)、高危、中危"],"key_points":["生活方式干预贯穿全程，是基础","二甲双胍是2型糖尿病一线首选，贯穿全程","合并ASCVD/心衰/CKD：不论HbA1c，优先SGLT2i或GLP-1RA","血糖控制目标个体化，避免低血糖","综合管理：血糖、血压、血脂、抗血小板、体重","定期筛查并发症：每年眼底、尿微量白蛋白、足部、神经"],"drug_recommendations":["二甲双胍：0.5g bid起，渐加至1-2g/d分2-3次，最大2g/d(餐中服减少胃肠反应)","SGLT2i：达格列净10mg qd、恩格列净10mg qd、卡格列净100mg qd(合并心衰/CKD优先，eGFR≥20可用)","GLP-1RA：利拉鲁肽0.6→1.2-1.8mg qd皮下、司美格鲁肽0.25→0.5-1.0mg qw、度拉糖肽1.5mg qw(减重/心血管获益)","DPP-4i：西格列汀100mg qd、沙格列汀5mg qd、利格列汀5mg qd(肾功能不全不需调量)","磺脲类：格列美脲1-4mg qd、格列齐特80-160mg bid(低血糖风险，老年慎用)","胰岛素：基础胰岛素(甘精/地特10U qn起始，按空腹调)、预混胰岛素(门冬30 bid)、强化治疗(三餐短效+睡前基础)","血压目标<130/80，ACEI/ARB首选；LDL-C目标极高危<1.4，他汀+依折麦布+PCSK9i"],"non_pharmacological":["医学营养治疗：控制总热量，碳水50-65%、蛋白15-20%、脂肪20-30%，低GI饮食","运动：每周≥150分钟中等强度有氧+2次抗阻，避免空腹运动防低血糖","减重：超重/肥胖者减重5-10%显著改善代谢","戒烟限酒","自我血糖监测：空腹+餐后2h，胰岛素治疗者更频繁","糖尿病教育：饮食、运动、用药、低血糖识别、足部护理"],"complications":["糖尿病酮症酸中毒(DKA)：补液(生理盐水前2h 1-2L)、小剂量胰岛素0.1U/kg/h、补钾、纠正诱因","高渗高血糖状态(HHS)：补液(更大量)、小剂量胰岛素、抗凝","低血糖：<3.9mmol/L，意识清楚口服15g糖，意识障碍静脉50%GS 40ml","糖尿病肾病：ACEI/ARB，SGLT2i，控制血压<130/80，低蛋白饮食0.8g/kg/d","糖尿病视网膜病变：控制血糖血压，激光光凝/抗VEGF注射","糖尿病足：减压、抗感染、血运重建、清创，严重者截肢"],"monitoring":["HbA1c：每3个月(稳定后每6个月)","血糖：空腹/餐后/睡前，胰岛素治疗者更频繁","每年：眼底检查、尿微量白蛋白/肌酐比、足部检查、神经病变检查、血脂、肝肾功能、心电图","血压每次就诊测量","体重/BMI定期"],"special_populations":["老年(≥65岁)：目标放宽HbA1c<7.5-8%，避免低血糖，优先低血糖风险低的药物(二甲双胍/DPP-4i/SGLT2i)","妊娠：胰岛素治疗(门冬/赖脯+地特/甘精)，目标空腹<5.3、餐后1h<7.8、2h<6.7，禁用口服降糖药","儿童青少年2型：生活方式+二甲双胍，不达标加胰岛素，关注代谢综合征","CKD：eGFR<30二甲双胍禁用，SGLT2i在eGFR≥20可用，胰岛素按肾功调量"],"references":"中华医学会糖尿病学分会. 中国2型糖尿病防治指南(2024). 中华糖尿病杂志"},{"name":"中国甲状腺功能亢进症诊治指南（2024）","category":"内分泌科","scope":"成人甲状腺功能亢进症(甲亢)诊断和治疗，主要为Graves病。","diagnosis":["高代谢症状：怕热多汗、心悸、手抖、体重下降、易激动、月经紊乱","体征：甲状腺肿大、突眼、胫前黏液水肿、心率快","TSH降低+FT3/FT4升高(原发性甲亢)","TSH升高+FT3/FT4升高(中枢性甲亢，罕见)","病因鉴别：Graves病(TRAb阳性、弥漫性甲状腺肿、突眼)、毒性结节性甲状腺肿、甲状腺炎(破坏性甲亢，摄碘率低)","甲状腺摄碘率：Graves病升高，甲状腺炎降低","甲状腺超声：Graves弥漫性增大血流丰富(火海征)"],"staging":["Graves眼病(GO)：活动期(CAS≥3分)、非活动期；严重度分级(轻度/中重度/威胁视力)","甲亢性心脏病：房颤、心衰、心脏扩大","甲亢危象：高热>39℃、心率>140、大汗、谵妄/昏迷、呕吐腹泻，死亡率高","妊娠期甲亢：孕早期HCG相关一过性甲亢(需鉴别)、Graves病","药物不良反应：粒细胞缺乏(0.1-0.5%)、肝损伤、皮疹、血管炎(PTU)"],"key_points":["三种治疗：抗甲状腺药物(ATD)、放射性碘(RAI)、手术，根据患者选择","ATD首选：甲巯咪唑(MMI)，妊娠早期/甲亢危象用丙硫氧嘧啶(PTU)","疗程12-18个月，TRAb转阴后可停药","RAI：适用于ATD失败/复发、甲状腺肿大、合并心脏病，禁忌妊娠/哺乳/活动期GO","手术：甲状腺明显肿大有压迫、怀疑恶性、药物无效","甲亢危象：PTU+碘剂+普萘洛尔+激素+降温+支持治疗"],"drug_recommendations":["MMI：起始10-30mg/d分1-3次，4-8周减至维持5-10mg/d，疗程12-18月","PTU：起始50-100mg tid，维持50-100mg/d(妊娠早期/危象首选)","β阻滞剂：普萘洛尔10-40mg tid或美托洛尔25-50mg bid(控制心率，支气管哮喘/心衰慎用)","碘剂：复方碘溶液(Lugol液)5-10滴tid(术前准备/危象，ATD后1h用，不超过2周)","糖皮质激素：GO活动期泼尼松40-60mg qd渐减，或甲泼尼龙500mg iv每周×6周","甲亢危象：PTU 500-1000mg负荷后250mg q4h、碘剂1h后、普萘洛尔60-80mg q4-6h、氢化可的松100mg q8h、降温(避免阿司匹林)"],"non_pharmacological":["低碘饮食：避免海带紫菜海鱼，用无碘盐","休息，避免劳累和精神刺激","补充营养：高蛋白高热量高维生素，补充维生素B族","戒烟：GO患者必须戒烟(加重突眼)","眼部护理：戴墨镜、人工泪液、夜间眼膏，高枕卧位","定期复查，遵医嘱不自行停药"],"complications":["甲亢危象：紧急处理，死亡率20-30%","甲亢性心脏病：控制甲亢后多可恢复，房颤需抗凝","GO活动期：激素/放疗，威胁视力需眼眶减压手术","粒细胞缺乏：发热咽痛立即查血常规，WBC<3或中性粒<1.5停药，升白细胞+抗感染","肝损伤：MMI胆汁淤积，PTU肝细胞坏死，严重者停药换治疗方式","低钾性周期性麻痹：男性亚洲人多见，补钾+β阻滞剂，控制甲亢后减少发作"],"monitoring":["ATD治疗初期：每2-4周查甲功、血常规、肝功能","甲功正常后每1-3个月复查","TRAb：治疗6-12个月评估，停药前查(转阴可停)","RAI后：每4-6周查甲功，监测甲减发生","术后：查甲功、甲状旁腺功能(血钙)、声带","GO：CAS评分、视力、突眼度"],"special_populations":["妊娠：孕早期PTU，孕中晚期MMI，目标FT4正常上限，最小有效剂量，避免甲减影响胎儿神经发育","哺乳期：MMI<20mg/d安全，哺乳后服药","儿童青少年：ATD首选，疗程更长(2-3年)，缓解率低，RAI慎用","老年：症状不典型(淡漠型甲亢)，房颤多见，积极治疗，注意药物剂量","GO活动期：RAI可加重GO，需激素预防，优先ATD或手术"],"references":"中华医学会内分泌学分会. 中国甲状腺功能亢进症诊治指南(2024). 中华内分泌代谢杂志"},{"name":"中国高尿酸血症与痛风诊疗指南（2024）","category":"内分泌科","scope":"成人高尿酸血症和痛风诊断、治疗和管理。","diagnosis":["高尿酸血症：非同日2次空腹血尿酸>420μmol/L(男)/>360μmol/L(女)","痛风急性发作：关节红肿热痛，第一跖趾关节最常见，夜间突发","痛风石：耳廓、关节周围皮下结节","关节液/痛风石穿刺：尿酸盐结晶(针状、负性双折光)为金标准","影像学：双能CT显示尿酸盐沉积，超声双轨征","排除化脓性关节炎、假性痛风(焦磷酸钙结晶)、类风湿关节炎"],"staging":["高尿酸血症：无症状期","急性痛风性关节炎：反复发作","间歇期：两次发作之间","慢性痛风石性关节炎：痛风石形成、关节破坏","痛风性肾病：尿酸性肾病、尿酸结石、慢性肾功能不全","分期：急性期、间歇期、慢性期"],"key_points":["急性期：抗炎止痛(秋水仙碱/NSAIDs/激素)，不启动降尿酸(已在用则不停)","降尿酸治疗：血尿酸≥480μmol/L或有痛风发作/痛风石/肾结石，目标<360(有痛风石<300)","降尿酸首选黄嘌呤氧化酶抑制剂(别嘌醇/非布司他)","降尿酸同时预防急性发作(秋水仙碱0.5mg qd×3-6月)","生活方式：低嘌呤饮食、限酒、多饮水、减重","别嘌醇用前查HLA-B*5801(汉族人高危，阳性禁用)"],"drug_recommendations":["急性期秋水仙碱：0.5mg每1-2h至症状缓解或腹泻，最大3mg/d；推荐低剂量0.5mg tid","NSAIDs：依托考昔120mg qd(急性首选)、塞来昔布200mg bid、双氯芬酸50mg tid，注意胃肠/肾/心血管风险","糖皮质激素：泼尼松10mg tid×3-5天(不能用秋水仙碱/NSAIDs时)，或关节腔注射曲安奈德","降尿酸别嘌醇：100mg qd起，每2-4周加100mg，目标300-600mg/d，用前查HLA-B*5801","降尿酸非布司他：20mg qd起，渐加至40-80mg qd，心血管病慎用","促尿酸排泄：苯溴马隆25-100mg qd(eGFR≥30)，多饮水+碱化尿液","碱化尿液：碳酸氢钠0.5-1g tid或枸橼酸钾，目标尿pH 6.2-6.9","预防发作：秋水仙碱0.5mg qd或NSAIDs小剂量，降尿酸开始后3-6个月"],"non_pharmacological":["低嘌呤饮食：避免动物内脏、海鲜、浓肉汤、啤酒，限制红肉","限酒：啤酒>白酒>红酒，最好不饮","多饮水：>2000ml/d，促进尿酸排泄","减重：BMI<24，腹型肥胖减重","避免含糖饮料和高果糖食物","避免剧烈运动和突然受凉(诱发发作)","戒烟"],"complications":["痛风石：破溃可流出白垩样物质，感染，手术切除","关节破坏：慢性期关节畸形功能障碍，影像学骨侵蚀","尿酸性肾结石：腰痛血尿，多饮水+碱化尿液，必要时碎石","痛风性肾病：间质性肾炎、肾功能不全，控制尿酸+ACEI/ARB护肾","急性发作：最常见，夜间剧痛，影响生活质量"],"monitoring":["降尿酸初期：每2-4周查血尿酸，调整剂量","达标后每3-6个月复查","肾功能、尿常规、泌尿系超声定期","关节超声/双能CT评估尿酸盐沉积变化","急性发作记录频率和部位"],"special_populations":["CKD：别嘌醇按eGFR调量，非布司他不需调量但心血管慎用，苯溴马隆eGFR<30禁用","心血管病：非布司他慎用(心血管事件风险)，别嘌醇优先","妊娠哺乳期：不推荐降尿酸药，急性期用激素","老年：注意肾功能和药物相互作用，小剂量起始","儿童：罕见，多为遗传性酶缺陷，专科治疗"],"references":"中华医学会内分泌学分会. 中国高尿酸血症与痛风诊疗指南(2024). 中华内分泌代谢杂志"},{"name":"中国急性缺血性脑卒中诊治指南（2024）","category":"神经内科","scope":"成人急性缺血性脑卒中(AIS)早期诊断和治疗。","diagnosis":["突发局灶性神经功能缺损(偏瘫、失语、偏盲、共济失调)或意识障碍","头颅CT排除出血(发病早期CT可正常)","头颅MRI DWI高信号为金标准(超早期敏感)","评估发病时间(最后正常时间)、NIHSS评分","血管评估：CTA/MRA/DSA明确大血管闭塞","病因分型：TOAST分型(大动脉粥样硬化/心源性/小血管/其他/不明原因)"],"staging":["NIHSS评分：0-42分，<4轻型、5-15中型、16-20中重型、>20重型","时间窗：静脉溶栓4.5h内(rt-PA)，6h内(尿激酶)；机械取栓6h内，符合DAWN/DEFUSE 3标准可延长至16-24h","大血管闭塞(LVO)：颈内动脉、大脑中动脉M1/M2、基底动脉","轻型卒中：NIHSS<4，致残性症状仍需溶栓","后循环卒中：基底动脉闭塞预后差，取栓时间窗可延长"],"key_points":["时间就是大脑，尽早识别和转运","静脉溶栓：4.5h内rt-PA，无禁忌首选","机械取栓：大血管闭塞6h内，符合标准可延长","抗血小板：未溶栓者尽早阿司匹林150-300mg/d，溶栓后24h开始","他汀：尽早高强度他汀(阿托伐他汀40-80mg)","血压管理：溶栓前<185/110，溶栓后<180/105；未溶栓>220/120才降压"],"drug_recommendations":["静脉溶栓rt-PA：0.9mg/kg(最大90mg)，10%静推1min，90%静滴1h，4.5h内","尿激酶：100-150万U+NS 100-200ml静滴30min，6h内","机械取栓：支架取栓(Solitaire)或抽吸导管，首选","抗血小板：阿司匹林150-300mg qd(未溶栓)，溶栓24h后100mg qd；轻型非致残可双抗(阿司匹林+氯吡格雷)21天","他汀：阿托伐他汀40-80mg qn或瑞舒伐他汀20-40mg qn，目标LDL<1.8","降压：溶栓前血压>185/110用拉贝洛尔10-20mg iv或尼卡地平5mg/h泵入","抗凝：心源性栓塞急性期不推荐早期抗凝，2周后开始华法林/NOAC"],"non_pharmacological":["气道管理：意识障碍/球麻痹者气道保护，必要时气管插管","氧疗：SpO2<94%吸氧，目标≥94%","体温：>38℃降温，查找感染源","血糖：7.8-10mmol/L，>10用胰岛素，<3.3补糖","营养：48h内评估吞咽功能，不能经口者鼻饲","早期康复：病情稳定后24-48h开始肢体功能位、被动活动"],"complications":["出血转化：溶栓/取栓后症状加重立即复查CT，出血停用抗栓，控制血压","脑水肿/脑疝：大面积梗死，甘露醇0.25-0.5g/kg q6h、去骨瓣减压","癫痫：卒中后癫痫，左乙拉西坦500mg bid或丙戊酸钠","感染：肺炎(误吸)、尿路感染，抗感染+护理","深静脉血栓：气压治疗+低分子肝素预防","压疮：定时翻身"],"monitoring":["溶栓/取栓后24h内：每15-30min生命体征+NIHSS，24h复查CT","生命体征：血压、心率、血氧、体温","神经功能：NIHSS定期评估","颅内出血征象：头痛、呕吐、意识下降","血糖每1-4h，电解质、血常规、凝血","心电监护(心律失常/心肌缺血)"],"special_populations":["老年(≥80岁)：溶栓仍可获益，取栓同样适用，注意并发症","轻型卒中(NIHSS<4)：致残性症状仍溶栓，非致残可双抗","后循环卒中：基底动脉闭塞取栓时间窗可延长至24h，预后差","妊娠：MRI无辐射优先，溶栓需权衡，取栓铅衣保护","儿童：少见，多为心源性/血管炎，治疗原则相同剂量按体重"],"references":"中华医学会神经病学分会. 中国急性缺血性脑卒中诊治指南(2024). 中华神经科杂志"},{"name":"中国帕金森病治疗指南（2024）","category":"神经内科","scope":"成人帕金森病(PD)诊断和药物/手术治疗。","diagnosis":["运动症状：静止性震颤(4-6Hz)、肌强直、运动迟缓、姿势平衡障碍","支持标准：单侧起病、静止性震颤、进行性加重、左旋多巴有效","排除标准：小脑症状、核上性凝视麻痹、早发严重自主神经障碍、锥体束征、额叶痴呆","警示征：发病5年内快速进展、发病3年内姿势不稳、球麻痹、吸气性呼吸障碍","辅助检查：多巴胺转运体SPECT/PET( DAT减少)、超声(黑质高回声)、MIBI心肌显像(减少)","鉴别：特发性震颤、帕金森叠加综合征(MSA/PSP/CBD)、药物性帕金森、血管性帕金森"],"staging":["Hoehn-Yahr分期：1期单侧、2期双侧、3期姿势反射受损、4期严重残疾需扶助、5期轮椅/卧床","运动并发症：症状波动(剂末现象、开关现象)、异动症(剂峰/双相/关期肌张力障碍)","非运动症状：抑郁、焦虑、认知障碍/痴呆、幻觉、睡眠障碍(RBD/失眠/嗜睡)、自主神经功能障碍(便秘/体位性低血压/尿失禁)、疼痛、疲劳","病程：早期(H-Y 1-1.5)、中期(H-Y 2-3)、晚期(H-Y 4-5)"],"key_points":["早期诊断早期治疗，药物治疗是首选","目标：改善症状，延缓运动并发症，提高生活质量","用药原则：剂量滴定，细水长流不求全效，最小有效剂量","年轻/早期无认知障碍：MAO-B抑制剂或多巴胺受体激动剂起始","老年/认知障碍：左旋多巴起始","中晚期运动并发症：调整药物方案，评估DBS手术","非运动症状同样需积极管理"],"drug_recommendations":["左旋多巴：美多芭(左旋多巴200mg+苄丝肼50mg)起始62.5mg tid，渐加至250mg tid，餐前1h或餐后1.5h；达灵复(左旋多巴+卡比多巴+恩他卡朋)","多巴胺受体激动剂：普拉克索0.125mg tid起渐加至0.5-1mg tid；罗匹尼罗0.25mg tid起；吡贝地尔50mg qd-bid；罗替戈汀贴剂2-8mg/24h","MAO-B抑制剂：司来吉兰2.5-5mg bid(早午)、雷沙吉兰1mg qd、沙芬酰胺50-100mg qd","COMT抑制剂：恩他卡朋100-200mg与左旋多巴同服、托卡朋100mg tid(监测肝功)","抗胆碱能：苯海索1-2mg tid(震颤为主，<70岁无认知障碍，老年/认知障碍禁用)","金刚烷胺50-100mg bid-tid(异动症有效)","DBS手术：药物治疗无效/运动并发症，STN或GPi靶点，术后仍需药物"],"non_pharmacological":["康复训练：步态训练、平衡训练、言语训练(LSVT)、吞咽训练、太极拳","营养：高蛋白饮食影响左旋多巴吸收，服药与高蛋白餐间隔，便秘增加膳食纤维水","运动：规律有氧运动(快走、游泳、骑行)改善运动和非运动症状","心理支持：抑郁焦虑常见，认知行为治疗","睡眠卫生：RBD注意安全防护，避免镇静药","护理：晚期防跌倒、压疮、误吸，家庭环境改造"],"complications":["运动并发症：剂末现象(增加服药次数/加COMT抑制剂/激动剂)、开关现象(换用控释剂/DBS)、异动症(减左旋多巴单次量/加金刚烷胺/DBS)","吞咽困难/误吸：吞咽训练，稠食，必要时胃造瘘","认知障碍/痴呆：胆碱酯酶抑制剂(卡巴拉汀/多奈哌齐)","精神症状：幻觉妄想，减抗胆碱能/金刚烷胺/激动剂，必要时氯氮平/喹硫平","体位性低血压：减降压药，米多君2.5mg tid，屈昔多巴","冻结步态：听觉/视觉提示，调整药物，DBS"],"monitoring":["每3-6个月随访：UPDRS评分、H-Y分期、运动并发症、非运动症状","药物不良反应：左旋多巴(异动、恶心、体位性低血压)、激动剂(冲动控制障碍、嗜睡、水肿)、抗胆碱能(认知、口干、尿潴留)","认知功能：MMSE/MoCA定期评估","药物依从性和服药时间","晚期营养状态、吞咽功能、跌倒风险"],"special_populations":["老年(≥70岁)：左旋多巴起始，避免抗胆碱能，注意认知和体位性低血压","年轻(<60岁)：MAO-B抑制剂或激动剂起始，延缓左旋多巴使用","妊娠：左旋多巴相对安全，其他药物慎用，多学科管理","认知障碍/痴呆：避免抗胆碱能，左旋多巴+胆碱酯酶抑制剂","晚期卧床：综合护理，预防并发症，姑息治疗"],"references":"中华医学会神经病学分会帕金森病及运动障碍学组. 中国帕金森病治疗指南(2024). 中华神经科杂志"},{"name":"成人心肺复苏与心血管急救指南（2024 AHA更新）","category":"急诊科","scope":"成人心脏骤停心肺复苏(CPR)和心血管急救。","diagnosis":["心脏骤停识别：意识丧失+无正常呼吸(仅喘息/无呼吸)+大动脉搏动消失(10秒内判断)","心电节律：室颤/无脉室速(VF/pVT)、无脉电活动(PEA)、心室停搏(asystole)","可除颤节律：VF/pVT；不可除颤：PEA/asystole","病因排查(4H4T)：低氧、低血容量、酸中毒、高/低钾、低体温；张力性气胸、心包填塞、血栓(冠脉/肺栓塞)、毒素","ROSC识别：自主呼吸、意识恢复、可触及脉搏、SpO2/ETCO2上升","目标温度管理(TTM)：ROSC后昏迷者32-36℃维持24h"],"staging":["生存链：识别呼救→早期CPR→快速除颤→高级生命支持→复苏后综合管理","院外心脏骤停(OHCA)：旁观者CPR+AED+EMS","院内心脏骤停(IHCA)：快速反应团队","复苏质量：按压深度5-6cm、频率100-120次/分、胸廓充分回弹、减少中断(<10秒)、避免过度通气","ETCO2：持续监测，高质量CPR时≥10-20mmHg，ROSC时突然升高"],"key_points":["立即识别，呼救，开始CPR","C-A-B顺序：胸外按压→开放气道→人工呼吸","尽早除颤(AED到达立即分析除颤)，除颤后立即继续CPR不检查脉搏","每2分钟轮换按压者，检查节律(尽量缩短中断)","高级气道建立后持续按压不中断，通气10次/分","肾上腺素1mg每3-5分钟一次(不可除颤节律尽早用)","ROSC后目标温度管理、冠脉造影(STEMI/疑似心源性)、神经预后评估"],"drug_recommendations":["肾上腺素：1mg iv/io，每3-5分钟一次(所有心脏骤停)","胺碘酮：300mg iv推(除颤+肾上腺素后VF/pVT持续)，可再给150mg；维持1mg/min×6h→0.5mg/min×18h","利多卡因：1-1.5mg/kg iv，可再给0.5-0.75mg/kg(胺碘酮不可用时)","镁剂：1-2g iv(尖端扭转型室速/低镁)","碳酸氢钠：不常规使用，仅严重酸中毒(pH<7.1)、高钾、三环类抗抑郁药过量时用","液体复苏：低血容量/分布性休克时晶体液","血管活性药(ROSC后)：去甲肾上腺素0.05-1μg/kg/min维持MAP≥65mmHg"],"non_pharmacological":["胸外按压：双手交叠，胸骨下半部，深度5-6cm，频率100-120次/分，充分回弹","开放气道：仰头抬颏(无颈椎损伤)，推举下颌(可疑颈椎损伤)","人工呼吸：球囊面罩，每次1秒见胸廓起伏，按压通气比30:2(高级气道后10次/分)","AED：开机→贴电极→分析(不接触)→除颤(所有人离开)→立即CPR","高级气道：气管插管/声门上气道，确认位置(ETCO2+听诊)","目标温度管理：ROSC后昏迷者32-36℃维持24h，避免发热(>37.7℃)"],"complications":["肋骨骨折/胸骨骨折：常见，不影响继续按压","气胸/血胸：按压或穿刺并发症，胸腔闭式引流","误吸/肺炎：气道管理，吸引，抗感染","缺血缺氧性脑病：TTM，神经预后评估(72h后)，避免过早撤除生命支持","心功能不全：正性肌力药/血管活性药，IABP/ECMO","多器官功能衰竭：ICU综合支持"],"monitoring":["CPR期间：ETCO2(≥10-20提示高质量)、心电节律、按压深度/频率(反馈装置)","ROSC后：心电监护、血压(有创)、血氧、体温、ETCO2、血气、电解质、乳酸、心肌酶、心电图","神经功能：瞳孔、GCS、脑电图(癫痫持续状态)、SSEP(72h后预后)","冠脉造影：STEMI或疑似心源性OHCA紧急造影","器官功能：肾功能、肝功能、凝血、DIC"],"special_populations":["妊娠：子宫左移(20周以上)，必要时围死亡期剖宫产(4分钟内)","老年：基础病多，预后差，但不影响复苏努力","创伤：张力性气胸/心包填塞/低血容量为常见原因，紧急处理","低温：核心体温<30℃除颤困难，药物间隔延长，积极复温","溺水/窒息：先给5次人工呼吸再CPR，低体温延长复苏至复温"],"references":"American Heart Association. 2024 AHA Guidelines for CPR and ECC. Circulation"},{"name":"严重过敏反应急诊处理指南（2024）","category":"急诊科","scope":"成人和儿童严重过敏反应(过敏性休克)的识别和急诊处理。","diagnosis":["急性起病(数分钟至数小时)，累及皮肤黏膜(荨麻疹/血管性水肿/瘙痒/潮红)+呼吸系统(呼吸困难/喘息/低氧)或循环系统(低血压/休克)","或暴露于已知过敏原后出现低血压/支气管痉挛/喉头水肿，即使无皮肤表现","皮肤症状缺如不能排除严重过敏反应(20%无皮疹)","双相反应：初始症状缓解后数小时(1-72h，多8-10h)再次发作","常见诱因：食物(花生/坚果/海鲜/牛奶/鸡蛋)、药物(青霉素/造影剂/NSAIDs)、昆虫毒液、乳胶、运动","鉴别：哮喘急性发作、晕厥、血管迷走反应、脓毒性休克、心源性休克、遗传性血管性水肿(无荨麻疹/瘙痒)"],"staging":["严重程度分级：I级(皮肤黏膜)、II级(呼吸/心血管中度)、III级(严重呼吸/循环衰竭)、IV级(呼吸心跳骤停)","过敏性休克：收缩压<90mmHg或较基线下降>30%，伴组织灌注不足","喉头水肿：声音嘶哑、吸气性喘鸣、吞咽困难，可窒息","支气管痉挛：喘息、呼气性呼吸困难、低氧","双相反应风险：严重发作、延迟肾上腺素、过敏原未清除、需要多剂肾上腺素者风险高"],"key_points":["肾上腺素是首选救命药，立即肌注(大腿前外侧)，不要延迟","体位：平卧抬高下肢(呼吸困难者半卧位)，呕吐者侧卧","立即呼救/拨打急救电话","吸氧：SpO2<94%或呼吸困难","建立静脉通路，快速补液(晶体液)","支气管痉挛：雾化沙丁胺醇","喉头水肿严重：气管插管/环甲膜穿刺","观察至少6-12小时(双相反应风险)"],"drug_recommendations":["肾上腺素：0.3-0.5mg(1:1000)肌注大腿前外侧，成人；儿童0.01mg/kg(最大0.3mg)；每5-15分钟可重复","肾上腺素静滴：休克/肌注无效，1mg+NS 250ml，1-4μg/min(成人)，监护","液体复苏：生理盐水或乳酸林格液，成人1-2L快速静滴，儿童20ml/kg","抗组胺药：西替利嗪10mg iv/po或氯雷他定10mg po(辅助，非首选，不缓解气道痉挛/休克)","糖皮质激素：甲泼尼龙40-80mg iv或氢化可的松100-200mg iv(预防双相反应，起效慢)","支气管痉挛：沙丁胺醇雾化2.5-5mg q20min，异丙托溴铵0.5mg","难治性休克：去甲肾上腺素0.05-1μg/kg/min，胰高血糖素1-2mg iv(β阻滞剂患者)"],"non_pharmacological":["立即停止/移除过敏原(药物停输、昆虫刺拔出、食物停止)","平卧抬高下肢(呼吸困难/呕吐者半卧/侧卧)","保持气道通畅，清除分泌物","吸氧：面罩高流量，目标SpO2≥94%","建立静脉通路(大口径)","心电监护、血压、血氧监测","保暖","严重喉头水肿：气管插管(困难时环甲膜穿刺/切开)"],"complications":["呼吸衰竭：喉头水肿窒息/支气管痉挛，紧急气道管理","循环衰竭/休克：补液+肾上腺素+血管活性药","心搏骤停：CPR+肾上腺素(每3-5min)","双相反应：观察6-12h，严重者24h，激素预防","急性肺水肿/ARDS：正压通气","应激性心肌病(儿茶酚胺相关)：支持治疗，多可恢复"],"monitoring":["持续心电监护、血压(每5-15min)、血氧、呼吸频率、意识","反复评估气道、呼吸、循环","实验室：血气、乳酸、心肌酶、胰酶(食物过敏可升高)、类胰蛋白酶(发作后1-2h采血，诊断价值)","尿量","观察双相反应迹象(皮疹复发、呼吸困难、血压下降)"],"special_populations":["妊娠：肾上腺素仍首选(剂量同)，左侧卧位，监测胎心，过敏性休克可致胎儿窘迫","儿童：剂量按体重，肾上腺素0.01mg/kg肌注(最大0.3mg)，补液20ml/kg","老年/心血管病：肾上腺素注意心律失常/心肌缺血，但仍首选，小剂量起始","β阻滞剂患者：肾上腺素效果差，胰高血糖素1-2mg iv","服用ACEI者：血管性水肿风险高，对抗组胺/激素反应差，注意气道"],"references":"World Allergy Organization. WAO Guidelines for the Assessment and Management of Anaphylaxis (2024 update)"},{"name":"中国慢性肾脏病早期评价与管理指南（2024）","category":"肾内科","scope":"成人慢性肾脏病(CKD)筛查、分期评估和管理。","diagnosis":["CKD定义：肾损害标志(白蛋白尿/尿沉渣异常/组织学/影像学/移植史)或eGFR<60ml/min/1.73m²，持续≥3个月","eGFR计算：CKD-EPI公式(肌酐+年龄+性别+种族)","白蛋白尿：ACR≥30mg/g为异常；A1<30、A2 30-300、A3>300","尿沉渣：红细胞管型、颗粒管型提示肾小球/肾小管损伤","影像学：肾脏大小、皮质厚度、结构异常","肾活检：蛋白尿/血尿/肾功能快速下降，明确病理类型"],"staging":["GFR分期：G1≥90、G2 60-89、G3a 45-59、G3b 30-44、G4 15-29、G5<15(透析)","白蛋白尿分期：A1正常/轻度、A2中度、A3重度","CKD进展风险：G1-2+A1低危、G1-2+A2/G3a+A1中危、G1-2+A3/G3a+A2/G3b+A1高危、G3a+A3/G3b+A2/G4+A1-2极高危、G5/G4+A3极高危","急性肾损伤(AKI)：48h内肌酐升高≥26.5μmol/L或7天内升高≥50%，或尿量<0.5ml/kg/h×6h","ESRD：G5期需要肾脏替代治疗(透析/移植)"],"key_points":["早期筛查：高危人群(糖尿病、高血压、心血管病、肥胖、吸烟、家族史、老年)每年查尿常规+eGFR+ACR","控制血压：CKD目标<130/80，ACEI/ARB首选(蛋白尿者)","控制血糖：糖尿病CKD HbA1c<7%，SGLT2i推荐","控制蛋白尿：ACEI/ARB减少蛋白尿，目标ACR<30","血脂管理：LDL<2.6(极高危<1.8)，他汀治疗","避免肾毒性药物：NSAIDs、氨基糖苷、造影剂、含马兜铃酸中药","营养：蛋白0.8g/kg/d(G3-5未透析)，低盐<5g/d，限钾限磷(G4-5)"],"drug_recommendations":["ACEI：贝那普利10-20mg qd、依那普利5-10mg bid(蛋白尿首选，起始后2-4周查血钾肌酐，肌酐升<30%可继续)","ARB：缬沙坦80-160mg qd、氯沙坦50-100mg qd、厄贝沙坦150-300mg qd","SGLT2i：达格列净10mg qd、恩格列净10mg qd(eGFR≥20可用，CKD全阶段获益)","GLP-1RA：利拉鲁肽1.2-1.8mg qd、司美格鲁肽0.5-1.0mg qw(糖尿病CKD)","利尿剂：呋塞米20-40mg qd(水肿/高血压)，eGFR<30噻嗪类效果差换袢利尿剂","降磷：碳酸钙/醋酸钙(餐中嚼服)、司维拉姆800mg tid、碳酸镧500mg tid(G4-5高磷)","纠正贫血：促红素(ESA)50-100U/kg tiw，目标Hb 100-120g/L；铁剂(静脉蔗糖铁)","纠正酸中毒：碳酸氢钠1-3g tid(CO2CP<22)"],"non_pharmacological":["低盐饮食：<5g/d(包括隐形盐)","优质低蛋白：0.8g/kg/d(G3-5未透析)，透析后1.0-1.2g/kg/d，动物蛋白为主","限钾：G4-5高钾者避免香蕉/橙子/土豆/坚果/低钠盐，蔬菜焯水去钾","限磷：避免加工肉/可乐/坚果/动物内脏，选磷蛋白比低的食物","限水：尿量减少/水肿/高血压者控制入量(前一日尿量+500ml)","戒烟限酒，控制体重(BMI 18.5-24)","适度运动：每周≥150分钟中等强度，避免剧烈运动","避免滥用药物和偏方"],"complications":["CKD进展至ESRD：透析(血液透析/腹膜透析)或肾移植","心血管疾病：CKD首要死因，冠心病/心衰/心律失常/猝死，积极控制危险因素","矿物质骨代谢异常(CKD-MBD)：高磷低钙继发性甲旁亢，肾性骨病，血管钙化","贫血：EPO缺乏+铁缺乏+炎症，ESA+铁剂","代谢性酸中毒：碳酸氢钠纠正","高钾血症：危及生命，钙剂(稳定心肌)+胰岛素+葡萄糖+降钾药(聚苯乙烯磺酸钙/环硅酸锆钠)+透析","感染：免疫功能低下，疫苗接种(乙肝/流感/肺炎球菌)"],"monitoring":["CKD 1-2期：每6-12个月查eGFR、ACR、电解质","CKD 3期：每3-6个月","CKD 4期：每1-3个月","CKD 5期：每月","每次：血压、体重、eGFR、电解质(钾钠氯钙磷)、CO2CP、血常规、PTH(G3b起)、铁蛋白/转铁蛋白饱和度","肾脏超声每年评估大小和结构","血管通路准备：预计1年内透析者提前建立动静脉内瘘"],"special_populations":["糖尿病肾病：SGLT2i+GLP-1RA+ACEI/ARB，严格控糖控压，蛋白尿是进展关键","高血压肾损害：控制血压<130/80，ACEI/ARB，夜尿增多为早期表现","老年：eGFR随年龄下降，避免肾毒性药，药物按eGFR调整","妊娠：CKD妊娠风险高(高血压/子痫/早产/肾功能恶化)，需多学科，ACEI/ARB/SGLT2i禁用","儿童：遗传性肾病多见(Alport综合征)，生长发育和营养关注"],"references":"中华医学会肾脏病学分会. 中国慢性肾脏病早期评价与管理指南(2024). 中华肾脏病杂志"},{"name":"抗菌药物临床应用指导原则（2024年版）","category":"感染科","scope":"抗菌药物临床合理应用的基本原则、适应证和管理。","diagnosis":["细菌感染诊断：症状体征+实验室(白细胞/中性粒/CRP/PCT升高)+病原学(培养/核酸/抗原)","病原学检查：用药前留取标本(血培养×2套、痰、尿、脑脊液、分泌物)，药敏指导用药","感染部位：呼吸道、泌尿道、消化道、皮肤软组织、血流、中枢、腹腔等","感染严重程度：轻症(门诊口服)、中症(住院静脉)、重症(ICU广谱联合)","宿主因素：免疫状态、肝肾功能、年龄、妊娠、过敏史、既往抗菌药使用","耐药风险评估：近3月抗菌药使用、住院史、护理院、侵袭性操作、当地耐药率"],"staging":["预防用药：手术预防(术前30-60min单剂，清洁手术不超过24h)、特定感染预防(风湿热/流脑/结核暴露)","经验治疗：未获病原前根据部位+严重程度+宿主选药，覆盖最可能病原","目标治疗：获得病原和药敏后，降阶梯/窄谱/口服转换","联合用药：重症/混合感染/耐药菌/协同作用(如草绿色链球菌心内膜炎青霉素+庆大)","疗程：一般体温正常/症状消退后72-96h；特殊感染更长(感染性心内膜炎4-6周、骨髓炎4-6周、结核6-9月)","抗菌药物分级管理：非限制级、限制级、特殊使用级(专家会诊)"],"key_points":["诊断为细菌感染者方有指征，病毒感染不用","尽早查明病原，根据药敏选药","按药物抗菌谱、药代动力学、药效学选药(PK/PD)","剂量足、疗程够，避免耐药和复发","根据肝肾功能调整剂量","尽量避免局部用药(除特殊情况)","严格控制预防用药指征","分级管理，特殊使用级需会诊"],"drug_recommendations":["时间依赖性(β内酰胺类)：青霉素/头孢/碳青霉烯，分次给药，延长输注时间(3-4h)提高T>MIC","浓度依赖性(氨基糖苷/喹诺酮)：每日1次给药，提高Cmax/MIC和AUC/MIC","社区获得性肺炎：阿莫西林/头孢曲松+大环内酯或呼吸喹诺酮","医院获得性肺炎：哌拉西林他唑巴坦/头孢吡肟/碳青霉烯，怀疑MRSA加万古霉素/利奈唑胺，怀疑铜绿覆盖","尿路感染：呋喃妥因/磷霉素(单纯性)，头孢/喹诺酮(复杂性)","皮肤软组织：苯唑西林/头孢唑林(金葡)，怀疑MRSA用万古霉素/达托霉素","腹腔感染：三代头孢+甲硝唑或哌拉西林他唑巴坦/碳青霉烯","中枢感染：三代头孢(头孢曲松/头孢噻肟)+万古霉素，李斯特菌加氨苄西林","MRSA：万古霉素15-20mg/kg q12h(谷浓度15-20)、利奈唑胺600mg q12h、达托霉素6mg/kg qd(非肺炎)","CRE：多黏菌素B/替加环素/头孢他啶阿维巴坦/美罗培南法硼巴坦，联合用药"],"non_pharmacological":["感染灶引流/清除：脓肿切开、胸腔/腹腔引流、坏死组织清创、拔除感染导管","支持治疗：补液、营养、氧疗、纠正电解质紊乱","免疫调节：丙种球蛋白(特定免疫缺陷)、粒细胞集落刺激因子(粒缺)","物理治疗：热敷、理疗","隔离：多重耐药菌接触隔离，空气传播(结核/麻疹)空气隔离","疫苗接种：流感、肺炎球菌、乙肝、HPV等预防感染"],"complications":["抗菌药物不良反应：过敏(青霉素/头孢)、肾毒性(氨基糖苷/万古霉素)、肝毒性(四环素/大环内酯)、耳毒性(氨基糖苷)、胃肠道反应(广谱抗生素腹泻)","艰难梭菌感染(CDI)：广谱抗生素后腹泻，甲硝唑/万古霉素/非达霉素，粪菌移植(复发)","二重感染：真菌(念珠菌/曲霉)、耐药菌","药物相互作用：QT延长(喹诺酮/大环内酯)、抗凝(甲硝唑/头孢哌酮)、茶碱(大环内酯/喹诺酮)","耐药菌产生：不合理使用导致MRSA/VRE/CRE/CRAB/CRPA"],"monitoring":["疗效评估：用药48-72h评估，体温、症状、白细胞、CRP/PCT、影像学","血药浓度：氨基糖苷(峰谷浓度)、万古霉素(谷浓度15-20)、茶碱","肝肾功能：用药前和用药中定期，调整剂量","过敏反应：用药后观察30min(青霉素/头孢)，备好急救","二重感染迹象：腹泻(艰难梭菌)、口腔白斑(真菌)","病原学随访：血培养阳性者复查至阴性"],"special_populations":["老年：肾功能减退，按eGFR调量，注意耳肾毒性，避免长效药物","儿童：避免四环素(8岁以下)、喹诺酮(骨骼影响)，氨基糖苷慎用，按体重算量","妊娠：青霉素/头孢/阿奇霉素相对安全，禁用四环素/喹诺酮/氨基糖苷/磺胺(孕晚期)","哺乳：多数抗菌药可分泌入乳汁，注意婴儿影响(四环素/喹诺酮避免)","肝肾功能不全：按Child-Pugh/eGFR调整，避免肝肾毒性药物","免疫低下：经验治疗更积极广谱，覆盖真菌/病毒/肺孢子菌等特殊病原"],"references":"国家卫生健康委员会. 抗菌药物临床应用指导原则(2024年版)"},{"name":"妊娠期高血压疾病诊治指南（2024）","category":"妇产科","scope":"妊娠期高血压疾病诊断、分类和处理。","diagnosis":["妊娠期高血压：妊娠20周后首次BP≥140/90，产后12周恢复，无蛋白尿","子痫前期：BP≥140/90+蛋白尿≥0.3g/24h或ACR≥30mg/g，或无蛋白尿但有器官损害(血小板<100、肝酶升高、肾功损害、肺水肿、新发生脑/视觉症状)","子痫：子痫前期基础上抽搐(不能用其他原因解释)","慢性高血压合并妊娠：妊娠前或20周前BP≥140/90","慢性高血压并发子痫前期：慢性高血压基础上出现蛋白尿/器官损害","高危因素：初产、高龄(≥40)、肥胖、多胎、家族史、慢性高血压/肾病/糖尿病/自身免疫病"],"staging":["轻度子痫前期：BP≥140/90，蛋白尿或器官损害轻","重度子痫前期：BP≥160/110，或严重器官损害(血小板<100、肝酶>2倍、肌酐>1.1、肺水肿、脑/视觉症状、上腹痛、FGR)","子痫：抽搐发作，产前/产时/产后","HELLP综合征：溶血(H)、肝酶升高(EL)、血小板减少(LP)，子痫前期严重并发症","远期风险：再次妊娠复发、慢性高血压、心血管病、肾病"],"key_points":["降压：BP≥140/90建议降压，≥160/110紧急降压，目标130-155/80-105","硫酸镁：子痫前期重度预防抽搐，子痫控制抽搐和预防复发","终止妊娠是根本治疗：重度子痫前期/子痫病情稳定后终止，孕龄决定方式","产前糖皮质激素：<34周预计早产者促胎肺成熟(地塞米松6mg im q12h×4次)","严密监测母儿：血压、尿蛋白、器官功能、胎心、胎儿生长","产后仍需监测：产后48h内是子痫高发期，降压继续"],"drug_recommendations":["降压口服：拉贝洛尔100mg bid起(最大2400mg/d)、硝苯地平缓释片20mg q12h(最大120mg/d)、甲基多巴250mg tid起(最大3g/d)","紧急降压静脉：拉贝洛尔20mg iv→40mg→80mg(每10min)，或硝苯地平10mg口服，或肼苯哒嗪5mg iv q15-20min","硫酸镁：负荷4-6g+5%GS 100ml静滴15-20min，维持1-2g/h，24h总量≤25g；用至产后24h(子痫预防)或抽搐控制后24h(子痫)","硫酸镁中毒：膝反射消失、呼吸<16次/分、尿量<25ml/h，钙剂解救(10%葡萄糖酸钙10ml iv慢推)","糖皮质激素：地塞米松6mg im q12h×4次或倍他米松12mg im q24h×2次(<34周)","镇静：地西泮10mg iv或冬眠合剂(硫酸镁无效时)","利尿剂：不常规用，仅肺水肿/脑水肿/心衰时用"],"non_pharmacological":["左侧卧位：减轻子宫对下腔静脉压迫，改善胎盘灌注","休息：重度子痫前期住院卧床休息","饮食：充足蛋白热量，不严格限盐(除非严重水肿)，补钙1.5-2g/d(高危者预防)","监测：血压每4h(重度每15-30min)、体重、尿量、胎动","胎儿监测：胎心监护、超声(生长/羊水/脐血流)","心理支持：焦虑恐惧常见，解释病情"],"complications":["子痫：抽搐→硫酸镁控制，防舌咬伤/窒息/外伤，控制后终止妊娠","HELLP综合征：溶血(贫血/黄疸/网织红高)、肝酶升高、血小板<100，糖皮质激素+终止妊娠","胎盘早剥：腹痛阴道出血胎心异常，紧急剖宫产","急性肾衰：少尿无尿肌酐升高，液体管理，必要时透析","肺水肿/心衰：呼吸困难低氧，利尿+扩血管+正压通气","脑血管意外：脑出血/脑水肿，控制血压+脱水","DIC：凝血功能障碍，补充凝血因子+肝素(慎用)"],"monitoring":["血压：每4h(重度每15-30min)","尿蛋白：24h尿蛋白或ACR","实验室：血常规(血小板)、肝酶、肌酐、尿酸、凝血、LDH(HELLP)、电解质","胎心监护：重度每日1-2次","超声：胎儿生长、羊水量、脐动脉血流","尿量：每小时记录(硫酸镁期间)","膝反射/呼吸(硫酸镁中毒监测)"],"special_populations":["早发型子痫前期(<34周)：尽量延长孕周(期待治疗)，严密监测，促胎肺成熟，≥34周终止","慢性高血压合并妊娠：孕前评估，孕期用拉贝洛尔/硝苯地平/甲基多巴，ACEI/ARB禁用，监测子痫前期","多胎妊娠：高危，加强监测，降压阈值更低","产后：产后48h内子痫高发，继续降压和硫酸镁，产后12周复查血压(慢性高血压诊断)","远期随访：慢性高血压、心血管病、肾病风险增加，长期管理"],"references":"中华医学会妇产科学分会妊娠期高血压疾病学组. 妊娠期高血压疾病诊治指南(2024). 中华妇产科杂志"},{"name":"儿童支气管哮喘诊断与防治指南（2024）","category":"儿科","scope":"儿童(0-14岁)支气管哮喘诊断、评估和长期管理。","diagnosis":["反复发作喘息、咳嗽、气促、胸闷，夜间/凌晨加重，与接触变应原/冷空气/运动/感染有关","发作时双肺闻及呼气相哮鸣音，呼气相延长","支气管舒张试验阳性：吸入SABA后FEV1改善≥12%(≥6岁)","PEF日间变异率>13%(≥6岁)","抗炎治疗有效：ICS治疗2-4周症状显著改善","排除其他原因：反复喘息鉴别(先天性气道畸形、异物、胃食管反流、支气管肺发育不良、囊性纤维化)","过敏原检测：皮肤点刺或血清sIgE，辅助判断诱因"],"staging":["病情分期：急性发作期、慢性持续期、临床缓解期(≥3个月无症状)","控制水平分级：良好控制、部分控制、未控制(按日间症状/夜间憋醒/SABA使用/活动受限/肺功能)","急性发作严重度：轻度、中度、重度、危重度(说话不连贯/发绀/意识改变/哮鸣音减弱消失)","哮喘预测指数(API)：<3岁反复喘息预测未来哮喘风险(阳性：父母哮喘/特应性皮炎/吸入过敏原阳性/嗜酸高/感冒无关喘息)","表型：婴幼儿喘息(病毒诱导型/多因素触发型)、学龄前喘息、学龄期哮喘"],"key_points":["坚持长期、持续、规范、个体化治疗","急性发作：快速缓解症状(SABA+全身激素+氧疗)","慢性持续：ICS是控制治疗首选，按控制水平升/降级","≥6岁：GINA阶梯治疗，低剂量ICS-福莫特罗按需(MART方案)","<6岁：ICS每天控制，或白三烯调节剂","治疗目标：良好控制症状，维持正常活动，预防急性发作和肺功能损害","患者教育：吸入技术、峰流速监测、行动计划、避免诱因"],"drug_recommendations":["SABA：沙丁胺醇雾化2.5mg(<20kg)/5mg(≥20kg) q20min×3次，或pMDI+储雾罐2-4揿","ICS：布地奈德雾化0.5-1mg bid(<6岁)，丙酸氟替卡松50-100μg bid(≥4岁)，布地奈德/福莫特罗80/4.5μg 1-2吸bid(≥6岁)","全身激素：泼尼松龙1-2mg/kg/d(最大40mg)×3-5天，重症甲泼尼龙1-2mg/kg iv q6h","抗胆碱能：异丙托溴铵雾化250μg(<6岁)/500μg(≥6岁)，与SABA联合(中重度发作)","白三烯调节剂：孟鲁司特4mg(2-5岁)/5mg(6-14岁) qn，ICS辅助或不能用ICS者","茶碱：氨茶碱负荷5mg/kg iv(>20min)后0.5-1mg/kg/h维持(重症，监测血药浓度)","生物制剂：≥6岁中重度嗜酸型/过敏型，奥马珠单抗(抗IgE)、美泊利单抗(抗IL-5)，按体重和IgE/嗜酸算剂量","危重度发作：SABA+异丙托溴铵雾化q20min，全身激素iv，硫酸镁25-40mg/kg iv(最大2g)，无效机械通气"],"non_pharmacological":["避免诱因：尘螨(防螨床罩/热水洗)、烟雾(包括二手三手烟)、宠物、霉菌、花粉季节防护","呼吸道感染预防：勤洗手，流感疫苗每年接种，RSV预防(高危婴幼儿帕利珠单抗)","运动管理：运动前吸入SABA预防，哮喘控制好可正常运动","呼吸训练：腹式呼吸、缩唇呼吸(≥6岁)","家庭监测：峰流速仪(≥6岁)，记录哮喘日记，识别发作先兆","营养：均衡饮食，肥胖者减重，避免已知过敏食物"],"complications":["哮喘持续状态/危重度发作：雾化SABA+激素+氧疗，无效插管机械通气，死亡率高","气胸/纵隔气肿：严重发作，胸腔闭式引流","呼吸衰竭：II型呼衰，无创或有创通气","闭锁肺综合征：严重支气管痉挛，药物无效，紧急机械通气","药物不良反应：ICS口腔念珠菌/声音嘶哑(漱口)、SABA心悸手抖、孟鲁司特神经精神事件(情绪/睡眠/自杀意念)","肺功能损害：长期未控制可致气道重塑，成人后COPD风险"],"monitoring":["控制良好每3个月随访，未控制每2-4周","每次：症状、夜间憋醒、SABA使用、活动受限、吸入技术、峰流速(≥6岁)","肺功能：≥6岁每年1-2次，急性发作后复查","FeNO/血嗜酸：评估表型和ICS反应","过敏原复查：必要时","治疗依从性评估，环境控制评估"],"special_populations":["婴幼儿(<3岁)：反复喘息多为病毒诱导，API阳性者按哮喘治疗，ICS或白三烯调节剂，避免过度诊断","学龄前(3-5岁)：ICS每天控制，或孟鲁司特，吸入用储雾罐+面罩","学龄期(≥6岁)：GINA阶梯，MART方案(低剂量ICS-福莫特罗维持+缓解)，干粉吸入器可用","运动诱发哮喘：运动前SABA预防，控制不佳者ICS维持","过敏性鼻炎合并哮喘：同时治疗鼻炎(鼻喷激素)，上气道下气道同治","重症哮喘：评估依从性/吸入技术/诱因/合并症，生物制剂，多学科管理"],"references":"中华医学会儿科学分会呼吸学组. 儿童支气管哮喘诊断与防治指南(2024). 中华儿科杂志"},{"name":"成人原发免疫性血小板减少症诊断与治疗中国指南（2024）","category":"血液科","scope":"成人原发免疫性血小板减少症(ITP)诊断和治疗。","diagnosis":["至少2次血常规血小板减少(<100×10⁹/L)，血涂片确认(排除假性血小板减少/EDTA依赖)","无白细胞异常和贫血(除非出血导致)","骨髓穿刺：巨核细胞数正常或增多伴成熟障碍，排除其他血液病","排除继发性：自身免疫病(SLE/抗磷脂)、感染(HCV/HIV/幽门螺杆菌)、药物、淋巴增殖性疾病、骨髓增生异常","出血表现：皮肤瘀点瘀斑、牙龈出血、鼻衄、月经过多，严重者内脏出血/颅内出血","血小板抗体(PAIg)：敏感性高特异性低，不做常规诊断依据","出血评分：WHO出血分级0-4级"],"staging":["新诊断ITP：确诊后3个月内","持续性ITP：确诊后3-12个月","慢性ITP：病程>12个月","重症ITP：血小板<10×10⁹/L伴活动性出血，需要急救治疗","难治性ITP：脾切除后复发或无效，仍需治疗","按血小板数：轻度(50-100)、中度(30-50)、重度(10-30)、极重度(<10)"],"key_points":["治疗目标：安全血小板数(≥30×10⁹/L无出血)，不追求正常","血小板≥30无出血：观察，不治疗","血小板<30或有出血：一线治疗糖皮质激素","激素无效/依赖：二线治疗(TPO受体激动剂/利妥昔单抗/脾切除)","重症ITP/大出血：急救治疗(IVIG+大剂量激素+血小板输注)","避免抗血小板/抗凝药物，避免外伤","幽门螺杆菌阳性者根除治疗(部分患者血小板恢复)"],"drug_recommendations":["一线糖皮质激素：地塞米松40mg qd×4天(口服/静滴)，或泼尼松1mg/kg/d(最大60-80mg)×2-4周渐减","IVIG：0.4g/kg/d×5天或1g/kg/d×2天(重症/激素禁忌/术前快速提升)","抗RhD免疫球蛋白：50-75μg/kg( Rh阳性非切脾者，注意溶血)","二线TPO受体激动剂：艾曲泊帕25mg qd起(最大75mg，空腹)、罗米司亭1μg/kg qw皮下、阿伐曲泊帕20mg qd起","利妥昔单抗：375mg/m²每周×4次，或100mg每周×4次(小剂量)，起效慢(4-8周)","脾切除：药物治疗无效，术前疫苗接种(肺炎球菌/流感/嗜血杆菌)，腹腔镜优先","急救：甲泼尼龙1g/d×3天+IVIG 1g/kg/d×2天+血小板输注，重组人活化因子VIIa(难治性出血)"],"non_pharmacological":["避免外伤、剧烈运动、重体力劳动","避免使用影响血小板功能的药物：阿司匹林、NSAIDs、氯吡格雷、华法林等(除非必需)","口腔护理：软毛牙刷，避免牙签牙线，牙龈出血用明胶海绵压迫","月经过多：妇科会诊，口服避孕药/孕激素控制","饮食：软食，避免坚硬粗糙食物","心理支持：慢性病程，焦虑抑郁常见"],"complications":["颅内出血：最严重并发症，血小板<10风险高，头痛呕吐意识改变立即CT，急救治疗","内脏出血：消化道(黑便呕血)、泌尿道(血尿)、呼吸道(咯血)，急救+专科处理","月经过多致缺铁性贫血：补铁+妇科治疗","激素不良反应：高血糖、高血压、骨质疏松、感染、消化道溃疡、精神症状","脾切除后感染：暴发性肺炎球菌感染(OPSI)，术前疫苗+术后抗生素预防","TPO受体激动剂：血栓风险(尤其有血栓危险因素者)、肝毒性(艾曲泊帕)、骨髓纤维化(长期)"],"monitoring":["治疗初期：每周查血常规，评估疗效","稳定期：每2-4周查血常规","激素治疗期间：血糖、血压、骨密度、胃肠道症状","TPO受体激动剂：肝功能(艾曲泊帕)、血小板(避免>400)、血栓征象","脾切除后：血常规( Howell-Jolly小体)、感染征象","出血评估：每次随访出血症状和评分"],"special_populations":["妊娠：ITP妊娠风险(产妇出血/新生儿血小板减少)，一线糖皮质激素(泼尼松)或IVIG，避免TPO激动剂和利妥昔单抗，分娩血小板≥50(阴道)/≥80(剖宫产)","老年：出血和血栓风险均高，治疗目标个体化，注意激素和TPO激动剂不良反应","合并自身免疫病(SLE/抗磷脂综合征)：同时治疗原发病，注意血栓风险","HIV/HCV相关ITP：抗病毒治疗为主，必要时IVIG/激素","药物诱导性ITP：停用可疑药物，必要时IVIG/激素"],"references":"中华医学会血液学分会止血与血栓学组. 成人原发免疫性血小板减少症诊断与治疗中国指南(2024). 中华血液学杂志"},{"name":"缺铁性贫血诊疗指南（2024）","category":"血液科","scope":"成人和儿童缺铁性贫血(IDA)诊断和治疗。","diagnosis":["贫血：男性Hb<120g/L，女性<110g/L，孕妇<100g/L","小细胞低色素：MCV<80fl，MCH<27pg，MCHC<320g/L","铁代谢：血清铁<8.95μmol/L，总铁结合力>64.4μmol/L，转铁蛋白饱和度<15%","血清铁蛋白：<15μg/L(绝对缺乏)，<30μg/L伴贫血(伴炎症时<100μg/L且转铁蛋白饱和度<20%)","骨髓铁染色：细胞外铁消失，铁粒幼细胞<15%(金标准，少用)","病因排查：慢性失血(消化道/月经过多/咯血/血尿)、摄入不足、吸收障碍(胃切除/乳糜泻)、需求增加(妊娠/哺乳/生长发育)","鉴别：地中海贫血(铁蛋白正常/高、血红蛋白电泳)、慢性病贫血(铁蛋白高、铁低)、铁粒幼细胞贫血"],"staging":["铁减少期(ID)：储存铁减少(铁蛋白<30)，Hb正常","缺铁性红细胞生成期(IDE)：铁蛋白低+转铁蛋白饱和度<15%，Hb正常","缺铁性贫血期(IDA)：Hb降低","贫血严重度：轻度(Hb 90-正常下限)、中度(60-90)、重度(30-60)、极重度(<30)","病因分类：摄入不足型、吸收障碍型、慢性失血型、需求增加型"],"key_points":["病因治疗是根本：找到并去除缺铁原因(消化道肿瘤/溃疡/月经过多等)","补铁治疗：口服铁剂首选，无机铁(硫酸亚铁)胃肠反应大，有机铁(琥珀酸亚铁/多糖铁)耐受性好","剂量：元素铁150-200mg/d，分2-3次，空腹吸收好(胃肠反应大可餐中)","疗程：Hb正常后继续补铁3-6个月(补足储存铁)，或铁蛋白>50μg/L","口服不耐受/吸收障碍/急需纠正：静脉铁剂","饮食：富铁食物(红肉/动物肝脏/血制品)，维生素C促进吸收，茶咖啡抑制吸收(间隔1-2h)"],"drug_recommendations":["口服铁剂：硫酸亚铁0.3g tid(元素铁60mg/片)、琥珀酸亚铁0.1-0.2g tid、多糖铁复合物150mg qd-bid、富马酸亚铁0.2g tid","维生素C 0.2g tid：促进铁吸收(与铁剂同服)","静脉铁剂：蔗糖铁200mg+NS 100ml静滴(每周2-3次，总量按公式)、右旋糖酐铁(需皮试)、羧基麦芽糖铁750mg单次(最大1000mg)、异麦芽糖酐铁1000mg单次","补铁总量公式：需铁量(mg)=体重(kg)×(目标Hb-实际Hb)(g/L)×0.24+储存铁500mg","辅助治疗：维生素B12/叶酸(合并缺乏时)、促红素(肾性贫血/慢性病贫血)","病因治疗：消化道出血(抑酸/内镜/手术)、月经过多(妇科治疗)、钩虫病(驱虫)"],"non_pharmacological":["饮食调整：增加血红素铁(红肉/动物肝脏/血制品)，植物铁(菠菜/木耳)吸收率低需配维生素C","避免茶/咖啡/高钙食物与铁剂同服(间隔1-2h)","烹饪用铁锅(增加少量铁)","婴幼儿：及时添加富铁辅食(强化铁米粉/肉泥)，纯母乳喂养4-6月后补铁","孕妇：常规补铁(妊娠中晚期元素铁30-60mg/d)","老年人：注意消化道肿瘤筛查(缺铁性贫血是消化道肿瘤信号)"],"complications":["口服铁剂不良反应：恶心、呕吐、上腹痛、便秘/腹泻、黑便(正常，需与消化道出血鉴别)","静脉铁剂不良反应：过敏反应(皮疹/低血压/过敏性休克)、输注部位疼痛、头痛、关节痛、低血压","铁过载：长期过量补铁导致血色病(肝/心/胰腺损害)，监测铁蛋白","贫血性心脏病：严重长期贫血致心脏扩大/心衰，补铁后可恢复","生长发育迟缓：儿童长期缺铁影响认知和行为发育","异食癖：缺铁可致嗜冰/泥土/淀粉等，补铁后消失"],"monitoring":["补铁后5-10天：网织红细胞升高(疗效最早指标)","2周后：Hb开始上升，每2周复查","Hb正常后：继续补铁3-6个月，复查铁蛋白>50停药","口服铁剂4周无改善：重新评估诊断(诊断错误/未除病因/吸收障碍/依从性差/其他贫血)","静脉铁剂：输注中监测过敏反应，输注后复查血常规和铁代谢","病因随访：消化道出血/月经过多等病因治疗后复查"],"special_populations":["妊娠：中晚期常规补铁30-60mg/d元素铁，贫血者100-200mg/d，口服不耐受用静脉铁(蔗糖铁安全)","婴幼儿/儿童：按体重算剂量(元素铁2-3mg/kg/d)，及时添加辅食，筛查地中海贫血(南方地区)","老年人：缺铁性贫血必须排查消化道肿瘤(胃镜/肠镜)，不可单纯补铁","胃切除/乳糜泻：口服铁吸收差，首选静脉铁剂","慢性肾病：缺铁+促红素缺乏，静脉铁+促红素联合，目标铁蛋白200-500、转铁蛋白饱和度>20%"],"references":"中华医学会血液学分会. 缺铁性贫血诊疗指南(2024). 中华血液学杂志"},{"name":"类风湿关节炎诊断及治疗指南（2024）","category":"风湿免疫科","scope":"成人类风湿关节炎(RA)诊断和治疗。","diagnosis":["2010 ACR/EULAR分类标准：关节受累(1-5分)、血清学(RF/抗CCP 0-3分)、急性期反应物(CRP/ESR 0-1分)、症状持续时间(0-1分)，总分≥6分诊断RA","典型表现：对称性多关节炎，手足小关节为主，晨僵>30分钟，滑膜增厚/积液","实验室：RF阳性(70-80%)、抗CCP抗体阳性(特异性>95%)、CRP/ESR升高","影像学：X线(骨质疏松/关节间隙狭窄/骨侵蚀)、超声/核磁(滑膜炎/骨侵蚀更敏感)","排除其他：银屑病关节炎、强直性脊柱炎、骨关节炎、痛风、反应性关节炎、结缔组织病","关节外表现：类风湿结节、间质性肺病、心包炎、巩膜炎、血管炎、Felty综合征"],"staging":["疾病活动度：DAS28(>5.1高活动、3.2-5.1中活动、2.6-3.2低活动、<2.6缓解)、SDAI、CDAI","X线分期：I期(骨质疏松)、II期(骨质疏松+轻度骨侵蚀)、III期(明显骨侵蚀+关节间隙狭窄)、IV期(纤维/骨性强直)","功能分级：I级(正常活动)、II级(中度受限但生活自理)、III级(明显受限生活不能自理)、IV级(卧床/轮椅)","预后不良因素：抗CCP高滴度、RF高滴度、早期骨侵蚀、关节外表现、吸烟、HLA-DR4","缓解定义：DAS28<2.6或ACR/EULAR Boolean缓解(压痛关节≤1、肿胀关节≤1、CRP≤1、患者总体评估≤1)"],"key_points":["早期诊断早期治疗，目标治疗(treat-to-target)，目标缓解或低活动度","DMARDs是基础，确诊后尽早启动(首选甲氨蝶呤)","传统DMARDs单药不达标：加用生物制剂或JAK抑制剂(联合或转换)","糖皮质激素：桥接治疗(短期小剂量)，不长期单用","非甾体抗炎药(NSAIDs)：对症止痛，不改变病程","关节腔注射激素：单关节炎急性发作","康复锻炼：关节功能维持，避免废用","定期评估疾病活动度，每1-3个月调整方案"],"drug_recommendations":["传统DMARDs：甲氨蝶呤7.5-25mg/w(口服/皮下，首选，加叶酸5mg/w)、来氟米特10-20mg qd、柳氮磺吡啶1-3g/d、羟氯喹0.2g bid","生物制剂：TNF抑制剂(阿达木单抗40mg q2w、英夫利昔单抗3mg/kg 0/2/6周后q8w、依那西普25mg biw/50mg qw、戈利木单抗50mg qw)、IL-6抑制剂(托珠单抗8mg/kg q4w)、T细胞共刺激抑制剂(阿巴西普)、抗CD20(利妥昔单抗1g 0/2周，B细胞清除)","JAK抑制剂：托法替布5mg bid、巴瑞替尼2mg qd、乌帕替尼15mg qd(口服，注意感染/血栓/心血管风险)","糖皮质激素：泼尼松5-10mg qd桥接，或甲泼尼龙40-80mg iv×3天(重症)，尽快减停","NSAIDs：塞来昔布0.2g bid、双氯芬酸50mg tid、依托考昔60mg qd(注意胃肠/肾/心血管)","局部：关节腔注射曲安奈德/倍他米松，外用NSAIDs乳膏"],"non_pharmacological":["患者教育：疾病认知、用药依从性、自我管理","休息与运动平衡：急性期休息，缓解期功能锻炼","物理治疗：热疗、冷疗、经皮神经电刺激(TENS)、水疗","康复锻炼：关节活动度训练、肌力训练、有氧运动(游泳/散步/太极)","关节保护：避免过度使用小关节，使用辅助工具(开瓶器/加粗手柄)","戒烟：吸烟加重RA病情和骨侵蚀，必须戒烟","营养：均衡饮食，骨质疏松者补钙和维生素D","心理支持：慢性病抑郁焦虑常见"],"complications":["关节畸形：尺偏、天鹅颈、纽扣花、掌指关节半脱位，晚期功能丧失","间质性肺病：RA最常见关节外表现，干咳气短，HRCT评估，免疫抑制治疗","心血管疾病：RA患者冠心病/心衰风险增加，控制炎症+传统危险因素","骨质疏松：炎症+激素+活动少，双能X线评估，补钙维D+双膦酸盐","感染：DMARDs/生物制剂/JAK抑制剂免疫抑制，筛查结核乙肝，疫苗接种","恶性肿瘤：淋巴瘤风险轻度增加(与慢性炎症相关)，长期随访","药物不良反应：甲氨蝶呤(肝/肺/骨髓)、生物制剂(感染/结核)、JAK(血栓/心血管)"],"monitoring":["治疗初期：每1-3个月评估DAS28、CRP/ESR，调整方案","稳定期：每3-6个月评估","甲氨蝶呤：用药前查血常规、肝肾功、胸片、乙肝丙肝；用药后每1-3个月查血常规肝肾功","生物制剂：用药前筛查结核(PPD/IGRA)、乙肝、丙肝、胸片；用药后每3-6个月查血常规肝肾功","JAK抑制剂：用药前和用药中查血常规、血脂、肝酶、血栓/心血管风险","影像学：每年X线评估骨侵蚀进展，超声/核磁评估滑膜炎","合并症筛查：间质性肺病(HRCT)、心血管、骨质疏松"],"special_populations":["妊娠：甲氨蝶呤/来氟米特/利妥昔单抗禁用，羟氯喹/柳氮磺吡啶/硫唑嘌呤/TNF抑制剂(孕中晚期)可用，孕前3月停甲氨蝶呤，计划妊娠者提前调整","老年：注意感染风险，生物制剂/JAK抑制剂谨慎，合并症多，药物相互作用","合并间质性肺病：避免甲氨蝶呤(肺毒性)，选利妥昔单抗/阿巴西普，激素+免疫抑制剂","难治性RA：多药联合，评估依从性/诊断/合并症，考虑新药或临床试验","青少年特发性关节炎(JIA)：儿科风湿专科，治疗原则类似但剂量按体重"],"references":"中华医学会风湿病学分会. 类风湿关节炎诊断及治疗指南(2024). 中华风湿病学杂志"},{"name":"系统性红斑狼疮诊断及治疗指南（2024）","category":"风湿免疫科","scope":"成人系统性红斑狼疮(SLE)诊断和治疗。","diagnosis":["2019 EULAR/ACR分类标准：入围标准ANA≥1:80，附加标准(临床7项+免疫3项)总分≥10分诊断SLE","典型表现：面部蝶形红斑、盘状红斑、光过敏、口腔溃疡、关节炎、浆膜炎(胸膜炎/心包炎)、肾脏病变、神经病变、血液学异常、免疫学异常(抗dsDNA/抗Sm/抗磷脂)、ANA阳性","实验室：ANA阳性(>95%)、抗dsDNA(活动期)、抗Sm(特异性)、补体C3/C4降低(活动期)、抗磷脂抗体","肾脏评估：尿常规(蛋白尿/血尿/管型)、24h尿蛋白、肾穿刺活检(明确病理类型和活动度)","神经精神狼疮：头痛、癫痫、脑血管病、认知障碍、精神病，排除其他原因","排除其他：类风湿关节炎、干燥综合征、混合性结缔组织病、药物性狼疮、感染"],"staging":["疾病活动度：SLEDAI-2K评分(0-4无活动、5-9轻度、10-14中度、≥15重度)、BILAG","狼疮肾炎分型(I型轻微系膜、II系膜增生、III局灶增生、IV弥漫增生、V膜性、VI硬化)","器官受累：皮肤黏膜、肌肉骨骼、肾脏、神经、心血管、肺、血液、消化","预后不良因素：狼疮肾炎(尤其IV型)、神经精神狼疮、肺动脉高压、间质性肺病、抗磷脂综合征、男性、黑人","缓解定义：无临床活动+免疫稳定，药物缓解(用药中)和无药缓解"],"key_points":["早期诊断早期治疗，目标治疗，目标缓解或低活动度","羟氯喹是基础用药，所有SLE患者均应使用(除非禁忌)","糖皮质激素：根据活动度选择剂量，尽快减至最小维持(<7.5mg/d泼尼松)","免疫抑制剂：中重度活动加用(环磷酰胺/吗替麦考酚酯/硫唑嘌呤/他克莫司)","狼疮肾炎：诱导缓解(激素+吗替麦考酚酯/环磷酰胺)，维持治疗(吗替麦考酚酯/硫唑嘌呤)≥3年","生物制剂：贝利尤单抗(抗BLyS)、泰它西普(抗BLyS/APRIL)用于中重度活动","避免日晒，戒烟，预防感染，避孕(活动期)"],"drug_recommendations":["羟氯喹：0.2g bid(基础用药，所有患者，注意眼底检查每年)","糖皮质激素：轻度泼尼松5-15mg/d，中度15-30mg/d，重度0.5-1mg/kg/d，冲击甲泼尼龙0.5-1g/d×3天(重症)，渐减至<7.5mg/d维持","免疫抑制剂：吗替麦考酚酯1-2g/d分2次(狼疮肾炎首选诱导/维持)、环磷酰胺0.5-1g/m²每月冲击×6次(重症诱导)或50mg bid口服、硫唑嘌呤50-100mg/d(维持)、他克莫司2-3mg/d分2次(膜性狼疮/V型)、环孢素A 3-5mg/kg/d分2次","生物制剂：贝利尤单抗10mg/kg 0/2/4周后每月1次、泰它西普160mg每周皮下、利妥昔单抗1g 0/2周(难治性/血细胞减少)","抗疟药：羟氯喹(上述)","对症：NSAIDs(关节痛)、降压(狼疮肾炎高血压ACEI/ARB)、抗凝(抗磷脂综合征)","补钙+维生素D+双膦酸盐(激素治疗预防骨质疏松)"],"non_pharmacological":["避光：避免日晒，防晒霜(SPF≥30)、遮阳伞、长袖衣物","戒烟：吸烟加重病情和皮肤损害，降低羟氯喹疗效","休息与运动：急性期休息，缓解期适度运动(散步/游泳/太极)","饮食：均衡，光敏性食物(芹菜/香菜/无花果)适量，肾损害限盐限蛋白","避孕：活动期避免妊娠，用避孕套或含孕激素IUD，避免含雌激素避孕药(抗磷脂阳性禁用)","疫苗接种：流感、肺炎球菌、HPV(免疫抑制前接种，避免活疫苗)","心理支持：慢性病容貌损害，抑郁焦虑常见","定期随访，自我监测病情变化"],"complications":["狼疮肾炎：最常见严重并发症，蛋白尿/血尿/肾功不全，肾穿刺指导治疗，可进展至ESRD","神经精神狼疮：癫痫/脑血管病/认知障碍/精神病，激素冲击+免疫抑制剂，排除感染","抗磷脂综合征：血栓/反复流产/血小板减少，抗凝治疗(华法林目标INR2-3)","肺动脉高压：预后差，超声筛查，靶向药物+免疫抑制","间质性肺病/肺泡出血：干咳气短，HRCT，激素+免疫抑制剂，肺泡出血危及生命","心血管：早发动脉粥样硬化/冠心病/心包炎/心肌炎，控制炎症+危险因素","感染：免疫抑制致感染风险高(结核/真菌/病毒)，是SLE主要死因之一","药物不良反应：激素(骨质疏松/高血糖/感染)、环磷酰胺(骨髓抑制/出血性膀胱炎/性腺抑制/致癌)、羟氯喹(眼底/心肌)"],"monitoring":["活动期：每2-4周查血常规、尿常规、肝肾功、补体、抗dsDNA、CRP/ESR","稳定期：每1-3个月复查","狼疮肾炎：尿常规、24h尿蛋白、肾功能每2-4周，肾穿刺指导治疗","羟氯喹：用药前和每年眼底检查(视野+OCT)","免疫抑制剂：血常规、肝肾功每1-4周(初期)，之后每1-3月","妊娠计划：病情稳定≥6月，停用致畸药(吗替麦考酚酯/环磷酰胺/甲氨蝶呤)≥3-6月，羟氯喹/硫唑嘌呤/激素可继续","骨密度：长期激素者每年双能X线"],"special_populations":["妊娠：病情稳定≥6月，无重要脏器损害，停用致畸药；孕期用羟氯喹+小剂量激素+硫唑嘌呤；抗磷脂阳性者低分子肝素+小剂量阿司匹林预防流产/血栓；孕期病情活动可激素加量","儿童SLE：起病急重，多系统受累，肾损害多见，治疗原则相同剂量按体重，注意生长发育","老年SLE：起病隐匿，病情轻，干燥/关节/肺表现多，注意合并肿瘤和感染","男性SLE：少见，病情重，肾损害和神经系统受累多，预后差","药物性狼疮：停用可疑药物(肼苯哒嗪/普鲁卡因胺/异烟肼/米诺环素)，多可缓解，抗组蛋白抗体阳性"],"references":"中华医学会风湿病学分会. 系统性红斑狼疮诊断及治疗指南(2024). 中华风湿病学杂志"},{"name":"肿瘤化疗所致恶心呕吐全程管理指南（2024）","category":"肿瘤科","scope":"肿瘤化疗所致恶心呕吐(CINV)的预防和处理。","diagnosis":["CINV分类：急性(化疗后24h内)、延迟性(24h后，可持续5-7天)、预期性(化疗前，条件反射)、爆发性(预防后仍发生)、难治性(既往预防失败)","致吐风险分级：高度(>90%，如顺铂/AC方案)、中度(30-90%，如卡铂/奥沙利铂/多柔比星)、低度(10-30%，如紫杉醇/多西他赛)、极低(<10%，如贝伐珠单抗/靶向药)","危险因素：女性、年龄<50岁、既往CINV史、晕动症、焦虑、妊娠呕吐史、酒精摄入少","评估：MASCC止吐评价工具，记录恶心呕吐发生时间、频率、严重度、对生活影响","鉴别：肠梗阻、脑转移、电解质紊乱(高钙/低钠)、尿毒症、阿片类药物、感染所致呕吐"],"staging":["致吐风险分级(上述)","CINV严重度：轻度(1-2次/24h)、中度(3-5次)、重度(6-10次)、极重度(>10次需住院)","恶心程度：VAS评分0-10分","功能影响：轻度(不影响进食活动)、中度(影响进食但能下床)、重度(不能进食需卧床/静脉补液)","爆发性呕吐：预防方案下仍发生，需解救治疗","难治性：既往多个周期预防失败"],"key_points":["预防为主，根据致吐风险分级选择止吐方案","高致吐：三联(5-HT3受体拮抗剂+地塞米松+NK1受体拮抗剂)，必要时加奥氮平(四联)","中致吐：5-HT3+地塞米松，高风险者加NK1或奥氮平","低致吐：地塞米松或胃复安/丙氯拉嗪","极低致吐：不常规预防，必要时对症","延迟性呕吐：地塞米松+NK1(高致吐)，5-HT3对延迟性效果差","预期性呕吐：苯二氮䓬类(阿普唑仑)+行为干预(放松/催眠)","爆发性：解救止吐(不同机制药物联合)+静脉补液，下一周期加强预防"],"drug_recommendations":["5-HT3受体拮抗剂：昂丹司琼8mg iv/po(化疗前30min)、格拉司琼3mg iv、帕洛诺司琼0.25mg iv(长效，对急性和延迟性均好)、托烷司琼5mg iv","NK1受体拮抗剂：阿瑞匹坦125mg d1(化疗前1h)+80mg d2-3 qd、福沙匹坦150mg iv d1(替代阿瑞匹坦d1)、奈妥匹坦(与帕洛诺司琼复方)","糖皮质激素：地塞米松12mg d1(与NK1联用时减至8mg)+8mg d2-4(高致吐延迟性)，中致吐d1 8mg","奥氮平：5-10mg qn d1-4(高致吐四联，注意嗜睡/体位性低血压)","多巴胺受体拮抗剂：胃复安10mg iv/po q6h、丙氯拉嗪10mg iv q6h、氟哌啶醇1-2mg iv(注意锥体外系反应，苯海拉明对抗)","苯二氮䓬类：阿普唑仑0.5-1mg q8h(预期性呕吐)、劳拉西泮0.5-1mg iv/po(焦虑/预期性)","爆发性解救：联合不同机制(如胃复安+苯海拉明+地塞米松)，或奥氮平5-10mg，静脉补液纠正脱水电解质"],"non_pharmacological":["饮食：少量多餐，清淡易消化，避免油腻辛辣过甜，化疗前后2h避免大量进食","环境：避免异味(油烟/香水)，通风，室温适宜","穴位按压：内关穴(P6)，可配合穴位电刺激","行为干预：放松训练、音乐疗法、引导想象、催眠(预期性呕吐有效)","生姜：姜片/姜茶(轻度恶心辅助)","补液：呕吐明显时静脉补液纠正脱水和电解质紊乱","口腔护理：呕吐后漱口，避免口腔异味刺激","心理支持：焦虑加重CINV，认知行为治疗"],"complications":["脱水/电解质紊乱：呕吐致低钾低钠低氯、代谢性碱中毒，静脉补液纠正","营养不良：长期CINV致体重下降、白蛋白降低，营养支持(肠内/肠外)","食管黏膜撕裂(Mallory-Weiss)：剧烈呕吐致食管贲门撕裂出血，呕血黑便，禁食+抑酸+止血","误吸/吸入性肺炎：意识障碍者呕吐误吸，侧卧位，吸引，抗感染","化疗药物外渗/延迟：严重呕吐影响化疗依从性，加强预防","预期性呕吐：条件反射，后续化疗前发生，苯二氮䓬+行为干预","生活质量下降：影响治疗信心和日常功能"],"monitoring":["化疗期间：每4-8h评估恶心呕吐次数、严重度、进食情况、脱水征象","记录呕吐日记：时间、次数、诱因、止吐药效果","实验室：电解质(钾钠氯)、肾功能、白蛋白","评估止吐方案效果，下一周期调整(爆发性者升级预防)","评估药物不良反应：便秘(5-HT3)、头痛、呃逆(地塞米松)、嗜睡(奥氮平)、锥体外系(胃复安/丙氯拉嗪)","患者教育：CINV预防重要性，居家呕吐处理和就医指征"],"special_populations":["老年：注意药物相互作用和不良反应，5-HT3 QT延长(尤其昂丹司琼)，奥氮平嗜睡跌倒，简化方案","儿童：按体重算剂量，昂丹司琼0.15mg/kg，阿瑞匹坦按体重，家长教育","妊娠相关肿瘤：避免致畸止吐药，用胃复安/昂丹司琼(相对安全)，多学科","脑转移：呕吐可能为颅内压增高，甘露醇+激素，鉴别CINV","肠梗阻：肿瘤致肠梗阻呕吐，胃肠减压+生长抑素，止吐药效果差","阿片类药物所致恶心呕吐：胃复安/昂丹司琼，耐受后多可缓解"],"references":"中国抗癌协会肿瘤临床化疗专业委员会. 肿瘤化疗所致恶心呕吐全程管理指南(2024). 中国肿瘤临床"},{"name":"癌症疼痛诊疗规范（2024年版）","category":"肿瘤科","scope":"癌症患者疼痛评估和治疗(癌痛三阶梯止痛)。","diagnosis":["癌痛评估：常规、量化、全面、动态评估","疼痛强度：数字评分法(NRS 0-10)，0无痛，1-3轻度，4-6中度，7-10重度","疼痛性质：伤害感受性(躯体痛/内脏痛)、神经病理性(烧灼/电击/麻木)、混合性","疼痛病因：肿瘤直接侵犯(70%)、抗肿瘤治疗相关(手术/化疗/放疗)、合并症(非癌痛)","全面评估：疼痛部位、性质、强度、时间、加重缓解因素、既往止痛史、心理状态、阿片类物质使用史","动态评估：止痛治疗后定期复评(口服1h、静脉15-30min)，调整剂量","爆发痛：基础疼痛控制好后突发剧痛，需解救剂量"],"staging":["WHO三阶梯：轻度(非阿片类±辅助)、中度(弱阿片类±非阿片±辅助)、重度(强阿片类±非阿片±辅助)","目前趋势：弱化二阶梯，中度疼痛可直接用小剂量强阿片类","疼痛控制目标：NRS≤3分(无痛或轻度)，24h爆发痛≤2-3次，解救药≤2-3次/d","神经病理性疼痛：阿片类+辅助药(抗惊厥/抗抑郁)","内脏痛：阿片类+抗胆碱能/糖皮质激素","骨转移痛：阿片类+NSAIDs+双膦酸盐/地诺单抗+放疗"],"key_points":["口服给药首选(简单方便经济)，不能口服选透皮贴/直肠/静脉/皮下","按阶梯给药(轻度NSAIDs，中重度阿片类)","按时给药(缓释制剂维持基础镇痛，不是按需)","个体化给药(剂量滴定至有效，无天花板效应)","注意细节(不良反应预防和处理)","阿片类是中重度癌痛首选，剂量无上限(以镇痛和耐受为度)","爆发痛用即释阿片类解救(剂量为日剂量的10-15%)","辅助用药：神经病理性加抗惊厥/抗抑郁，骨转移加双膦酸盐，内脏痛加激素/抗胆碱能"],"drug_recommendations":["非阿片类：对乙酰氨基酚0.5-1g q6h(最大4g/d，注意肝毒性)、NSAIDs(塞来昔布0.2g bid、双氯芬酸50mg tid，注意胃肠/肾/心血管，有天花板)","弱阿片类：可待因15-60mg q4-6h、曲马多50-100mg q4-6h(最大400mg/d)","强阿片类即释(滴定)：吗啡5-15mg po q4h(未耐受者起始5mg)，或吗啡2-5mg iv q10-15min滴定","强阿片类缓释(维持)：吗啡缓释片10-30mg q12h、羟考酮缓释片5-10mg q12h、芬太尼透皮贴12-25μg/h q72h(阿片耐受者，不能用于未耐受/急性痛)","爆发痛解救：即释吗啡(日剂量10-15%)，或芬太尼舌下/鼻喷雾","辅助药神经病理性：加巴喷丁0.3g tid起渐加、普瑞巴林75mg bid、阿米替林12.5-25mg qn、度洛西汀30-60mg qd","辅助药骨转移：唑来膦酸4mg iv每月、地诺单抗120mg皮下每月、放疗","辅助药内脏痛/脑水肿：地塞米松4-16mg/d","阿片不良反应预防：便秘(缓泻剂常规预防，如乳果糖15ml bid/聚乙二醇)、恶心(胃复安，耐受后多缓解)、嗜睡(耐受)、呼吸抑制(罕见，纳洛酮解救)"],"non_pharmacological":["患者教育：癌痛可控制，阿片类成瘾罕见(癌痛患者)，按时用药不按需","心理干预：认知行为治疗、放松训练、音乐疗法、支持性心理治疗","物理治疗：热敷/冷敷、按摩、经皮神经电刺激(TENS)、针灸","介入治疗：神经阻滞(腹腔神经丛阻滞治胰腺癌痛)、鞘内药物输注系统、射频消融、椎体成形术(骨转移)","放疗：骨转移痛、脑转移痛局部放疗有效","社会支持：家属陪伴、姑息治疗团队、志愿者","营养支持：改善一般状况","宗教/精神支持(患者有需求时)"],"complications":["阿片类便秘：最常见，不会耐受，常规预防(缓泻剂+饮食+运动)，严重者灌肠","阿片类恶心呕吐：用药初期，胃复安，1-2周耐受","阿片类嗜睡/头晕：初期，耐受，避免驾驶","阿片类呼吸抑制：罕见(缓慢滴定)，嗜睡先于呼吸抑制，纳洛酮解救(0.4mg iv稀释慢推)","阿片类耐受/躯体依赖：正常药理现象，不是成瘾，逐渐减量避免戒断","成瘾(心理依赖)：癌痛患者罕见(<0.1%)，不必因担心成瘾拒绝止痛","NSAIDs不良反应：胃肠溃疡出血、肾损伤、心血管事件、血小板功能，有天花板效应不超量","镇痛不全：评估疼痛性质，调整剂量/加辅助药/介入治疗"],"monitoring":["止痛治疗后：口服1h、静脉15-30min复评疼痛强度和不良反应","稳定期：每24h评估，调整剂量","便秘评估和预防：每次随访","肾功能/肝功能：NSAIDs和阿片类(肾功能不全吗啡代谢产物蓄积，换芬太尼/羟考酮)","镇静程度：RASS评分，过度镇静提示剂量过大","爆发痛次数和解救药使用：>3次/d提示基础剂量不足，增加缓释剂量","患者依从性和用药正确性(缓释片不可掰开/咀嚼)","生活质量和功能状态评估"],"special_populations":["老年：肝肾功能减退，小剂量起始，缓慢滴定，注意便秘和认知，芬太尼透皮贴方便(依从性好)","肾功能不全：避免吗啡(代谢产物蓄积致肌阵挛/嗜睡)，选芬太尼/羟考酮/美沙酮","肝功能不全：阿片类清除减少，小剂量，避免对乙酰氨基酚(肝毒性)","儿童：按体重算剂量，吗啡0.2-0.5mg/kg po q4h，家长教育","临终关怀：舒适优先，阿片类剂量可快速滴定，缓解呼吸困难也有效","既往物质使用障碍：多学科管理，不拒绝止痛，可能需更高剂量，监测非医疗使用"],"references":"国家卫生健康委员会. 癌症疼痛诊疗规范(2024年版)"},{"name":"急性呼吸窘迫综合征诊疗指南（2024）","category":"重症医学科","scope":"成人急性呼吸窘迫综合征(ARDS)诊断和治疗。","diagnosis":["柏林定义：1周内新发/恶化呼吸系统症状；胸部影像(胸片/CT)双肺浸润不能完全用积液/肺不张/结节解释；呼吸衰竭不能用心衰/液体过负荷解释(无危险因素时需客观评估如心超)；氧合障碍(PEEP/CPAP≥5cmH2O时PaO2/FiO2≤300)","危险因素：肺炎(最常见)、脓毒症、误吸、胰腺炎、创伤、输血、烧伤、药物中毒、溺水","轻度：PaO2/FiO2 200-300(PEEP≥5)；中度：100-200；重度：<100","辅助检查：血气分析(低氧血症/呼吸性酸中毒)、胸片/CT(双肺浸润/磨玻璃/实变)、心超(排除心源性肺水肿)、B型脑钠肽(鉴别心衰)、炎症指标","鉴别：心源性肺水肿、肺炎(可致ARDS)、弥漫性肺泡出血、急性间质性肺炎、肺血管炎","肺损伤生物标志物：KL-6、SP-D、IL-6、ANG-2(研究阶段)"],"staging":["柏林分级：轻度(PaO2/FiO2 200-300)、中度(100-200)、重度(<100)","病程分期：渗出期(1-7天，肺水肿/炎症)、增生期(7-21天，Ⅱ型肺泡细胞增生/纤维化开始)、纤维化期(>21天，肺纤维化/囊性变)","预后评估：APACHE II、SOFA评分、肺损伤评分(LIS)","高危因素：直接肺损伤(肺炎/误吸/肺挫伤)、间接肺损伤(脓毒症/胰腺炎/输血/创伤)","机械通气参数：潮气量、PEEP、平台压、驱动压、呼吸频率","脱机评估：自主呼吸试验(SBT)、浅快呼吸指数"],"key_points":["原发病治疗：控制感染(抗生素+感染灶引流)、纠正休克、停止损伤因素","肺保护性通气：小潮气量(6ml/kg理想体重)、平台压≤30cmH2O、限制驱动压(ΔP≤15)","PEEP滴定：根据FiO2-PEEP表或食道压，中重度用较高PEEP","俯卧位通气：中重度ARDS(PaO2/FiO2<150)，每天≥12小时","液体管理：保守液体策略(稳定期)，避免液体过负荷","神经肌肉阻滞剂：中重度ARDS早期短期使用(≤48h)","ECMO：重度ARDS常规治疗无效(PaO2/FiO2<80持续>6h或pH<7.25)，VV-ECMO","避免高氧(PaO2 55-80/SpO2 88-95%)"],"drug_recommendations":["抗菌药物：脓毒症/肺炎相关ARDS，经验性广谱抗生素(覆盖革兰阴性+阳性+非典型)，根据病原学降阶梯","糖皮质激素：中重度ARDS早期(72h内)地塞米松20mg qd×5天→10mg×5天→5mg×3天，或甲泼尼龙1mg/kg/d(争议，部分研究获益)","神经肌肉阻滞剂：顺阿曲库铵0.1-0.2mg/kg负荷后0.1-0.3mg/kg/min泵入，中重度ARDS早期≤48h","血管活性药：脓毒症休克去甲肾上腺素0.05-1μg/kg/min维持MAP≥65","镇静镇痛：咪达唑仑/丙泊酚+芬太尼/瑞芬太尼，目标RASS -2至-4(俯卧位/人机不同步更深)","支气管扩张剂：合并支气管痉挛时雾化沙丁胺醇/异丙托溴铵","抗凝：预防深静脉血栓(低分子肝素)，除非禁忌","吸入肺血管扩张剂：一氧化氮(NO)或前列环素吸入(难治性低氧，不改善生存)"],"non_pharmacological":["机械通气：有创通气首选，小潮气量6ml/kg理想体重，平台压≤30，PEEP滴定","高流量氧疗/无创通气：轻度ARDS可尝试，密切监测，恶化及时插管","俯卧位通气：中重度(PaO2/FiO2<150)，每天≥12h，注意管路安全和压疮","肺复张：控制性肺膨胀(30-40cmH2O×30-40s)或PEEP递增法，血流动力学不稳定慎用","保守液体策略：稳定期限制液体(入量≤出量)，利尿剂(液体过负荷时)","ECMO：VV-ECMO(重度呼吸衰竭)，中心建立，抗凝管理","营养支持：肠内营养优先(48h内开始)，允许性低热卡(初期)，蛋白1.2-2g/kg/d","气道管理：密闭式吸痰，避免脱开PEEP，声门下吸引"],"complications":["呼吸机相关肺损伤(VILI)：气压伤/容积伤/萎陷伤/生物伤，小潮气量+限制平台压预防","呼吸机相关肺炎(VAP)：抬高床头30-45°、每日唤醒评估脱机、口腔护理、声门下吸引","气压伤：气胸/纵隔气肿/皮下气肿，胸腔闭式引流","深静脉血栓/肺栓塞：常规预防(低分子肝素+气压治疗)","应激性溃疡：PPI/H2RA预防，注意增加肺炎风险","ICU获得性肌无力：早期活动、避免过度镇静和神经肌肉阻滞剂、营养支持","肺纤维化：晚期ARDS，激素(争议)、康复，预后差","多器官功能衰竭：肾(血液滤过)、肝、心、凝血(DIC)，综合支持"],"monitoring":["持续：心电、血压(有创)、血氧、呼吸频率、潮气量、气道压(平台压/PEEP/驱动压)、ETCO2","血气分析：每4-8h或参数调整后，评估氧合和通气","胸片/CT：每日或病情变化时，评估肺部病变和导管位置","血流动力学：PiCCO/心超评估容量和心功能，指导液体管理","镇静深度：RASS评分，每4h评估","神经肌肉阻滞：TOF监测(四个成串刺激，目标1-2/4)","器官功能：肾功能(尿量/肌酐)、肝功能、凝血、乳酸、炎症指标","每日唤醒和脱机评估：SBT( T管/PSV)，浅快呼吸指数<105预测脱机成功"],"special_populations":["老年：基础病多，预后差，肺保护性通气同样适用，注意容量和肾功能","免疫低下：感染病原特殊(真菌/肺孢子菌/病毒)，积极病原学检查，覆盖特殊病原","创伤相关ARDS：处理原发病(骨折固定/颅脑损伤)，注意容量和凝血病","妊娠：ARDS少见但危重，左侧卧位，氧合目标更高(SpO2≥95)，必要时终止妊娠","儿童：儿科ARDS(PARDS)定义略有不同，小潮气量3-6ml/kg，俯卧位适用","肥胖：理想体重算潮气量，较高PEEP，注意腹压影响呼吸"],"references":"中华医学会重症医学分会. 急性呼吸窘迫综合征诊疗指南(2024). 中华内科杂志"},{"name":"ICU成人疼痛、躁动、谵妄管理指南（2024）","category":"重症医学科","scope":"ICU成人患者疼痛、躁动和谵妄(PAD)评估和管理。","diagnosis":["疼痛评估：能交流者用NRS(0-10)，不能交流者用行为疼痛量表(BPS)或重症疼痛观察工具(CPOT)","躁动评估：RASS评分(+4攻击到-5不可唤醒)，目标轻度镇静(-2至0)","谵妄评估：CAM-ICU或ICDSC，每日评估，分活动增多型/活动减少型/混合型","危险因素：疼痛、睡眠剥夺、约束、机械通气、镇静药(苯二氮䓬)、感染、代谢紊乱、老年、痴呆、酒精戒断","睡眠评估：ICU睡眠质量差，主观/客观评估(脑电双频指数BIS/脑电)","鉴别：疼痛、躁动、谵妄、癫痫、脑器质性病变、药物不良反应、戒断综合征"],"staging":["疼痛：轻度(NRS1-3)、中度(4-6)、重度(7-10)","镇静深度(RASS)：+4攻击、+3非常躁动、+2躁动、+1不安、0清醒平静、-1嗜睡、-2轻度镇静、-3中度镇静、-4深度镇静、-5不可唤醒","谵妄：CAM-ICU阳性(意识改变+注意力不集中+思维紊乱+意识水平改变)","镇静目标：常规-2至0(清醒镇静)，特殊情况(ARDS/颅高压/难治性休克)更深(-3至-4)","镇痛优先：先评估镇痛，镇静前先镇痛","每日唤醒：中断镇静，评估神经功能和脱机可能性"],"key_points":["镇痛优先：先镇痛再镇静，阿片类是ICU镇痛首选","目标导向镇静：RASS目标-2至0，每日评估调整","最小化镇静：避免过度镇静，每日唤醒，缩短机械通气和ICU住院","非苯二氮䓬类优先：丙泊酚或右美托咪定优于苯二氮䓬(减少谵妄)","谵妄预防：非药物干预为主(早期活动、睡眠改善、定向力、减少约束)","药物治疗谵妄：氟哌啶醇或非典型抗精神病药(喹硫平)，不常规预防","多模式镇痛：阿片类+非阿片(对乙酰氨基酚/NSAIDs/区域阻滞)，减少阿片用量","睡眠改善：集中护理、减少夜间干扰、耳塞眼罩、模拟昼夜"],"drug_recommendations":["镇痛阿片类：芬太尼0.3-0.5μg/kg负荷后0.7-10μg/kg/h泵入(短效)、吗啡0.05-0.1mg/kg负荷后0.07-0.28mg/kg/h、氢吗啡酮0.2-0.6mg/h、瑞芬太尼0.5-8μg/kg/h(超短效，肝外代谢)","非阿片镇痛：对乙酰氨基酚1g q6h(肝功能正常)、NSAIDs(短期，注意肾/胃肠/出血)、氯胺酮0.1-0.3mg/kg/h(辅助镇痛，减少阿片)、区域阻滞(硬膜外/神经阻滞，术后/创伤)","镇静丙泊酚：0.3-0.5mg/kg负荷后5-50μg/kg/min泵入，注意高脂血症/丙泊酚输注综合征","镇静右美托咪定：0.2-0.7μg/kg/h(可不用负荷或0.5-1μg/kg 10min)，可唤醒，减少谵妄，注意心动过缓/低血压","苯二氮䓬类：咪达唑仑0.01-0.1mg/kg负荷后0.02-0.1mg/kg/h(酒精戒断/癫痫/难治性躁动，不常规首选)、劳拉西泮0.02-0.06mg/kg q2-6h","谵妄药物：氟哌啶醇0.5-2mg iv q4-6h(注意QT延长)、喹硫平12.5-100mg qn(非典型，活动增多型)、右美托咪定(辅助)","神经肌肉阻滞剂：顺阿曲库铵(特定指征ARDS/颅高压/人机不同步，深度镇静+镇痛基础上)"],"non_pharmacological":["疼痛非药物：放松训练、音乐疗法、冷敷热敷、体位调整、分散注意力","躁动非药物：解释安慰、家属陪伴、环境优化(减少噪音光线)、早期活动、避免约束(必要时用最小约束)","谵妄预防ABCDEF集束：A唤醒协调、B自主呼吸试验、C镇痛镇静选择、D谵妄评估管理、E早期活动、F家属参与","睡眠改善：集中护理操作、夜间减少干扰、耳塞眼罩、模拟昼夜节律(白天亮灯夜间暗)、避免白天过度睡眠","早期活动：病情稳定后被动/主动活动，减少ICU获得性肌无力和谵妄","定向力：时钟日历、眼镜助听器、家属照片、频繁交流","减少医源性刺激：尽量减少有创操作，合理约束，避免不必要的报警噪音"],"complications":["过度镇静：延迟脱机、ICU获得性肌无力、谵妄、深静脉血栓、压疮","镇痛不足：躁动、人机不同步、应激反应(高血糖/高血压/心动过速)、创伤后应激障碍(PTSD)","谵妄：延长机械通气和ICU住院、增加死亡率、长期认知功能下降","阿片类不良反应：呼吸抑制(机械通气者可控)、便秘、肠梗阻、耐受/依赖、戒断(长期用后突然停)","丙泊酚输注综合征：长期大剂量(>4mg/kg/h>48h)致代谢性酸中毒/横纹肌溶解/心衰/死亡，监测肌酸激酶/乳酸","苯二氮䓬类：谵妄风险、呼吸抑制、耐受戒断、老年人跌倒","氟哌啶醇：QT延长/尖端扭转型室速，监测QTc<500ms","神经肌肉阻滞剂：长期用致肌无力，需深度镇静+镇痛，监测TOF"],"monitoring":["疼痛：每2-4h或操作前后评估(NRS/BPS/CPOT)","镇静：每2-4h评估RASS，调整药物维持目标","谵妄：每日评估CAM-ICU/ICDSC，至少每班一次","镇静深度客观：BIS(40-60深度镇静)或脑电监测(难治性镇静/神经肌肉阻滞时)","生命体征：血压、心率、血氧、呼吸(药物影响)","药物不良反应：便秘、意识状态、QT间期(氟哌啶醇)、甘油三酯(丙泊酚)、乳酸/肌酸激酶(丙泊酚综合征)","每日唤醒：中断镇静，评估神经功能、脱机可能性、药物需求","戒断评估：长期阿片/苯二氮䓬逐渐减量，评估戒断症状(焦虑/出汗/心动过速/震颤)"],"special_populations":["老年：谵妄风险高，避免苯二氮䓬，小剂量起始，注意药物蓄积和认知","慢性疼痛/阿片耐受者：基础阿片需求高，按换算剂量调整，避免戒断","酒精/药物依赖：戒断风险，苯二氮䓬类预防酒精戒断(CIWA-Ar评分指导)，阿片替代","颅脑损伤：镇静镇痛不影响神经评估，每日唤醒，避免颅内压升高，丙泊酚/芬太尼常用","老年痴呆/认知障碍：谵妄风险极高，非药物预防为主，小剂量抗精神病药","肾功能不全：避免吗啡(代谢产物蓄积)，选芬太尼/瑞芬太尼/舒芬太尼","肝功能不全：药物清除减慢，小剂量，避免劳拉西泮(溶剂丙二醇毒性)"],"references":"中华医学会重症医学分会. ICU成人疼痛、躁动、谵妄管理指南(2024). 中华内科杂志"},{"name":"中国银屑病诊疗指南（2024）","category":"皮肤科","scope":"成人和儿童银屑病(牛皮癣)诊断和治疗。","diagnosis":["典型表现：红色丘疹/斑块，上覆银白色鳞屑，边界清楚，刮除鳞屑有薄膜现象和点状出血(Auspitz征)","好发部位：头皮、四肢伸侧(肘膝)、腰骶部，对称分布","特殊类型：点滴状(链球菌感染后，儿童青少年)、脓疱型(泛发性/掌跖)、红皮病型、关节病型(银屑病关节炎)","甲银屑病：甲凹点、甲剥离、甲下角化过度、油滴征","同形反应(Koebner)：外伤部位出现皮损，活动期常见","组织病理：角化过度伴角化不全、棘层肥厚、真皮乳头水肿、毛细血管扩张、Munro微脓肿","鉴别：脂溢性皮炎、玫瑰糠疹、扁平苔藓、体癣、副银屑病、湿疹","银屑病关节炎：炎性关节痛/肿胀，远端指间关节受累，腊肠指/趾，影像学骨侵蚀/骨赘"],"staging":["严重程度：轻度(BSA<3%或PASI<10)、中度(BSA 3-10%或PASI 10-20)、重度(BSA>10%或PASI>20)","BSA：体表面积受累(手掌法，患者手掌=1%BSA)","PASI：银屑病面积和严重度指数(0-72)，评估红斑/浸润/鳞屑和面积","DLQI：皮肤病生活质量指数(0-30)，>10提示严重影响生活","疾病分期：进行期(新疹不断/同形反应)、静止期(稳定)、消退期(减少变淡)","特殊类型严重度：泛发性脓疱型/红皮病型为重症，需系统治疗","关节病型：关节活动度、影像学、炎症指标"],"key_points":["治疗目标：控制皮损，提高生活质量，减少复发，避免不良反应","轻度：外用药物为主(糖皮质激素+维生素D3衍生物)","中重度：系统治疗(甲氨蝶呤/阿维A/环孢素)或生物制剂","生物制剂是中重度银屑病重大进展：TNF抑制剂、IL-17抑制剂、IL-23抑制剂","银屑病关节炎：甲氨蝶呤或生物制剂( TNF/IL-17/IL-23抑制剂)","避免诱因：感染(链球菌)、外伤、精神紧张、饮酒、某些药物(β阻滞剂/锂剂/NSAIDs/抗疟药)","长期管理：慢性病，定期随访，心理支持"],"drug_recommendations":["外用糖皮质激素：弱效(氢化可的松)用于面部/皱褶，中效(曲安奈德)躯干四肢，强效(卤米松/氯倍他索)掌跖/肥厚皮损，连续不超过2-4周","外用维生素D3衍生物：卡泊三醇软膏0.005% bid(非面部)、他卡西醇软膏(面部可用)，与激素交替/联合","外用复方：卡泊三醇倍他米松凝胶/软膏qd(方便，依从性好)","外用钙调磷酸酶抑制剂：他克莫司软膏0.03-0.1%、吡美莫司乳膏1%(面部/皱褶/生殖器，无激素副作用)","系统甲氨蝶呤：7.5-25mg/w(口服/皮下)，加叶酸5mg/w，监测肝肾功血常规","系统阿维A：0.3-0.5mg/kg/d(脓疱型可0.5-1mg/kg)，致畸(育龄期避孕)，监测血脂肝功","系统环孢素：2.5-5mg/kg/d分2次，短期(≤1-2年)，监测肾功血压","生物制剂TNF抑制剂：阿达木单抗40mg q2w、英夫利昔单抗5mg/kg 0/2/6周后q8w、依那西普50mg qw","生物制剂IL-17抑制剂：司库奇尤单抗300mg 0/1/2/3/4周后q4w、依奇珠单抗80mg 0/2周后q4w、布罗利尤单抗","生物制剂IL-23抑制剂：古塞奇尤单抗200mg 0/4周后q8w、替拉珠单抗、瑞莎珠单抗","光疗：窄谱UVB(NB-UVB)每周2-3次，PUVA(中重度)"],"non_pharmacological":["患者教育：慢性病不传染，治疗可控制，避免过度焦虑","避免诱因：预防上呼吸道感染(链球菌诱发点滴状)，避免外伤(同形反应)，避免精神紧张熬夜","饮食：均衡，避免饮酒(加重)，肥胖者减重(改善疗效)，戒烟","皮肤护理：保湿润肤剂(每天2次)，温和清洁，避免热水烫洗和搔抓","光疗：NB-UVB门诊治疗，注意保护眼睛和生殖器","温泉浴/海水浴：部分患者有效，辅助治疗","心理支持：容貌影响致抑郁焦虑，认知行为治疗，病友支持","避免自行使用偏方(含激素/重金属，致红皮病型/脓疱型转化)"],"complications":["银屑病关节炎：约30%患者，关节肿痛畸形，甲银屑病患者风险高，早期风湿科会诊","代谢综合征：银屑病患者肥胖/高血压/高血糖/高血脂风险高，心血管病风险增加，综合管理","心理问题：抑郁焦虑自杀风险增加，心理评估和干预","药物不良反应：激素(皮肤萎缩/毛细血管扩张/反跳)、甲氨蝶呤(肝纤维化)、阿维A(致畸/血脂升高/皮肤干燥)、环孢素(肾毒性/高血压)、生物制剂(感染/结核)","红皮病型/脓疱型转化：不规范治疗(突然停激素/刺激性外用药)可诱发，重症需住院","感染：生物制剂增加结核/真菌/细菌感染风险，用药前筛查"],"monitoring":["外用治疗：每2-4周评估皮损，调整方案，激素使用时间和部位","系统治疗前：血常规、肝肾功、血脂、乙肝丙肝、结核筛查(IGRA/PPD)、胸片、妊娠试验","系统治疗中：甲氨蝶呤每1-3个月查血常规肝肾功；阿维A每月查血脂肝功；环孢素每月查肾功血压","生物制剂：用药前结核/乙肝/丙肝筛查，用药中每3-6个月查血常规肝肾功，感染征象","PASI/BSA/DLQI：每4-12周评估疗效，达标(PASI 75/90/100)维持","关节症状：每次随访评估关节肿痛，必要时风湿科会诊","妊娠计划：阿维A停药后避孕3年，甲氨蝶呤停药3月，生物制剂孕期可用(部分)"],"special_populations":["儿童：弱效激素/钙调磷酸酶抑制剂为主，严重者甲氨蝶呤/生物制剂，按体重算剂量，注意生长发育","妊娠：外用弱中效激素/保湿安全，避免阿维A/甲氨蝶呤/环孢素，生物制剂( TNF抑制剂孕中晚期可用)，IL-17/IL-23数据有限","老年：注意合并症和药物相互作用，生物制剂感染风险，环孢素肾毒性高血压","红皮病型/脓疱型：住院治疗，阿维A或环孢素或生物制剂，支持治疗(补液/电解质/体温)","银屑病关节炎：风湿科联合，甲氨蝶呤或生物制剂，康复锻炼","合并炎症性肠病：避免IL-17抑制剂(可能加重)，选TNF/IL-23抑制剂"],"references":"中华医学会皮肤性病学分会. 中国银屑病诊疗指南(2024). 中华皮肤科杂志"},{"name":"特应性皮炎诊疗指南（2024）","category":"皮肤科","scope":"成人和儿童特应性皮炎(AD，异位性皮炎/湿疹)诊断和治疗。","diagnosis":["Williams标准：瘙痒+典型形态部位(屈侧皮炎/成人手湿疹/婴儿面头皮躯干)+慢性反复发作+个人/家族特应性史(哮喘/过敏性鼻炎/AD)+皮肤干燥","婴儿期(2岁内)：面头皮躯干四肢伸侧红斑丘疹渗出，剧烈瘙痒","儿童期(2-12岁)：屈侧(肘窝腘窝)苔藓化斑块，瘙痒","青少年成人期：屈侧苔藓化，手湿疹常见，可泛发","实验室：血嗜酸粒细胞升高、总IgE升高、过敏原sIgE阳性(辅助，非必需)","特应性标志：干皮症、鱼鳞病、掌纹症、白色糠疹、乳头湿疹、口角唇炎","鉴别：接触性皮炎、脂溢性皮炎、银屑病、疥疮、免疫缺陷病(高IgE综合征/Wiskott-Aldrich)、淋巴瘤样丘疹病","严重度：SCORAD评分(0-103)或EASI评分(0-72)，IGA评估"],"staging":["疾病分期：急性期(红斑丘疹水疱渗出)、亚急性期(鳞屑结痂)、慢性期(苔藓化皮肤增厚)","严重度：轻度(SCORAD<25或EASI<7)、中度(SCORAD 25-50或EASI 7-21)、重度(SCORAD>50或EASI>21)","受累面积：BSA评估","生活质量：DLQI(成人)/CDLQI(儿童)，POEM(患者定向湿疹测量)","合并症：哮喘、过敏性鼻炎、食物过敏、过敏性结膜炎、睡眠障碍、心理问题","控制水平：控制/部分控制/未控制(按瘙痒/睡眠/皮损/发作频率)"],"key_points":["基础治疗是核心：保湿润肤(每天≥2次)、避免诱因、患者教育","轻度：外用糖皮质激素(TCS)或钙调磷酸酶抑制剂(TCI)","中度：中强效TCS+TCI，湿裹治疗，光疗","重度：系统治疗(环孢素/甲氨蝶呤/硫唑嘌呤)或生物制剂(度普利尤单抗)","瘙痒管理：避免搔抓，抗组胺药(夜间镇静类)，冷敷","急性发作：短期中强效TCS控制，之后维持治疗(每周2次TCS/TCI主动维持)","食物过敏：不盲目忌口，明确过敏才避免，婴儿母乳喂养至少4个月"],"drug_recommendations":["外用糖皮质激素：弱效(氢化可的松)面部/皱褶/婴儿，中效(糠酸莫米松/曲安奈德)躯干四肢，强效(卤米松)肥厚苔藓化，短期2-4周，面部/皱褶≤1-2周","外用钙调磷酸酶抑制剂：他克莫司软膏0.03%(儿童)/0.1%(成人)、吡美莫司乳膏1%，面部/皱褶/生殖器首选，无激素萎缩，初期灼热感","外用磷酸二酯酶4抑制剂：克立硼罗软膏2%(轻中度，2岁以上)","外用JAK抑制剂：鲁索利替尼乳膏1.5%(轻中度，12岁以上)","系统免疫抑制剂：环孢素2.5-5mg/kg/d(短期，重度)、甲氨蝶呤7.5-25mg/w、硫唑嘌呤1-3mg/kg/d、霉酚酸酯","生物制剂：度普利尤单抗(抗IL-4Rα)成人600mg负荷后300mg q2w，儿童按体重；JAK抑制剂口服(乌帕替尼15mg qd、阿布昔替尼100mg qd，注意感染/血栓/心血管)","抗组胺药：西替利嗪/氯雷他定(白天)，羟嗪/扑尔敏(夜间镇静止痒)","急性渗出：湿敷(生理盐水/3%硼酸)，氧化锌油，感染时抗生素(莫匹罗星/夫西地酸)","保湿剂：每天≥2次，沐浴后3分钟内涂抹，含神经酰胺/尿素/甘油成分"],"non_pharmacological":["保湿润肤：基础治疗，每天≥2次，沐浴后立即涂抹，选择无香料低敏产品","沐浴：温水(<37℃)短时间(<10min)，温和无皂清洁剂，避免热水烫洗","避免诱因：过敏原(尘螨/花粉/宠物)、刺激物(羊毛/化纤/香料/酒精)、温度剧烈变化、出汗、精神紧张","衣物：纯棉宽松，新衣物洗后穿，避免羊毛化纤直接接触","环境：尘螨控制(防螨床罩/热水洗/除湿)，避免宠物，保持湿度50-60%","饮食：不盲目忌口，明确食物过敏才避免，婴儿添加辅食循序渐进","心理支持：瘙痒影响睡眠和生活，焦虑加重瘙痒，放松训练/认知行为治疗","避免搔抓：剪短指甲，夜间戴棉手套，冷敷止痒"],"complications":["皮肤感染：金黄色葡萄球菌定植/感染(脓疱/渗出/结痂)，单纯疱疹病毒感染(疱疹性湿疹/Kaposi水痘样疹，重症)，真菌感染","睡眠障碍：夜间瘙痒致失眠，影响儿童生长发育和学习，成人工作","心理问题：容貌影响+慢性瘙痒致抑郁焦虑，儿童行为问题","生长发育迟缓：儿童重度AD+长期激素+睡眠差，监测身高体重","白内障/视网膜脱离：重度AD/长期揉眼，眼科随访","红皮病：重度泛发，住院系统治疗","药物不良反应：激素(皮肤萎缩/毛细血管扩张/色素改变/反跳)、TCI(初期灼热/皮肤感染风险)、系统免疫抑制剂(感染/骨髓/肝肾)、生物制剂(结膜炎/注射反应)"],"monitoring":["治疗初期：每2-4周评估皮损(SCORAD/EASI)、瘙痒、睡眠、生活质量","稳定期：每1-3个月随访，主动维持治疗","外用激素：评估使用部位和时间，避免长期大面积使用","系统治疗前：血常规、肝肾功、乙肝丙肝、结核筛查、妊娠试验","系统治疗中：每1-3个月查血常规肝肾功，环孢素监测血压肾功","生物制剂/JAK：用药前结核/乙肝筛查，用药中感染征象，JAK监测血常规血脂血栓","过敏原复查：必要时，避免长期不必要忌口","儿童生长发育：身高体重定期"],"special_populations":["婴儿(2岁内)：面头皮为主，弱效激素+保湿，避免强效，母乳喂养，食物过敏评估","儿童(2-12岁)：屈侧为主，中弱效激素，TCI(他克莫司0.03%)，严重者甲氨蝶呤/度普利尤单抗(按体重)","老年：皮肤更干燥，注意激素萎缩，合并症多，系统药物谨慎","妊娠：保湿+弱中效激素安全，避免系统免疫抑制剂，度普利尤单抗孕期可用(数据有限)","手部AD：避免接触刺激物，强效激素+封包，保湿，必要时X光治疗","眼睑AD：TCI首选，避免激素(青光眼/白内障风险)，眼科随访","合并哮喘/过敏性鼻炎：特应性进程，同时治疗，度普利尤单抗对AD+哮喘均有效"],"references":"中华医学会皮肤性病学分会. 特应性皮炎诊疗指南(2024). 中华皮肤科杂志"},{"name":"中国原发性青光眼诊疗指南（2024）","category":"眼科","scope":"成人原发性青光眼(开角型POAG和闭角型PACG)诊断和治疗。","diagnosis":["POAG：眼压>21mmHg(正常眼压性青光眼眼压可正常)、青光眼性视神经损害(视盘杯盘比扩大/盘沿切迹/神经纤维层缺损)、相应视野缺损，前房角开放","PACG：前房角关闭(虹膜周边前粘连)，眼压升高，可急性发作(眼痛头痛视力骤降/恶心呕吐/角膜水肿/前房浅/瞳孔散大)","高危因素：POAG(近视/家族史/黑人/眼压高)、PACG(远视/小眼球/浅前房/窄角/老年女性/亚洲人)","检查：眼压(Goldmann压平眼压计金标准)、前房角镜(区分开角/闭角)、眼底(视盘/OCT神经纤维层)、视野(标准自动视野计)、中央角膜厚度(影响眼压测量)","正常眼压性青光眼：眼压≤21但有青光眼性视神经损害和视野缺损，需排除其他视神经病变","鉴别：继发性青光眼(激素/外伤/色素播散/剥脱综合征/新生血管)、视神经炎/缺血性视神经病变/颅内病变"],"staging":["POAG分期：早期(旁中心暗点/鼻侧阶梯，MD>-6dB)、中期(弓形暗点/周边视野缩小，MD -6至-12dB)、晚期(管状视野/颞侧视岛，MD<-12dB)、绝对期(失明)","PACG：临床前期、前驱期、急性发作期、间歇期、慢性期、绝对期","眼压分级：正常≤21、轻度升高22-25、中度26-30、重度>30","目标眼压：根据基线眼压和分期设定，早期降20%，中期降30%，晚期降40%以上，正常眼压性青光眼降30%","视神经损害：盘沿面积、杯盘比、神经纤维层厚度(OCT)","视野进展：GPA分析，定期比较"],"key_points":["POAG：降眼压是唯一证实有效的治疗，目标眼压个体化，药物→激光→手术阶梯","PACG：解除瞳孔阻滞是关键，激光周边虹膜切除术(LPI)或白内障手术，眼压仍高加药物/小梁手术","药物治疗：前列腺素类衍生物一线(降眼压30-33%)，每晚1次","激光治疗：选择性激光小梁成形术(SLT)可作为POAG一线或药物辅助","手术治疗：小梁切除术是金标准，引流阀植入术(难治性)，微创青光眼手术(MIGS)中轻度","定期随访：眼压、视野、视神经，评估进展调整目标眼压","患者教育：终身疾病，依从性重要，避免诱因(暗室/情绪激动/大量饮水/衣领过紧)"],"drug_recommendations":["前列腺素类：拉坦前列素0.005% qn、曲伏前列素0.004% qn、贝美前列素0.03% qn、他氟前列素0.0015% qn(一线，降眼压30-33%，注意虹膜色素加深/睫毛增长/眶周脂肪萎缩)","β受体阻滞剂：噻吗洛尔0.25-0.5% bid、卡替洛尔1-2% bid(降20-25%，支气管哮喘/心动过缓/心衰禁用)","α2肾上腺素能激动剂：溴莫尼定0.1-0.2% bid-tid(降20-25%，注意口干/嗜睡/过敏，儿童禁用)","碳酸酐酶抑制剂：布林佐胺1% bid-tid(局部)、乙酰唑胺125-250mg qid(口服，急性发作短期，注意电解质/肾结石/磺胺过敏)","复方制剂：拉坦前列素噻吗洛尔qd、布林佐胺噻吗洛尔bid(提高依从性)","缩瞳剂：毛果芸香碱1-2% tid-qid(PACG，开放房角，注意眉弓痛/近视加深/视网膜脱离风险)","高渗剂：20%甘露醇1-2g/kg iv快速滴注(急性发作/术前，注意心肾功能)、50%甘油盐水口服","急性闭角发作：综合治疗(缩瞳剂+β阻滞剂+碳酸酐酶抑制剂+高渗剂+激素)，眼压控制后激光虹膜周切或白内障手术"],"non_pharmacological":["激光周边虹膜切除术(LPI)：PACG各期(临床前期/前驱期/间歇期)首选，解除瞳孔阻滞","选择性激光小梁成形术(SLT)：POAG开角型，可重复，作为一线或辅助","激光周边虹膜成形术：急性闭角发作药物控制不佳时","手术小梁切除术：药物/激光控制不良的中晚期POAG/PACG，抗代谢药(丝裂霉素C)提高成功率","引流阀植入术：难治性青光眼(新生血管性/外伤性/多次手术失败)","微创青光眼手术(MIGS)：iStent/小梁网消融/ Schlemm管成形，轻中度POAG，联合白内障手术","生活方式：避免暗室久留、情绪激动、大量饮水(一次<300ml)、衣领过紧，适度有氧运动(降眼压)，避免倒立/举重(升高眼压)","定期随访：眼压每1-6个月，视野每6-12个月，视神经OCT每年"],"complications":["急性闭角发作：视力骤降/眼痛头痛恶心呕吐，紧急降眼压，延误可致永久性视力丧失","视神经萎缩/视野缺损：进行性，不可逆，晚期管状视野/失明","白内障：青光眼患者白内障发生早/进展快，白内障手术可同时治疗闭角青光眼","恶性青光眼：闭角术后/缩瞳剂后，前房极浅眼压高，阿托品+高渗剂+激素，无效玻璃体切割","药物不良反应：前列腺素类(虹膜色素加深/睫毛增长/眶周萎缩)、β阻滞剂(心动过缓/支气管痉挛)、溴莫尼定(过敏/嗜睡)、口服CAI(电解质紊乱/肾结石)","手术并发症：浅前房/低眼压、滤过泡感染/漏、白内障、出血、感染(眼内炎罕见但严重)","低眼压性黄斑病变：术后眼压过低，黄斑皱褶视力下降"],"monitoring":["眼压：治疗初期每2-4周，稳定后每1-6个月，24小时眼压曲线(波动评估)","视野：每6-12个月，早期更频繁，GPA分析进展","视神经：眼底照相/OCT神经纤维层，每6-12个月","前房角：闭角型定期房角镜检查","药物不良反应：每次随访询问，眼部和全身","手术眼：滤过泡形态、眼压、前房深度、并发症","目标眼压评估：根据视野/视神经进展调整，进展则降低目标","患者依从性：用药频率和方法检查"],"special_populations":["正常眼压性青光眼：目标眼压降30%，注意血压(夜间低血压加重)，改善微循环药物(辅助)","高眼压症：眼压>21但无视神经/视野损害，危险因素(角膜薄/家族史/近视)者治疗，否则定期观察","青少年型青光眼：药物(前列腺素类)效果差，手术(小梁切开/小梁切除)，注意鉴别发育性青光眼","妊娠：避免前列腺素类(子宫收缩)和碳酸酐酶抑制剂，用β阻滞剂(注意新生儿)，激光/手术优先考虑","老年：注意全身合并症(哮喘/心衰/肾功)，药物选择谨慎，手术耐受性评估","合并白内障：白内障手术可加深前房/开放房角(闭角型)，联合MIGS或小梁切除"],"references":"中华医学会眼科学分会青光眼学组. 中国原发性青光眼诊疗指南(2024). 中华眼科杂志"},{"name":"变应性鼻炎诊断和治疗指南（2024）","category":"耳鼻喉科","scope":"成人和儿童变应性鼻炎(过敏性鼻炎)诊断和治疗。","diagnosis":["典型症状：阵发性喷嚏、清水样涕、鼻痒、鼻塞(2项以上，每天≥1h)","体征：鼻黏膜苍白水肿，鼻腔水样分泌物，可伴眼结膜充血/眼睑水肿","过敏原检测：皮肤点刺试验(SPT)阳性或血清特异性IgE(sIgE)阳性，结合症状","分类：按过敏原季节(季节性/常年性)，按持续时间(间歇性<4天/周或<4周/持续性)，按严重度(轻度/中重度)","鼻激发试验：诊断困难时(过敏原阴性但高度怀疑)","鉴别：血管运动性鼻炎、感染性鼻炎、嗜酸性粒细胞增多性非变应性鼻炎(NARES)、药物性鼻炎、脑脊液鼻漏","合并症：变应性结膜炎、哮喘、鼻窦炎、鼻息肉、分泌性中耳炎、睡眠呼吸暂停"],"staging":["ARIA分类：间歇性(症状<4天/周或<4周)、持续性(>4天/周且>4周)","严重度：轻度(睡眠/日常活动/工作学习不受影响，无烦恼症状)、中重度(上述受影响)","过敏原类型：季节性(花粉/真菌孢子)、常年性(尘螨/宠物/蟑螂)","控制水平：控制/部分控制/未控制(按症状/用药/生活质量)","鼻结膜炎生活质量问卷(RQLQ)：评估生活影响","合并哮喘评估：肺功能/支气管激发试验，上下气道同治"],"key_points":["避免过敏原是基础：尘螨(防螨床罩/热水洗/除湿)、花粉(季节防护)、宠物(避免接触)","药物治疗阶梯：轻度间歇性→口服抗组胺药/鼻用抗组胺药；中重度/持续性→鼻用糖皮质激素(一线)","鼻用糖皮质激素是中重度AR一线用药，疗效优于抗组胺药","抗组胺药：第二代(西替利嗪/氯雷他定/非索非那定)，嗜睡少，鼻用起效快","白三烯受体拮抗剂：孟鲁司特，合并哮喘者优选","过敏原特异性免疫治疗(AIT)：唯一对因治疗，改变自然病程，适用于尘螨/花粉等，疗程3-5年","手术治疗：药物无效的下鼻甲肥大/鼻中隔偏曲，辅助治疗"],"drug_recommendations":["鼻用糖皮质激素：布地奈德鼻喷剂64μg qd、糠酸莫米松鼻喷剂200μg qd、丙酸氟替卡松鼻喷剂200μg qd、糠酸氟替卡松110μg qd(一线，中重度，疗程≥2周，可长期，注意鼻出血/鼻黏膜干燥)","第二代口服抗组胺药：西替利嗪10mg qd、氯雷他定10mg qd、非索非那定120mg qd、地氯雷他定5mg qd、左西替利嗪5mg qd(轻度/间歇性，起效快，嗜睡少)","鼻用抗组胺药：氮卓斯汀鼻喷剂1喷bid、奥洛他定鼻喷剂2喷bid(起效快，15-30min，轻中度)","白三烯受体拮抗剂：孟鲁司特10mg qn(成人)，5mg(2-5岁)，4mg(6月-2岁)，合并哮喘优选，注意神经精神不良反应(情绪/睡眠/自杀意念)","减充血剂：羟甲唑啉/赛洛唑啉鼻喷剂(短期≤7天，缓解鼻塞，长期用致药物性鼻炎)，口服伪麻黄碱(高血压/心脏病慎用)","肥大细胞稳定剂：色甘酸钠鼻喷剂(预防，提前1-2周用，起效慢)","眼用抗组胺药：奥洛他定滴眼液/氮卓斯汀滴眼液(变应性结膜炎)","免疫治疗(AIT)：皮下注射(SCIT)或舌下含服(SLIT)，尘螨制剂/花粉制剂，疗程3-5年，起效6-12月","鼻腔冲洗：生理盐水/海盐水冲洗鼻腔，每天1-2次，辅助治疗"],"non_pharmacological":["过敏原避免：尘螨(防螨床罩枕套、55℃以上热水洗床品、除湿<50%、空气净化器HEPA)、花粉(季节关窗/口罩/护目镜/外出回家洗脸洗鼻/避免晾晒)、宠物(避免饲养/隔离卧室/空气净化)、霉菌(通风除湿/修复漏水)","环境控制：戒烟(包括二手烟)，避免刺激性气味，保持室内清洁","鼻腔冲洗：生理盐水/海盐水每天1-2次，清除过敏原和分泌物，安全可长期","适度运动：增强体质，但花粉季节避免户外运动","饮食：避免已知过敏食物，部分患者对花粉相关食物(交叉反应)敏感","免疫治疗：唯一对因治疗，改变疾病自然进程，减少哮喘发生风险，适用于5岁以上","患者教育：疾病认知、用药方法(鼻喷剂头偏向对侧)、依从性、长期管理"],"complications":["支气管哮喘：AR患者哮喘风险增加3倍，上下气道同治，约40%AR合并哮喘","变应性鼻窦炎/鼻息肉：长期炎症致鼻窦炎/鼻息肉，中重度AR需评估","分泌性中耳炎：咽鼓管功能障碍，耳闷听力下降，儿童多见","睡眠呼吸暂停：鼻塞致张口呼吸/打鼾/睡眠呼吸暂停，影响睡眠质量和白天功能","嗅觉障碍：长期炎症/鼻息肉致嗅觉减退或丧失","药物性鼻炎：长期用减充血剂(>7天)致反跳性鼻塞，停用减充血剂+鼻用激素","鼻息肉：中重度持续性AR风险，CT评估，药物(激素)或手术","结膜炎：眼痒流泪眼红，眼用抗组胺药/肥大细胞稳定剂"],"monitoring":["治疗初期：每2-4周评估症状(喷嚏/流涕/鼻痒/鼻塞)、生活质量、用药依从性","稳定期：每1-3个月随访，调整药物阶梯(降阶梯/维持)","鼻喷剂使用技术：每次随访检查纠正(头微低、喷头朝向外侧、避免对着鼻中隔)","药物不良反应：鼻出血(鼻用激素，对着外侧喷可减少)、嗜睡(抗组胺药)、神经精神事件(孟鲁司特)","免疫治疗：每次注射后观察30min(SCIT)，过敏反应处理，定期评估疗效调整剂量","合并症筛查：哮喘(肺功能)、鼻窦炎/鼻息肉(鼻内镜/CT)、中耳炎","过敏原复查：必要时，环境控制评估"],"special_populations":["儿童：鼻用激素(2岁以上糠酸莫米松/布地奈德)，口服抗组胺药按年龄，免疫治疗5岁以上，注意生长发育(鼻用激素影响小)，合并腺样体肥大/中耳炎","妊娠：鼻用激素(布地奈德相对安全)、生理盐水冲洗，避免口服减充血剂，抗组胺药(氯雷他定/西替利嗪相对安全但尽量孕早期避免)","老年：注意药物相互作用(抗组胺药抗胆碱/嗜睡跌倒)，鼻用激素安全，合并高血压避免口服减充血剂","合并哮喘：孟鲁司特或鼻用激素，上下气道同治，吸入激素治疗哮喘，AIT对两者均有效","合并鼻息肉/鼻窦炎：鼻用激素+鼻腔冲洗，必要时口服激素(短期)或手术","职业性变应性鼻炎：避免职业暴露是关键，早期脱离，AIT部分有效"],"references":"中华耳鼻咽喉头颈外科杂志编委会. 变应性鼻炎诊断和治疗指南(2024). 中华耳鼻咽喉头颈外科杂志"},{"name":"中国良性前列腺增生症诊疗指南（2024）","category":"泌尿外科","scope":"成人良性前列腺增生(BPH)诊断和治疗。","diagnosis":["下尿路症状(LUTS)：储尿期(尿频/尿急/夜尿/急迫性尿失禁)、排尿期(排尿困难/尿线变细/间断/腹压排尿)、排尿后(尿不尽/滴沥)","国际前列腺症状评分(IPSS)：0-35分，0-7轻度、8-19中度、20-35重度","生活质量评分(QoL)：0-6分，≥4分提示患者不满意需治疗","直肠指检(DRE)：前列腺增大、质地中等、中央沟变浅/消失，排除硬结(前列腺癌)","辅助检查：尿常规(排除感染/血尿)、血清PSA(前列腺癌筛查，BPH可轻度升高)、前列腺超声(体积/残余尿)、尿流率(Qmax<10ml/s提示梗阻)","侵入性检查：尿动力学(诊断困难/神经源性膀胱)、膀胱镜(血尿/结石/肿瘤怀疑)","鉴别：前列腺癌、神经源性膀胱、尿道狭窄、膀胱颈挛缩、前列腺炎、膀胱癌(原位癌可致刺激症状)"],"staging":["IPSS评分：轻度0-7、中度8-19、重度20-35","前列腺体积：超声测量，<30ml、30-50ml、>50ml(大体积)","残余尿(PVR)：<50ml正常，>50ml提示梗阻，>200ml提示膀胱功能受损","Qmax：>15正常，10-15可疑梗阻，<10提示梗阻","并发症：急性尿潴留、反复血尿、反复泌尿系感染、膀胱结石、肾积水/肾功能损害、疝气/痔疮(腹压排尿)","手术指征：中重度LUTS药物无效、并发症(尿潴留/肾积水/结石/反复感染/血尿)、残余尿>50-100ml"],"key_points":["观察等待：轻度症状(IPSS≤7)或中度但生活质量影响小，定期随访","药物治疗：中重度症状，α1受体阻滞剂(快速缓解症状)+5α还原酶抑制剂(缩小体积，大体积前列腺)联合","α1受体阻滞剂：坦索罗辛/特拉唑嗪，起效快(数天)，不缩小体积，注意体位性低血压/逆行射精","5α还原酶抑制剂：非那雄胺/度他雄胺，缩小体积20-30%，减少急性尿潴留和手术风险，起效慢(3-6月)，注意性功能障碍","M受体拮抗剂/β3激动剂：储尿期症状为主(尿急尿频)，残余尿不多者，注意尿潴留风险","手术治疗：药物无效或有并发症，经尿道前列腺电切术(TURP)金标准，激光手术( HoLEP/绿激光)出血少，大体积可选开放/腹腔镜剜除","定期随访：IPSS/QoL/尿流率/残余尿/PSA，药物6个月评估疗效"],"drug_recommendations":["α1受体阻滞剂：坦索罗辛0.2mg qn(高选择性α1A，心血管副作用少)、特拉唑嗪2mg qn(起始1mg)、多沙唑嗪4mg qd、阿夫唑嗪2.5mg tid(注意体位性低血压，首剂睡前)","5α还原酶抑制剂：非那雄胺5mg qd(Ⅱ型5α还原酶)、度他雄胺0.5mg qd(Ⅰ+Ⅱ型，起效更快)，3-6月起效，疗程≥6-12月评估","联合治疗：α1阻滞剂+5α还原酶抑制剂(中重度+大体积前列腺>30ml，症状改善+减少进展)","M受体拮抗剂：托特罗定2mg bid、索利那新5mg qd(储尿期症状，残余尿<50ml，注意口干/便秘/尿潴留)","β3肾上腺素能激动剂：米拉贝隆50mg qd(储尿期症状，不影响排尿期，注意血压升高)","植物制剂：普适泰/锯叶棕提取物(疗效不确切，可作为辅助)","急性尿潴留：留置导尿(首选)，α1阻滞剂提高拔管成功率，拔管前试夹管训练膀胱"],"non_pharmacological":["观察等待：轻度症状，生活方式指导(限水/避免咖啡因酒精/定时排尿/二次排尿)，定期随访","生活方式：夜间限水，避免咖啡因/酒精(利尿刺激)，避免久坐/受凉，适度运动，定时排尿，二次排尿(减少残余尿)","膀胱训练：延迟排尿，延长排尿间隔，改善储尿期症状","盆底肌训练：凯格尔运动，改善控尿","避免加重药物：抗组胺药/抗胆碱药/减充血剂/某些抗抑郁药(加重排尿困难)","定期随访：IPSS/QoL/尿流率/残余尿/PSA/DRE，观察等待者每6-12月","患者教育：疾病认知，药物起效时间(5α还原酶抑制剂慢)，手术指征"],"complications":["急性尿潴留：突然不能排尿，下腹胀痛，留置导尿，反复发作需手术","反复泌尿系感染：残余尿致感染，抗感染+解除梗阻","膀胱结石：残余尿/感染致结石，手术同时取石+前列腺切除","反复血尿：前列腺黏膜血管破裂，5α还原酶抑制剂减少出血，严重者手术","肾积水/肾功能损害：长期梗阻致膀胱高压→输尿管反流→肾积水，解除梗阻可恢复(早期)","疝气/痔疮/脱肛：长期腹压排尿所致，前列腺手术可改善","膀胱功能损害：长期梗阻致逼尿肌肥厚/纤维化，术后排尿困难可能不恢复","药物不良反应：α阻滞剂(体位性低血压/头晕/逆行射精)、5α还原酶抑制剂(性欲降低/勃起功能障碍/射精量减少/男性乳房发育)、M拮抗剂(口干/便秘/尿潴留)"],"monitoring":["观察等待：每6-12个月IPSS/QoL/尿流率/残余尿/尿常规，症状加重及时就诊","药物治疗：1个月评估症状改善(α阻滞剂起效快)，6个月评估(5α还原酶抑制剂)，调整方案","PSA：每年检查，5α还原酶抑制剂可使PSA降低约50%，用药6月后PSA×2解读，排除前列腺癌","DRE：每年，发现硬结进一步检查(前列腺穿刺)","尿流率/残余尿：每6-12个月或症状变化时","术后随访：IPSS/QoL/尿流率/残余尿/尿常规，评估手术效果和并发症(尿失禁/尿道狭窄/逆行射精)","肾功能：有肾积水者随访肌酐和超声"],"special_populations":["老年(>70岁)：注意合并症(心血管病/糖尿病)，α阻滞剂体位性低血压跌倒风险，选择高选择性坦索罗辛，手术耐受性评估","前列腺癌筛查：PSA升高/DRE硬结需前列腺穿刺，BPH和前列腺癌可并存","合并前列腺炎：抗感染+α阻滞剂，避免过度治疗","合并膀胱过度活动症(OAB)：α阻滞剂+M拮抗剂/β3激动剂，注意残余尿","合并勃起功能障碍：他达拉非5mg qd(PDE5抑制剂，同时改善BPH症状和ED，注意硝酸盐禁忌)","大体积前列腺(>80-100ml)：5α还原酶抑制剂+激光剜除(HoLEP)或开放手术，TURP风险高","术后逆行射精：常见(70-90%)，术前告知，不影响健康但影响生育(有生育需求者慎重)"],"references":"中华医学会泌尿外科学分会. 中国良性前列腺增生症诊疗指南(2024). 中华泌尿外科杂志"},{"name":"原发性骨质疏松症诊疗指南（2024）","category":"骨科","scope":"成人原发性骨质疏松症(绝经后/老年)诊断和防治。","diagnosis":["脆性骨折：轻微外伤(站立高度跌倒)或日常活动发生的骨折，即可诊断骨质疏松症","骨密度检测：双能X线吸收法(DXA)，T值≤-2.5诊断骨质疏松，-1.0至-2.5骨量减少，≥-1.0正常","T值：(实测骨密度-正常年轻成人峰值)/标准差，用于绝经后女性和50岁以上男性","Z值：用于绝经前女性和50岁以下男性，Z值≤-2.0为低于同年龄预期","危险因素：不可控(年龄/女性/绝经/家族史/种族)、可控(低体重/吸烟/过量饮酒/缺乏运动/钙维D不足/跌倒)、继发性(激素/甲亢/甲旁亢/慢性肾病/胃肠疾病/药物)","骨折风险评估：FRAX工具(10年髋部骨折和主要骨质疏松性骨折概率)","实验室：血钙磷、碱性磷酸酶、25-羟维生素D、PTH、肝肾功能、甲功、血常规、血沉(排除继发性)","骨转换标志物：β-CTX、PINP(评估骨转换和治疗反应)"],"staging":["骨量正常：T值≥-1.0","低骨量(骨量减少)：T值-1.0至-2.5","骨质疏松症：T值≤-2.5","严重骨质疏松症：T值≤-2.5+脆性骨折","骨折部位：椎体(最常见，胸腰椎)、髋部(最严重，致死致残率高)、桡骨远端、肱骨近端","椎体骨折分级：Genant半定量法(轻度20-25%高度丢失、中度25-40%、重度>40%)","治疗反应：骨密度每年DXA，骨转换标志物3-6月"],"key_points":["基础措施：钙和维生素D补充、生活方式、跌倒预防","药物治疗指征：T值≤-2.5；T值-1.0至-2.5+FRAX高危；脆性骨折(椎体/髋部)","抗骨吸收药：双膦酸盐(一线)、地舒单抗、降钙素、雌激素/SERM","促骨形成药：特立帕肽(PTH类似物)、阿巴洛肽，用于严重骨质疏松/高骨折风险","联合/序贯：促骨形成后抗骨吸收维持，不建议同时用两类(抵消)","疗程：双膦酸盐3-5年后评估药物假期，地舒单抗长期用(停药需过渡双膦酸盐)","跌倒预防：家居改造、视力检查、平衡训练、避免镇静药、髋部保护器"],"drug_recommendations":["钙：元素钙1000-1200mg/d(饮食+补充)，碳酸钙(餐中)、枸橼酸钙(空腹/胃酸少)","维生素D：普通成人400-800IU/d，骨质疏松/老年人800-1200IU/d，25-羟维生素D目标≥20ng/ml(最好30ng/ml)","双膦酸盐：阿仑膦酸钠70mg qw(空腹200ml水，服后30min直立)、利塞膦酸钠35mg qw、唑来膦酸5mg iv每年(口服不耐受/依从性差)、伊班膦酸钠","地舒单抗：60mg皮下每6个月(抗RANKL，不建议停药，停药骨量快速丢失，需过渡双膦酸盐)","特立帕肽：20μg皮下qd(促骨形成，疗程≤2年，用于严重骨质疏松/多发椎体骨折)","阿巴洛肽：80μg皮下qd(促骨形成，疗程≤2年)","降钙素：鲑鱼降钙素50IU im qd或鼻喷剂200IU qd(镇痛效果好，椎体骨折急性期，不长期用)","雌激素：绝经早期女性，个体化评估(乳腺癌/血栓/心血管风险)，最低有效剂量","SERM：雷洛昔芬60mg qd(椎体骨折，不增加乳腺癌风险，潮热/血栓风险)、巴多昔芬","罗莫单抗：210mg皮下每月×12月(抗硬化蛋白，促形成+抗吸收，之后过渡抗骨吸收)"],"non_pharmacological":["钙摄入：奶制品(牛奶300ml/d约300mg钙)、豆制品、深绿叶菜、小鱼虾，不足补充剂","维生素D：日晒(每天15-20min暴露四肢)、深海鱼/蛋黄/强化食品，不足补充剂","运动：负重运动(快走/慢跑/爬楼)和抗阻训练(哑铃/弹力带)每周≥3次，每次30min，增加骨密度防跌倒","戒烟限酒：吸烟降低骨密度，过量酒精(>2单位/d)增加骨折风险","防跌倒：家居改造(防滑垫/扶手/夜灯/移除地毯)、视力检查、平衡训练(太极)、避免镇静药、穿防滑鞋","避免低体重：BMI<19风险高，均衡营养","避免久坐：每小时起身活动","避免过量咖啡因/碳酸饮料(影响钙吸收)"],"complications":["脆性骨折：椎体(身高变矮/驼背/背痛)、髋部(卧床并发症/致死致残)、桡骨远端、肱骨近端","椎体骨折：可无症状(影像学发现)，多发致身高变矮/驼背/胸廓畸形/呼吸功能下降","髋部骨折：1年内死亡率20-30%，致残率50%，需手术(内固定/关节置换)+康复+抗骨质疏松治疗","骨折后急性疼痛：降钙素镇痛，椎体成形术/后凸成形术(顽固性疼痛椎体骨折)","长期卧床并发症：肺部感染、深静脉血栓、压疮、肌肉萎缩、骨量进一步丢失","药物不良反应：双膦酸盐(胃肠道/下颌骨坏死罕见/非典型股骨骨折罕见)、地舒单抗(感染/皮疹/停药反弹)、特立帕肽(头痛/恶心/骨肉瘤风险理论上)、雌激素(血栓/乳腺癌/心血管)"],"monitoring":["骨密度DXA：治疗前基线，治疗后每年(腰椎+髋部)，评估疗效(骨密度不下降或升高为有效)","骨转换标志物：β-CTX/PINP，治疗前基线，治疗后3-6月(抗骨吸收药应下降≥30-50%)","身高体重：每年，身高下降>2cm提示椎体骨折","椎体影像学：有症状或身高下降时胸腰椎X线","实验室：血钙磷、25-羟维生素D、PTH、肝肾功能，每年","药物不良反应：双膦酸盐下颌骨坏死(牙科检查，避免侵入性牙科操作)、非典型股骨骨折(大腿/腹股沟痛警惕)","跌倒风险评估：每年，环境和平衡评估","骨折事件记录：评估治疗失败(治疗中仍骨折需调整方案)"],"special_populations":["绝经后女性：最常见，雌激素缺乏是主因，绝经早期可考虑雌激素，双膦酸盐一线","老年男性(>70岁)：睾酮缺乏/年龄相关，双膦酸盐一线，睾酮水平低者可补充(前列腺癌禁忌)","绝经前女性：多为继发性，查找病因，Z值评估，避免致畸药，钙维D基础","糖皮质激素诱导骨质疏松：用激素≥3个月者，钙维D+双膦酸盐预防，剂量≥7.5mg泼尼松/d者","骨折后：立即启动抗骨质疏松治疗(不要等恢复)，手术+康复+药物综合","长期卧床/制动：快速骨量丢失，早期康复，抗骨吸收药","合并慢性肾病：双膦酸盐(eGFR<35慎用)，地舒单抗(不需调量但低钙风险)，专科评估"],"references":"中华医学会骨质疏松和骨矿盐疾病分会. 原发性骨质疏松症诊疗指南(2024). 中华骨质疏松和骨矿盐疾病杂志"},{"name":"中国骨关节炎诊疗指南（2024）","category":"骨科","scope":"成人骨关节炎(OA，退行性骨关节病)诊断和治疗。","diagnosis":["症状：关节疼痛(活动后加重，休息缓解)、晨僵(<30min)、骨摩擦感、关节肿胀、活动受限、晚期畸形","体征：关节压痛、肿胀、畸形、骨摩擦音(捻发感)、活动受限、肌萎缩","好发部位：膝关节(最常见)、髋关节、手(远端指间关节Heberden结节/近端Bouchard结节)、脊柱、足(第一跖趾)","影像学：X线(关节间隙狭窄、骨赘形成、软骨下骨硬化/囊性变)，Kellgren-Lawrence分级0-IV级","MRI：软骨缺损、骨髓水肿、半月板损伤、滑膜炎(早期诊断和鉴别)","实验室：一般正常，血沉/CRP轻度升高，排除炎症性关节炎(类风湿/痛风)","鉴别：类风湿关节炎(对称小关节/晨僵>1h/RF抗CCP阳性)、痛风(急性红肿热痛/尿酸高)、银屑病关节炎、感染性关节炎、骨坏死"],"staging":["Kellgren-Lawrence X线分级：0级正常、I级可疑骨赘、II级明确骨赘+关节间隙可疑狭窄、III级中等骨赘+明确关节间隙狭窄+硬化、IV级大骨赘+严重关节间隙狭窄+明显硬化+畸形","症状严重度：VAS疼痛评分(0-10)、WOMAC评分(疼痛/僵硬/功能)、Lequesne指数(膝/髋)","功能状态：轻度(日常活动不受限)、中度(上下楼/蹲起困难)、重度(行走受限/需助行器/夜间痛)","炎症表现：有无滑膜炎(关节肿胀积液)、急性发作","合并症：肥胖、高血压、糖尿病、心血管病(影响治疗选择)","关节外影响：生活质量、工作能力、心理状态"],"key_points":["基础治疗是核心：患者教育、运动治疗、物理治疗、行动辅助，所有患者均应接受","阶梯治疗：基础→药物→修复性治疗→重建治疗(关节置换)","运动治疗：有氧运动(快走/游泳/骑车)+肌力训练(股四头肌)+关节活动度，减重(肥胖者)","药物：对乙酰氨基酚/NSAIDs(外用→口服)、关节腔注射(激素/玻璃酸钠)、慢作用药(氨基葡萄糖/双醋瑞因，疗效不确切)","外用NSAIDs优先于口服(胃肠道副作用少)，口服NSAIDs注意胃肠/肾/心血管风险","关节腔注射糖皮质激素：急性发作/积液，短期缓解，每年≤3-4次","手术：保守治疗无效的终末期OA，关节置换术(膝/髋)是成熟有效方法","避免过度医疗：不推荐长期用氨基葡萄糖/玻璃酸钠作为主要治疗"],"drug_recommendations":["对乙酰氨基酚：0.5-1g q6h(最大4g/d)，轻中度疼痛，胃肠副作用少，注意肝毒性","外用NSAIDs：双氯芬酸凝胶/乳胶剂、酮洛芬贴剂、氟比洛芬凝胶贴膏(轻中度，局部作用，全身副作用少，每天3-4次)","口服NSAIDs：塞来昔布0.2g qd-bid(COX-2选择性，胃肠少)、双氯芬酸50mg tid、布洛芬400mg tid、萘普生500mg bid(注意胃肠/肾/心血管，最短疗程最低有效量，胃肠高危加PPI)","关节腔注射糖皮质激素：曲安奈德20-40mg或倍他米松7mg，急性发作/积液，每年≤3-4次，间隔≥3月","关节腔注射玻璃酸钠：25mg每周×5次(黏弹性补充，疗效争议，轻中度可尝试)","关节腔注射富血小板血浆(PRP)：自体血制备，轻中度，证据有限","慢作用药：氨基葡萄糖1500mg/d、硫酸软骨素1200mg/d、双醋瑞因50mg bid(疗效不确切，可作为辅助)","镇痛药：曲马多50mg q12h(NSAIDs无效/禁忌，注意成瘾/便秘)、度洛西汀(慢性疼痛/抑郁)","中成药：外用/口服，辅助治疗"],"non_pharmacological":["患者教育：疾病认知(退行性变不可逆转)、治疗目标(缓解疼痛改善功能)、避免过度活动和负重","减重：BMI>25者减重5-10%显著改善膝OA症状，每减1kg膝关节压力减4kg","运动治疗：有氧运动(快走/游泳/骑自行车/椭圆机，避免爬山爬楼深蹲)、股四头肌肌力训练(直腿抬高/静蹲)、关节活动度训练，每周≥3次每次30min","物理治疗：热疗(热敷/红外线/蜡疗)、冷疗(急性肿胀)、经皮神经电刺激(TENS)、超声波、针灸","行动辅助：手杖(对侧手持)、助行器、护膝(髌股关节OA)、楔形鞋垫(膝内侧间室OA)","避免诱发：避免长时间跑跳蹲、爬山爬楼、频繁上下楼、负重","关节保护：避免同一关节长时间负重，交替活动，使用辅助工具","康复锻炼：术后早期康复(关节置换后)是功能恢复关键"],"complications":["关节畸形：膝内翻(O型腿)/外翻(X型腿)，屈曲挛缩，严重影响行走","关节功能丧失：终末期行走困难/需助行器/卧床，生活质量下降","肌肉萎缩：疼痛致活动减少，股四头肌萎缩，进一步加重关节不稳","滑膜炎/关节积液：急性发作，肿胀疼痛，关节腔穿刺抽液+激素注射","关节内游离体：软骨脱落，交锁症状(关节卡住)，关节镜取出","骨坏死：罕见，长期激素/酒精/创伤","药物不良反应：NSAIDs(胃肠溃疡出血/肾损伤/心血管事件)、对乙酰氨基酚(肝毒性)、激素注射(感染罕见/反复注射损害软骨)","手术并发症：关节置换(感染/假体松动/深静脉血栓/脱位/神经血管损伤)"],"monitoring":["症状评估：VAS疼痛、WOMAC/Lequesne评分，每1-3个月","影像学：X线每1-2年或症状变化时，评估进展","体重/BMI：肥胖者定期，减重效果评估","药物不良反应：NSAIDs(胃肠/肾/心血管)、对乙酰氨基酚(肝功能)，定期","运动依从性：每次随访评估，调整运动方案","手术评估：保守治疗无效、终末期、生活质量严重受影响，转骨科手术","术后随访：关节置换术后伤口/关节活动度/假体位置(X线)/并发症，康复指导"],"special_populations":["老年：注意合并症(心血管/胃肠/肾)，NSAIDs选择COX-2选择性+PPI，外用优先，手术耐受性评估","肥胖：减重是关键，减重手术可改善OA，关节置换术前减重降低风险","合并心血管病：NSAIDs(尤其非选择性)增加心血管事件，避免长期用，外用/对乙酰氨基酚优先","合并慢性肾病：NSAIDs禁用/慎用，对乙酰氨基酚(减量)、曲马多、关节腔注射","手OA：外用NSAIDs/激素注射，避免冷水，康复，严重者关节融合/置换","髋OA：避免负重，手杖，终末期全髋关节置换(效果好)","膝OA：股四头肌训练+减重，内侧间室OA可高位胫骨截骨(年轻活动多)，终末期全膝/单髁置换"],"references":"中华医学会骨科学分会. 中国骨关节炎诊疗指南(2024). 中华骨科杂志"},{"name":"围术期患者评估与管理指南（2024）","category":"麻醉科","scope":"成人围术期(术前/术中/术后)评估和管理。","diagnosis":["术前评估：病史(合并症/手术麻醉史/过敏/用药/烟酒)、体格检查、气道评估(Mallampati/张口度/甲颏距离/颈部活动)、心肺听诊、实验室和辅助检查","ASA分级：I级健康、II级轻度系统性疾病、III级重度系统性疾病、IV级危及生命、V级濒死、VI级脑死亡(器官捐献)","心功能评估：NYHA分级、运动耐量(METs，>4METs低风险)、心脏风险指数(RCRI)、心电图/心脏超声/负荷试验(按需)","肺功能评估：吸烟/COPD/哮喘，肺功能检查(FEV1/FVC)、动脉血气(严重肺病)，戒烟≥2周","凝血/血液：血常规、凝血功能、血型、交叉配血(大手术)，抗凝/抗血小板药管理","术前禁食：清饮料2h、母乳4h、配方奶/淀粉类固体6h、油炸/脂肪/肉类8h以上","困难气道评估：Mallampati III-IV、张口<3cm、甲颏距离<6cm、颈部活动受限、小下颌/龅牙/短颈"],"staging":["ASA分级(上述)","手术风险分级：低风险(<1%死亡率，体表/乳腺/白内障)、中风险(1-5%，腹腔/胸腔/骨科大手术)、高风险(>5%，心脏大血管/急诊大手术)","心功能NYHA：I级(无受限)、II级(一般活动受限)、III级(轻微活动受限)、IV级(静息症状)","METs运动耐量：>10优秀、7-10良好、4-7中等、<4差(围术期心血管风险高)","RCRI心脏风险指数：缺血性心脏病、心衰、脑血管病、胰岛素依赖糖尿病、术前肌酐>177(每项1分，0分0.4%、1分0.9%、2分6.6%、≥3分>11%)","术后恶心呕吐(PONV)风险：女性/不吸烟/PONV史/术后阿片类(每项1分，≥3分高危)"],"key_points":["术前优化：控制血压(<180/110)、血糖(8-10mmol/L)、纠正贫血/电解质、治疗心律失常/心衰","抗凝药管理：华法林术前5天停，INR<1.4手术，高血栓风险桥接低分子肝素；NOAC术前24-48h停(按肾功能)；阿司匹林(心血管支架不轻易停)；氯吡格雷术前5-7天停(裸支架≥1月/药物支架≥6月不建议停)","气道管理：困难气道准备(可视喉镜/喉罩/纤维支气管镜/环甲膜穿刺)，清醒插管指征","麻醉选择：根据手术/患者/麻醉师，全麻/椎管内/神经阻滞/局部麻醉，联合麻醉减少全麻药用量","术中监测：标准监测(心电/血压/血氧/ETCO2/体温)，高危加有创动脉压/CVP/尿量/麻醉深度(BIS)","液体管理：目标导向液体治疗(GDFT)，避免过负荷或不足，大手术监测每搏量变异(SVV)","术后管理：镇痛(多模式)、恶心呕吐预防、早期活动、营养、血栓预防"],"drug_recommendations":["术前用药：镇静(咪达唑仑1-2mg iv，焦虑者)、抗胆碱能(东莨菪碱0.3mg im，分泌物多/小儿)、抑酸药(奥美拉唑40mg，反流高危)","全麻诱导：咪达唑仑0.05mg/kg+丙泊酚1-2mg/kg+芬太尼1-3μg/kg+罗库溴铵0.6mg/kg(或顺阿曲库铵0.15mg/kg)","全麻维持：丙泊酚4-12mg/kg/h+瑞芬太尼0.05-2μg/kg/min+七氟烷1-2MAC，肌松按需","椎管内麻醉：腰麻(布比卡因10-15mg重比重)、硬膜外(2%利多卡因/0.5%罗哌卡因)，试验剂量","神经阻滞：0.25-0.5%罗哌卡因(超声引导，臂丛/股神经/腹横肌平面等)","血管活性药：麻黄碱5-10mg iv、去氧肾上腺素50-100μg iv、去甲肾上腺素0.05-1μg/kg/min(低血压)、硝酸甘油(高血压)","术后镇痛：多模式(对乙酰氨基酚1g q6h+NSAIDs+阿片类PCA+区域阻滞)，阿片PCA(吗啡1mg/次锁定5min或芬太尼)","PONV预防：高危联合(地塞米松5mg+昂丹司琼8mg+氟哌啶醇1mg)，术中丙泊酚维持，减少阿片"],"non_pharmacological":["术前宣教：解释麻醉过程、禁食要求、术后镇痛、缓解焦虑","术前禁食：清饮料2h(无反流风险)、固体6-8h，减少误吸风险","戒烟：术前≥2周(最好4-8周)，减少肺部并发症","营养支持：营养不良者术前7-10天营养支持(肠内优先)","术前康复(prehabilitation)：运动训练+营养+心理，改善大手术预后","术中保温：充气加温毯/液体加温，维持体温≥36℃，减少出血/感染/心血管事件","术后早期活动：术后24h内下床，减少血栓/肺部并发症/肠麻痹","术后疼痛管理：多模式镇痛，患者自控镇痛(PCA)，评估疼痛评分"],"complications":["困难气道/插管失败：预充氧，可视喉镜，喉罩，纤维支气管镜，紧急环甲膜穿刺/切开","术中低血压/高血压：调整麻醉深度，血管活性药，评估容量/失血/心功能","术中知晓：麻醉深度监测(BIS 40-60)，足够麻醉药，高危者术中唤醒评估","术后恶心呕吐(PONV)：高危预防，联合用药，影响恢复和满意度","术后疼痛控制不全：多模式镇痛，PCA，区域阻滞，评估调整","术后谵妄：老年高危，避免苯二氮䓬/抗胆碱药，早期活动，定向力，非药物预防","深静脉血栓/肺栓塞：机械预防(气压)+药物预防(低分子肝素)，早期活动","肺部并发症：肺不张/肺炎，术前戒烟/呼吸训练，术后镇痛+咳嗽排痰+早期活动","急性肾损伤：避免肾毒性药，维持灌注，目标导向液体，监测尿量肌酐"],"monitoring":["标准监测：心电(Ⅱ/V5)、无创血压(每3-5min)、脉搏血氧、ETCO2(全麻/镇静)、体温(大手术>30min)","高危/大手术：有创动脉压(连续血压/血气)、中心静脉压(CVP)、尿量(每小时)、BIS(麻醉深度)、肌松监测(TOF)、血气/电解质/血糖/乳酸","术前：血常规、凝血、肝肾功、电解质、血糖、心电图(>40岁或心脏病)、胸片(胸腔/上腹部手术或肺病)、肺功能(严重肺病)","术后：生命体征(每15-30min至稳定)、疼痛评分、恶心呕吐、尿量、引流液、血氧、意识","麻醉恢复室(PACU)：Aldrete评分(活动/呼吸/循环/意识/氧合)≥9分可回病房","出室标准：生命体征稳定、意识清醒、疼痛控制、无活动性出血、恶心呕吐控制"],"special_populations":["老年：器官功能减退，药物减量，注意认知/谵妄，目标导向液体，避免低血压，区域麻醉可减少肺部并发症和谵妄","小儿：按体重算剂量，气道管理(头大颈短/喉位置高/环状软骨最窄)，体温管理(易低体温)，液体计算精确","妊娠：仰卧低血压综合征(子宫左移)，避免致畸药(孕早期)，误吸风险高(禁食/抑酸)，区域麻醉优先(凝血正常)，胎儿监测","肥胖：困难气道风险高，坐位预充氧，药物按理想体重/校正体重，术后呼吸监测，血栓预防","心脏病：心内科会诊，优化心功能，维持心肌氧供需平衡(心率/血压/血氧)，有创监测，β阻滞剂继续(术前不停)","慢性肾病：避免肾毒性药(NSAIDs/氨基糖苷)，调整药物剂量(按eGFR)，维持肾灌注，电解质(尤其钾)","糖尿病：术前血糖控制8-10mmol/L，术中每1-2h查血糖，胰岛素静脉泵入，避免低血糖"],"references":"中华医学会麻醉学分会. 围术期患者评估与管理指南(2024). 中华麻醉学杂志"},{"name":"急性ST段抬高型心肌梗死诊断和治疗指南（2024）","category":"心血管内科","scope":"急性ST段抬高型心肌梗死（STEMI）的早期识别、再灌注治疗、药物治疗和二级预防。","diagnosis":["典型胸痛：持续大于20分钟，含服硝酸甘油不缓解，可放射至左肩背下颌","心电图：相邻2个导联ST段抬高，胸导大于等于0.2mV，肢导大于等于0.1mV，或新发左束支传导阻滞","心肌损伤标志物：肌钙蛋白cTnI/cTnT升高，肌红蛋白早期升高，CK-MB反映梗死面积","鉴别：主动脉夹层（撕裂样痛，双上肢血压差大，CTA）、肺栓塞（D-二聚体升高，心电图S1Q3T3）、急性心包炎（广泛ST弓背向下抬高）","高危征象：持续胸痛、低血压、肺水肿、心源性休克、恶性心律失常"],"staging":["Killip分级：I级无啰音，II级啰音小于50%肺野，III级啰音大于50%肺水肿，IV级心源性休克","TIMI血流分级：0级无灌注，1级渗透但无灌注，2级部分灌注，3级完全灌注","梗死部位：前壁（V1-V4）、下壁（II III aVF）、侧壁（I aVL V5-V6）、后壁（V7-V9）、右室（V3R-V5R）"],"key_points":["时间就是心肌，发病120分钟内首选直接PCI，门-球时间小于等于90分钟","不能及时PCI且发病小于12小时无禁忌者，溶栓治疗（尿激酶150万IU 30分钟，阿替普酶50mg加速方案），溶栓后2-24小时转运行PCI","抗血小板：阿司匹林300mg负荷+替格瑞洛180mg负荷（或氯吡格雷600mg），维持阿司匹林100mg qd+替格瑞洛90mg bid至少12个月","抗凝：普通肝素（PCI时）或低分子肝素（依诺肝素1mg/kg q12h），磺达肝癸钠2.5mg qd","他汀：高强度他汀（阿托伐他汀40-80mg或瑞舒伐他汀20-40mg），目标LDL-C小于1.4mmol/L","β受体阻滞剂：无禁忌24小时内启动（美托洛尔/比索洛尔），降低死亡率","ACEI/ARB/ARNI：前壁心梗或心功能不全者24小时内启动","右室心梗：避免利尿剂和硝酸酯，需扩容补液"],"drug_recommendations":["再灌注治疗是核心，直接PCI优于溶栓","双联抗血小板至少12个月（阿司匹林+替格瑞洛/氯吡格雷），不可随意停药","他汀类需长期服用，目标LDL-C小于1.4mmol/L","β受体阻滞剂长期服用降低死亡率","ACEI/ARB/ARNI改善心室重构","右室心梗需扩容补液，避免利尿剂和硝酸酯"],"non_pharmacological":["急性期卧床休息，保持安静，避免情绪激动和用力","戒烟限酒，控制血压血糖血脂","心脏康复：病情稳定后逐步开始运动训练，从低强度开始","控制体重，低盐低脂饮食，保持大便通畅","心理疏导，避免情绪激动和过度劳累","定期随访，不可自行停药"],"complications":["心律失常：室颤（立即非同步电除颤）、室速（同步电复律或胺碘酮）、房室传导阻滞（下壁心梗常见，临时起搏）","心力衰竭：Killip II-IV级，利尿剂+血管扩张剂+正性肌力药","心源性休克：升压（去甲肾上腺素）、IABP、ECMO、紧急血运重建","机械并发症：室间隔穿孔、乳头肌断裂、心脏破裂（急诊手术）","梗死后心绞痛：提示残余缺血，需冠脉造影评估","心包炎：Dressler综合征（发热、胸痛、心包摩擦音），阿司匹林/秋水仙碱","猝死：恶性心律失常，需ICD预防（LVEF小于等于35%）"],"monitoring":["心电监护：持续心电血压血氧监护至少24-48小时","心肌标志物：入院即刻、6小时、12小时、24小时查cTn和CK-MB","心电图：入院即刻、溶栓后90分钟、每日复查，胸痛随时查","超声心动图：评估室壁运动、LVEF、机械并发症","冠脉造影：直接PCI时完成，评估病变程度和支架植入","血常规、凝血、肝肾功能、电解质、血糖、血脂","出院前评估：LVEF、运动负荷试验或心肌灌注显像","长期随访：1个月、3个月、6个月、12个月门诊复查"],"special_populations":["老年人：症状不典型（可无痛性心梗），出血风险高，抗栓药物需减量评估","女性：症状不典型（恶心、乏力、背痛），微血管病变多见","糖尿病：无痛性心梗多见，血糖控制目标个体化（避免低血糖）","肾功能不全：造影剂肾病风险，术前水化，根据eGFR调整抗凝和抗血小板剂量","心力衰竭：LVEF降低者优先ARNI+β阻滞剂+MRA+SGLT2i新四联","右室心梗：避免利尿剂和硝酸酯，需扩容，注意合并下壁心梗","心源性休克：IABP/ECMO支持，紧急血运重建"],"references":["中华医学会心血管病学分会. 急性ST段抬高型心肌梗死诊断和治疗指南（2019）","2024 ESC急性冠脉综合征管理指南","AHA/ACC STEMI管理指南"]},{"name":"中国成人血脂异常防治指南（2024年版）","category":"心血管内科","scope":"成人血脂异常的筛查、诊断、危险分层、治疗目标和管理策略。","diagnosis":["血脂检测：总胆固醇TC、甘油三酯TG、低密度脂蛋白胆固醇LDL-C、高密度脂蛋白胆固醇HDL-C、载脂蛋白A1/B、脂蛋白(a)","诊断标准：TC大于等于6.2mmol/L升高，LDL-C大于等于4.1mmol/L升高，TG大于等于2.3mmol/L升高，HDL-C小于1.0mmol/L降低","筛查：40岁以上男性和绝经后女性每年查血脂，高危人群每3-6个月查","继发性血脂异常：糖尿病、甲减、肾病综合征、肝胆疾病、药物（激素、利尿剂）"],"staging":["低危：10年ASCVD发病风险小于5%","中危：10年风险5%-9%","高危：10年风险大于等于10%，或糖尿病+1个危险因素，或CKD3-4期","极高危：ASCVD患者，或糖尿病+靶器官损害，或高血压+3个危险因素","超高危：ASCVD复发事件，或多血管床病变，或家族性高胆固醇血症+ASCVD"],"key_points":["生活方式干预是基础，所有患者均应坚持","LDL-C是首要干预靶点，非-HDL-C是次要靶点","低危中危：LDL-C目标小于3.4mmol/L","高危：LDL-C目标小于2.6mmol/L","极高危：LDL-C目标小于1.8mmol/L，且较基线降大于等于50%","超高危：LDL-C目标小于1.4mmol/L，且较基线降大于等于50%","低HDL-C：首选生活方式干预，不推荐药物升HDL"],"drug_recommendations":["他汀类首选：中等强度他汀（阿托伐他汀10-20mg、瑞舒伐他汀5-10mg）起始，4-6周复查调整","他汀不达标：加用依折麦布10mg qd，仍不达标加PCSK9抑制剂（依洛尤单抗/阿利西尤单抗）","高甘油三酯：TG大于等于5.6mmol/L首选贝特类（非诺贝特）防急性胰腺炎，TG 2.3-5.6可他汀+贝特联合","家族性高胆固醇血症：他汀+依折麦布+PCSK9抑制剂联合，必要时脂蛋白置换"],"non_pharmacological":["饮食控制：减少饱和脂肪酸和胆固醇摄入，增加膳食纤维、全谷物、蔬菜水果","控制体重：BMI维持18.5-23.9，腰围男性小于90cm女性小于85cm","规律运动：每周至少150分钟中等强度有氧运动，配合抗阻训练","戒烟限酒：完全戒烟，限制饮酒（男性酒精小于25g/d，女性小于15g/d）","控制血压血糖：高血压糖尿病患者达标管理","减少反式脂肪酸摄入，避免油炸食品和加工肉类","保持良好作息，避免熬夜和精神紧张"],"complications":["动脉粥样硬化：冠心病、脑梗死、外周动脉疾病","急性胰腺炎：TG大于等于5.6mmol/L时风险显著增加","脂肪肝：血脂异常常合并非酒精性脂肪肝","黄色瘤：家族性高胆固醇血症可见肌腱黄色瘤、角膜弓","胆石症：长期高胆固醇血症增加胆结石风险","药物不良反应：他汀致肌痛肌炎横纹肌溶解、肝酶升高、新发糖尿病；贝特致胆结石、肌病；依折麦布致腹泻头痛"],"monitoring":["治疗前：血脂、肝酶（ALT/AST）、肌酸激酶CK、血糖、肾功能","他汀治疗后4-6周：复查血脂、肝酶、CK，评估疗效和安全性","达标后：每3-6个月复查血脂，长期稳定者6-12个月复查","肝酶升高大于3倍正常上限：暂停他汀，复查，恢复后换用其他他汀或减量","肌痛伴CK升高大于5倍正常上限：停药，水化，严重者按横纹肌溶解处理","家族性高胆固醇血症：筛查家族成员，基因检测","ASCVD患者：定期评估心血管事件复发风险"],"special_populations":["老年人：他汀起始剂量减半，密切监测肌病和肝酶，避免高强度他汀","孕妇哺乳期：禁用他汀（致畸），需血脂管理用生活方式或胆汁酸螯合剂","儿童：家族性高胆固醇血症8岁以上可考虑他汀，需专科评估","糖尿病患者：血脂目标更严格（高危以上），他汀不增加新发糖尿病风险（获益大于风险）","CKD患者：他汀可延缓肾病进展，根据eGFR调整剂量，避免贝特类（eGFR小于30）","甲状腺功能减退：先纠正甲减再评估血脂，甲减本身致高胆固醇","酗酒者：避免大剂量他汀（肝损伤风险），贝特类增加胆结石风险"],"references":["中国成人血脂异常防治指南修订联合委员会. 中国成人血脂异常防治指南（2024年版）","2023 ESC/EAS血脂异常管理指南","ACC/AHA胆固醇管理指南"]},{"name":"中国甲状腺功能减退症诊治指南（2024）","category":"内分泌科","scope":"成人甲状腺功能减退症（甲减）的病因、诊断、治疗和特殊人群管理。","diagnosis":["临床表现：乏力、怕冷、体重增加、便秘、皮肤干燥、毛发脱落、声音嘶哑、记忆力减退、月经紊乱","体征：面色苍白、眼睑水肿、皮肤干燥发凉、心动过缓、腱反射松弛期延长","实验室：TSH升高（原发性甲减最敏感指标），FT4降低（临床甲减），FT4正常（亚临床甲减）","甲状腺自身抗体：TPOAb和TgAb阳性提示桥本甲状腺炎（最常见病因）","鉴别：中枢性甲减（TSH正常或降低+FT4降低）、低T3综合征（严重疾病，rT3升高）","病因：桥本甲状腺炎（最常见）、甲亢治疗后（手术/碘131/抗甲状腺药）、碘缺乏、药物（胺碘酮、锂剂）、先天性"],"staging":["临床甲减：TSH升高+FT4降低，需治疗","亚临床甲减：TSH升高+FT4正常，TSH大于10mIU/L或TPOAb阳性或有症状需治疗","重度甲减：TSH明显升高伴明显症状，需缓慢替代","黏液性水肿昏迷：严重甲减伴意识障碍、低体温、低血压、呼吸抑制，急诊抢救","中枢性甲减：TSH正常或降低+FT4降低，需查垂体MRI"],"key_points":["左甲状腺素钠（L-T4）是首选替代治疗，早餐前30-60分钟空腹服用","起始剂量：年轻无心脏病者1.6-1.8μg/kg/d；老年人和心脏病者12.5-25μg/d起始，每2-4周加量","目标：临床甲减TSH维持0.5-2.5mIU/L（老年人可放宽至4-6），FT4在正常范围","亚临床甲减：TSH大于10mIU/L需治疗；TSH 4-10伴TPOAb阳性、血脂异常、症状、备孕需治疗","妊娠期甲减：TSH目标早孕小于2.5，中晚孕小于3.0，L-T4剂量需增加20-30%","黏液性水肿昏迷：静脉L-T4（首剂200-400μg），氢化可的松，保温，呼吸支持，避免被动升温","定期复查：调整剂量期每4-6周查TSH，达标后每6-12个月查","不可随意停药，多数需终身替代"],"drug_recommendations":[],"non_pharmacological":["碘摄入：适碘饮食，避免长期大量摄入高碘食物（海带紫菜），碘缺乏地区需补碘","保暖：怕冷患者注意保暖，避免寒冷刺激","适度运动：根据心功能选择，避免剧烈运动","皮肤护理：使用润肤剂，避免过度清洁","保持大便通畅：高纤维饮食，必要时缓泻剂","心理支持：甲减可致抑郁，需关注心理健康","避免使用致甲减药物：胺碘酮、锂剂、酪氨酸激酶抑制剂等（如必须用需监测甲功）"],"complications":["黏液性水肿昏迷：最严重并发症，低温、意识障碍、呼吸抑制，死亡率高，急诊抢救","心血管疾病：甲减致心动过缓、心包积液、血脂异常，增加冠心病风险","贫血：甲减常合并正细胞正色素性贫血或大细胞性贫血","不孕和流产：甲减影响排卵和妊娠，增加流产早产风险","胎儿神经发育异常：妊娠期甲减未控制影响胎儿智力发育","肌病：甲减致肌痛、肌无力、CK升高","抑郁和认知障碍：长期甲减影响情绪和认知"],"monitoring":["治疗前：TSH、FT4、FT3、TPOAb、TgAb、血脂、血常规、肝肾功能","调整剂量期：每4-6周复查TSH和FT4","达标后：每6-12个月复查TSH","妊娠期：每4周复查TSH，调整剂量","中枢性甲减：查FT4（TSH不可靠），垂体MRI，其他垂体激素","长期服用者：每年查血脂、心电图（甲减致心包积液和心肌病变）","出现心悸、手抖、失眠：提示药物过量，查甲功减量"],"special_populations":["妊娠期：TSH目标更严格（早孕小于2.5），确诊后立即增加L-T4剂量，每4周复查","老年人：起始剂量小（12.5-25μg），缓慢加量，TSH目标可放宽（4-6mIU/L），避免过度治疗致房颤和骨质疏松","冠心病患者：小剂量起始，缓慢加量，避免诱发心绞痛","中枢性甲减：不能以TSH为目标，以FT4正常为目标，需同时评估肾上腺皮质功能（先补激素再补甲状腺素）","儿童：需足量替代保证生长发育，定期监测身高和骨龄","哺乳期：L-T4安全，可正常哺乳","胺碘酮治疗者：用药前和用药中每3-6个月查甲功"],"references":["中华医学会内分泌学分会. 中国甲状腺功能减退症诊治指南（2024）","ATA甲减治疗指南","2023 ETA甲减管理指南"]},{"name":"中国脑出血诊治指南（2024）","category":"神经内科","scope":"成人自发性脑出血（ICH）的急诊评估、诊断、治疗和康复管理。","diagnosis":["临床表现：突发剧烈头痛、呕吐、意识障碍、局灶神经功能缺损（偏瘫、失语、凝视麻痹）","血压常显著升高（大于180/100mmHg）","头颅CT是首选检查：脑出血呈高密度影，可明确部位、出血量、是否破入脑室","CTA：评估有无动脉瘤、血管畸形、造影剂外渗（点征提示血肿扩大风险）","MRI：鉴别肿瘤卒中、脑血管畸形，亚急性期出血更敏感","出血量估算：多田公式（长×宽×层数/2）","鉴别：脑梗死（CT低密度）、蛛网膜下腔出血（CT蛛网膜下腔高密度）、外伤"],"staging":["按部位：基底节区（最常见，壳核出血）、丘脑、脑叶、小脑、脑干、脑室","按出血量：小量（小于30ml幕上/小于10ml幕下）、中量（30-50ml）、大量（大于50ml）","按意识状态：清醒、嗜睡、昏睡、浅昏迷、深昏迷（GCS评分）","按病因：高血压性（最常见）、动脉瘤、血管畸形、淀粉样血管病（脑叶出血老年）、凝血障碍、肿瘤卒中"],"key_points":["急诊处理：保持气道通畅，吸氧，心电监护，建立静脉通路，控制血压","血压管理：收缩压大于220mmHg积极降压；150-220mmHg无禁忌可快速降至140mmHg（目标130-140）；避免低于130","降颅压：抬高床头30度，甘露醇125ml q6-8h（注意肾功能和电解质），甘油果糖，高渗盐水，严重者手术","止血：凝血障碍者用相应拮抗剂（华法林用维生素K+PCC，肝素用鱼精蛋白），rFVIIa不常规推荐","抗癫痫：有癫痫发作者用抗癫痫药，不预防性用抗癫痫药（脑叶出血可考虑）","手术：小脑出血大于10ml或脑干受压、脑积水需手术；幕上血肿大于30ml伴意识恶化可考虑血肿清除；脑室出血铸型需脑室外引流","并发症防治：应激性溃疡（PPI）、感染（肺炎尿路感染）、深静脉血栓（气压治疗，出血停止后可考虑低分子肝素）","康复：病情稳定后尽早开始康复训练（肢体功能、语言、吞咽）"],"drug_recommendations":[],"non_pharmacological":["急性期卧床休息，保持安静，避免情绪激动和用力","保持大便通畅，避免用力排便（升高颅压）","呼吸道管理：昏迷者侧卧位，及时吸痰，必要时气管切开","营养支持：吞咽困难者鼻饲，保证热量和蛋白质摄入","控制血压：长期规律服降压药，目标小于130/80mmHg","戒烟限酒，低盐低脂饮食","控制血糖血脂","康复训练：病情稳定后24-48小时开始被动活动，意识清楚后主动训练，包括肢体功能、语言、吞咽、认知","定期随访，避免重体力劳动和剧烈运动","二级预防：控制血压是关键，避免抗凝和抗血小板药物（除非有明确指征）"],"complications":["血肿扩大：发病24小时内常见，CTA点征预测，控制血压可减少","脑水肿和颅高压：发病3-5天高峰，甘露醇脱水，严重者脑疝","脑积水：脑室出血或小脑出血压迫导水管，脑室外引流","癫痫：脑叶出血和皮质受累多见，发作时抗癫痫治疗","肺部感染：昏迷和吞咽困难者常见，需加强护理和抗生素","消化道出血：应激性溃疡，PPI预防和治疗","深静脉血栓和肺栓塞：长期卧床者，气压治疗预防","中枢性高热：脑干出血，物理降温","抑郁和认知障碍：卒中后常见，需评估和干预","死亡：大量脑出血和脑干出血死亡率高"],"monitoring":["急诊：头颅CT（首选）、CTA（查找病因和血肿扩大风险）、血常规、凝血、肝肾功能、血糖、电解质、心电图、心肌酶","住院期间：动态复查头颅CT（24小时、病情变化时），监测生命体征、意识、瞳孔、出入量","凝血功能：INR、APTT、纤维蛋白原，指导止血治疗","康复评估：肌力、肌张力、平衡、语言、吞咽、认知功能","长期：血压监测（家庭自测）、血脂血糖、头颅影像学复查","病因查找：年轻患者或非高血压部位出血需查DSA/MRA排除血管畸形、动脉瘤","认知和情绪评估：卒中后抑郁和认知障碍筛查"],"special_populations":["老年人：脑淀粉样血管病致脑叶出血多见，脑萎缩明显，颅压代偿空间大，预后差，降压需谨慎","孕妇：少见，需兼顾胎儿，避免致畸药物","口服抗凝药者：华法林相关脑出血需立即用维生素K+PCC逆转，DOAC用特异性拮抗剂（依达赛珠单抗/安德沙奈）","血小板减少或白血病：血小板输注，治疗原发病","肝功能衰竭：凝血障碍，补充凝血因子和血小板","透析患者：肝素相关，用鱼精蛋白，调整透析方案","大量脑出血：手术决策需综合评估年龄、意识、出血量、基础疾病，家属知情同意"],"references":["中华医学会神经病学分会. 中国脑出血诊治指南（2024）","AHA/ASA自发性脑出血管理指南","2023 ESO脑出血指南"]},{"name":"中国癫痫诊疗指南（2024）","category":"神经内科","scope":"成人和儿童癫痫的分类、诊断、药物治疗、手术评估和长期管理。","diagnosis":["临床表现：反复性、发作性、刻板性的神经功能异常，包括意识丧失、抽搐、感觉异常、精神症状、自主神经症状","脑电图（EEG）：发作间期痫样放电（棘波、尖波、棘慢复合波），长程视频EEG提高阳性率","头颅MRI：首选影像学检查，查找致痫灶（海马硬化、肿瘤、血管畸形、皮层发育不良）","CT：急诊排除出血、肿瘤、钙化","分类：部分性发作（单纯部分、复杂部分、部分继发全面）、全面性发作（失神、肌阵挛、强直-阵挛、强直、失张力）、不能分类","癫痫综合征：特发性（儿童失神、青少年肌阵挛、良性中央颞区癫痫）、症状性、隐源性","鉴别：晕厥（短暂意识丧失，EEG正常）、心因性非癫痫发作（PNES，视频EEG鉴别）、偏头痛、TIA、睡眠障碍","诊断需至少2次非诱发性发作，或1次发作伴再发高风险"],"staging":["按发作类型：部分性发作、全面性发作、不能分类发作","按病因：特发性（遗传相关）、症状性（结构性/代谢性/感染/免疫）、隐源性（未找到病因）、未知病因","按癫痫综合征：儿童失神癫痫、青少年肌阵挛癫痫、良性中央颞区癫痫、Lennox-Gastaut综合征、West综合征（婴儿痉挛）、Dravet综合征","药物难治性癫痫：经2种正确选择的抗癫痫药（单药或联合）规律治疗2年仍未控制","癫痫持续状态：发作持续大于5分钟，或两次发作间意识未恢复，急诊抢救"],"key_points":["根据发作类型选药：部分性发作首选卡马西平/奥卡西平/左乙拉西坦；全面强直-阵挛首选丙戊酸钠/左乙拉西坦/拉莫三嗪；失神首选乙琥胺/丙戊酸钠/拉莫三嗪；肌阵挛首选丙戊酸钠/左乙拉西坦/氯硝西泮","单药治疗起始，小剂量开始逐渐加量，至发作控制或最大耐受量","单药无效换另一种单药（重叠加量），两药无效考虑联合（选择作用机制不同、相互作用少的药物）","常用药物：丙戊酸钠（广谱，注意肝毒性体重增加致畸）、卡马西平（部分性，注意皮疹低钠）、奥卡西平（卡马西平类似，副作用少）、左乙拉西坦（广谱，副作用少，无肝酶诱导）、拉莫三嗪（广谱，注意皮疹（SJS），缓慢加量）、托吡酯（广谱，注意认知副作用肾结石）、唑尼沙胺、氯硝西泮（肌阵挛和失神，注意嗜睡耐受）","癫痫持续状态：地西泮10mg静推（每分钟小于2mg），无效15分钟重复；或劳拉西泮4mg静推；继之丙戊酸钠15-30mg/kg静推或左乙拉西坦1500mg静推；仍不止用丙泊酚或咪达唑仑麻醉","撤药：完全无发作2-5年（不同综合征不同），EEG正常，可缓慢减量（至少6个月），复发则恢复原量","药物难治性癫痫：评估手术（致痫灶切除、胼胝体切开、迷走神经刺激VNS、脑深部电刺激DBS）"],"drug_recommendations":[],"non_pharmacological":["规律作息：避免熬夜、过度劳累，保证充足睡眠","避免诱因：闪光刺激（光敏性癫痫）、饮酒、情绪激动、过度换气","饮食：生酮饮食（儿童难治性癫痫，高脂肪低碳水化合物），需在专业指导下进行","安全防护：避免登高、游泳、驾驶（发作未控制者禁止驾驶），洗澡用淋浴不用盆浴","记录发作日记：发作时间、表现、持续时间、诱因，帮助调整治疗","心理支持：癫痫患者易合并抑郁焦虑，需关注心理健康","避免使用致癫痫药物：喹诺酮类、亚胺培南、茶碱、抗精神病药大剂量等","职业选择：避免高空作业、操作危险机械、驾驶等职业"],"complications":["癫痫持续状态：最严重急性并发症，可致脑损伤、呼吸循环衰竭、死亡","外伤：发作时跌倒致骨折、颅脑外伤、舌咬伤","吸入性肺炎：发作时呕吐物吸入","猝死（SUDEP）：罕见但严重，多见于长期频繁发作、夜间发作、多药治疗者","认知障碍：长期癫痫发作或某些抗癫痫药（苯巴比妥、托吡酯）影响认知","精神心理障碍：抑郁、焦虑、自卑、社交退缩","药物不良反应：皮疹（SJS/TEN，拉莫三嗪卡马西平）、肝损伤（丙戊酸钠）、骨髓抑制（卡马西平）、致畸（丙戊酸钠）、骨质疏松（肝酶诱导剂）","耐药和药物相互作用：肝酶诱导剂（卡马西平、苯妥英、苯巴比妥）加速其他药物代谢"],"monitoring":["治疗前：血常规、肝肾功能、电解质、凝血、乙肝丙肝、脑电图、头颅MRI","用药初期：每2-4周复查血常规肝肾功能（尤其丙戊酸钠卡马西平），评估疗效","稳定期：每3-6个月复查血常规肝肾功能，每年复查脑电图","血药浓度：治疗窗窄的药物（卡马西平、丙戊酸钠、苯妥英），或疗效不佳/怀疑中毒/依从性差时查","发作控制后：每年复查脑电图，评估撤药可能性","术前评估：长程视频EEG、MRI、PET、脑磁图、Wada试验，定位致痫灶","孕期：每月复查血药浓度，监测胎儿发育","长期：骨密度（长期用肝酶诱导剂）、认知和情绪评估"],"special_populations":["儿童：根据体重计算剂量，注意对认知发育的影响，Dravet综合征禁用卡马西平奥卡西平（加重），生酮饮食用于难治性","孕妇：备孕前调整为致畸风险低的药物（左乙拉西坦、拉莫三嗪），补充叶酸（5mg/d），孕期每月查血药浓度，产后哺乳多数抗癫痫药安全","老年人：肝肾功能减退，小剂量起始，注意药物相互作用（多药合用），避免苯巴比妥（认知跌倒）","肝功能不全：避免丙戊酸钠，选择左乙拉西坦、拉莫三嗪","肾功能不全：左乙拉西坦、加巴喷丁、普瑞巴林需减量","驾驶：发作控制1年以上（各国规定不同）可申请驾驶，需医生评估","育龄女性：避免丙戊酸钠（致畸和认知影响），如必须用需知情同意和最小剂量"],"references":["中华医学会神经病学分会. 中国癫痫诊疗指南（2024）","ILAE癫痫分类和定义（2017）","NICE癫痫诊治指南"]},{"name":"中国特发性肺纤维化诊断和治疗指南（2024）","category":"呼吸内科","scope":"特发性肺纤维化（IPF）的诊断标准、评估、抗纤维化治疗和长期管理。","diagnosis":["临床表现：隐匿起病的活动后呼吸困难、干咳、乏力，可有杵状指","体征：双肺底Velcro啰音（爆裂音），杵状指，晚期发绀、右心衰","肺功能：限制性通气功能障碍（FVC降低、TLC降低），弥散功能（DLco）显著降低","高分辨率CT（HRCT）：双肺基底部、胸膜下网格影、蜂窝肺，伴或不伴牵拉性支气管扩张，典型UIP型","支气管镜肺泡灌洗（BAL）：排除感染、肿瘤、嗜酸粒细胞增多","外科肺活检：HRCT不典型时需活检确认UIP型","诊断标准：排除已知原因（结缔组织病、环境暴露、药物），HRCT典型UIP型可临床诊断；不典型需活检","鉴别：结缔组织病相关间质性肺病、慢性过敏性肺炎、石棉肺、结节病、药物性肺损伤"],"staging":["按HRCT分型：典型UIP型、可能UIP型、不符合UIP型","按肺功能分期：轻度（FVC大于等于70%预计值）、中度（50-70%）、重度（小于50%）","按症状和进展：稳定型、进展型（FVC年下降大于等于10%预计值）、急性加重型","合并症：肺动脉高压、肺气肿、肺癌、胃食管反流、睡眠呼吸暂停","急性加重：1个月内呼吸困难加重，低氧血症，CT出现新的磨玻璃影/实变，排除感染心衰，死亡率高"],"key_points":["抗纤维化治疗是核心，确诊后尽早启动","吡非尼酮：200mg tid起始，每周加量至600mg tid（每次随餐服），注意光敏反应皮疹胃肠道反应，防晒","尼达尼布：150mg bid（起始可100mg bid耐受后加量），注意腹泻（常见，对症处理）、肝酶升高、出血风险","抗纤维化药物可延缓FVC下降，不能逆转纤维化，需长期服用","对症治疗：干咳用镇咳药（右美沙芬、复方甘草片），氧疗（静息血氧小于等于88%或运动后低于88%需长期氧疗）","胃食管反流：PPI治疗（IPF常合并GERD，可能加重肺损伤）","急性加重：高流量氧疗或无创通气，糖皮质激素（甲泼尼龙冲击），抗感染（排除感染），抗纤维化继续，必要时ICU","肺移植：终末期IPF的唯一有效治疗，符合条件者尽早转诊评估","康复治疗：呼吸康复训练、营养支持、心理支持","疫苗接种：流感疫苗、肺炎球菌疫苗、新冠疫苗，预防感染诱发急性加重"],"drug_recommendations":[],"non_pharmacological":["戒烟：吸烟是IPF危险因素，戒烟可延缓进展","避免环境暴露：避免粉尘、烟雾、有害气体、鸟类羽毛（过敏性肺炎鉴别）","氧疗：符合指征者长期家庭氧疗，每天大于15小时","呼吸康复：缩唇呼吸、腹式呼吸、上肢和下肢耐力训练，改善运动耐力","营养支持：保证蛋白质和热量，营养不良者营养干预","预防感染：接种疫苗，避免去人群密集场所，出现发热咳嗽及时就医","心理支持：IPF预后差，易焦虑抑郁，需心理疏导和社会支持","避免剧烈运动和重体力劳动，活动以不引起明显呼吸困难为宜","保持室内空气流通，湿度适宜，避免干燥"],"complications":["急性加重：最严重并发症，1个月内呼吸困难加重，死亡率大于50%，需积极抢救","呼吸衰竭：晚期出现I型呼吸衰竭，需长期氧疗或无创通气","肺动脉高压：IPF合并PH提示预后差，需评估，严重者可考虑靶向药物","肺癌：IPF患者肺癌发生率高（约10-15%），定期CT随访","肺气肿：合并肺气肿（CPFE综合征），肺癌风险更高","胃食管反流：常见，可能加重肺纤维化，PPI治疗","心血管疾病：冠心病、心律失常","肺心病：晚期肺动脉高压致右心衰竭","抑郁焦虑：常见，影响生活质量","药物不良反应：吡非尼酮致光敏皮疹胃肠道反应，尼达尼布致腹泻肝酶升高出血"],"monitoring":["诊断时：HRCT、肺功能（含DLco）、血气分析、血常规、生化、自身抗体（排除结缔组织病）、BAL（必要时）、外科肺活检（必要时）","治疗初期：每4-6周评估症状、耐受性、肝酶（尼达尼布）、皮疹（吡非尼酮）","稳定期：每3-6个月复查肺功能（FVC和DLco）、HRCT（每年或病情变化时）、6分钟步行试验","急性加重：急诊查血气、CT、血常规、CRP、降钙素原、病原学（排除感染）、BNP（排除心衰）","长期随访：定期评估肺功能下降速度（FVC年下降率），调整治疗","肺移植评估：终末期患者转诊肺移植中心，定期评估移植指征","合并症筛查：定期查心电图、心脏超声（肺动脉高压）、肿瘤标志物和CT（肺癌）"],"special_populations":["老年人：IPF多见于50岁以上，老年人合并症多，药物耐受性差，需个体化","孕妇：IPF罕见于育龄女性，抗纤维化药物有致畸风险，需专科评估","肝功能不全：尼达尼布主要经肝脏代谢，轻中度肝功不全需减量，重度禁用；吡非尼酮也需监测肝功","肾功能不全：抗纤维化药物肾排泄少，一般不需调整，但需监测","吸烟者：必须戒烟，吸烟影响疗效和预后","合并肺气肿：CPFE综合征，肺癌风险高，需密切CT随访","急性加重高危：既往急性加重史、FVC快速下降、低氧血症者，需密切监测"],"references":["中华医学会呼吸病学分会. 特发性肺纤维化诊断和治疗中国专家共识（2024）","2023 ATS/ERS/JRS/ALAT IPF临床实践指南","NICE IPF管理指南"]},{"name":"急性上消化道出血诊治指南（2024）","category":"消化内科","scope":"急性上消化道出血（UGIB）的急诊评估、危险分层、止血治疗和病因管理。","diagnosis":["临床表现：呕血（咖啡样或鲜红色）、黑便（柏油样）、便血（大量出血时）、头晕、乏力、心悸","体征：面色苍白、心率增快、血压下降、肠鸣音活跃、上腹压痛","急诊内镜：24小时内（高危12小时内）胃镜检查明确病因和止血","危险分层：Glasgow-Blatchford评分（GBS），0分可门诊处理，大于等于1分需住院；Rockall评分评估死亡率","常见病因：消化性溃疡（最常见）、食管胃底静脉曲张破裂（肝硬化）、急性胃黏膜病变、胃癌、Mallory-Weiss综合征、血管畸形","实验室：血红蛋白（注意血液浓缩早期可正常）、血小板、凝血、肝肾功能、血型、交叉配血","鉴别：咯血（呼吸系统，血中混有痰液，碱性）、口鼻咽部出血、食物/药物致黑便（铁剂铋剂活性炭）"],"staging":["按出血量：少量（小于500ml，无明显循环障碍）、中量（500-1000ml，心率增快血压下降）、大量（大于1000ml，休克）","按出血速度：急性、慢性","按病因：非静脉曲张性出血（溃疡、黏膜病变、肿瘤）、静脉曲张性出血（肝硬化门脉高压）","按Rockall评分：低危（0-2分）、中危（3-4分）、高危（大于等于5分，死亡率高）","按GBS评分：0分（低危，可门诊）、大于等于1分（需住院）","再出血高危：溃疡基底可见血管、活动性出血、附着血凝块、溃疡大于2cm、后壁溃疡"],"key_points":["急诊复苏：保持气道通畅（呕血者侧卧位防误吸），建立两条大静脉通路，液体复苏（晶体液），输血（Hb小于70g/L，或心血管病者小于90），避免过度复苏","危险分层：GBS评分决定处置，0分可门诊，高危需监护","药物：PPI（奥美拉唑/泮托拉唑80mg静推+8mg/h持续泵入，非静脉曲张性出血）；生长抑素/奥曲肽（250μg静推+250μg/h持续，静脉曲张性出血）；特利加压素（静脉曲张出血，2mg q4h）；抗生素（静脉曲张出血者预防感染，头孢曲松1g qd×7天）","内镜止血：注射肾上腺素、钛夹、热凝、套扎（静脉曲张）、组织胶（胃底静脉曲张），高危溃疡需联合止血","介入治疗：内镜止血失败可行血管栓塞（胃十二指肠动脉）","手术治疗：药物和内镜均失败，或穿孔、癌变，需外科手术","静脉曲张出血：三腔二囊管压迫（临时止血，为内镜争取时间），TIPS（药物内镜无效时）","病因治疗：溃疡查Hp并根除，肿瘤手术，静脉曲张降低门脉压力（普萘洛尔/卡维地洛）"],"drug_recommendations":[],"non_pharmacological":["急性期禁食：呕血停止后可逐渐过渡到温凉流质饮食","卧床休息，保持安静，避免紧张","保持呼吸道通畅，呕血时头偏向一侧防窒息","观察记录：呕血黑便次数量、生命体征、尿量、神志","口腔护理：呕血后漱口，保持口腔清洁","排便护理：黑便刺激肛周，便后温水清洁","恢复期：规律饮食，避免辛辣刺激、过烫、粗糙食物，戒烟酒","避免使用致溃疡药物：NSAIDs、阿司匹林、糖皮质激素（如必须用需PPI保护）","控制门脉压力：肝硬化者低盐饮食，避免剧烈运动","定期复查胃镜：溃疡治疗后复查，静脉曲张定期内镜随访"],"complications":["失血性休克：大量出血致组织灌注不足，多器官功能衰竭","误吸和窒息：呕血时血液吸入气道，尤其意识障碍者","肝性脑病：肝硬化静脉曲张出血后，肠道积血产氨增加，诱发肝性脑病（乳果糖、门冬氨酸鸟氨酸）","感染：肝硬化出血后易发生自发性腹膜炎、肺炎，抗生素预防","急性肾损伤：低血容量致肾前性肾衰，或肝肾综合征","多器官功能障碍综合征（MODS）：严重休克后","再出血：溃疡止血后再出血率约10-20%，静脉曲张出血更高","死亡：大量出血或合并严重基础病者死亡率高"],"monitoring":["急诊：血常规（动态监测Hb）、血型交叉配血、凝血功能、肝肾功能、电解质、血糖、心电图、心肌酶（排除心梗）、血气分析","内镜：高危12小时内，普通24小时内胃镜，明确病因并止血","复苏期间：每15-30分钟监测生命体征（血压心率呼吸血氧）、尿量、神志","止血后：复查血常规（每4-6小时），观察有无再出血征象","病因检查：Hp检测（溃疡者），肝脏超声和肝功能（静脉曲张者），肿瘤标志物","长期：溃疡者根除Hp后复查胃镜确认愈合；静脉曲张者定期内镜随访（每3-6个月）","再出血评估：Rockall评分高危者密切监测，出现呕血黑便增多、心率增快、血压下降、Hb下降提示再出血"],"special_populations":["老年人：症状不典型，合并心血管病多，输血阈值提高（Hb小于90），死亡率高","肝硬化患者：注意肝性脑病、感染、肝肾综合征，避免过度复苏（增加门脉压力加重出血），抗生素预防感染","服用抗凝/抗血小板药者：华法林用维生素K+PCC逆转，DOAC用特异性拮抗剂，阿司匹林/氯吡格雷需评估心血管风险决定是否停用","孕妇：少见，需兼顾胎儿，避免致畸药物，内镜需谨慎","肾功能不全：输血注意容量负荷，PPI和生长抑素一般安全","服用NSAIDs者：停用NSAIDs，PPI治疗，换用对胃肠道影响小的止痛药","大量出血者：ICU监护，必要时气管插管保护气道"],"references":["中华医学会消化病学分会. 急性上消化道出血诊治指南（2024）","2023 ESC急性胃肠道出血管理指南","ACG溃疡出血管理指南"]},{"name":"中国肾病综合征诊断和治疗指南（2024）","category":"肾内科","scope":"成人肾病综合征（NS）的诊断、病理分型、免疫抑制治疗和并发症管理。","diagnosis":["诊断标准：大量蛋白尿（大于3.5g/d）、低白蛋白血症（小于30g/L）、水肿、高脂血症，前两项必备","尿常规：蛋白尿（大于3+），可有镜下血尿","24小时尿蛋白定量：大于3.5g","血生化：白蛋白小于30g/L，胆固醇和甘油三酯升高","肾穿刺活检：明确病理类型（成人NS均建议活检），指导治疗和判断预后","常见病理类型：微小病变性肾病（MCD）、膜性肾病（MN）、局灶节段性肾小球硬化（FSGS）、系膜增生性肾炎（IgA肾病）、膜增生性肾炎（MPGN）","继发性NS：糖尿病肾病、狼疮性肾炎、乙肝相关性肾炎、肿瘤相关性、药物性","并发症评估：血栓栓塞、感染、急性肾损伤、蛋白质营养不良"],"staging":["按病理类型：微小病变、膜性肾病、FSGS、系膜增生性、膜增生性","按病因：原发性、继发性（糖尿病、狼疮、乙肝、肿瘤、药物）","按对激素反应：激素敏感型（4周内缓解）、激素依赖型（减量复发）、激素抵抗型（8周不缓解）","按活动度：活动期（大量蛋白尿低蛋白血症）、缓解期（尿蛋白小于0.3g/d，白蛋白正常）、复发期","按肾功能：肾功能正常、肾功能不全（CKD分期）","膜性肾病危险分层：低危（尿蛋白小于4g/d，肾功能正常）、中危（4-8g/d）、高危（大于8g/d或肾功能恶化）"],"key_points":["一般治疗：优质蛋白饮食（0.8-1.0g/kg/d），低盐（小于3g/d），利尿消肿（噻嗪类+袢利尿剂，注意电解质），降脂（他汀）","对症：水肿用利尿剂（呋塞米+螺内酯），严重低蛋白血症可输白蛋白后利尿；高脂血症用他汀；抗凝（血浆白蛋白小于20g/L或膜性肾病高危，用低分子肝素或华法林）","糖皮质激素：泼尼松1mg/kg/d（最大60-80mg），8-12周后逐渐减量，总疗程6-12个月；MCD首选激素","免疫抑制剂：激素抵抗/依赖/复发者加用环磷酰胺（0.5-1g/m²每月冲击，或1-2mg/kg/d口服）、环孢素A（3-5mg/kg/d，监测血药浓度）、他克莫司（0.05-0.1mg/kg/d）、吗替麦考酚酯（1-2g/d）、利妥昔单抗（CD20单抗，膜性肾病和难治性NS）","膜性肾病：中高危加免疫抑制剂（环磷酰胺+激素交替，或利妥昔单抗），抗PLA2R抗体监测活动度","微小病变：激素首选，反复复发者用环磷酰胺或钙调磷酸酶抑制剂","FSGS：激素+环孢素/他克莫司，难治性可用利妥昔单抗","IgA肾病：激素+ACEI/ARB，新月体性用激素冲击+环磷酰胺","并发症防治：感染（及时抗感染）、血栓（抗凝）、急性肾损伤（扩容利尿，必要时透析）、营养不良（优质蛋白）","终末期肾病：透析或肾移植"],"drug_recommendations":[],"non_pharmacological":["休息：严重水肿和低蛋白血症时卧床休息，水肿消退后适当活动","饮食：优质低蛋白（0.8-1.0g/kg/d），低盐（小于3g/d），低脂，保证热量（30-35kcal/kg/d）","控制水钠摄入：水肿者限制水（前一日尿量+500ml）和钠","避免劳累和感染：感染是复发和加重的常见诱因","避免使用肾毒性药物：氨基糖苷类、非甾体抗炎药、含马兜铃酸中药","戒烟限酒","适当活动：水肿消退后可轻度活动，避免剧烈运动和重体力劳动","定期监测：尿蛋白、血白蛋白、肾功能、血脂","预防血栓：长期卧床者注意活动下肢，高危者抗凝","心理支持：慢性病需长期治疗，关注情绪"],"complications":["感染：最常见并发症，呼吸道、泌尿道、皮肤、腹膜炎（尤其腹水者），与低球蛋白、免疫抑制剂有关，需及时抗感染","血栓栓塞：肾静脉血栓、下肢深静脉血栓、肺栓塞，膜性肾病高发，血浆白蛋白小于20g/L需抗凝","急性肾损伤：有效血容量不足（过度利尿）、肾静脉血栓、药物性、特发性，需扩容利尿，必要时透析","蛋白质和脂肪代谢紊乱：营养不良、肌肉萎缩、维生素D缺乏、缺铁性贫血、高脂血症","内分泌紊乱：甲状腺功能异常（低T3）、性功能减退","药物不良反应：激素致库欣综合征、骨质疏松、高血糖、感染；环磷酰胺致骨髓抑制、出血性膀胱炎、性腺抑制、致癌；环孢素致肾毒性、牙龈增生、多毛；利妥昔单抗致输注反应、低丙种球蛋白血症、进行性多灶性白质脑病（罕见）","终末期肾病：进展至ESRD需透析或肾移植"],"monitoring":["诊断时：尿常规、24小时尿蛋白定量、血白蛋白、血脂、肝肾功能、电解质、凝血、血常规、自身抗体（ANA、dsDNA、补体）、乙肝丙肝、肿瘤标志物、肾穿刺活检","治疗初期：每1-2周查尿常规、血常规、肝肾功能、电解质；激素治疗者监测血糖血压","免疫抑制剂治疗：环磷酰胺每周查血常规，每2周查肝肾功能；环孢素/他克莫司监测血药浓度（谷浓度）","稳定期：每2-4周查尿常规、24小时尿蛋白、血白蛋白、肾功能、血脂","膜性肾病：监测抗PLA2R抗体滴度（评估活动度和缓解）","长期：骨密度（长期激素）、血糖、血压、眼底、感染筛查","缓解评估：完全缓解（尿蛋白小于0.3g/d，白蛋白正常）、部分缓解（尿蛋白下降大于50%且小于3.5g/d）、无效","复发监测：尿蛋白增加、血白蛋白下降提示复发"],"special_populations":["儿童：微小病变多见，激素敏感，注意激素对生长发育的影响，长期用需监测骨龄和身高","老年人：膜性肾病多见，合并症多，免疫抑制剂耐受性差，感染和血栓风险高，需个体化","孕妇：激素相对安全，避免环磷酰胺（致畸）、利妥昔单抗（需评估），ACEI/ARB禁用，需产科和肾内科共管","糖尿病肾病：NS表现需排除糖尿病肾病，激素慎用（升高血糖），控制血糖血压","乙肝相关性肾炎：抗病毒治疗（恩替卡韦/替诺福韦）联合免疫抑制，监测HBV-DNA","狼疮性肾炎：激素+环磷酰胺/吗替麦考酚酯，羟氯喹基础治疗，监测狼疮活动","肿瘤相关性：治疗肿瘤，部分NS在肿瘤切除后缓解","肾功能不全：根据eGFR调整免疫抑制剂剂量，避免肾毒性药物"],"references":["中华医学会肾脏病学分会. 中国肾病综合征诊断和治疗指南（2024）","KDIGO肾小球肾炎临床实践指南（2021更新）","KDIGO膜性肾病治疗指南"]},{"name":"中国泌尿系结石诊断和治疗指南（2024）","category":"泌尿外科","scope":"成人泌尿系结石（肾结石、输尿管结石、膀胱结石）的诊断、治疗和预防。","diagnosis":["临床表现：肾绞痛（突发腰腹部剧烈绞痛，向会阴部放射，伴恶心呕吐）、血尿（镜下或肉眼）、尿频尿急尿痛（下段结石）、发热（合并感染）、无尿（双侧梗阻或孤立肾梗阻）","体征：患侧肾区叩击痛、输尿管走行区压痛","尿常规：红细胞（血尿），白细胞（合并感染），结晶","泌尿系超声：首选筛查，可发现肾结石和肾积水，输尿管中下段结石易漏诊","泌尿系CT平扫（NCCT）：诊断金标准，可发现X线阴性结石，测量结石大小密度位置，评估肾积水","KUB平片：可发现含钙结石（90%），尿酸结石不显影","静脉肾盂造影（IVP）：评估肾功能和梗阻程度，已被CTU替代","鉴别：急性阑尾炎、胆囊炎、胰腺炎、宫外孕、卵巢囊肿蒂扭转、肾盂肾炎","肾功能评估：血肌酐、eGFR，核素肾动态显像评估分肾功能"],"staging":["按部位：肾结石（肾盏肾盂）、输尿管结石（上中下段）、膀胱结石、尿道结石","按成分：含钙结石（草酸钙、磷酸钙，最常见约80%）、尿酸结石（约10%，X线阴性，可溶石）、感染性结石（磷酸镁铵，与尿路感染有关）、胱氨酸结石（罕见，遗传性）","按大小：小于6mm（可自行排出）、6-20mm（可体外碎石或输尿管镜）、大于20mm（经皮肾镜或手术）","按梗阻程度：无梗阻、不全梗阻、完全梗阻（肾积水）","按肾功能：肾功能正常、肾功能受损、肾衰（孤立肾或双侧梗阻）","按感染：单纯结石、结石合并感染（发热、脓尿，需紧急引流）","复发风险：低危（首次单发含钙小结石）、高危（多发、复发、家族史、代谢异常）"],"key_points":["急诊处理：肾绞痛止痛（非甾体抗炎药双氯芬酸钠/酮咯酸，阿片类哌替啶/吗啡，解痉药山莨菪碱/坦索罗辛），止吐（甲氧氯普胺）","排石治疗：小于6mm输尿管结石，多饮水（2-3L/d），适度运动，α受体阻滞剂（坦索罗辛0.4mg qd促进排石），排石颗粒，观察2-4周","体外冲击波碎石（ESWL）：直径小于20mm肾结石、小于10mm输尿管上段结石，禁忌：妊娠、出血倾向、严重肥胖、结石远端梗阻、尿路感染未控制","输尿管镜碎石取石术（URL）：中下段输尿管结石、ESWL失败、结石大于10mm，用钬激光或气压弹道碎石","经皮肾镜碎石取石术（PCNL）：大于20mm肾结石、鹿角形结石、ESWL失败的结石","腹腔镜/开放手术：复杂结石、微创手术失败、合并解剖异常","膀胱结石：经尿道膀胱镜碎石取石，同时处理下尿路梗阻（前列腺增生）","紧急引流：结石梗阻合并感染发热（脓肾）需立即留置输尿管支架或经皮肾穿刺造瘘引流，二期碎石","双侧结石处理原则：先处理梗阻严重或肾功能差的一侧，或同时处理","溶石治疗：尿酸结石（碱化尿液枸橼酸钾，目标尿pH 6.5-7.0，别嘌醇降尿酸），胱氨酸结石（碱化尿液+硫普罗宁）"],"drug_recommendations":[],"non_pharmacological":["多饮水：每日尿量大于2L，是预防结石最有效的方法，均匀饮水（包括夜间）","饮食调节：含钙结石正常钙摄入（不限制钙，避免过量补钙），限制草酸（菠菜、苋菜、杏仁、巧克力、红茶），限制钠盐（小于5g/d），限制动物蛋白（0.8-1.0g/kg/d），尿酸结石限制高嘌呤（动物内脏、海鲜、啤酒）","适度运动：跳绳、跑步、爬楼梯有助于小结石排出，避免久坐","控制体重：肥胖是结石危险因素","定期复查：结石治疗后定期超声复查，早期发现复发","代谢评估：复发结石、多发结石、特殊成分结石需查24小时尿钙、草酸、尿酸、枸橼酸、胱氨酸","预防用药：含钙结石用噻嗪类利尿剂（氢氯噻嗪减少尿钙）+枸橼酸钾（碱化尿液增加枸橼酸）；尿酸结石用别嘌醇/非布司他+枸橼酸钾；感染性结石控制感染+乙酰异羟肟酸（脲酶抑制剂）","避免憋尿，及时排尿","保持良好作息，避免长期高温环境作业（脱水）"],"complications":["急性肾盂肾炎/脓肾：结石梗阻合并感染，高热寒战腰痛，可致感染性休克，需紧急引流+抗生素","肾积水和肾功能损害：长期梗阻致肾皮质萎缩，肾功能不可逆","肾绞痛：剧烈疼痛，需止痛处理","血尿：结石摩擦黏膜致出血，大量出血少见","尿路刺激症状：尿频尿急尿痛，下段结石或合并感染","无尿和急性肾衰：双侧结石梗阻或孤立肾梗阻，急诊解除梗阻","结石复发：5年复发率约30-50%，需预防","输尿管狭窄：长期结石刺激或碎石后狭窄，需内镜处理","肾切除：患肾无功能合并反复感染或大出血，对侧肾功能正常时考虑","药物不良反应：排石药致低血压头晕，溶石药致电解质紊乱"],"monitoring":["急诊：尿常规、血常规、CRP、降钙素原（感染）、肾功能、电解质、泌尿系超声、KUB、CT平扫","术前：凝血功能、肝肾功能、心电图、胸片、CTU（评估解剖）、尿培养（感染时）","ESWL后：复查KUB或超声（1-2周），评估碎石效果和排石情况","内镜术后：复查超声或CT（4周），评估结石清除和肾积水，拔除输尿管支架（通常2-4周）","长期随访：每3-6个月超声复查，监测复发和肾积水","代谢评估：24小时尿成分分析（复发或高危者），血钙磷尿酸甲状旁腺激素（排除甲旁亢）","肾功能监测：长期梗阻者定期查肌酐eGFR，核素肾动态（分肾功能）","结石成分分析：排出或取出的结石做成分分析，指导预防"],"special_populations":["孕妇：禁用ESWL（辐射和冲击波），首选保守治疗（多饮水止痛），梗阻合并感染时留置输尿管支架或经皮肾造瘘，分娩后处理结石","儿童：少见，多与代谢异常和解剖异常有关，治疗尽量微创（输尿管镜），减少辐射","老年人：合并症多，手术风险高，需评估心肺功能，尽量选择创伤小的方式","孤立肾：结石梗阻可致急性肾衰，需积极处理，保护肾功能","出血倾向：抗凝药使用者ESWL和手术风险高，需评估停药桥接","肥胖患者：ESWL定位困难效果差，首选内镜手术","肾功能不全：根据eGFR调整药物剂量，避免肾毒性造影剂（CT用低渗造影剂+水化）","感染未控制：禁忌碎石和内镜手术（感染扩散致脓毒症），需先引流+抗感染"],"references":["中华医学会泌尿外科学分会. 中国泌尿系结石诊断和治疗指南（2024）","EAU泌尿系结石指南","AUA/ASRM肾结石管理指南"]},{"name":"颈椎病诊治指南（2024）","category":"骨科","scope":"成人颈椎病（颈型、神经根型、脊髓型、椎动脉型、交感型）的诊断、分型、保守治疗和手术指征。","diagnosis":["临床表现：颈肩痛、上肢麻木疼痛（神经根型）、四肢无力行走不稳踩棉感（脊髓型）、头晕头痛（椎动脉型/交感型）、恶心呕吐、心慌","体征：颈椎活动受限、棘突压痛、臂丛牵拉试验（Eaten试验）阳性、压头试验（Spurling试验）阳性（神经根型）；Hoffmann征阳性、踝阵挛、Babinski征阳性、肌张力增高、腱反射亢进（脊髓型）","影像学：颈椎X线（生理曲度变直、骨质增生、椎间隙狭窄、椎间孔变小）；颈椎MRI（首选，明确椎间盘突出、脊髓受压、神经根受压、脊髓信号改变）；颈椎CT（骨结构、后纵韧带骨化）","肌电图：神经根型和脊髓型可辅助诊断","分型：颈型（颈肩痛，无神经受压）、神经根型（最常见，上肢放射痛麻木）、脊髓型（最严重，四肢麻木无力，需手术）、椎动脉型（头晕眩晕，与转头有关）、交感型（心慌胸闷出汗，诊断困难）、混合型","鉴别：肩周炎、腕管综合征、肘管综合征、运动神经元病、脊髓肿瘤、美尼尔病、冠心病"],"staging":["按分型：颈型、神经根型、脊髓型、椎动脉型、交感型、混合型","按严重程度：轻度（症状轻，不影响生活）、中度（影响日常生活）、重度（明显功能障碍，脊髓型出现行走困难或大小便障碍）","按病理：颈椎间盘突出症、颈椎管狭窄症、颈椎后纵韧带骨化症（OPLL）、颈椎不稳","按病程：急性发作期、缓解期、康复期","脊髓型颈椎病分级：JOA评分（17分法），评估脊髓功能，小于等于12分建议手术"],"key_points":["保守治疗：适用于颈型、神经根型、椎动脉型、交感型，以及早期脊髓型（症状轻）","休息和制动：急性发作期卧床休息，颈托制动（不超过2周，避免肌肉萎缩）","药物：非甾体抗炎药（塞来昔布、依托考昔、双氯芬酸）止痛消炎；营养神经（甲钴胺、维生素B1）；肌肉松弛剂（乙哌立松、替扎尼定）；神经根型急性发作可短期用激素（泼尼松或地塞米松）+脱水（甘露醇）；椎动脉型用改善循环药（倍他司汀、氟桂利嗪）","物理治疗：颈椎牵引（神经根型，重量3-5kg，每次15-20分钟）、推拿按摩（脊髓型禁忌推拿！）、针灸、理疗（中频、超声波、热疗）","康复锻炼：症状缓解后进行颈部肌肉功能锻炼（米字操、靠墙收下巴、游泳），避免长期低头","手术治疗：脊髓型颈椎病确诊后建议尽早手术（脊髓受压不可逆）；神经根型保守治疗3-6个月无效或反复发作者；出现肌肉萎缩、大小便障碍者","手术方式：前路手术（ACDF椎间盘切除融合，适合1-2节段）、后路手术（椎管扩大成形术，适合多节段或后纵韧带骨化）、前后联合手术（复杂病例）","术后康复：颈托保护4-6周，逐步进行颈部功能锻炼，定期复查"],"drug_recommendations":[],"non_pharmacological":["姿势管理：避免长期低头（看手机电脑），保持颈椎中立位，屏幕与视线平齐","枕头选择：高度以一拳为宜，材质软硬适中，支撑颈椎生理曲度","颈部保暖：避免受凉（空调直吹），寒冷可加重肌肉痉挛","避免颈部外伤：乘车系安全带，避免急刹车，避免突然转头","工作间隙：每30-60分钟活动颈部，做简单伸展","适度运动：游泳（蛙泳）、羽毛球、放风筝等对颈椎有益的运动，避免剧烈对抗运动","避免提重物和重体力劳动","控制体重，减轻颈椎负担","戒烟（吸烟影响椎间盘血供，加速退变）","保持良好心态，慢性疼痛易焦虑，需心理调节"],"complications":["神经根损伤：神经根长期受压致上肢肌肉萎缩、肌力下降、感觉减退","脊髓损伤：脊髓型颈椎病未及时手术可致不可逆脊髓损伤，四肢瘫痪、大小便障碍，严重者致残","椎动脉供血不足：眩晕、猝倒，增加跌倒风险","颈心综合征：交感型颈椎病致心慌胸闷心律失常，易误诊为冠心病","吞咽困难：巨大颈椎骨赘压迫食管（少见）","术后并发症：前路手术致吞咽困难、声音嘶哑（喉返神经损伤）、植骨不融合、内固定松动；后路手术致颈项痛、C5神经根麻痹","慢性疼痛和残疾：长期颈肩痛影响生活质量和工作能力","抑郁焦虑：慢性疼痛和功能障碍易合并心理问题","复发：术后相邻节段退变（ASD），需长期保护颈椎"],"monitoring":["诊断时：颈椎X线（正侧位、动力位）、颈椎MRI（首选，评估脊髓神经根受压）、颈椎CT（骨结构和OPLL）、肌电图（鉴别神经损伤）、血常规、血沉、CRP（排除感染和风湿）","保守治疗期间：定期评估症状变化（VAS疼痛评分、NDI功能评分），复查MRI（症状加重或保守无效时）","术前：颈椎MRI+CT、心电图、胸片、凝血、肝肾功能、肌电图（必要时）","术后：复查X线（内固定位置和融合情况）、MRI（脊髓减压情况），评估神经功能恢复（JOA评分）","长期随访：每3-6个月复查，评估症状、颈椎活动度、相邻节段情况","脊髓型：密切观察神经功能变化，出现加重及时手术","保守治疗3个月无效：复查MRI，评估手术指征"],"special_populations":["老年人：颈椎退变严重，合并 OPLL 和椎管狭窄多见，手术风险高，需评估心肺功能，脊髓型尽早手术避免瘫痪","儿童：少见，多与外伤、先天畸形有关，需专科评估","孕妇：避免X线和CT，MRI相对安全，保守治疗为主，避免使用影响胎儿的药物","脊髓型颈椎病：禁忌推拿按摩（可致急性脊髓损伤瘫痪），确诊后尽早手术，不可拖延","神经根型：牵引需在医生指导下进行，重量和时间个体化，避免过度牵引","椎动脉型：避免突然转头和颈部过伸，防猝倒跌倒","服用抗凝药者：有创治疗（封闭、手术）需评估出血风险，调整抗凝","糖尿病患者：术后感染风险高，控制血糖"],"references":["中华医学会骨科学分会. 颈椎病诊治指南（2024）","2023 AO Spine颈椎病诊疗指南","北美脊柱学会颈椎病管理指南"]},{"name":"阿尔茨海默病诊治指南（2024）","category":"神经内科","scope":"阿尔茨海默病（AD）的早期识别、诊断标准、药物治疗和照护管理。","diagnosis":["临床表现：隐匿起病、进行性记忆力下降（近期记忆为主）、定向力障碍、语言功能减退、视空间能力下降、人格改变、生活能力下降","认知评估：MMSE量表、MoCA量表（更敏感）、ADL日常生活能力量表、NPI神经精神问卷","生物标志物：脑脊液Aβ42降低、p-tau升高；Amyloid-PET显示Aβ沉积；FDG-PET显示颞顶叶代谢减低","影像学：头颅MRI显示海马萎缩、内侧颞叶萎缩；CT排除血管性病变和肿瘤","基因检测：APP、PSEN1、PSEN2（早发型家族性），APOEε4（晚发型风险基因）","诊断标准：NIA-AA 2021框架（ATN系统：Aβ、tau、神经变性），临床诊断需符合认知下降+生物标志物证据","鉴别：血管性痴呆（阶梯式进展，影像学梗死灶）、路易体痴呆（波动性认知+视幻觉+帕金森症状）、额颞叶痴呆（人格行为改变早于记忆）、正常压力脑积水（步态障碍+尿失禁+痴呆）、抑郁性假性痴呆"],"staging":["按认知阶段：轻度（MMSE 21-26，生活基本自理）、中度（MMSE 10-20，需协助生活）、重度（MMSE小于10，完全依赖）","按生物标志物：临床前期（无症状但生物标志物阳性）、轻度认知障碍期（MCI）、痴呆期","按遗传类型：早发型（小于65岁，常染色体显性遗传）、晚发型（大于65岁，APOE相关）","合并精神行为症状（BPSD）：抑郁、焦虑、激越、幻觉、妄想、睡眠障碍"],"key_points":["胆碱酯酶抑制剂：多奈哌齐5mg qn起始，4-6周后加至10mg qn（轻中度AD）；卡巴拉汀3mg bid起始，加至6mg bid；加兰他敏4mg bid起始，加至8-12mg bid","NMDA受体拮抗剂：美金刚5mg qd起始，每周加量至10mg bid（中重度AD），可与胆碱酯酶抑制剂联用","抗Aβ单抗：仑卡奈单抗（Lecanemab）、多奈单抗（Donanemab），用于早期AD，需定期查MRI排除ARIA（淀粉样蛋白相关影像异常）","精神行为症状：非药物干预优先；抑郁用SSRI（舍曲林、西酞普兰）；激越幻觉用非典型抗精神病药（喹硫平、利培酮，小剂量短期，注意老年痴呆患者死亡率增加黑框警告）；睡眠障碍用褪黑素","辅助用药：银杏叶提取物、奥拉西坦、吡拉西坦（疗效有限）","避免使用抗胆碱能药物（苯海索、三环类抗抑郁药、第一代抗组胺药），加重认知障碍"],"drug_recommendations":[],"non_pharmacological":["认知训练：记忆力训练、定向力训练、现实导向疗法，延缓认知下降","生活方式：规律运动（每周150分钟中等强度有氧运动）、地中海饮食（橄榄油、鱼类、坚果、蔬菜水果）、社交活动、脑力活动（阅读、下棋）","安全防护：防止走失（佩戴定位设备）、家居安全（防滑、防烫伤、锁好危险物品）、驾驶评估（中重度禁止驾驶）","照护者支持：照护者教育、喘息服务、心理支持，预防照护者抑郁","营养支持：保证蛋白质和热量摄入，吞咽困难者调整食物质地或鼻饲","预防感染：肺炎和尿路感染是晚期常见死因，注意口腔卫生和排尿护理","避免长期卧床：鼓励活动，预防压疮和深静脉血栓","临终关怀：晚期患者姑息治疗，减轻痛苦，尊重患者意愿"],"complications":["肺炎：晚期患者吞咽困难和卧床致吸入性肺炎，最常见死因","尿路感染：尿失禁和留置尿管致感染","压疮：长期卧床，需定时翻身","营养不良：进食困难、忘记进食，体重下降","深静脉血栓和肺栓塞：长期卧床","跌倒骨折：视空间障碍和步态异常，易跌倒","精神行为异常：激越、攻击行为，增加照护难度","走失：定向力障碍，需定位设备","药物不良反应：胆碱酯酶抑制剂致恶心呕吐腹泻，美金刚致头晕便秘，抗精神病药致嗜睡跌倒和心血管事件","疾病进展：目前无法治愈，药物仅延缓进展，最终进展至完全依赖"],"monitoring":["诊断时：MMSE/MoCA、ADL、NPI量表，头颅MRI，血常规、肝肾功能、甲状腺功能、维生素B12、叶酸（排除可逆性痴呆），脑脊液或Amyloid-PET（必要时）","治疗初期：每4-6周评估药物耐受性和不良反应（胆碱酯酶抑制剂胃肠道反应）","稳定期：每3-6个月复查认知量表（MMSE/MoCA）、ADL、NPI，评估疾病进展速度","抗Aβ单抗治疗：用药前MRI，用药后每2-4次输注后MRI监测ARIA（脑水肿/微出血），出现头痛意识障碍立即查MRI","长期：定期复查肝肾功能、电解质，营养评估（体重、白蛋白）","照护者评估：定期评估照护者负担和心理健康","晚期：评估是否需要鼻饲、气管切开等有创操作，提前进行医疗预嘱"],"special_populations":["老年人：最常见人群，合并多种疾病和用药，注意药物相互作用，避免抗胆碱能药","孕妇：AD罕见于育龄女性，抗Aβ单抗有致畸风险，需专科评估","肝功能不全：多奈哌齐和卡巴拉汀经肝代谢，需减量监测","肾功能不全：美金刚经肾排泄，eGFR小于30需减量或停用","癫痫病史：美金刚可能降低癫痫阈值，需谨慎","心血管疾病：胆碱酯酶抑制剂可致心动过缓，病窦综合征或传导阻滞者慎用","驾驶：轻中度患者需评估驾驶能力，中重度禁止驾驶","独居患者：需定期探访或安装监控，防止意外和走失"],"references":["中华医学会神经病学分会. 阿尔茨海默病诊治指南（2024）","NIA-AA阿尔茨海默病诊断框架（2021）","2023 EAN阿尔茨海默病指南"]},{"name":"偏头痛诊治指南（2024）","category":"神经内科","scope":"成人偏头痛的诊断分型、急性期治疗、预防性治疗和生活方式管理。","diagnosis":["临床表现：反复发作的单侧搏动性头痛，持续4-72小时，伴恶心呕吐、畏光畏声，活动后加重","先兆偏头痛：头痛前60分钟内出现可逆性神经系统症状（视觉闪光暗点、感觉异常、语言障碍）","无先兆偏头痛：最常见，无先兆症状","慢性偏头痛：每月头痛大于等于15天，其中大于等于8天符合偏头痛，持续大于3个月","诊断标准：ICHD-3标准，至少5次发作（无先兆）或2次（有先兆），符合疼痛特征和伴随症状","鉴别：紧张型头痛（双侧压迫感，无恶心呕吐，活动不加重）、丛集性头痛（单侧眼眶周围剧痛，伴结膜充血流泪鼻塞，周期性发作）、药物过度使用性头痛、颞动脉炎（老年，血沉增快）、颅内病变（肿瘤、出血，影像学排除）","诱因：睡眠不足或过多、饮食（巧克力、奶酪、红酒、咖啡因）、情绪压力、月经、天气变化、强光"],"staging":["按有无先兆：无先兆偏头痛（80%）、有先兆偏头痛（10-20%）","按发作频率：偶发性（每月小于1天）、频发（每月1-14天）、慢性（每月大于等于15天）","按严重程度：轻度（不影响活动）、中度（影响活动但可继续）、重度（需卧床）","特殊类型：视网膜性偏头痛、偏瘫型偏头痛、脑干先兆偏头痛、月经期偏头痛","药物过度使用性头痛：每月使用急性止痛药大于等于10-15天，持续大于3个月"],"key_points":["急性期治疗：轻度用非甾体抗炎药（布洛芬400-800mg、萘普生500-1000mg、对乙酰氨基酚1000mg）；中重度用曲坦类（舒马曲坦50-100mg口服或6mg皮下、利扎曲坦5-10mg、佐米曲坦2.5-5mg）；恶心呕吐加用甲氧氯普胺10mg或多潘立酮10mg","曲坦类禁忌：冠心病、未控制高血压、偏瘫型偏头痛、脑干先兆、妊娠","预防治疗指征：每月发作大于等于2次、急性期治疗无效或不耐受、特殊类型偏头痛","预防药物：β受体阻滞剂（普萘洛尔40-160mg/d、美托洛尔50-200mg/d，首选）；钙通道阻滞剂（氟桂利嗪5-10mg qn）；抗癫痫药（托吡酯25-100mg/d、丙戊酸钠500-1500mg/d）；抗抑郁药（阿米替林10-75mg qn、文拉法辛75-150mg/d）；CGRP单抗（依瑞奈尤单抗、弗雷米珠单抗，每月皮下注射，用于难治性偏头痛）","预防治疗需足量足疗程（至少3个月），有效后维持6-12个月再逐渐减量","月经期偏头痛：月经前2天开始用非甾体抗炎药或曲坦类预防","避免药物过度使用：急性止痛药每月不超过10-15天"],"drug_recommendations":[],"non_pharmacological":["记录头痛日记：记录发作时间、诱因、症状、用药效果，帮助识别诱因和调整治疗","规律作息：固定睡眠时间，避免熬夜和过度睡眠，避免长时间午睡","饮食管理：避免已知诱因食物（巧克力、奶酪、红酒、加工肉类、味精），规律进餐，避免空腹","适度运动：每周3-5次有氧运动（快走、游泳、骑行），减少发作频率","压力管理：放松训练、冥想、瑜伽、生物反馈，避免情绪剧烈波动","避免诱因：强光、噪音、强烈气味、天气剧烈变化","戒烟限酒：避免红酒和过量饮酒","咖啡因管理：避免突然戒断（可诱发头痛），控制每日摄入量","颈部放松：颈肩肌肉紧张可诱发，热敷和按摩放松","保持良好心态，避免焦虑（焦虑本身是诱因）"],"complications":["慢性偏头痛：频发偏头痛进展为慢性，每月头痛大于等于15天，严重影响生活质量","药物过度使用性头痛：长期频繁使用急性止痛药致头痛加重和频率增加，需逐渐停用过度使用的药物","偏头痛持续状态：发作持续大于72小时，需急诊处理（静脉输液、止吐、镇静）","偏头痛性梗死：先兆症状持续大于60分钟伴影像学梗死灶，罕见但严重","癫痫：偏头痛患者癫痫发生率增加","抑郁焦虑：偏头痛患者合并抑郁焦虑比例高，需同时治疗","认知功能：长期频繁发作可能影响认知功能","药物不良反应：曲坦类致胸闷头晕感觉异常；预防药致嗜睡体重增加认知影响（托吡酯）、低血压心动过缓（β阻滞剂）","跌倒：眩晕和头晕发作时易跌倒"],"monitoring":["诊断时：详细头痛病史、头痛日记、神经系统查体、头颅MRI（排除继发性头痛）、血压、血沉（老年排除颞动脉炎）","急性期治疗：评估用药效果和不良反应，记录头痛日记","预防治疗：用药前查基线（血压、心率、肝肾功能、体重、情绪），用药后每4-8周评估疗效和不良反应，至少3个月评估是否有效","慢性偏头痛：定期评估头痛频率、用药天数、生活质量（HIT-6量表、MIDAS量表）","药物过度使用性头痛：监测急性止痛药使用天数，超过10-15天/月需干预","长期：每年复查神经系统查体，必要时影像学复查（症状变化时）","共病筛查：定期筛查抑郁焦虑、睡眠障碍、癫痫"],"special_populations":["孕妇：曲坦类和多数预防药禁用，急性期用对乙酰氨基酚，预防用普萘洛尔（需评估），避免丙戊酸钠（致畸）","哺乳期：对乙酰氨基酚和布洛芬安全，曲坦类可使用（舒马曲坦乳汁分泌少），避免麦角胺","儿童青少年：诊断标准同成人但持续时间可短（1-72小时），预防药需专科评估，优先生活方式干预","老年人：需排除颞动脉炎（血沉、颞动脉超声），曲坦类心血管风险高需谨慎，预防药注意体位性低血压和跌倒","心血管疾病：曲坦类禁忌（冠心病、未控制高血压），预防用β阻滞剂需评估心功能","肝肾功能不全：根据肝肾功能调整药物剂量，避免肝毒性药物","癫痫患者：避免使用降低癫痫阈值的药物（曲坦类相对安全），优先丙戊酸钠或托吡酯预防","驾驶：急性期发作时避免驾驶，预防药致嗜睡者也需谨慎"],"references":["中华医学会神经病学分会. 偏头痛诊治指南（2024）","国际头痛疾病分类第3版（ICHD-3）","AAN/AHS偏头痛预防治疗指南"]},{"name":"阻塞性睡眠呼吸暂停诊治指南（2024）","category":"呼吸内科","scope":"成人阻塞性睡眠呼吸暂停（OSA）的筛查、诊断、严重程度分级和治疗管理。","diagnosis":["临床表现：打鼾（响亮、不规律）、呼吸暂停（目击）、夜间憋醒、白天嗜睡（ESS评分大于10分）、晨起头痛、口干、注意力不集中、记忆力下降、夜尿增多","高危因素：肥胖（BMI大于28）、颈围粗（男性大于43cm女性大于38cm）、腺样体扁桃体肥大、下颌后缩、鼻中隔偏曲、饮酒、镇静催眠药、吸烟、家族史","筛查量表：STOP-Bang问卷（大于等于3分高危）、Berlin问卷、Epworth嗜睡量表（ESS）","多导睡眠监测（PSG）：诊断金标准，监测脑电、眼电、肌电、心电、血氧、口鼻气流、胸腹运动","睡眠呼吸暂停低通气指数（AHI）：每小时呼吸暂停+低通气次数","鉴别：中枢性睡眠呼吸暂停（无呼吸努力）、肥胖低通气综合征、发作性睡病、不宁腿综合征、甲状腺功能减退","并发症：高血压（难治性）、冠心病、心律失常（房颤）、脑卒中、2型糖尿病、认知障碍"],"staging":["按AHI分级：轻度（AHI 5-14.9次/小时）、中度（AHI 15-29.9）、重度（AHI大于等于30）","按最低血氧：轻度（大于等于85%）、中度（80-84%）、重度（小于80%）","按临床表型：阻塞性（最常见）、中枢性、混合性","按病因：原发性（肥胖、解剖狭窄）、继发性（甲减、肢端肥大症、神经肌肉疾病）","合并症：OSA合并高血压、冠心病、房颤、脑卒中、糖尿病、肥胖低通气综合征"],"key_points":["持续气道正压通气（CPAP）：中重度OSA首选治疗，每晚使用大于4小时，压力滴定确定最佳压力，自动调压CPAP（APAP）更舒适","口腔矫治器：轻中度OSA或不能耐受CPAP者，下颌前移装置，需口腔科定制","药物：目前无特效药物；莫达非尼/阿莫达非尼用于CPAP治疗后仍有白天嗜睡者；滴鼻剂减轻鼻塞（辅助）","手术治疗：腺样体扁桃体切除术（儿童首选）、腭咽成形术（UPPP）、下颌前移术、舌下神经刺激术（Inspire，适合不能耐受CPAP者）","减重：肥胖者减重5-10%可显著改善AHI","体位治疗：侧卧位睡眠（适合体位性OSA，仰卧AHI是侧卧2倍以上）","氧疗：不单独用于OSA（可加重CO2潴留），合并低氧血症时可与CPAP联用","合并症治疗：控制血压、血糖、心律失常，治疗甲减","避免饮酒和镇静催眠药（加重上气道塌陷）"],"drug_recommendations":[],"non_pharmacological":["减重：控制饮食+运动，BMI目标小于24，腰围男性小于90cm女性小于85cm","睡眠体位：侧卧位睡眠，可使用体位枕头或背部缝网球防止仰卧","戒烟限酒：戒烟减轻气道炎症，睡前3小时避免饮酒","避免镇静药：苯二氮䓬类、巴比妥类可加重OSA，避免睡前使用","规律作息：固定睡眠时间，保证7-8小时睡眠，避免熬夜","鼻腔护理：生理盐水洗鼻，保持鼻腔通畅","口腔护理：保持口腔卫生，治疗牙周病","驾驶安全：白天嗜睡者避免驾驶和高空作业，CPAP治疗后评估嗜睡改善情况","定期随访：评估CPAP依从性（每晚使用时间）和疗效","家庭监测：可使用便携式睡眠监测仪随访"],"complications":["心脑血管疾病：高血压（难治性）、冠心病、心肌梗死、心律失常（房颤、室性心律失常）、心力衰竭、脑卒中（风险增加2倍）","代谢综合征：胰岛素抵抗、2型糖尿病、血脂异常","认知功能障碍：长期缺氧致注意力记忆力下降，增加痴呆风险","交通事故：白天嗜睡致反应迟钝，事故风险增加2-7倍","性功能障碍：男性勃起功能障碍，女性性欲减退","胃食管反流：夜间腹压变化加重反流","抑郁焦虑：OSA患者抑郁发生率高","夜间猝死：严重OSA夜间心律失常和缺氧致猝死","围手术期风险：OSA患者术后呼吸并发症增加，需围手术期CPAP","CPAP不良反应：面罩漏气、皮肤压痕、鼻腔干燥、腹胀（吞气）、幽闭恐惧"],"monitoring":["诊断时：PSG（金标准）或便携式睡眠监测（初筛）、ESS嗜睡量表、STOP-Bang问卷、BMI、颈围、血压、甲状腺功能（排除甲减）","CPAP治疗：压力滴定（实验室或自动），治疗后1-3个月评估依从性（机器数据：使用时间、AHI、漏气量）和嗜睡改善","稳定期：每3-6个月随访，评估CPAP使用时间（目标每晚大于4小时，大于70%天数）、体重变化、血压、嗜睡评分","口腔矫治器：每6-12个月口腔科复查，评估牙齿和颞下颌关节","手术后：术后3-6个月复查PSG评估手术效果，部分患者需联合CPAP","长期：每年复查血压、血糖、血脂、心电图，评估心脑血管并发症","家庭监测：便携式设备可用于随访和疗效评估"],"special_populations":["孕妇：OSA可加重妊娠期高血压和子痫前期，CPAP治疗相对安全，需专科评估","儿童：腺样体扁桃体肥大是主要病因，腺样体扁桃体切除术首选，肥胖儿童需减重","老年人：症状不典型（嗜睡可能被误认为衰老），合并心脑血管病多，CPAP耐受性需评估","肥胖患者：减重是基础，严重肥胖可考虑减重手术（同时改善OSA）","甲状腺功能减退：甲减可致黏液性水肿加重气道狭窄，需同时治疗甲减","肢端肥大症：生长激素过多致舌体肥大和气道狭窄，需治疗原发病","驾驶员和高空作业者：白天嗜睡是安全隐患，需积极治疗并评估工作能力","围手术期患者：术前筛查OSA，围手术期继续CPAP，减少术后呼吸并发症"],"references":["中华医学会呼吸病学分会. 阻塞性睡眠呼吸暂停诊治指南（2024）","2023 AASM成人OSA临床实践指南","ESRS睡眠呼吸暂停指南"]},{"name":"肺结核诊断和治疗指南（2024）","category":"感染科","scope":"成人肺结核的诊断、分型、抗结核治疗方案和管理。","diagnosis":["临床表现：咳嗽咳痰大于2周、咯血或痰中带血、午后低热、盗汗、乏力、体重下降、胸痛、呼吸困难","体征：可无阳性体征，或患侧呼吸音减低、湿啰音、叩诊浊音，大量胸腔积液时患侧胸廓饱满","影像学：胸部CT（首选）显示上叶尖后段、下叶背段斑片影、结节影、空洞影、纤维条索影、钙化灶；粟粒性肺结核显示三均匀粟粒结节","痰抗酸杆菌涂片：快速筛查，阳性提示传染性","痰结核分枝杆菌培养：诊断金标准，需2-8周","分子生物学检测：Xpert MTB/RIF（快速检测结核菌和利福平耐药）、GeneXpert、PCR","结核菌素试验（PPD）：阳性提示感染或接种卡介苗，不能区分活动性和潜伏性","γ-干扰素释放试验（IGRA）：T-SPOT.TB或QFT，阳性提示结核感染，不能区分活动性和潜伏性","鉴别：肺炎（急性起病，抗感染有效）、肺癌（中老年，痰找癌细胞、肿瘤标志物、PET-CT）、肺脓肿（大量脓臭痰）、支气管扩张"],"staging":["按病变部位：原发性肺结核（原发综合征，儿童多见）、血行播散性肺结核（急性粟粒性、亚急性、慢性）、继发性肺结核（浸润性、空洞性、干酪性肺炎、结核球、纤维空洞性，成人最常见）、结核性胸膜炎、气管支气管结核","按治疗史：初治肺结核（未治疗或治疗小于1个月）、复治肺结核（治疗大于等于1个月失败或复发）、耐药肺结核（利福平耐药RR-TB、耐多药MDR-TB、广泛耐药XDR-TB）","按传染性：涂阳肺结核（痰涂片阳性，传染性强）、涂阴肺结核（痰涂片阴性但培养或分子生物学阳性）","按病情：轻症、重症（高热、呼吸困难、咯血、合并肺外结核）"],"key_points":["初治方案：2HRZE/4HR（强化期2个月异烟肼H+利福平R+吡嗪酰胺Z+乙胺丁醇E，巩固期4个月H+R）；每日顿服，或强化期每日+巩固期每周3次（2HRZE/4H3R3）","复治方案：2HRZES/6HRE（强化期2个月H+R+Z+E+链霉素S，巩固期6个月H+R+E），或根据药敏调整","利福平耐药（RR-TB）/耐多药（MDR-TB）：全口服短程方案（BPaL/M：贝达喹啉+普托马尼+利奈唑胺±异烟肼），或长程方案（至少4种有效药物，疗程18-20个月）","药物剂量：异烟肼300mg qd（5mg/kg），利福平450-600mg qd（10mg/kg），吡嗪酰胺1500mg qd（25mg/kg），乙胺丁醇750mg qd（15mg/kg）","对症治疗：咯血用氨甲环酸、垂体后叶素（大咯血），必要时支气管动脉栓塞；高热用退热剂；胸腔积液多者穿刺抽液","糖皮质激素：仅用于结核性脑膜炎、心包炎、大量胸腔积液、严重急性粟粒性肺结核，需在有效抗结核基础上使用","潜伏性结核感染（LTBI）：异烟肼6-9个月，或利福平3-4个月，或3HR方案","保肝治疗：抗结核药可致肝损伤，定期查肝功能，异常时加用保肝药（水飞蓟宾、双环醇），严重肝损伤需停药调整方案"],"drug_recommendations":[],"non_pharmacological":["隔离：涂阳肺结核患者需呼吸道隔离至痰菌转阴，戴口罩，保持室内通风","营养支持：高蛋白、高热量、高维生素饮食，纠正营养不良（营养不良影响疗效）","休息：急性期卧床休息，病情稳定后逐渐增加活动","戒烟戒酒：吸烟加重肺损伤，饮酒增加肝损伤风险","规范服药：直接督导下服药（DOTS），确保依从性，不可自行停药或漏服","定期复查：每月查痰涂片、肝肾功能、血常规，每2-3个月复查胸部CT","避免传染：不随地吐痰，痰液消毒处理，咳嗽打喷嚏掩口鼻，密切接触者筛查","心理支持：结核病治疗周期长，易焦虑，需心理疏导","疫苗接种：新生儿接种卡介苗（预防重症结核，对成人肺结核保护力有限）","职业防护：医护人员戴N95口罩，病房负压通风"],"complications":["咯血：常见并发症，大咯血可致窒息和失血性休克，需紧急处理（患侧卧位、镇静、止血、支气管动脉栓塞）","自发性气胸：肺内空洞或病灶破裂致气胸，需胸腔闭式引流","呼吸衰竭：重症肺结核或广泛肺纤维化致呼吸衰竭，需氧疗或机械通气","肺心病：慢性纤维空洞性肺结核致肺动脉高压和右心衰竭","继发感染：肺结核基础上合并细菌或真菌感染","肺外结核：结核性脑膜炎（最严重）、骨结核、肾结核、肠结核、生殖器结核","药物不良反应：异烟肼致周围神经炎（维生素B6预防）、肝损伤；利福平致肝损伤、橙色体液、药物相互作用（肝酶诱导）；吡嗪酰胺致高尿酸血症、肝损伤、关节痛；乙胺丁醇致视神经炎（视力下降、色觉障碍）；链霉素致耳毒性和肾毒性","耐药结核：不规范治疗致耐药，治疗困难、疗程长、费用高、预后差","死亡：重症结核、大咯血窒息、结核性脑膜炎死亡率高"],"monitoring":["治疗前：痰涂片+培养+Xpert（明确诊断和耐药）、胸部CT、血常规、肝肾功能、尿酸、视力视野（乙胺丁醇）、听力（链霉素）、HIV检测、乙肝丙肝","治疗期间：每月复查痰涂片（评估传染性）、肝肾功能、血常规、尿酸；每2-3个月复查胸部CT（评估病灶吸收）","视力视野：用乙胺丁醇者每月查视力和红绿色觉，出现视力下降立即停药","听力：用链霉素者定期查听力，出现耳鸣听力下降立即停药","疗效评估：2个月末痰菌转阴率、疗程结束时痰菌转阴率、病灶吸收率、空洞闭合率","停药后：定期随访2-3年，每6个月查痰和胸片，监测复发","耐药结核：每月查痰培养，每3个月查药敏，监测药物不良反应（贝达喹啉QT间期、利奈唑胺骨髓抑制和周围神经炎）","密切接触者：PPD或IGRA筛查，阳性者评估LTBI并预防治疗"],"special_populations":["孕妇：妊娠合并结核需治疗，避免链霉素（耳毒性），首选HRZE方案（乙胺丁醇相对安全），吡嗪酰胺孕期使用需权衡，哺乳期可继续抗结核治疗","儿童：剂量按体重计算，异烟肼10-15mg/kg，利福平10-20mg/kg，吡嗪酰胺30-40mg/kg，乙胺丁醇15-25mg/kg（需监测视力），避免喹诺酮类","老年人：肝肾功能减退，药物剂量需调整，密切监测不良反应，乙胺丁醇视神经炎风险高","HIV感染者：结核是HIV最常见机会性感染，需同时抗结核和抗病毒治疗（ART），注意免疫重建炎症综合征（IRIS）","肝功能不全：避免肝毒性大的方案，根据肝功能调整药物，密切监测","肾功能不全：链霉素、阿米卡星肾毒性，避免使用，乙胺丁醇需减量","糖尿病患者：结核与糖尿病相互影响，需控制血糖（目标HbA1c小于7%），抗结核治疗疗程可延长","酗酒者：肝损伤风险高，需戒酒，密切监测肝功能"],"references":["中华医学会结核病学分会. 肺结核诊断和治疗指南（2024）","WHO结核病治疗指南（2023更新）","ATS/CDC/IDSA结核病治疗指南"]},{"name":"消化性溃疡诊治指南（2024）","category":"消化内科","scope":"胃和十二指肠溃疡的诊断、Hp根除、抑酸治疗和预防复发。","diagnosis":["临床表现：慢性、周期性、节律性上腹痛；胃溃疡餐后痛（餐后半小时至1小时），十二指肠溃疡空腹痛和夜间痛，进食缓解；可伴反酸、嗳气、恶心、呕吐","体征：上腹部局限性压痛，缓解期可无体征","胃镜检查：诊断金标准，可明确溃疡部位、大小、形态、分期，取活检排除恶性溃疡","幽门螺杆菌（Hp）检测：侵入性（胃镜活检快速尿素酶试验、病理染色、培养）；非侵入性（13C/14C尿素呼气试验、粪便抗原检测、血清抗体）","上消化道钡餐：不能耐受胃镜者，龛影为直接征象","鉴别：胃癌（中老年、体重下降、大便隐血持续阳性、胃镜活检）、功能性消化不良（胃镜正常）、胆囊炎胆石症（右上腹痛、油腻饮食诱发、超声）、冠心病（不典型胸痛、心电图）","并发症：出血（黑便呕血）、穿孔（突发剧烈腹痛、板状腹）、幽门梗阻（呕吐宿食）、癌变（胃溃疡）"],"staging":["按部位：胃溃疡（GU）、十二指肠溃疡（DU）、复合性溃疡、吻合口溃疡","按内镜分期：活动期A（A1厚苔周围黏膜肿胀、A2薄苔周围黏膜集中）、愈合期H（H1苔变薄周围黏膜集中、H2苔基本消失上皮再生）、瘢痕期S（S1红色瘢痕、S2白色瘢痕）","按大小：小溃疡（小于1cm）、大溃疡（1-2cm）、巨大溃疡（大于2cm，胃溃疡需警惕恶性）","按病因：Hp相关性溃疡（最常见，约70-90%）、NSAIDs/阿司匹林相关性溃疡、应激性溃疡、特发性溃疡","按并发症：单纯性溃疡、出血性溃疡、穿孔性溃疡、梗阻性溃疡、可疑恶性溃疡"],"key_points":["Hp根除治疗：铋剂四联方案（PPI+铋剂+两种抗生素，疗程14天），如艾司奥美拉唑20mg bid+枸橼酸铋钾220mg bid+阿莫西林1000mg bid+克拉霉素500mg bid；青霉素过敏者用四环素+甲硝唑或呋喃唑酮方案","抑酸治疗：PPI（艾司奥美拉唑20-40mg qd、雷贝拉唑10-20mg qd、泮托拉唑40mg qd），十二指肠溃疡疗程4-6周，胃溃疡疗程6-8周","胃黏膜保护剂：硫糖铝1g qid、瑞巴派特100mg tid、替普瑞酮50mg tid、铝碳酸镁1g tid（中和胆汁）","NSAIDs相关溃疡：停用NSAIDs，PPI治疗，不能停用者用选择性COX-2抑制剂（塞来昔布）+PPI预防","应激性溃疡预防：危重患者用PPI或H2受体拮抗剂","止血：溃疡出血内镜下止血（注射、钛夹、热凝）+PPI大剂量静推（80mg负荷+8mg/h持续72小时）","维持治疗：反复复发者用PPI半量维持（如奥美拉唑10mg qd或20mg qod）","Hp根除后复查：停药4周后复查尿素呼气试验或粪便抗原，确认根除"],"drug_recommendations":[],"non_pharmacological":["饮食：规律进餐，细嚼慢咽，避免辛辣刺激、过烫、粗糙食物，避免暴饮暴食","戒烟戒酒：吸烟延缓溃疡愈合增加复发，酒精刺激胃黏膜","避免致溃疡药物：NSAIDs（布洛芬、双氯芬酸）、阿司匹林、糖皮质激素，如必须用需PPI保护","休息：急性期注意休息，避免过度劳累和精神紧张","心理调节：精神压力是溃疡诱因，保持心情舒畅，必要时心理疏导","避免空腹服用刺激性药物，餐后服药减少胃黏膜刺激","定期复查胃镜：胃溃疡治疗后复查胃镜确认愈合（排除恶性），十二指肠溃疡有报警症状时复查","保持良好作息，避免熬夜","控制体重，避免肥胖（增加反流风险）","避免饮用浓茶、浓咖啡、碳酸饮料"],"complications":["上消化道出血：最常见并发症，表现为黑便、呕血、头晕乏力，严重者休克，需急诊内镜止血","穿孔：突发剧烈腹痛、板状腹、肝浊音界消失、膈下游离气体，需急诊手术（腹腔镜或开腹修补）","幽门梗阻：呕吐宿食、胃型、振水音，先胃肠减压+PPI治疗，瘢痕性梗阻需手术","癌变：胃溃疡癌变率约1%，十二指肠溃疡几乎不癌变，胃溃疡需活检排除恶性，治疗后复查胃镜","溃疡复发：Hp未根除、继续用NSAIDs、吸烟饮酒是复发原因，根除Hp可显著降低复发率","难治性溃疡：规范治疗8周不愈合，需排查恶性、Hp耐药、胃泌素瘤（Zollinger-Ellison综合征）、克罗恩病","药物不良反应：PPI长期用致骨质疏松、维生素B12缺乏、肠道菌群紊乱、肾脏损伤；铋剂长期用致铋蓄积（疗程不超过8周）；抗生素致肠道菌群紊乱和耐药"],"monitoring":["诊断时：胃镜+活检（胃溃疡必取活检）、Hp检测、血常规、大便隐血、肝肾功能","治疗期间：4-6周（DU）或6-8周（GU）后复查胃镜评估愈合，胃溃疡必须复查确认愈合和排除恶性","Hp根除后：停药4周后复查尿素呼气试验或粪便抗原，确认根除成功","长期服用PPI者：定期监测骨密度、维生素B12、肾功能、电解质（低镁）","出血患者：复查血常规（Hb变化）、大便隐血，评估再出血风险（Rockall评分）","溃疡复发：复查胃镜和Hp，评估复发原因","胃泌素瘤可疑：查空腹胃泌素（大于1000pg/ml）、胃酸分泌量，腹部CT/MRI定位肿瘤","报警症状（消瘦、贫血、黑便、吞咽困难、呕吐）：及时胃镜检查排除恶性"],"special_populations":["老年人：症状不典型，巨大溃疡和恶性溃疡多见，NSAIDs使用多，出血和穿孔风险高，PPI需注意与其他药物相互作用","孕妇：PPI相对安全（奥美拉唑B类），铋剂和某些抗生素（四环素、呋喃唑酮）禁用，需产科和消化科共管","儿童：少见，多与Hp感染相关，治疗方案按体重调整","肾功能不全：铋剂需避免（蓄积中毒），PPI一般安全，H2受体拮抗剂需减量","肝功能不全：PPI经肝代谢，严重肝功不全需减量，避免肝毒性抗生素","心血管疾病：服用阿司匹林和氯吡格雷者，PPI选择泮托拉唑或雷贝拉唑（不影响氯吡格雷活化），避免奥美拉唑","胃大部切除术后：吻合口溃疡需排除胃泌素瘤，PPI治疗疗程延长","长期服用NSAIDs者：评估胃肠道风险，高危者用PPI或选择性COX-2抑制剂预防"],"references":["中华医学会消化病学分会. 消化性溃疡诊治指南（2024）","幽门螺杆菌感染处理共识报告（2022）","ACG溃疡出血管理指南"]},{"name":"肝硬化诊治指南（2024）","category":"消化内科","scope":"成人肝硬化的病因诊断、分期、并发症防治和长期管理。","diagnosis":["临床表现：代偿期可无症状或仅有乏力、食欲减退、腹胀；失代偿期出现黄疸、腹水、脾大、食管胃底静脉曲张、肝性脑病、出血倾向","体征：肝病面容、蜘蛛痣、肝掌、男性乳房发育、腹壁静脉曲张、腹水、下肢水肿、脾大","实验室：肝功能异常（ALT/AST升高、白蛋白降低、胆红素升高、凝血酶原时间延长）、血小板减少（脾功能亢进）、球蛋白升高","影像学：腹部超声（肝表面凹凸不平、肝内回声增粗、门静脉增宽、脾大、腹水）；CT/MRI（肝硬化结节、肝癌筛查）；肝脏弹性成像（FibroScan，评估肝纤维化程度）","胃镜：筛查食管胃底静脉曲张","肝穿刺活检：诊断金标准（但凝血差者风险高）","病因：乙肝（最常见我国）、丙肝、酒精性、非酒精性脂肪性（NASH）、自身免疫性、胆汁淤积性、遗传代谢性（Wilson、血色病）、药物性","鉴别：慢性肝炎（无门脉高压表现）、肝癌（AFP升高、影像学占位）、其他原因腹水（结核、肿瘤、心衰、肾病）"],"staging":["按肝功能：代偿期肝硬化（Child-Pugh A级，无腹水、出血、肝性脑病）、失代偿期肝硬化（Child-Pugh B/C级，出现腹水、出血、肝性脑病、黄疸）","按Child-Pugh分级：A级（5-6分，预后好）、B级（7-9分，中等）、C级（10-15分，预后差）","按病因：病毒性（乙肝/丙肝）、酒精性、脂肪性、自身免疫性、胆汁淤积性、遗传代谢性、隐源性","按并发症：单纯肝硬化、肝硬化合并腹水、合并食管胃底静脉曲张出血、合并肝性脑病、合并肝癌、合并肝肾综合征","肝癌筛查：每6个月查腹部超声+AFP"],"key_points":["病因治疗：乙肝用核苷（酸）类似物（恩替卡韦、替诺福韦、丙酚替诺福韦）长期抗病毒；丙肝用直接抗病毒药物（DAA，索磷布韦维帕他韦等12周治愈）；酒精性肝硬化严格戒酒；NASH减重和控制代谢；自身免疫性用激素+硫唑嘌呤；胆汁淤积性用熊去氧胆酸","抗纤维化：目前无特效药物，病因治疗是关键，可辅以安络化纤丸、扶正化瘀胶囊、复方鳖甲软肝片（中成药）","腹水治疗：限钠（小于2g/d）、利尿剂（螺内酯+呋塞米，比例100:40mg）、大量放腹水+输白蛋白（每放1L补8g白蛋白）、顽固性腹水用TIPS","食管胃底静脉曲张出血预防：一级预防用非选择性β受体阻滞剂（普萘洛尔10mg tid或卡维地洛6.25mg qd）或内镜套扎；急性出血用生长抑素/奥曲肽+内镜套扎/组织胶+抗生素（头孢曲松）","肝性脑病：去除诱因（感染、出血、便秘、电解质紊乱、镇静药），乳果糖15-30ml tid（保持每日2-3次软便），拉克替醇，利福昔明400mg tid（预防复发），门冬氨酸鸟氨酸","肝肾综合征：停用肾毒性药物，扩容（白蛋白），特利加压素+白蛋白，TIPS，肝移植","自发性腹膜炎：腹水中性粒细胞大于250/mm³，头孢曲松2g qd×5天，白蛋白（第1天1.5g/kg，第3天1g/kg）","营养支持：高蛋白饮食（1.0-1.2g/kg/d，肝性脑病急性期限制蛋白）、高热量（35-40kcal/kg/d）、补充支链氨基酸","肝移植：终末期肝硬化的唯一有效治疗，MELD评分评估优先级"],"drug_recommendations":[],"non_pharmacological":["休息：代偿期可轻体力活动，失代偿期卧床休息","饮食：高热量、高蛋白、高维生素、易消化饮食；腹水者限钠限水；肝性脑病者限制蛋白（急性期）；食管静脉曲张者避免粗糙坚硬食物","严格戒酒：酒精性肝硬化必须完全戒酒，非酒精性也应避免饮酒","避免肝毒性药物：避免不必要的药物，慎用镇静催眠药、非甾体抗炎药、肝毒性抗生素","预防感染：注意饮食卫生，避免受凉，接种流感疫苗、肺炎球菌疫苗","皮肤护理：黄疸致皮肤瘙痒时避免搔抓，温水擦浴，润肤剂","口腔护理：保持口腔卫生，预防感染","定期随访：每3-6个月复查肝功能、凝血、血常规、腹部超声、AFP（肝癌筛查）","避免劳累和情绪激动，保持大便通畅（便秘可诱发肝性脑病）","家庭支持：肝硬化治疗周期长，需家人照护和心理支持"],"complications":["食管胃底静脉曲张破裂出血：最凶险并发症，呕血黑便休克，死亡率高，急诊内镜+药物治疗","肝性脑病：性格改变、行为异常、意识障碍、昏迷，去除诱因+降氨治疗","腹水：腹胀、移动性浊音，利尿剂+放腹水+TIPS","自发性细菌性腹膜炎（SBP）：发热、腹痛、腹水白细胞升高，抗生素+白蛋白","肝肾综合征（HRS）：少尿无尿、血肌酐升高，特利加压素+白蛋白，肝移植","肝癌：肝硬化患者肝癌年发生率2-4%，每6个月超声+AFP筛查","肝肺综合征：呼吸困难、低氧血症，氧疗，肝移植","门静脉血栓：腹痛、腹水加重，抗凝治疗","电解质紊乱：低钠低钾（利尿剂）、代谢性碱中毒（诱发肝性脑病）","肝性骨病：骨质疏松，补充钙和维生素D","死亡：终末期肝硬化多死于出血、肝性脑病、感染、肝肾综合征、肝癌"],"monitoring":["诊断时：肝功能（ALT/AST/ALB/TBIL/PT/INR）、血常规、凝血、乙肝丙肝病毒标志物、自身抗体、免疫球蛋白、血清铁/铜蓝蛋白（排除代谢性）、腹部超声/CT、胃镜（静脉曲张筛查）、肝脏弹性成像、肝穿刺（必要时）","代偿期：每3-6个月复查肝功能、血常规、凝血、腹部超声、AFP","失代偿期：每1-3个月复查，监测腹水、肝性脑病、出血征象","肝癌筛查：每6个月腹部超声+AFP（高危者每3个月）","胃镜：无静脉曲张者每2-3年复查，轻度静脉曲张每年复查，中重度需预防治疗","利尿剂治疗：监测体重、腹围、电解质（钠钾）、肾功能，调整利尿剂剂量","肝性脑病：监测血氨、意识状态、肝功能，评估诱因","TIPS术后：定期复查超声（支架通畅）、肝功能、肝性脑病","肝移植评估：定期MELD评分，符合条件者转诊肝移植中心"],"special_populations":["老年人：合并症多，药物耐受性差，肝癌风险高，需密切筛查","孕妇：妊娠合并肝硬化风险高（静脉曲张出血、流产、早产），需产科和消化科共管，避免使用致畸药物","儿童：多为先天性胆道闭锁、遗传代谢性肝硬化，需儿科专科","酒精性肝硬化：戒酒是关键，戒酒后部分可逆转，需营养支持和心理干预","乙肝肝硬化：长期抗病毒不可停药，定期查HBV-DNA和耐药","丙肝肝硬化：DAA治愈后仍需定期筛查肝癌（肝硬化基础持续存在）","肾功能不全：避免肾毒性药物，利尿剂需谨慎，肝肾综合征需积极处理","大量腹水者：避免剧烈咳嗽和用力（防脐疝破裂），注意脐部护理"],"references":["中华医学会肝病学分会. 肝硬化诊治指南（2024）","AASLD肝硬化实践指南（2023）","EASL肝硬化临床实践指南"]},{"name":"肥胖症诊治指南（2024）","category":"内分泌科","scope":"成人肥胖症的诊断、评估、生活方式干预、药物治疗和手术治疗。","diagnosis":["诊断标准：BMI大于等于28kg/m²为肥胖（中国标准），BMI 24-27.9为超重；中心性肥胖：男性腰围大于等于90cm，女性大于等于85cm","评估：体脂率（男性大于25%女性大于30%）、腰臀比、内脏脂肪面积（CT/MRI）","鉴别：单纯性肥胖（最常见）、继发性肥胖（库欣综合征、甲减、多囊卵巢综合征、下丘脑性肥胖、药物性肥胖）","并发症评估：高血压、糖尿病、血脂异常、脂肪肝、睡眠呼吸暂停、骨关节病、多囊卵巢综合征、肿瘤风险","实验室：血糖、HbA1c、血脂、肝肾功能、尿酸、甲状腺功能、皮质醇（怀疑库欣）、性激素（女性怀疑PCOS）、胰岛素","鉴别库欣综合征：向心性肥胖、满月脸、水牛背、紫纹、高血压、低血钾，查24小时尿游离皮质醇、午夜唾液皮质醇、地塞米松抑制试验"],"staging":["按BMI：超重（24-27.9）、轻度肥胖（28-32）、中度肥胖（32-37）、重度肥胖（大于等于37）","按脂肪分布：中心性肥胖（腹型，内脏脂肪多，代谢风险高）、外周性肥胖（皮下脂肪多）","按病因：单纯性肥胖、继发性肥胖（内分泌、遗传、药物）","按并发症：代谢健康型肥胖（无并发症）、代谢异常型肥胖（合并高血压糖尿病血脂异常脂肪肝）","按年龄：儿童青少年肥胖、成人肥胖、老年肥胖"],"key_points":["生活方式干预是基础，所有肥胖患者均应坚持","减重目标：3-6个月减重5-10%，长期维持","药物治疗指征：BMI大于等于28，或BMI大于等于24合并并发症（高血压、糖尿病、血脂异常、脂肪肝），生活方式干预3-6个月无效","减重药物：GLP-1受体激动剂（司美格鲁肽2.4mg每周皮下注射，减重效果最强；利拉鲁肽3.0mg qd）；奥利司他120mg tid（餐时服，抑制脂肪吸收，注意胃肠道不良反应和脂溶性维生素缺乏）；替尔泊肽（GIP/GLP-1双受体激动剂，减重效果优于司美格鲁肽）","药物治疗需配合生活方式干预，6个月评估疗效（减重小于5%考虑换药或停药）","手术治疗指征：BMI大于等于37.5，或BMI大于等于32.5合并并发症，内科治疗无效","手术方式：袖状胃切除术（最常用）、Roux-en-Y胃旁路术、可调节胃束带术","继发性肥胖：治疗原发病（库欣手术、甲减替代、PCOS调经）","合并症治疗：同时控制血压血糖血脂，治疗脂肪肝和睡眠呼吸暂停"],"drug_recommendations":[],"non_pharmacological":["饮食控制：减少总热量摄入（每日减少500-750kcal），高蛋白（1.2-1.6g/kg）、低升糖指数碳水、充足膳食纤维、限制饱和脂肪和添加糖；可采用限能量平衡膳食、轻断食（5:2）、地中海饮食","运动：每周至少150分钟中等强度有氧运动（快走、游泳、骑行），配合每周2-3次抗阻训练（增加肌肉量），减少久坐","行为干预：自我监测体重和饮食、设定合理目标、刺激控制（避免高热量食物环境）、问题解决、认知重构、社会支持","规律作息：保证7-8小时睡眠，避免熬夜（睡眠不足增加食欲）","心理支持：肥胖患者易自卑抑郁，需心理疏导，必要时认知行为治疗","避免极端节食：极低热量饮食（小于800kcal/d）需在医生监督下短期使用","戒烟限酒：戒烟后体重可能增加，需提前干预；酒精热量高且增加食欲","家庭参与：家人共同健康饮食和运动，提高依从性","定期称重：每周固定时间称重，记录变化","维持期：减重后需长期维持，继续健康生活方式，避免反弹"],"complications":["2型糖尿病：肥胖是T2DM最重要危险因素，减重可改善血糖甚至缓解糖尿病","高血压：肥胖致血容量增加和胰岛素抵抗，减重可降低血压","血脂异常：高甘油三酯、低HDL、小而密LDL增加","非酒精性脂肪肝：肥胖最常见肝脏并发症，可进展为脂肪性肝炎、肝硬化","睡眠呼吸暂停：肥胖致上气道狭窄，减重可改善","多囊卵巢综合征：肥胖加重胰岛素抵抗和高雄激素，影响月经和生育","骨关节病：负重关节（膝、髋）磨损增加，骨关节炎风险高","痛风：肥胖致尿酸生成增加，高尿酸血症和痛风风险增加","肿瘤：肥胖增加乳腺癌、子宫内膜癌、结直肠癌、肝癌等多种肿瘤风险","胃食管反流：肥胖增加腹压，加重反流","药物不良反应：GLP-1致恶心呕吐腹泻便秘、胰腺炎、胆囊疾病；奥利司他致油性便、排便急、脂溶性维生素缺乏；手术致营养不良、倾倒综合征、吻合口漏"],"monitoring":["诊断时：身高体重BMI、腰围、体脂率、血压、血糖HbA1c、血脂、肝肾功能、尿酸、甲状腺功能、心电图、腹部超声（脂肪肝）、睡眠评估（必要时）","生活方式干预：每2-4周随访，监测体重、饮食、运动，调整方案","药物治疗：用药前查基线（血糖、血脂、肝肾功能、甲状腺、胰腺），用药后每4-8周评估疗效和不良反应，6个月评估是否继续","手术前：全面评估（心肺功能、营养、心理），术后定期随访营养状况（蛋白质、维生素、微量元素）","长期：每3-6个月复查体重、腰围、血压、血糖、血脂、肝功能、腹部超声","减重维持期：定期随访防止反弹，体重增加超过3%及时干预","并发症监测：定期筛查糖尿病、高血压、脂肪肝、睡眠呼吸暂停、骨关节病"],"special_populations":["孕妇：孕期不建议减重，需控制体重增长速度（根据孕前BMI），避免使用减重药物和手术","儿童青少年：优先生活方式干预，药物需严格评估（12岁以上可用奥利司他，16岁以上可用GLP-1），手术需极重度肥胖且合并严重并发症","老年人：减重需谨慎，避免肌肉流失（肌少症），目标是改善功能而非单纯减重，配合抗阻训练","哺乳期：不建议减重药物，需保证营养和乳汁分泌","多囊卵巢综合征患者：减重5-10%可改善月经和排卵，提高生育力","糖尿病患者：减重可改善血糖，注意低血糖，调整降糖药剂量","心血管疾病患者：运动需评估心功能，避免剧烈运动","暴食症患者：需先治疗进食障碍，再进行减重干预"],"references":["中华医学会内分泌学分会. 肥胖症诊治指南（2024）","中国超重/肥胖医学营养治疗指南（2023）","AACE/ACE肥胖症临床实践指南"]},{"name":"急性肾损伤诊治指南（2024）","category":"肾内科","scope":"成人急性肾损伤（AKI）的早期识别、分期、病因治疗和肾脏替代治疗。","diagnosis":["诊断标准：48小时内血肌酐升高大于等于0.3mg/dl（26.5μmol/L），或7天内血肌酐升至基础值1.5倍以上，或尿量小于0.5ml/kg/h持续6小时","分期：1期（Cr升高1.5-1.9倍或升高大于等于0.3mg/dl，尿量小于0.5ml/kg/h×6-12h）、2期（Cr 2.0-2.9倍，尿量小于0.5×大于12h）、3期（Cr大于3倍或大于4mg/dl或开始透析，尿量小于0.3×大于24h或无尿大于12h）","病因分类：肾前性（低血容量、心衰、肝肾综合征，占40-70%）、肾性（急性肾小管坏死ATN最常见、急性间质性肾炎、肾小球疾病、血管性）、肾后性（尿路梗阻，占5-10%）","鉴别肾前性和ATN：尿钠（肾前性小于20mmol/L，ATN大于40）、FENa（肾前性小于1%，ATN大于2%）、尿渗透压（肾前性大于500，ATN小于350）、尿沉渣（ATN可见肾小管上皮细胞管型）","肾后性：影像学（超声、CT）发现肾盂积水、输尿管扩张","危险因素：高龄、慢性肾病、糖尿病、高血压、心衰、肝硬化、大手术、脓毒症、肾毒性药物"],"staging":["按分期：1期（轻度）、2期（中度）、3期（重度，需透析风险高）","按病因：肾前性AKI、肾性AKI（ATN、AIN、肾小球、血管）、肾后性AKI","按病程：起始期（数小时至数天，肾灌注下降）、维持期（1-2周，少尿或无尿）、恢复期（数天至数月，尿量增多，肾功能逐渐恢复）","按尿量：少尿型（尿量小于400ml/d）、非少尿型（尿量正常或增多，预后相对好）、无尿型（尿量小于100ml/d，预后差）","按严重程度：单纯AKI、AKI合并多器官功能障碍（MODS）"],"key_points":["去除病因和诱因是治疗关键","肾前性：快速补液（晶体液）纠正低血容量，心衰者改善心功能，避免过度利尿","肾后性：解除梗阻（留置尿管、输尿管支架、经皮肾穿刺造瘘），梗阻解除后注意利尿期电解质紊乱","ATN：维持水电解质酸碱平衡，营养支持，避免肾毒性药物，等待肾功能恢复","急性间质性肾炎（AIN）：停用致敏药物，必要时糖皮质激素（泼尼松1mg/kg/d，逐渐减量）","肾小球疾病所致AKI：根据病理类型用激素+免疫抑制剂（如急进性肾炎用甲泼尼龙冲击+环磷酰胺+血浆置换）","血管性：肾动脉栓塞/血栓需溶栓或取栓，血栓性微血管病需血浆置换","高钾血症：紧急处理（钙剂稳定心肌、胰岛素+葡萄糖降钾、碳酸氢钠、聚苯乙烯磺酸钙/环硅酸锆钠、严重者透析）","代谢性酸中毒：碳酸氢钠，严重者透析","肾脏替代治疗（RRT）：指征包括严重高钾（大于6.5mmol/L）、严重酸中毒（pH小于7.2）、容量负荷过重肺水肿、尿毒症脑病/心包炎、某些药物中毒；方式包括间歇性血液透析（IHD）、连续性肾脏替代治疗（CRRT，重症首选）、腹膜透析","避免肾毒性药物：氨基糖苷类、造影剂、非甾体抗炎药、万古霉素（需监测血药浓度）、含马兜铃酸中药"],"drug_recommendations":[],"non_pharmacological":["监测：密切监测尿量、血肌酐、电解质、血压、体重、出入量","液体管理：量出为入（前一日尿量+500ml不显性失水），避免容量不足和容量过负荷","营养支持：保证热量（25-30kcal/kg/d），蛋白质0.8-1.0g/kg/d（透析者1.0-1.5g/kg/d），避免高蛋白增加氮质血症","休息：急性期卧床休息，减少代谢","饮食：低盐（小于3g/d）、低钾（少尿期）、低磷、优质蛋白，恢复期增加营养","避免感染：AKI患者感染风险高，注意无菌操作，预防肺部和尿路感染","造影剂肾病预防：水化（等渗晶体液）、停用肾毒性药、使用等渗低渗造影剂、最小剂量、N-乙酰半胱氨酸（辅助）","药物剂量调整：根据肾功能调整经肾排泄药物剂量，避免药物蓄积中毒","心理支持：AKI起病急，患者易焦虑，需解释病情和治疗方案","恢复期：逐渐增加活动量，定期复查肾功能（部分可进展为慢性肾病）"],"complications":["高钾血症：最危险电解质紊乱，可致心律失常和心脏骤停，需紧急处理","代谢性酸中毒：深大呼吸、意识障碍，碳酸氢钠或透析纠正","容量过负荷和肺水肿：呼吸困难、低氧血症，利尿剂无效时透析","尿毒症脑病：意识障碍、抽搐、昏迷，透析治疗","尿毒症心包炎：胸痛、心包摩擦音，可致心包填塞，紧急透析","感染：AKI患者免疫力下降，肺部和尿路感染常见，是主要死亡原因之一","多器官功能障碍综合征（MODS）：严重AKI常合并呼吸、循环、凝血、消化等多器官衰竭","慢性肾脏病：部分AKI肾功能不能完全恢复，进展为CKD甚至终末期肾病","电解质紊乱：低钠、低钙、高磷、高镁（少尿期），低钾（多尿期）","出血：尿毒症致血小板功能异常，消化道出血风险增加","死亡：重症AKI合并MODS死亡率高（30-50%）"],"monitoring":["诊断时：血肌酐（动态监测）、尿常规+尿沉渣、尿钠+尿渗透压+FENa、电解质、血气、凝血、血常规、肾功能（eGFR）、泌尿系超声（排除梗阻）、肾血管超声（怀疑肾动脉狭窄）、肾穿刺（不明原因肾性AKI）","急性期：每4-8小时监测尿量、血压、生命体征；每日查血肌酐、电解质、血气；每1-2天查血常规、凝血、肝肾功能","RRT期间：监测透析充分性（Kt/V）、电解质、凝血（抗凝）、血流动力学、体温","恢复期：每周查血肌酐、电解质，监测肾功能恢复情况，多尿期注意脱水和低钾","长期随访：AKI恢复后每3-6个月复查肾功能、尿常规、血压，监测是否进展为慢性肾病","病因排查：不明原因AKI需查自身抗体、补体、免疫球蛋白、蛋白电泳、ANCA、抗GBM抗体","肾穿刺后：监测血压、尿常规（出血），卧床24小时"],"special_populations":["老年人：肾功能储备差，药物需调整剂量，AKI恢复慢，易进展为慢性肾病，避免肾毒性药物","孕妇：妊娠期AKI病因特殊（子痫前期、HELLP、产后出血、急性脂肪肝），需产科和肾内科共管，避免致畸药物","儿童：腹泻脱水致肾前性AKI常见，溶血尿毒综合征（HUS）需血浆置换","慢性肾病基础：AKI-on-CKD常见，恢复差，需评估基础肾功能，避免肾毒性药物","脓毒症患者：脓毒症相关AKI（S-AKI）最常见，早期目标导向治疗，CRRT优于IHD（血流动力学不稳定者）","造影剂使用者：检查前评估肾功能，高危者水化预防，避免短期内重复造影","大手术后患者：术中低血压和输血是AKI危险因素，术后监测尿量和肌酐","服用肾毒性药物者：立即停用，评估肾功能，必要时拮抗剂或加速清除"],"references":["中华医学会肾脏病学分会. 急性肾损伤诊治指南（2024）","KDIGO急性肾损伤临床实践指南（2012更新）","ICU患者急性肾损伤防治专家共识"]},{"name":"脓毒症诊治指南（2024）","category":"急诊科","scope":"成人脓毒症和感染性休克的早期识别、集束化治疗和器官功能支持。","diagnosis":["脓毒症定义：感染引起的危及生命的器官功能障碍，SOFA评分急性增加大于等于2分","感染性休克：脓毒症伴持续性低血压，需血管活性药维持MAP大于等于65mmHg，且血乳酸大于2mmol/L（充分液体复苏后）","临床表现：发热（大于38.3℃）或低体温（小于36℃）、心率增快（大于90次/分）、呼吸增快（大于20次/分）、意识改变、皮肤湿冷花斑、少尿","筛查工具：qSOFA（呼吸大于等于22、意识改变、收缩压小于等于100，大于等于2项提示脓毒症高危）、NEWS评分、MEWS评分","实验室：白细胞升高或降低、CRP升高、降钙素原（PCT）升高、血乳酸升高（大于2mmol/L提示组织灌注不足）、凝血异常（DIC）、肝肾功能异常","病原学：血培养（需氧+厌氧，两套，不同部位）、尿培养、痰培养、脑脊液、感染部位分泌物培养","影像学：胸片/CT（肺炎）、腹部CT（腹腔感染）、超声（胆道、泌尿系）","鉴别：全身炎症反应综合征（SIRS，非感染性）、心源性休克、低血容量休克、过敏性休克、神经源性休克、肾上腺危象"],"staging":["按严重程度：脓毒症（器官功能障碍SOFA大于等于2）、感染性休克（低血压+高乳酸）、多器官功能障碍综合征（MODS）","按感染部位：肺部感染（最常见）、腹腔感染、泌尿系感染、皮肤软组织感染、血流感染、中枢神经系统感染","按病原体：细菌（革兰阴性菌、革兰阳性菌）、真菌（念珠菌、曲霉）、病毒（流感、新冠）、混合感染","按耐药情况：普通感染、多重耐药菌感染（MDR）、广泛耐药菌感染（XDR）","按免疫状态：免疫正常宿主、免疫抑制宿主（激素、化疗、移植、HIV）"],"key_points":["1小时集束化治疗（Hour-1 Bundle）：测量血乳酸、留取血培养（抗生素前）、广谱抗生素、晶体液30ml/kg（低血压或乳酸大于4）、血管活性药（液体复苏后仍低血压用去甲肾上腺素）","抗生素：1小时内启动经验性广谱抗生素（覆盖可能病原体），脓毒症休克1小时内，普通脓毒症3小时内；根据培养和药敏降阶梯；疗程一般7-10天，金葡菌心内膜炎4-6周","液体复苏：晶体液（平衡盐溶液如乳酸林格液、醋酸林格液，避免大量生理盐水致高氯性酸中毒），初始30ml/kg，之后根据容量反应性调整（被动抬腿试验、脉压变异率）","血管活性药：去甲肾上腺素0.05-0.5μg/kg/min（首选），联合血管加压素0.03U/min（减少去甲剂量），肾上腺素（二线），多巴胺（心律失常风险，少用）","糖皮质激素：感染性休克液体和血管活性药效果不佳时，氢化可的松200mg/d（50mg q6h或持续泵入），逐渐减量","控制感染源：脓肿引流、坏死组织清创、拔除感染导管、解除梗阻（胆道/泌尿系），12小时内完成","器官功能支持：呼吸衰竭机械通气（肺保护性通气VT 6ml/kg，PEEP）；急性肾损伤CRRT；心衰用正性肌力药（多巴酚丁胺）；DIC用肝素（有指征时）；应激性溃疡预防（PPI）；血糖控制（目标8-10mmol/L，避免严格控糖致低血糖）","营养支持：血流动力学稳定后24-48小时内启动肠内营养","免疫调节：静脉用免疫球蛋白（IVIG）不常规推荐，特定感染可考虑"],"drug_recommendations":[],"non_pharmacological":["监测：持续心电血压血氧监护，每小时记录尿量、生命体征、意识状态、皮肤灌注","容量管理：精确记录出入量，避免容量过负荷（增加肺水肿和死亡率），目标MAP 65-70mmHg","体位：半卧位（床头抬高30-45度，预防VAP和误吸）","口腔护理：每4-6小时口腔护理，预防呼吸机相关性肺炎","预防深静脉血栓：气压治疗+低分子肝素（出血风险低者）","预防压疮：定时翻身，使用减压床垫","心理支持：ICU患者易出现谵妄和焦虑，每日唤醒，减少镇静，家人探视","早期活动：病情稳定后尽早床上活动和下床，减少ICU获得性衰弱","沟通：向家属解释病情和治疗方案，获得知情同意","恢复期康复：呼吸康复、肢体功能康复、营养支持、心理康复"],"complications":["感染性休克：严重低血压和组织灌注不足，需血管活性药维持，死亡率高","急性呼吸窘迫综合征（ARDS）：严重低氧血症，肺保护性通气，俯卧位通气（重度）","急性肾损伤：少尿无尿，需CRRT，部分进展为慢性肾病","弥散性血管内凝血（DIC）：广泛微血栓形成+出血，治疗原发病，必要时肝素和补充凝血因子","多器官功能障碍综合征（MODS）：两个以上器官功能衰竭，死亡率高","应激性溃疡和消化道出血：PPI预防，出血时内镜止血","深静脉血栓和肺栓塞：长期卧床和高凝状态，预防为主","ICU获得性衰弱：长期卧床和肌松药致肌肉萎缩，早期活动预防","谵妄：ICU常见，影响预后，减少镇静，早期活动，家人探视","死亡：脓毒症休克死亡率20-40%，MODS死亡率更高"],"monitoring":["急诊：血常规、CRP、PCT、血乳酸、凝血、肝肾功能、电解质、血糖、血气、血培养（两套）、尿常规、感染部位影像学","集束化治疗执行记录：1小时内完成测量乳酸、血培养、抗生素、液体复苏、血管活性药（休克者）","住院期间：每4-6小时复查血乳酸（目标降至正常）、血气、电解质；每日查血常规、CRP、PCT、肝肾功能、凝血","血流动力学监测：有创动脉压、中心静脉压（CVP 8-12mmHg）、心输出量（PiCCO或超声）、容量反应性评估","呼吸机：监测潮气量、PEEP、血氧、气道压，每日评估脱机","CRRT：监测超滤量、电解质、凝血、透析充分性","抗生素疗效评估：48-72小时评估，根据培养药敏降阶梯，PCT指导停药","影像学复查：评估感染控制情况，必要时调整引流或手术","长期：出院后随访器官功能恢复情况，康复评估"],"special_populations":["老年人：症状不典型（可无发热），合并症多，死亡率高，抗生素需根据肾功能调整，注意药物相互作用","孕妇：脓毒症可致流产早产，需产科和ICU共管，避免致畸抗生素（四环素、喹诺酮），选择青霉素/头孢类","儿童：液体复苏剂量不同（20ml/kg），血管活性药剂量按体重，注意低血糖","免疫抑制患者：感染病原体多样（真菌、病毒、机会性感染），经验性抗感染需覆盖更广，影像学表现不典型","肿瘤化疗后：中性粒细胞缺乏伴发热，需立即广谱抗生素（覆盖铜绿假单胞菌），G-CSF升白","烧伤患者：感染是主要死因，创面处理+广谱抗生素，注意液体复苏量更大","腹腔感染：需外科干预（引流/手术），抗生素覆盖革兰阴性菌和厌氧菌","中心静脉导管相关感染：拔除导管，导管尖端培养，根据病原体决定疗程"],"references":["中华医学会重症医学分会. 中国脓毒症/感染性休克急诊治疗指南（2024）","拯救脓毒症运动（SSC）国际指南（2021更新）","NICE脓毒症诊治指南"]},{"name":"带状疱疹诊治指南（2024）","category":"皮肤科","scope":"成人带状疱疹（缠腰龙）的诊断、抗病毒治疗、疼痛管理和并发症防治。","diagnosis":["临床表现：发疹前1-5天局部皮肤疼痛、灼热、感觉过敏，随后出现红斑基础上的簇集性水疱，沿单侧周围神经呈带状分布，不超过中线，伴明显神经痛","好发部位：胸背部（肋间神经，最常见）、头面部（三叉神经）、腰腹部、四肢","特殊类型：眼带状疱疹（三叉神经眼支，可致角膜炎、失明）、耳带状疱疹（Ramsay-Hunt综合征，面瘫+耳痛+外耳道疱疹）、播散型带状疱疹（免疫低下者，皮疹泛发）、无疹型带状疱疹（仅有疼痛无皮疹）","诊断：典型临床表现即可诊断，不典型者可取疱液PCR检测VZV-DNA","鉴别：单纯疱疹（好发口周生殖器，反复发作，不沿神经分布）、接触性皮炎（有接触史，瘙痒为主，边界清楚）、肋间神经痛（无皮疹）、胸膜炎（胸痛与呼吸有关）、阑尾炎（右下腹痛）","并发症：带状疱疹后神经痛（PHN，皮疹愈合后疼痛持续大于3个月）、眼部并发症（角膜炎、葡萄膜炎、青光眼、失明）、面瘫、细菌感染、脑炎（免疫低下者）"],"staging":["按皮疹范围：局限型（单一神经节段）、播散型（20个以上皮疹或跨皮节，免疫低下者）","按部位：胸背部、头面部（眼/耳）、腰腹部、四肢、骶尾部","按严重程度：轻度（皮疹少、疼痛轻）、中度（皮疹多、疼痛明显）、重度（头面部、播散型、免疫低下、剧烈疼痛）","按病程：急性期（发疹后1个月内）、亚急性期（1-3个月）、慢性期（大于3个月，PHN）","按免疫状态：免疫正常宿主、免疫抑制宿主（HIV、肿瘤、移植、激素、高龄）"],"key_points":["抗病毒治疗：发疹72小时内启动最佳，超过72小时但仍有新疹出现或重度患者仍可用","抗病毒药物：阿昔洛韦800mg 5次/d×7天；伐昔洛韦1000mg tid×7天（生物利用度高，首选）；泛昔洛韦500mg tid×7天；重症或免疫低下者用阿昔洛韦10mg/kg q8h静滴×7-10天","止痛：轻中度用对乙酰氨基酚或非甾体抗炎药；神经痛用加巴喷丁（300mg tid起始，逐渐加量至900-3600mg/d）或普瑞巴林（75mg bid起始，加至150-300mg/d）；严重疼痛可短期用阿片类（氨酚羟考酮）","局部治疗：水疱未破用炉甘石洗剂、阿昔洛韦乳膏；破溃后用莫匹罗星软膏预防细菌感染；眼部带状疱疹需眼科会诊（抗病毒滴眼液、散瞳）","糖皮质激素：无禁忌的重度患者可在抗病毒基础上短期用泼尼松（30-40mg/d，逐渐减量，疗程7-14天），可减轻急性期疼痛，但不减少PHN发生率","PHN治疗：加巴喷丁/普瑞巴林（一线）、5%利多卡因贴剂（局部）、度洛西汀/文拉法辛（SNRI，二线）、阿米替林（三环类，老年慎用）、阿片类（三线）、神经阻滞治疗","疫苗：重组带状疱疹疫苗（Shingrix，50岁以上接种，2剂间隔2-6个月，预防带状疱疹和PHN有效率大于90%）","眼部带状疱疹：眼科紧急会诊，局部抗病毒（阿昔洛韦眼膏）+散瞳（阿托品）+糖皮质激素滴眼液，全身抗病毒"],"drug_recommendations":[],"non_pharmacological":["休息：急性期注意休息，避免劳累，保证充足睡眠","皮肤护理：保持皮疹清洁干燥，避免搔抓（防细菌感染和病毒播散），穿宽松柔软衣物，水疱不要挑破","饮食：清淡易消化，高蛋白高维生素，避免辛辣刺激和发物（酒、海鲜、羊肉）","疼痛管理：记录疼痛程度（VAS评分），按时服药，避免疼痛加重","眼部护理：眼带状疱疹注意眼部卫生，避免揉眼，按时用滴眼液，定期眼科复查","口腔护理：口腔内疱疹用生理盐水漱口，避免刺激性食物","心理支持：剧烈疼痛和神经痛易致焦虑抑郁，需心理疏导","避免接触：皮疹结痂前避免接触孕妇、新生儿、免疫低下者（可传染水痘）","预防：50岁以上接种带状疱疹疫苗，提高免疫力，避免过度劳累和精神紧张","恢复期：皮疹消退后仍需关注疼痛，PHN需早期干预"],"complications":["带状疱疹后神经痛（PHN）：最常见并发症，皮疹愈合后疼痛持续大于3个月，烧灼痛、刺痛、痛觉过敏，可持续数月至数年，影响睡眠和生活质量","眼部并发症：角膜炎、角膜溃疡、葡萄膜炎、青光眼、视神经炎，严重者失明，眼带状疱疹需眼科紧急处理","Ramsay-Hunt综合征：面神经膝状神经节受累，周围性面瘫+耳痛+外耳道疱疹，可伴听力下降眩晕，早期激素+抗病毒，部分面瘫恢复不完全","细菌感染：水疱破溃后合并金黄色葡萄球菌感染，出现脓疱、红肿加重，需抗生素","脑炎/脑膜炎：免疫低下者病毒播散致中枢神经系统感染，头痛发热意识障碍，需静脉抗病毒","运动神经麻痹：罕见，可致相应肌肉无力（如膈肌麻痹致呼吸困难）","瘢痕和色素沉着：皮疹消退后可留色素沉着或瘢痕（尤其继发感染后）","脱发：头面部带状疱疹可致局部瘢痕性脱发","药物不良反应：抗病毒药致恶心呕吐头痛肾功能损害（多饮水）；加巴喷丁/普瑞巴林致嗜睡头晕共济失调；激素致血糖升高血压升高感染扩散"],"monitoring":["诊断时：典型皮疹可临床诊断，不典型者疱液PCR、Tzanck涂片（多核巨细胞）、病毒培养，免疫低下者查HIV","治疗初期：评估疼痛VAS评分、皮疹范围、有无眼部受累、免疫状态，抗病毒+止痛","眼部带状疱疹：眼科检查（视力、裂隙灯、眼压、眼底），每日或隔日复查","PHN评估：皮疹愈合后1个月、3个月评估疼痛，VAS评分、睡眠影响、生活质量","抗病毒疗效：观察皮疹结痂时间（一般7-10天）、新疹停止出现时间、疼痛减轻情况","长期：PHN患者定期随访调整止痛方案，评估药物不良反应和疗效","疫苗接种后：评估局部和全身不良反应","免疫低下者：监测有无播散和内脏受累，必要时住院静脉抗病毒"],"special_populations":["老年人：最常见人群，PHN发生率高（60岁以上约20%），疼痛重，需积极抗病毒和止痛，接种疫苗预防","孕妇：避免使用阿昔洛韦静脉制剂（相对安全但需评估），严重者需产科和皮肤科共管","儿童：少见，症状轻，多为接触水痘患者后发病，一般预后好","免疫抑制患者（HIV、肿瘤、移植、长期激素）：皮疹重、播散型多、内脏受累风险高，需静脉抗病毒，住院治疗","眼部受累：眼科紧急会诊，不可延误（可致失明）","糖尿病患者：激素慎用（升高血糖），止痛药物注意肾功能","肾功能不全：阿昔洛韦、伐昔洛韦、泛昔洛韦均经肾排泄，需根据eGFR调整剂量，多饮水","服用抗凝药者：神经阻滞治疗需评估出血风险"],"references":["中华医学会皮肤性病学分会. 带状疱疹诊治指南（2024）","2023 EAN带状疱疹和PHN指南","AAN带状疱疹后神经痛治疗指南"]},{"name":"荨麻疹诊治指南（2024）","category":"皮肤科","scope":"成人和儿童荨麻疹（风疹块）的诊断、分型、治疗和长期管理。","diagnosis":["临床表现：风团（暂时性、水肿性、瘙痒性红斑，24小时内消退不留痕迹）、血管性水肿（皮下组织肿胀，多见于眼睑口唇）","急性荨麻疹：小于6周；慢性荨麻疹：大于等于6周，每周发作大于等于2次","分型：自发性（急性、慢性）、诱导性（物理性：人工荨麻疹、冷接触、热接触、日光、延迟压力、振动；非物理性：水源性、胆碱能、接触性）","诊断：典型临床表现即可诊断，慢性荨麻疹需查血常规、CRP、血沉、甲状腺功能和自身抗体、感染筛查","鉴别：荨麻疹性血管炎（风团持续大于24小时，留紫癜，活检血管炎）、过敏性休克、虫咬皮炎、多形红斑","诱因：感染（病毒细菌）、食物（海鲜坚果）、药物（青霉素、非甾体抗炎药）、物理因素、精神压力、自身免疫"],"staging":["按病程：急性荨麻疹（小于6周）、慢性荨麻疹（大于等于6周）","按严重程度：轻度（不影响生活睡眠）、中度（影响生活睡眠）、重度（广泛风团+血管性水肿+严重影响生活，UAS7评分）","按病因：自发性、诱导性（物理性/非物理性）","特殊类型：胆碱能性荨麻疹（运动热水后小风团）、人工荨麻疹（划痕后条状风团）、寒冷性荨麻疹（接触冷水冷风）、日光性荨麻疹","血管性水肿：可单独发生或与荨麻疹伴发，喉头水肿可致窒息（急症）"],"key_points":["第二代非镇静H1抗组胺药是一线治疗：西替利嗪10mg qd、氯雷他定10mg qd、非索非那定120mg qd、依巴斯汀10mg qd、地氯雷他定5mg qd、左西替利嗪5mg qd","常规剂量1-2周无效可加量至2-4倍（慢性荨麻疹指南推荐），仍无效加用其他药物","急性重症或喉头水肿：肾上腺素0.3-0.5mg肌注（大腿前外侧），糖皮质激素（甲泼尼龙40mg静推或泼尼松30-40mg口服），吸氧，必要时气管切开","慢性荨麻疹二线：奥马珠单抗（抗IgE单抗，150-300mg每4周皮下注射，对难治性慢性荨麻疹有效）；环孢素A 3-5mg/kg/d（三线，注意肾毒性和高血压）；孟鲁司特（辅助，尤其合并阿司匹林加重）","避免使用第一代抗组胺药（扑尔敏、苯海拉明）作为长期治疗（嗜睡、抗胆碱副作用）","局部治疗：炉甘石洗剂止痒，冷敷减轻症状","诱导性荨麻疹：避免诱因，抗组胺药预防（如运动前30分钟服药）","急性荨麻疹疗程：症状控制后逐渐减量，一般1-2周；慢性荨麻疹需长期治疗（3-6个月以上），逐渐减量"],"drug_recommendations":[],"non_pharmacological":["寻找并避免诱因：记录饮食日记，避免已知过敏食物和药物，避免物理刺激","急性发作：冷敷减轻瘙痒，避免热水烫洗和搔抓，穿宽松棉质衣物","慢性荨麻疹：规律作息，避免熬夜和精神压力，保持心情舒畅","饮食：避免辛辣刺激、酒精、海鲜等已知诱因食物，无需盲目忌口（除非明确过敏）","皮肤护理：使用温和沐浴露，避免过度清洁，洗澡水温不宜过高，涂抹保湿润肤剂","避免使用诱发荨麻疹的药物：阿司匹林、非甾体抗炎药、吗啡、可待因等（如必须用需谨慎）","运动：胆碱能性荨麻疹患者避免剧烈运动和热水浴，运动前可预防性服药","心理支持：慢性荨麻疹影响生活质量，易焦虑，需心理疏导","患者教育：解释疾病性质（非传染性、不遗传给下一代），治疗目标是控制症状而非根治","随身携带急救药物：有血管性水肿或过敏性休克史者随身携带肾上腺素自动注射笔"],"complications":["过敏性休克：严重过敏反应，血压下降、呼吸困难、意识障碍，立即肾上腺素肌注+急救","喉头水肿：血管性水肿累及喉部，声音嘶哑、呼吸困难、窒息，急诊处理（肾上腺素、激素、气管切开）","慢性荨麻疹影响生活质量：瘙痒影响睡眠和工作，焦虑抑郁发生率高","药物不良反应：抗组胺药致嗜睡（第一代明显）、口干；环孢素致肾毒性、高血压、多毛；奥马珠单抗致注射部位反应、过敏反应（罕见）","荨麻疹性血管炎：风团持续大于24小时伴疼痛，活检确诊，需激素+免疫抑制剂治疗","感染：慢性荨麻疹常合并隐匿感染（幽门螺杆菌、寄生虫、牙齿感染），需排查","自身免疫病：慢性荨麻疹常合并甲状腺自身免疫病、白癜风、1型糖尿病等","妊娠：荨麻疹在孕期可能加重或减轻，治疗需选择安全药物"],"monitoring":["诊断时：详细病史（诱因、持续时间、伴随症状）、体格检查、血常规、CRP、血沉；慢性荨麻疹加查甲状腺功能+抗体、幽门螺杆菌、寄生虫、自身抗体","急性荨麻疹：观察风团变化（24小时内消退），监测有无血管性水肿和呼吸困难","慢性荨麻疹：UAS7评分（每周风团数量+瘙痒程度）评估严重程度和疗效，每2-4周评估","治疗期间：评估药物疗效和不良反应，抗组胺药加量后注意嗜睡","奥马珠单抗治疗：用药前查IgE水平和体重确定剂量，注射后观察30分钟（过敏反应），每4周注射，治疗3-6个月评估疗效","长期：慢性荨麻疹定期随访，逐渐减量停药，复发后重新治疗","诱因排查：反复发作且治疗效果差时，进一步查感染、自身免疫、肿瘤（罕见）"],"special_populations":["孕妇：首选西替利嗪或氯雷他定（妊娠B类，相对安全），避免使用其他新药，严重急性发作用肾上腺素和激素（权衡利弊）","哺乳期：西替利嗪、氯雷他定、非索非那定可使用（乳汁分泌少），避免第一代抗组胺药","儿童：按体重计算剂量，2岁以上可用西替利嗪、氯雷他定糖浆，6个月以上可用左西替利嗪滴剂","老年人：避免第一代抗组胺药（嗜睡、跌倒、抗胆碱副作用），选择第二代，注意药物相互作用","肝肾功能不全：根据肝肾功能调整抗组胺药剂量，环孢素需监测血药浓度和肾功能","哮喘患者：荨麻疹合并哮喘常见，奥马珠单抗同时有效，注意哮喘控制","阿司匹林加重性疾病：避免阿司匹林和非甾体抗炎药，白三烯受体拮抗剂（孟鲁司特）有效","免疫抑制患者：治疗效果可能较差，需排查感染和肿瘤"],"references":["中华医学会皮肤性病学分会. 荨麻疹诊治指南（2024）","2023 EAACI/GA²LEN/EDF/WAO荨麻疹指南","AAD荨麻疹管理指南"]},{"name":"痤疮诊治指南（2024）","category":"皮肤科","scope":"成人和青少年痤疮（青春痘）的分级、治疗方案和长期维持。","diagnosis":["临床表现：粉刺（白头闭合性、黑头开放性）、丘疹、脓疱、结节、囊肿，好发于面部、胸背部","发病机制：皮脂腺分泌旺盛、毛囊口角化异常、痤疮丙酸杆菌增殖、炎症反应","分级：轻度（I级，仅有粉刺）、中度（II级，粉刺+炎性丘疹；III级，丘疹+脓疱）、重度（IV级，结节+囊肿+瘢痕）","瘢痕评估：萎缩性瘢痕（冰锥型、滚动型、车厢型）、增生性瘢痕、瘢痕疙瘩","鉴别：玫瑰痤疮（面中部红斑毛细血管扩张，无粉刺）、细菌性毛囊炎（以毛囊为中心脓疱，无粉刺）、马拉色菌毛囊炎（胸背瘙痒性丘疹，真菌检查阳性）、药物性痤疮（激素、锂剂、异烟肼）","诱因：青春期雄激素、高糖高脂饮食、乳制品（脱脂牛奶）、熬夜、精神压力、化妆品堵塞"],"staging":["按严重程度：I级（轻度，粉刺为主）、II级（中度，粉刺+丘疹）、III级（中重度，丘疹+脓疱）、IV级（重度，结节+囊肿）","按类型：寻常痤疮、聚合性痤疮（严重结节囊肿窦道）、暴发性痤疮（急性发热伴溃疡性皮损）、药物性痤疮、新生儿痤疮","按瘢痕：无瘢痕、萎缩性瘢痕、增生性瘢痕、瘢痕疙瘩","按部位：面部痤疮、胸背痤疮、下颌线痤疮（激素相关，女性多囊卵巢）"],"key_points":["轻度（I级）：外用维A酸类（阿达帕林0.1%凝胶qn、维A酸0.025%乳膏qn）+外用抗菌药（过氧化苯甲酰2.5-5%凝胶qd-bid、克林霉素凝胶bid）","中度（II-III级）：外用维A酸+过氧化苯甲酰+外用抗生素；炎症明显者加口服抗生素（多西环素100mg qd或米诺环素50-100mg bid，疗程6-8周，不超过12周）","重度（IV级）：口服异维A酸（0.5-1mg/kg/d，分2次，疗程16-24周，累积剂量120-150mg/kg）是金标准；或口服抗生素+外用药物联合；严重炎症可短期用糖皮质激素（泼尼松10-20mg/d，2-4周）","女性激素相关痤疮：口服避孕药（达英-35、优思明）、螺内酯（50-100mg/d，抗雄激素）","物理治疗：红蓝光照射（抗炎杀菌）、光动力疗法（重度）、化学换肤（果酸水杨酸，粉刺和痘印）、激光治疗（瘢痕）","瘢痕治疗：萎缩性瘢痕用点阵激光、微针、皮下分离；增生性瘢痕用激素局部注射（曲安奈德）、硅酮凝胶","维持治疗：痤疮缓解后外用维A酸类维持6-12个月，预防复发","避免单独外用抗生素（耐药），需与过氧化苯甲酰联用","异维A酸注意：致畸（育龄期女性需避孕，停药后3个月）、皮肤黏膜干燥、血脂升高、肝酶升高、抑郁情绪（监测）"],"drug_recommendations":[],"non_pharmacological":["皮肤清洁：温和洁面，每日1-2次，避免过度清洁和磨砂，水温不宜过高","护肤：使用清爽不致粉刺的保湿剂和防晒霜（痤疮皮肤也需保湿和防晒），避免油性化妆品","饮食：减少高糖食物、脱脂牛奶、乳制品摄入，增加蔬菜水果和Omega-3（鱼类坚果），避免辛辣刺激（个体差异）","生活方式：规律作息，避免熬夜（熬夜加重痤疮），减少精神压力，适度运动","避免挤压：不要用手挤压粉刺和痘痘（致感染扩散和瘢痕），专业清痘需无菌操作","防晒：紫外线加重炎症后色素沉着，使用不致粉刺的防晒霜","戒烟限酒：吸烟加重痤疮和影响愈合，酒精加重炎症","心理支持：重度痤疮影响容貌和心理，易自卑抑郁，需心理疏导","化妆：选择不致粉刺（non-comedogenic）的化妆品，睡前彻底卸妆","定期复查：治疗期间定期复诊，调整方案，监测药物不良反应"],"complications":["瘢痕：重度痤疮（结节囊肿型）易留萎缩性或增生性瘢痕，早期规范治疗可预防","炎症后色素沉着（痘印）：痤疮消退后留下的褐色斑，防晒+外用维A酸/壬二酸/氢醌，数月消退","药物不良反应：异维A酸致畸、皮肤干燥、唇炎、血脂升高、肝酶升高、肌肉酸痛、情绪变化；口服抗生素致胃肠道反应、光敏（多西环素）、阴道念珠菌感染；外用维A酸致皮肤刺激发红脱屑","暴发性痤疮：急性发热、关节痛、溃疡性皮损，需口服激素+异维A酸","聚合性痤疮：严重结节囊肿窦道瘢痕，治疗困难，需异维A酸+激素+抗生素联合","耐药：长期单独使用外用或口服抗生素致痤疮丙酸杆菌耐药，需联合过氧化苯甲酰","抑郁：重度痤疮患者抑郁和自杀风险增加，需关注心理状态，异维A酸期间监测情绪"],"monitoring":["诊断时：详细病史（病程、诱因、用药史、月经史女性）、体格检查（分级、瘢痕）、女性严重者查性激素（睾酮、LH/FSH、多囊卵巢）","治疗初期：每2-4周复诊，评估疗效和皮肤刺激反应，调整外用药物","口服异维A酸：用药前查肝功能、血脂、妊娠试验（育龄女性），用药期间每月查肝功能血脂，每3个月评估疗效，累积剂量达标后停药","口服抗生素：每6-8周评估，疗程不超过12周，避免长期使用","维持期：每3-6个月复诊，评估复发情况，调整维持方案","瘢痕治疗：痤疮完全控制后再进行瘢痕治疗（激光、微针等）","长期：痤疮是慢性病，易复发，需长期维持治疗和生活方式管理"],"special_populations":["孕妇：禁用异维A酸（致畸）、四环素类（影响骨骼牙齿）、维A酸外用（相对禁忌），可外用过氧化苯甲酰、红霉素、克林霉素（需医生评估）","哺乳期：避免异维A酸和四环素，外用药物相对安全，口服抗生素选青霉素或头孢类","儿童：新生儿痤疮无需特殊治疗（数月自愈），青春期前痤疮需排查性早熟和内分泌疾病","多囊卵巢综合征女性：痤疮+多毛+月经不规律，查性激素和妇科超声，口服避孕药+螺内酯有效","男性重度痤疮：异维A酸是首选，注意血脂和肝功能，无需避孕但需告知致畸风险（性伴侣）","瘢痕体质者：增生性瘢痕和瘢痕疙瘩风险高，早期积极治疗痤疮，避免有创操作","深色皮肤：炎症后色素沉着更明显，优先选择不引起色素沉着的治疗，加强防晒","肝肾功能不全：异维A酸和口服抗生素需调整剂量或避免，监测肝肾功能"],"references":["中华医学会皮肤性病学分会. 痤疮诊治指南（2024）","2023 AAD痤疮管理指南","全球痤疮治疗联盟（GAM）指南"]},{"name":"白内障诊治指南（2024）","category":"眼科","scope":"成人年龄相关性白内障的诊断、手术指征、手术方式和术后管理。","diagnosis":["临床表现：无痛性、渐进性视力下降，视物模糊、畏光、眩光、单眼复视、近视度数加深（核性白内障）、色觉改变","体征：晶状体混浊（皮质性、核性、后囊下型），眼底窥不清","分型：皮质性（最常见，楔形混浊）、核性（核变黄棕色硬化，近视加深）、后囊下型（后极部盘状混浊，眩光明显，早期影响视力）、混合型","诊断：视力检查、裂隙灯检查（晶状体混浊程度）、眼压、眼底检查（评估眼底情况）、角膜内皮计数、人工晶状体度数测算（IOL Master）","鉴别：老花眼（戴镜矫正视力正常）、黄斑变性（眼底病变，矫正视力不提高）、青光眼（眼压升高、视野缺损）、角膜病变","手术指征：视力下降影响生活质量（一般矫正视力小于0.5），或白内障影响眼底疾病的诊治（如糖尿病视网膜病变激光）"],"staging":["按晶状体混浊部位：皮质性、核性、后囊下型、混合型","按混浊程度：初发期、膨胀期（虹膜投影阳性）、成熟期（虹膜投影消失，视力手动/光感）、过熟期（晶状体核下沉，可致晶状体溶解性青光眼）","按病因：年龄相关性（最常见）、先天性、外伤性、并发性（葡萄膜炎、青光眼、视网膜脱离）、代谢性（糖尿病、低钙血症）、药物性（糖皮质激素、氯丙嗪）、放射性","按视力影响：轻度（视力大于0.5）、中度（0.3-0.5）、重度（小于0.3，影响生活）"],"key_points":["早期白内障：无特效药物，可试用吡诺克辛滴眼液（白内停）、谷胱甘肽滴眼液（疗效有限），控制血糖和避免紫外线","手术治疗是唯一有效方法：超声乳化白内障吸除术+人工晶状体植入术（主流，切口小2-3mm，恢复快）；飞秒激光辅助白内障手术（精准）；囊外摘除术（大切口，用于硬核或复杂病例）","人工晶状体选择：单焦点IOL（最常用，看远清楚，看近需戴老花镜）；多焦点IOL（看远看近，费用高，可能有眩光光晕）；散光矫正型IOL（Toric，矫正角膜散光）；三焦IOL（远中近全程视力）","术前准备：抗生素滴眼液（左氧氟沙星）术前3天，控制血压血糖（空腹血糖小于8.3mmol/L），泪道冲洗（排除慢性泪囊炎），散瞳（复方托吡卡胺）","术后用药：抗生素滴眼液（左氧氟沙星）4次/d×2周；糖皮质激素滴眼液（氟米龙/妥布霉素地塞米松）4次/d逐渐减量×1个月；非甾体抗炎药滴眼液（普拉洛芬）4次/d×2周；人工泪液（缓解干眼）","术后并发症处理：后发性白内障（YAG激光后囊膜切开）；眼内炎（急诊，玻璃体腔注射抗生素+玻璃体切割）；角膜水肿（高渗盐水+激素，严重者角膜内皮移植）；人工晶状体脱位（手术复位或更换）；黄斑囊样水肿（激素+非甾体抗炎药）","围手术期控制基础病：糖尿病患者血糖控制，高血压患者血压稳定"],"drug_recommendations":[],"non_pharmacological":["术前：控制血糖血压，术前3天抗生素滴眼液，术前一天洗头洗澡，手术当天不化妆不喷香水","术后当天：休息，避免揉眼，戴眼罩保护，避免弯腰低头和剧烈活动","术后护理：按医嘱滴眼药水（注意洗手，瓶口不接触眼睛），保持眼部清洁，1周内避免水进入眼内，1个月内避免游泳","饮食：清淡易消化，多吃蔬菜水果，保持大便通畅（避免用力排便），避免辛辣刺激和烟酒","活动：术后1周可轻度活动，1个月内避免剧烈运动、重体力劳动、游泳，避免碰撞眼部","复查：术后1天、1周、1个月、3个月复查视力、眼压、裂隙灯","配镜：术后3个月屈光稳定后验光配镜（单焦点IOL看近需老花镜）","防晒：外出戴防紫外线太阳镜，减少紫外线对晶状体和眼底的损伤","控制基础病：糖尿病患者控制血糖，高血压患者控制血压，定期查眼底","避免长时间用眼：术后初期避免长时间看手机电脑，注意休息"],"complications":["术后眼内炎：最严重并发症，术后1-7天出现眼痛、视力急剧下降、前房积脓，急诊玻璃体腔注射抗生素（万古霉素+头孢他啶）+玻璃体切割术","后发性白内障：术后数月至数年出现视力下降，YAG激光后囊膜切开（简单有效）","角膜水肿：术后角膜内皮损伤致角膜混浊，轻度用高渗盐水+激素，严重者角膜内皮移植","人工晶状体脱位：术后外伤或悬韧带松弛致IOL移位，手术复位或更换","黄斑囊样水肿（Irvine-Gass综合征）：术后视力下降，黄斑囊样水肿，激素+非甾体抗炎药治疗","青光眼：术后激素性青光眼（长期用激素滴眼液）、恶性青光眼（罕见），需降眼压治疗","视网膜脱离：高度近视患者术后风险增加，出现闪光感、黑影遮挡及时就诊","干眼：术后常见，人工泪液缓解，一般数月恢复","术中并发症：后囊膜破裂、玻璃体脱出、核坠入玻璃体腔（需玻璃体切割手术）"],"monitoring":["术前：视力、矫正视力、眼压、裂隙灯、眼底、角膜内皮计数、IOL度数测算（眼轴长度+角膜曲率）、泪道冲洗、心电图、血常规、凝血、血糖、传染病筛查","术后1天：视力、眼压、裂隙灯（角膜、前房、IOL位置）","术后1周：视力、眼压、裂隙灯，调整眼药水","术后1个月：视力、眼压、裂隙灯、眼底，逐渐停激素滴眼液","术后3个月：视力、验光（配镜）、眼压、眼底，评估最终视力","长期：每年眼科检查，监测对侧眼白内障进展和眼底情况","糖尿病患者：术后定期查眼底（糖尿病视网膜病变进展），必要时眼底激光","出现眼痛、视力急剧下降、眼红加重：立即就诊（排除眼内炎等严重并发症）"],"special_populations":["老年人：最常见人群，合并全身病多，术前评估心肺功能，手术可在表面麻醉下进行，术后注意防跌倒","糖尿病患者：术前控制血糖（空腹小于8.3，餐后小于11.1），术后感染和黄斑水肿风险高，密切随访","高度近视患者：视网膜脱离风险高，术前查周边眼底，术后避免剧烈运动，出现闪光感及时就诊","青光眼患者：术后激素可升高眼压，需监测眼压，选择对眼压影响小的激素（氟米龙）","独眼患者：手术需更谨慎，充分告知风险，选择经验丰富的医生","儿童先天性白内障：需尽早手术（避免形觉剥夺性弱视），术后弱视训练，IOL植入时机需评估","服用抗凝药者：白内障手术一般不需停抗凝药（表面麻醉切口小），但需告知医生","妊娠：一般择期手术推迟至产后，紧急情况需产科和眼科共管"],"references":["中华医学会眼科学分会. 白内障诊治指南（2024）","2023 ESCRS白内障手术指南","AAO年龄相关性白内障临床指南"]},{"name":"糖尿病视网膜病变诊治指南（2024）","category":"眼科","scope":"糖尿病视网膜病变（DR）的筛查、分期、治疗和长期管理。","diagnosis":["临床表现：早期可无症状，逐渐出现视力下降、视物变形、眼前黑影飘动、闪光感，严重者视力丧失","眼底检查：微动脉瘤、出血点（点状/片状）、硬性渗出、棉絮斑、视网膜水肿、新生血管、玻璃体积血、视网膜脱离","分型：非增殖性糖尿病视网膜病变（NPDR，轻中重度）、增殖性糖尿病视网膜病变（PDR，新生血管形成）、糖尿病黄斑水肿（DME，可发生于任何期）","辅助检查：眼底照相（免散瞳）、光学相干断层扫描（OCT，评估黄斑水肿）、荧光素眼底血管造影（FFA，评估缺血和新生血管）、眼部B超（玻璃体积血时）","筛查时机：1型糖尿病诊断后5年开始每年查眼底；2型糖尿病诊断时即查眼底，之后每年1次；妊娠前和妊娠期每3个月查眼底","危险因素：血糖控制差（HbA1c每降1%DR风险降35%）、高血压、高血脂、糖尿病病程、妊娠、肾病、吸烟、肥胖"],"staging":["按国际分期：轻度NPDR（仅有微动脉瘤）、中度NPDR（微动脉瘤+出血渗出，未达重度）、重度NPDR（4-2-1法则：4个象限出血、2个象限静脉串珠、1个象限微血管异常）、PDR（新生血管、玻璃体积血、纤维增殖）","糖尿病黄斑水肿（DME）：无明显黄斑水肿、累及中心凹的DME、不累及中心凹的DME","按视力影响：无视功能损害、轻度视力下降、中度视力下降、重度视力下降/失明","按治疗需求：观察期、激光治疗期、抗VEGF治疗期、手术期（玻璃体切割）"],"key_points":["控制基础病是根本：血糖（HbA1c目标小于7%，个体化）、血压（小于130/80mmHg）、血脂（LDL-C小于1.8mmol/L）","轻度NPDR：控制基础病+定期随访（每6-12个月），可口服羟苯磺酸钙、递法明（改善微循环，辅助）","中度NPDR：每3-6个月随访，控制基础病，必要时眼底激光","重度NPDR和PDR：全视网膜光凝术（PRP，激光治疗，减少新生血管和失明风险）","糖尿病黄斑水肿（DME）：抗VEGF玻璃体腔注射（雷珠单抗、阿柏西普、康柏西普，一线治疗，每月1次连续3次后按需）；黄斑格栅激光（二线）；糖皮质激素玻璃体腔注射（地塞米松缓释剂，二线，注意眼压升高和白内障）","PDR并发症：玻璃体积血（不吸收者玻璃体切割术）、视网膜脱离（玻璃体切割+硅油填充）、新生血管性青光眼（抗VEGF+全视网膜光凝+青光眼手术）","药物：非诺贝特（降低DR进展风险，尤其合并高血脂）；阿司匹林不增加眼底出血风险，可用于心血管预防","定期筛查是关键：早期发现早期治疗可显著降低失明风险"],"drug_recommendations":[],"non_pharmacological":["血糖管理：严格控制血糖（HbA1c小于7%），避免血糖剧烈波动（低血糖也加重DR），饮食控制+运动+药物","血压管理：控制血压小于130/80mmHg，首选ACEI/ARB类降压药（同时保护肾脏和视网膜）","血脂管理：控制LDL-C小于1.8mmol/L，他汀类+非诺贝特（非诺贝特延缓DR进展）","戒烟：吸烟加重DR和黄斑病变，必须戒烟","饮食：低盐低脂低糖，增加膳食纤维和Omega-3，避免高糖饮食","运动：适度有氧运动（快走、游泳），避免剧烈运动（PDR患者剧烈运动可致玻璃体积血）","定期眼科检查：严格按筛查频率查眼底，出现视力变化立即就诊","眼部保护：避免眼部外伤，PDR患者避免剧烈运动和重体力劳动","心理支持：DR可致失明，患者易焦虑，需心理疏导和低视力康复","妊娠管理：糖尿病患者妊娠前评估眼底，妊娠期每3个月查眼底，DR进展及时治疗"],"complications":["玻璃体积血：PDR新生血管破裂致玻璃体出血，视力突然下降，少量可吸收，大量不吸收需玻璃体切割术","牵拉性视网膜脱离：纤维增殖膜收缩牵拉视网膜致脱离，视力严重下降，需玻璃体切割+硅油填充","新生血管性青光眼：虹膜和房角新生血管致眼压升高，眼痛头痛视力丧失，治疗困难（抗VEGF+PRP+青光眼手术）","黄斑水肿：DME是糖尿病患者视力下降最常见原因，抗VEGF治疗有效，但需多次注射","失明：晚期PDR和DME可致不可逆失明，是工作年龄人群首位致盲原因","治疗相关并发症：抗VEGF注射致眼内炎（罕见但严重）、眼压升高；激光致视野缺损、暗适应下降；玻璃体切割术致白内障进展、视网膜脱离、感染","心血管事件：抗VEGF玻璃体腔注射全身吸收少，心血管风险低，但需评估","肾功能损害：DR常合并糖尿病肾病，需同时管理肾功能"],"monitoring":["筛查：1型糖尿病诊断5年后每年查眼底；2型糖尿病诊断时即查，之后每年1次；血糖控制差或已有DR者每3-6个月查","诊断时：视力、眼压、裂隙灯、散瞳眼底检查、眼底照相、OCT（黄斑），必要时FFA","治疗期间：抗VEGF注射后1周复查（视力、眼压、眼底），每月评估是否需要再次注射（OCT评估黄斑水肿）","激光治疗后：1-3个月复查眼底，评估激光效果，必要时补充激光","玻璃体切割术后：1天、1周、1个月、3个月复查，硅油填充者3-6个月取硅油","长期：每3-6个月查眼底和OCT，监测DR进展和DME复发","全身指标：每3个月查HbA1c，每月测血压，每3-6个月查血脂和肝肾功能","出现视力突然下降、眼前黑影增多、闪光感：立即就诊（玻璃体积血或视网膜脱离）"],"special_populations":["1型糖尿病：发病年龄轻，DR进展快，需更密切筛查（诊断后5年开始，每年1次），血糖控制更严格","2型糖尿病：诊断时可能已有DR，需立即筛查，常合并高血压高血脂，需综合管理","孕妇：妊娠可加速DR进展，妊娠前评估眼底，妊娠期每3个月查眼底，DR进展及时治疗（激光或抗VEGF，需权衡胎儿安全）","老年人：合并白内障影响眼底观察，必要时先做白内障手术再查眼底和治疗","肾功能不全：DR常合并糖尿病肾病，造影剂（FFA）需谨慎，抗VEGF药物需评估","青光眼患者：激素治疗DME可升高眼压，需监测，优先抗VEGF","服用抗凝药者：玻璃体腔注射一般不需停抗凝药，但需告知医生","激光治疗后：避免强光刺激，佩戴太阳镜，注意暗适应下降"],"references":["中华医学会眼科学分会. 糖尿病视网膜病变诊治指南（2024）","2023 ADA糖尿病视网膜病变立场声明","AAO糖尿病视网膜病变临床指南"]},{"name":"慢性鼻窦炎诊治指南（2024）","category":"耳鼻喉科","scope":"成人慢性鼻窦炎（CRS）的分型、诊断、药物治疗和手术治疗。","diagnosis":["临床表现：鼻塞（持续性）、流涕（黏脓性，可后流）、头面部胀痛、嗅觉减退或丧失，病程大于12周","分型：慢性鼻窦炎不伴鼻息肉（CRSsNP）、慢性鼻窦炎伴鼻息肉（CRSwNP）","体征：鼻内镜检查见中鼻道黏脓性分泌物、黏膜充血水肿、鼻息肉（半透明荔枝肉样新生物）","影像学：鼻窦CT（窦口鼻道复合体阻塞、鼻窦黏膜增厚、积液、息肉），术前必查","鉴别：过敏性鼻炎（阵发性喷嚏清水涕，鼻黏膜苍白水肿）、急性鼻窦炎（病程小于12周）、鼻腔鼻窦肿瘤（单侧血涕、面部麻木，活检确诊）、胃食管反流（后流刺激）","伴随疾病：过敏性鼻炎、哮喘、阿司匹林加重性呼吸道疾病（AERD）、囊性纤维化（儿童）、免疫缺陷","诱因：急性鼻窦炎反复发作、鼻腔结构异常（鼻中隔偏曲、泡状中鼻甲）、过敏、吸烟、空气污染、胃食管反流"],"staging":["按有无鼻息肉：CRSsNP（不伴鼻息肉）、CRSwNP（伴鼻息肉）","按炎症类型：嗜酸性粒细胞型（CRSwNP多见，术后易复发）、中性粒细胞型（CRSsNP多见）","按严重程度：轻度（症状轻，不影响生活）、中度（影响生活）、重度（严重影响生活，VAS评分大于7）","按范围：单鼻窦炎、多鼻窦炎、全鼻窦炎","术后分型：根据术中所见和病理评估复发风险（嗜酸性粒细胞浸润、AERD、哮喘者复发率高）"],"key_points":["药物治疗是基础，手术是药物治疗无效后的选择","鼻用糖皮质激素：糠酸莫米松鼻喷剂2喷qd、氟替卡松鼻喷剂2喷qd、布地奈德鼻喷剂2喷qd，疗程至少3个月（一线，抗炎消肿）","鼻腔冲洗：生理盐水或高渗盐水冲洗鼻腔，每日1-2次，清除分泌物和过敏原（基础治疗）","抗生素：急性发作或脓性分泌物多时用，阿莫西林克拉维酸钾625mg tid×10-14天，或克拉霉素500mg bid（小剂量长期抗炎12周，CRSsNP）","口服糖皮质激素：CRSwNP围手术期用泼尼松30-40mg/d×5-7天（缩小息肉，减少术中出血），不长期口服（副作用大）","白三烯受体拮抗剂：孟鲁司特10mg qn（合并过敏性鼻炎和哮喘者）","抗组胺药：合并过敏性鼻炎者用第二代抗组胺药（氯雷他定、西替利嗪）","减充血剂：羟甲唑啉滴鼻液（短期使用不超过7天，缓解鼻塞，长期用致药物性鼻炎）","手术治疗：鼻内镜下鼻窦开放术（FESS），指征为药物治疗3个月无效、鼻息肉、窦口鼻道复合体阻塞、并发症（眶内感染、颅内感染）","术后处理：鼻内镜清理（术后1周、2周、1个月）、鼻用激素继续3-6个月、鼻腔冲洗、定期随访（减少复发）","生物制剂：难治性CRSwNP（术后复发、嗜酸性粒细胞高、合并哮喘AERD）用抗IL-4/IL-13单抗（度普利尤单抗）、抗IL-5单抗（美泊利珠单抗）"],"drug_recommendations":[],"non_pharmacological":["鼻腔冲洗：每日1-2次生理盐水冲洗，坚持长期使用，是最基础的治疗","环境控制：避免过敏原（尘螨、花粉、宠物），戴口罩，保持室内空气湿润清洁，避免空气污染和吸烟","戒烟：吸烟加重鼻窦炎和影响术后愈合，必须戒烟，避免二手烟","饮食：避免辛辣刺激、酒精（加重黏膜充血），过敏体质者避免已知过敏食物","适度运动：增强体质，减少上呼吸道感染","预防感冒：及时治疗急性鼻炎鼻窦炎，避免迁延不愈成慢性","控制过敏：合并过敏性鼻炎者规范治疗，避免接触过敏原","术后护理：定期鼻内镜复查清理（关键，减少复发），坚持鼻腔冲洗和鼻用激素","避免滥用滴鼻净：减充血剂连续使用不超过7天，防止药物性鼻炎","职业防护：接触粉尘、化学物质者戴防护口罩"],"complications":["鼻息肉：CRSwNP常见，鼻塞进行性加重，嗅觉丧失，术后易复发（嗜酸性粒细胞型复发率高）","眶内并发症：鼻窦炎扩散致眶内蜂窝织炎、眶内脓肿（眼球突出、视力下降、眼球运动受限），急诊抗生素+手术引流","颅内并发症：硬膜外脓肿、脑膜炎、脑脓肿（头痛发热意识障碍），罕见但严重，急诊处理","分泌性中耳炎：咽鼓管咽口受压致中耳积液，听力下降，治疗鼻窦炎同时处理中耳","嗅觉丧失：长期炎症和息肉压迫致嗅觉不可逆损害，早期治疗可恢复","哮喘加重：CRSwNP常合并哮喘，鼻窦炎控制不佳可诱发哮喘发作","术后复发：CRSwNP术后复发率20-40%（嗜酸性粒细胞型、AERD、哮喘者更高），需长期随访和维持治疗","药物不良反应：长期口服激素致骨质疏松、高血糖、感染；抗生素致肠道菌群紊乱和耐药；鼻用激素局部副作用少（鼻腔干燥、出血）","萎缩性鼻炎：过度手术或长期炎症致鼻腔黏膜萎缩，干燥结痂、恶臭"],"monitoring":["诊断时：鼻内镜检查、鼻窦CT（评估病变范围和结构）、过敏原检测（合并过敏者）、嗅觉功能评估、血常规嗜酸性粒细胞计数","药物治疗期间：每2-4周评估症状（VAS评分）、鼻内镜，调整药物，3个月评估是否需要手术","术前：鼻窦CT、鼻内镜、凝血功能、心电图、控制血压血糖，停用抗凝药（评估）","术后1周：鼻内镜清理血痂和分泌物，评估术腔愈合","术后1-3个月：每2-4周鼻内镜复查清理，坚持鼻腔冲洗和鼻用激素","术后6个月：评估手术效果，调整维持治疗方案","长期：每3-6个月随访，监测复发，CRSwNP需长期维持治疗（鼻用激素+冲洗）","出现眼球突出、视力下降、剧烈头痛发热：立即就诊（眶内或颅内并发症）"],"special_populations":["儿童：慢性鼻窦炎多与腺样体肥大和过敏有关，先药物治疗+腺样体切除，鼻窦手术需谨慎（影响面部发育）","孕妇：避免口服激素和某些抗生素，用鼻腔冲洗+鼻用激素（布地奈德相对安全），严重者需产科和耳鼻喉共管","老年人：合并心脑血管病多，手术需评估全身情况，术后注意止血和血压控制","哮喘患者：CRSwNP合并哮喘常见，围手术期需控制哮喘，术后鼻窦炎改善有助于哮喘控制","阿司匹林加重性呼吸道疾病（AERD）：鼻息肉+哮喘+阿司匹林不耐受，术后复发率极高，需生物制剂或阿司匹林脱敏治疗","免疫缺陷患者：反复感染，需排查免疫缺陷，长期抗生素预防和免疫球蛋白替代","囊性纤维化：儿童和年轻人，全鼻窦炎+鼻息肉，需多学科管理","鼻中隔偏曲：影响鼻窦引流，手术时同时矫正鼻中隔"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 慢性鼻窦炎诊治指南（2024）","EPOS 2020（欧洲鼻窦炎和鼻息肉立场文件）","AAO-HNS慢性鼻窦炎临床实践指南"]},{"name":"中耳炎诊治指南（2024）","category":"耳鼻喉科","scope":"成人和儿童急性中耳炎、分泌性中耳炎、慢性化脓性中耳炎的诊断和治疗。","diagnosis":["急性中耳炎（AOM）：耳痛（儿童哭闹抓耳）、听力下降、发热、耳流脓（鼓膜穿孔后）；鼓膜充血膨隆、活动度差","分泌性中耳炎（OME）：听力下降、耳闷堵感、耳鸣，一般无耳痛发热；鼓膜内陷、琥珀色、可见液平或气泡","慢性化脓性中耳炎（CSOM）：反复耳流脓、听力下降、鼓膜穿孔；可伴胆脂瘤（白色鳞屑、恶臭、骨质破坏）","辅助检查：耳镜/耳内镜（鼓膜情况）、纯音测听（听力损失类型和程度）、声导抗（鼓室图，A型正常、B型积液、C型负压）、颞骨CT（慢性中耳炎和胆脂瘤术前评估）","鉴别：外耳道炎（耳廓牵拉痛，鼓膜正常）、大疱性鼓膜炎（鼓膜血疱，剧烈耳痛，流感病毒）、中耳癌（中老年，长期耳流脓血，面部麻木，活检）","危险因素：儿童（咽鼓管短平宽）、腺样体肥大、腭裂、免疫缺陷、吸烟、胃食管反流、哺乳姿势不当（儿童）"],"staging":["按病程：急性中耳炎（小于3周）、亚急性（3周-3个月）、慢性（大于3个月）","按类型：急性中耳炎（AOM）、分泌性中耳炎（OME）、慢性化脓性中耳炎（CSOM，单纯型/骨疡型/胆脂瘤型）","按鼓膜：鼓膜完整（AOM早期、OME）、鼓膜穿孔（AOM穿孔后、CSOM）","按并发症：单纯性中耳炎、并发症型（面瘫、迷路炎、颅内并发症）","胆脂瘤型：先天性胆脂瘤、后天性原发性胆脂瘤、后天性继发性胆脂瘤"],"key_points":["急性中耳炎：观察等待（轻中度、大于2岁、无高危因素，48-72小时观察）；抗生素指征（小于6个月、双侧AOM、伴耳流脓、高危因素、症状重），首选阿莫西林80-90mg/kg/d（成人500mg tid）×10天；青霉素过敏用头孢克肟或阿奇霉素；耳痛用对乙酰氨基酚或布洛芬；鼓膜穿孔后用氧氟沙星滴耳液","分泌性中耳炎：观察3个月（部分自行恢复）；治疗病因（腺样体肥大切除、过敏性鼻炎治疗）；鼓膜置管术（持续积液大于3个月、听力下降明显、言语发育迟缓儿童）；口服激素（短期，泼尼松1mg/kg/d×7天，疗效有限不推荐常规）；抗组胺药和减充血剂不推荐常规使用","慢性化脓性中耳炎单纯型：局部治疗为主，3%双氧水清洗脓液+氧氟沙星滴耳液bid×2周；干耳3个月后可行鼓膜修补术（鼓室成形术）","骨疡型和胆脂瘤型：手术治疗（乳突根治术+鼓室成形术），胆脂瘤必须手术（破坏骨质致颅内并发症）","并发症治疗：面瘫（面神经减压+激素）、迷路炎（抗生素+激素）、颅内并发症（急诊手术+抗生素）","预防：儿童接种肺炎球菌疫苗和流感疫苗，避免二手烟，正确哺乳姿势（头高位），积极治疗腺样体肥大和过敏性鼻炎"],"drug_recommendations":[],"non_pharmacological":["急性中耳炎：休息，多饮水，退热止痛，避免用力擤鼻（可致感染扩散），患耳朝上滴药","分泌性中耳炎：做咽鼓管吹张（捏鼻鼓气法，急性感染期禁用），咀嚼口香糖，多做吞咽动作","慢性中耳炎：保持耳部干燥，避免水进入耳道（洗澡游泳用耳塞），不要自行掏耳","饮食：清淡，避免辛辣刺激和酒精，急性炎症期多饮水","预防感冒：上呼吸道感染是中耳炎常见诱因，增强体质，接种疫苗","儿童护理：避免平躺喂奶（乳汁经咽鼓管进入中耳），喂奶后竖抱拍嗝，避免安抚奶嘴过度使用","环境：避免吸烟环境，过敏体质者避免过敏原","术后护理：耳部手术后保持耳道干燥，定期复查清理，避免感冒和用力擤鼻","听力康复：听力损失者及时干预（助听器、手术），儿童注意言语发育","定期复查：慢性中耳炎定期耳内镜和听力检查，胆脂瘤术后长期随访（复发率）"],"complications":["急性乳突炎：急性中耳炎扩散致乳突炎，耳后红肿压痛、耳廓前突，抗生素+乳突切开引流","面神经麻痹：中耳炎侵犯面神经管致周围性面瘫，抗生素+激素+手术减压","迷路炎：内耳感染致眩晕、恶心呕吐、听力下降，抗生素+激素+手术","颅内并发症：脑膜炎、硬膜外脓肿、脑脓肿、乙状窦血栓性静脉炎（头痛发热意识障碍），急诊手术+大剂量抗生素","胆脂瘤：破坏骨质致面瘫、迷路炎、颅内并发症，必须手术切除","传导性耳聋：鼓膜穿孔和听骨链破坏致听力下降，手术修补可恢复","粘连性中耳炎：分泌性中耳炎后遗症，鼓膜粘连听骨链固定，听力下降，治疗困难","胆固醇肉芽肿：中耳出血胆固醇结晶沉积，蓝色鼓膜，手术治疗","药物不良反应：抗生素致胃肠道反应、过敏、肠道菌群紊乱；滴耳液致局部刺激；激素致血糖升高感染扩散","术后复发：胆脂瘤术后复发率5-15%，需长期随访"],"monitoring":["急性中耳炎：耳镜检查（鼓膜充血膨隆）、声导抗、血常规（细菌感染白细胞升高）；抗生素治疗后48-72小时评估疗效","分泌性中耳炎：耳镜（液平气泡）、声导抗（B型图）、纯音测听（传导性聋）；每3个月随访，评估积液是否吸收","慢性中耳炎：耳内镜（鼓膜穿孔、肉芽、胆脂瘤）、纯音测听、颞骨CT（评估骨质破坏和胆脂瘤范围）","术前：颞骨CT、纯音测听、凝血、心电图、控制感染（干耳）","术后：1周、1个月、3个月复查耳内镜和听力，评估鼓膜愈合和听力恢复","胆脂瘤术后：长期随访（每6-12个月），耳内镜+CT，监测复发","儿童：定期听力检查，注意言语发育，必要时言语康复","出现耳后红肿、面瘫、眩晕、剧烈头痛发热：立即就诊（并发症）"],"special_populations":["儿童：AOM高发（6-18个月），观察等待策略（大于2岁轻中度），抗生素剂量按体重，鼓膜置管术指征严格，注意言语发育","孕妇：避免使用耳毒性药物（氨基糖苷类滴耳液鼓膜穿孔时禁用），选择安全抗生素（青霉素、头孢）","老年人：听力下降影响生活，及时干预，手术需评估全身情况","免疫缺陷患者：反复感染，需排查免疫缺陷，抗生素疗程延长，必要时免疫球蛋白替代","鼓膜穿孔者：禁用氨基糖苷类滴耳液（耳毒性），可用氧氟沙星滴耳液，保持耳道干燥","游泳者：慢性中耳炎患者游泳需戴耳塞，避免水进入耳道诱发感染","腭裂儿童：咽鼓管功能障碍，OME高发，需多学科管理，早期鼓膜置管","糖尿病患者：感染不易控制，需控制血糖，抗生素疗程延长，警惕恶性外耳道炎"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 中耳炎诊治指南（2024）","AAO-HNS急性中耳炎临床实践指南","NICE中耳炎和耳痛管理指南"]},{"name":"多囊卵巢综合征诊治指南（2024）","category":"妇产科","scope":"育龄女性多囊卵巢综合征（PCOS）的诊断、分型、治疗和长期管理。","diagnosis":["诊断标准（鹿特丹标准，符合2项并排除其他疾病）：稀发排卵或无排卵（月经稀发/闭经）、高雄激素表现（多毛、痤疮、脱发）或高雄激素血症、卵巢多囊样改变（超声一侧或双侧卵泡大于等于12个，直径2-9mm）","临床表现：月经不规律（稀发、闭经、不规则出血）、不孕、多毛（性毛增多）、痤疮、雄激素性脱发、肥胖（约50-60%）、黑棘皮症（胰岛素抵抗）","分型：按体重（肥胖型/非肥胖型）、按雄激素（高雄激素型/非高雄型）、按胰岛素抵抗（IR型/非IR型）","实验室：性激素（LH/FSH大于2-3、睾酮升高）、AMH升高、胰岛素释放试验（胰岛素抵抗）、血糖血脂、甲状腺功能、泌乳素（排除其他原因）","超声：卵巢多囊样改变（PCOM），注意青春期和口服避孕药者可出现生理性PCOM","鉴别：库欣综合征、先天性肾上腺皮质增生、甲状腺疾病、高泌乳素血症、卵巢雄激素分泌肿瘤、药物性高雄激素","并发症：2型糖尿病、心血管疾病、子宫内膜癌（长期无排卵雌激素刺激）、妊娠期糖尿病、妊高症、抑郁焦虑"],"staging":["按年龄：青春期PCOS、育龄期PCOS、围绝经期PCOS","按体重：肥胖型（BMI大于等于24，胰岛素抵抗常见）、非肥胖型（瘦型PCOS，也可有胰岛素抵抗）","按主要诉求：调经、祛痘多毛、备孕、代谢管理","按严重程度：轻度（月经稀发+轻度高雄）、中度（闭经+明显高雄+胰岛素抵抗）、重度（肥胖+糖尿病前期+不孕）","合并症：合并胰岛素抵抗/糖尿病前期、合并子宫内膜增生、合并妊娠"],"key_points":["生活方式干预是所有PCOS患者的基础治疗（减重5-10%可恢复排卵）","调经：周期性使用孕激素（地屈孕酮10mg bid×10天，每月后半周期）或短效口服避孕药（达英-35、优思明、优思悦，适用于高雄激素表现，同时调经和避孕）","降雄激素：短效口服避孕药（达英-35降雄最强）、螺内酯（50-100mg/d，抗雄激素，需避孕和监测血钾）","改善胰岛素抵抗：二甲双胍500mg tid起始（随餐服，胃肠道反应），逐渐加至1500-2000mg/d；GLP-1受体激动剂（司美格鲁肽，肥胖型PCOS，减重+改善代谢）","促排卵（备孕）：一线来曲唑2.5-5mg/d×5天（月经第3-5天开始）；二线克罗米芬50-100mg/d×5天；三线促性腺激素或腹腔镜卵巢打孔；IVF（以上失败）","孕期管理：控制体重，筛查妊娠期糖尿病（24-28周OGTT），监测血压，预防妊高症","子宫内膜保护：长期无排卵者需定期孕激素转化内膜，防止子宫内膜增生和癌变","痤疮多毛：避孕药+螺内酯+外用药物（阿达帕林、过氧化苯甲酰），多毛可激光脱毛","代谢管理：控制血糖血脂血压，糖尿病前期用二甲双胍，定期筛查糖尿病和心血管风险","心理支持：PCOS患者抑郁焦虑发生率高，需心理疏导"],"drug_recommendations":[],"non_pharmacological":["饮食控制：低升糖指数饮食，减少精制碳水和添加糖，增加膳食纤维、蛋白质、健康脂肪，限制热量（每日减少300-500kcal）","运动：每周至少150分钟中等强度有氧运动+2-3次抗阻训练，减少久坐，目标减重5-10%","体重管理：肥胖型PCOS减重是首要目标，瘦型PCOS也需体成分管理（减少内脏脂肪）","规律作息：避免熬夜，保证7-8小时睡眠，睡眠不足加重胰岛素抵抗","心理调节：减轻压力，PCOS是慢性病需长期管理，避免焦虑，必要时心理咨询","皮肤护理：痤疮和多毛的局部护理，避免挤压，温和护肤","戒烟限酒：吸烟加重心血管风险，酒精增加热量摄入","定期体检：每年查血糖、血脂、血压、妇科超声（子宫内膜）","备孕准备：提前3个月补充叶酸（0.4-0.8mg/d），控制体重和血糖，评估排卵","家庭支持：家人理解和支持，共同健康生活方式"],"complications":["2型糖尿病：PCOS患者糖尿病风险是正常人群的3-7倍，需定期筛查（OGTT）","心血管疾病：高血压、血脂异常、肥胖、胰岛素抵抗增加心血管风险，需综合管理","子宫内膜癌：长期无排卵致子宫内膜持续受雌激素刺激，增生甚至癌变，需定期孕激素保护内膜","妊娠期并发症：妊娠期糖尿病、妊高症、早产、流产风险增加，需加强孕期管理","不孕：无排卵是PCOS不孕的主要原因，促排卵治疗可使多数患者妊娠","抑郁焦虑：PCOS患者抑郁发生率约30-40%，与激素变化、容貌改变（多毛痤疮脱发）、不孕压力有关","代谢综合征：PCOS患者代谢综合征发生率高，需早期干预","药物不良反应：二甲双胍致胃肠道反应（腹泻恶心）；避孕药致血栓风险（吸烟、肥胖、大于35岁者慎用）、情绪变化；螺内酯致高钾血症、月经紊乱；促排卵致多胎、卵巢过度刺激综合征","卵巢过度刺激综合征（OHSS）：促排卵治疗并发症，腹胀腹水胸水、血液浓缩、血栓，严重者危及生命"],"monitoring":["诊断时：性激素六项（月经第2-4天）、AMH、甲状腺功能、泌乳素、17α-羟孕酮（排除先天性肾上腺皮质增生）、空腹血糖+胰岛素、血脂、妇科超声","治疗初期：每1-3个月评估月经情况、症状改善、体重变化、药物不良反应","代谢监测：每6-12个月查空腹血糖、胰岛素、血脂、血压、腰围BMI","妇科超声：每年查子宫内膜厚度（长期无排卵者），异常出血及时诊刮排除内膜病变","备孕期间：监测排卵（B超），评估促排卵效果，预防OHSS","孕期：定期产检，24-28周OGTT筛查妊娠期糖尿病，监测血压和胎儿发育","长期：每年全面体检（血糖、血脂、血压、子宫内膜、乳腺），评估心血管和肿瘤风险","青春期：诊断需谨慎（青春期生理变化可类似PCOS），需长期随访确认"],"special_populations":["青春期PCOS：诊断需符合鹿特丹标准且排除青春期生理变化，治疗以生活方式+调经为主，避免过度诊断和治疗","育龄期PCOS：根据诉求选择调经、降雄、促排卵，备孕前控制代谢，孕期加强管理","围绝经期PCOS：仍需管理代谢和心血管风险，注意子宫内膜保护，激素替代需评估","肥胖型PCOS：减重是核心，GLP-1受体激动剂可考虑，代谢并发症筛查更频繁","瘦型PCOS：也可有胰岛素抵抗，需查胰岛素释放试验，同样需代谢管理","合并糖尿病前期/糖尿病：二甲双胍+生活方式，必要时内分泌科共管，备孕前优化血糖","合并子宫内膜增生：孕激素治疗（甲地孕酮、左炔诺孕酮宫内缓释系统），定期诊刮评估","有血栓风险者（吸烟、肥胖、大于35岁、血栓史）：避免使用口服避孕药，用孕激素调经","服用避孕药者：定期评估血栓风险，出现头痛、胸痛、下肢肿胀立即就诊"],"references":["中华医学会妇产科学分会. 多囊卵巢综合征诊治指南（2024）","2023 ESHRE PCOS指南","AE-PCOS学会PCOS诊疗共识"]},{"name":"绝经综合征诊治指南（2024）","category":"妇产科","scope":"女性围绝经期和绝经后期综合征的诊断、激素治疗和长期健康管理。","diagnosis":["临床表现：月经紊乱（周期延长/缩短、经量变化、不规则出血）、血管舒缩症状（潮热盗汗，最常见）、睡眠障碍、情绪波动（焦虑抑郁易怒）、泌尿生殖道萎缩（阴道干涩、性交痛、尿频尿急反复感染）、骨痛（骨质疏松）、心悸、记忆力下降","诊断：年龄（40岁以上）+典型症状+月经改变，FSH升高（大于25IU/L提示围绝经期，大于40提示绝经），E2降低","分期：绝经过渡期（月经紊乱开始至最后一次月经）、围绝经期（过渡期+绝经后1年）、绝经后期（最后一次月经后）、早绝经（40-45岁）、卵巢早衰（小于40岁）","鉴别：甲状腺功能亢进（潮热心悸体重下降）、抑郁症、嗜铬细胞瘤、类癌综合征、药物性潮热、妊娠（40岁以上仍可能）","影响因素：遗传、吸烟（提前绝经）、体重、运动、营养、子宫切除（手术绝经症状更重）","长期风险：骨质疏松和骨折、心血管疾病、泌尿生殖道萎缩、认知功能下降、阿尔茨海默病风险增加"],"staging":["按年龄：40-45岁（早绝经）、45-55岁（正常绝经）、55岁以上（晚绝经）","按症状严重程度：轻度（不影响生活）、中度（影响生活睡眠）、重度（严重影响生活，潮热频繁）","按绝经原因：自然绝经、人工绝经（手术切除双侧卵巢、化疗放疗致卵巢功能衰竭，症状更重）","按治疗需求：仅泌尿生殖道症状、全身血管舒缩症状、骨质疏松预防、综合管理","按激素治疗风险分层：低危（无禁忌证）、中危（有慎用情况）、高危（有禁忌证）"],"key_points":["绝经激素治疗（MHT）是缓解血管舒缩症状和泌尿生殖道萎缩最有效的方法，有适应证无禁忌证者推荐使用","适应证：潮热盗汗等血管舒缩症状、泌尿生殖道萎缩症状、骨质疏松症（尤其早绝经者）","禁忌证：已知或可疑乳腺癌、子宫内膜癌、不明原因阴道出血、活动性静脉血栓、严重肝肾功能障碍、近期心肌梗死脑卒中、卟啉病、耳硬化症","慎用情况：子宫肌瘤、子宫内膜异位症、乳腺增生、血栓史、胆囊疾病、垂体泌乳素瘤、高血压、糖尿病、哮喘、癫痫、系统性红斑狼疮","方案：单纯雌激素（子宫切除者）、雌孕激素序贯（有子宫，希望来月经，克龄蒙/芬吗通）、雌孕激素连续联合（有子宫，不希望来月经，安今益/替勃龙）、局部雌激素（仅泌尿生殖道症状，欧维婷软膏/更宝芬）","启动时机：窗口期（小于60岁或绝经10年内）启动获益大于风险，超过窗口期不推荐启动全身MHT","剂量：最低有效剂量，根据症状调整，定期评估（每年）是否继续","非激素治疗：潮热用帕罗西汀/文拉法辛（SSRI/SNRI）、加巴喷丁、奥昔布宁；骨质疏松用双膦酸盐（阿仑膦酸钠）、地舒单抗、特立帕肽；阴道干涩用润滑剂和保湿剂","中药：莉芙敏（黑升麻提取物）、坤泰胶囊等（辅助，疗效因人而异）","生活方式干预是基础：运动、饮食、心理、戒烟限酒"],"drug_recommendations":[],"non_pharmacological":["规律运动：每周至少150分钟中等强度有氧运动+抗阻训练（预防骨质疏松和肌肉流失），如快走、游泳、瑜伽、太极","饮食：均衡饮食，增加钙摄入（1000-1200mg/d，牛奶豆制品绿叶菜），维生素D（800-1000IU/d，晒太阳），低盐低脂，增加膳食纤维，限制咖啡因和酒精","体重管理：维持健康BMI（18.5-23.9），避免肥胖（增加乳腺癌和心血管风险）和过度消瘦（骨质疏松风险）","睡眠卫生：规律作息，卧室凉爽（减少潮热），避免睡前咖啡因和酒精，放松训练","心理调节：接受绝经是自然生理过程，减轻焦虑，保持社交和兴趣爱好，必要时心理咨询","皮肤和阴道护理：使用保湿剂，阴道干涩用润滑剂和局部雌激素，避免过度清洁","戒烟限酒：吸烟加速骨丢失和皮肤老化，过量酒精增加乳腺癌风险，限制饮酒","定期体检：每年妇科检查（宫颈防癌筛查、乳腺超声/钼靶）、骨密度、血脂血糖血压","性生活：绝经后可保持性生活，阴道干涩用润滑剂，保持亲密关系","社交活动：多与家人朋友交流，参与社区活动，预防抑郁和认知下降"],"complications":["骨质疏松和骨折：绝经后骨量快速丢失（前5年每年丢失2-3%），椎体和髋部骨折风险增加，需补钙+维生素D+抗骨质疏松药","心血管疾病：绝经后心血管风险显著增加（雌激素保护消失），需控制血压血糖血脂，戒烟，定期心血管评估","泌尿生殖道萎缩：阴道干涩、性交痛、反复尿路感染，局部雌激素治疗有效，长期不治疗影响生活质量","阿尔茨海默病：绝经后认知功能下降风险增加，MHT窗口期可能有保护作用，运动和脑力活动有益","抑郁焦虑：绝经后抑郁发生率增加，需关注情绪变化，必要时心理和药物治疗","肥胖和代谢综合征：绝经后体脂重新分布（腹型肥胖），代谢综合征风险增加，需饮食运动管理","乳腺癌：MHT可能轻度增加乳腺癌风险（雌孕激素连续联合5年以上），需定期乳腺筛查，单纯雌激素不增加风险","子宫内膜癌：有子宫者使用雌激素必须加孕激素保护内膜，不规则出血及时诊刮","血栓栓塞：口服雌激素增加静脉血栓风险，窗口期低剂量风险低，有血栓史者避免口服（可考虑经皮雌激素）","药物不良反应：MHT致乳房胀痛、阴道出血、头痛、恶心、水肿，一般初期出现，逐渐耐受"],"monitoring":["诊断时：FSH、E2、甲状腺功能、血常规、肝肾功能、血脂、血糖、乳腺超声/钼靶、妇科超声（子宫内膜厚度）、宫颈防癌筛查、骨密度（必要时）","MHT启动前：全面评估适应证和禁忌证，乳腺检查（超声/钼靶）、妇科超声（内膜厚度）、血压、血脂血糖、肝肾功能、血栓风险评估","MHT治疗中：每3-6个月评估症状改善和不良反应，每年全面复查（乳腺、妇科、血脂血糖血压、肝肾功能），决定是否继续","骨密度：绝经后每2-3年查骨密度，骨质疏松者每年查，评估骨折风险","心血管：每年查血压、血脂、血糖、心电图，评估心血管风险","乳腺：每年乳腺超声，40岁以上每1-2年钼靶，发现肿块及时就诊","不规则出血：MHT期间出现异常阴道出血需及时就诊，必要时诊刮排除内膜病变","长期随访：MHT使用年限根据症状和风险评估，无固定期限，每年评估利弊"],"special_populations":["早绝经（40-45岁）和卵巢早衰（小于40岁）：MHT获益更大（预防骨质疏松和心血管疾病），建议用至平均绝经年龄（50岁左右），之后评估是否继续","子宫切除者：可单纯雌激素治疗（不需加孕激素），乳腺癌风险不增加","有子宫者：必须雌孕激素联合（保护内膜），根据是否希望来月经选择序贯或连续联合方案","乳腺癌病史者：禁用全身MHT，泌尿生殖道症状用非激素方法（润滑剂），严重者需乳腺科评估","血栓高危者：避免口服雌激素，可考虑经皮雌激素（不增加血栓风险），需个体化评估","胆囊疾病者：口服雌激素增加胆囊疾病风险，可考虑经皮雌激素","子宫内膜异位症/子宫肌瘤者：MHT可能加重，需小剂量密切随访，必要时妇科评估","60岁以上或绝经超过10年：不推荐新启动全身MHT（心血管风险增加），已使用者评估是否继续","严重肝肾功能不全：禁用MHT，用非激素方法缓解症状"],"references":["中华医学会妇产科学分会. 绝经管理与绝经激素治疗指南（2024）","2022 ACOG绝经激素治疗临床指南","NICE绝经管理指南"]},{"name":"儿童肺炎诊治指南（2024）","category":"儿科","scope":"5岁以下儿童社区获得性肺炎（CAP）的诊断、严重程度评估、抗感染治疗和管理。","diagnosis":["临床表现：发热（高热或低热）、咳嗽（早期干咳后期有痰）、呼吸增快（WHO标准：小于2月龄大于等于60次/分，2-12月龄大于等于50，1-5岁大于等于40）、呼吸困难（鼻翼扇动、三凹征、呻吟）、肺部固定中细湿啰音","重症征象：拒食、脱水、意识改变、紫绀、呼吸大于等于70次/分、收缩压低（婴儿小于70mmHg，年长儿小于80）、血氧饱和度小于92%","影像学：胸片（斑片状阴影、肺实变、胸腔积液），必要时胸部CT","病原学：病毒（呼吸道合胞病毒RSV、流感、腺病毒、新冠，最常见）、细菌（肺炎链球菌、流感嗜血杆菌、金黄色葡萄球菌）、非典型病原体（支原体、衣原体，5岁以上多见）","鉴别：急性支气管炎（无呼吸困难和湿啰音，胸片正常）、支气管哮喘（喘息反复发作，过敏史）、肺结核（慢性咳嗽低热盗汗，结核接触史）、异物吸入（突然呛咳，单侧体征）、先天性心脏病（心脏杂音，反复肺炎）","危险因素：早产、低出生体重、营养不良、先天性心脏病、免疫缺陷、慢性肺病、拥挤环境、被动吸烟"],"staging":["按严重程度：轻度（可门诊治疗，精神好，无呼吸困难，血氧正常）、重度（需住院，呼吸困难、缺氧、拒食、意识改变）、极重度（需ICU，呼吸衰竭、休克、多器官功能障碍）","按病原：病毒性肺炎、细菌性肺炎、支原体肺炎、混合感染","按部位：大叶性肺炎、支气管肺炎（最常见儿童）、间质性肺炎","按病程：急性（小于1个月）、迁延性（1-3个月）、慢性（大于3个月）","按并发症：单纯肺炎、合并胸腔积液/脓胸、合并肺脓肿、合并呼吸衰竭、合并心力衰竭"],"key_points":["轻症门诊：口服抗生素，阿莫西林80-100mg/kg/d分3次（首选，覆盖肺炎链球菌），青霉素过敏用头孢克肟或阿奇霉素；疗程5-7天","重症住院：静脉抗生素，阿莫西林克拉维酸钾或头孢呋辛/头孢曲松；怀疑金黄色葡萄球菌用苯唑西林或万古霉素（MRSA）；支原体用阿奇霉素10mg/kg/d×3-5天","病毒性肺炎：一般不用抗生素（除非合并细菌感染），流感用奥司他韦（48小时内），RSV用支持治疗，严重者用利巴韦林雾化（有限证据）","对症治疗：退热（对乙酰氨基酚10-15mg/kg/次或布洛芬5-10mg/kg/次，避免阿司匹林）、止咳化痰（氨溴索、乙酰半胱氨酸）、雾化（生理盐水+布地奈德+支气管扩张剂，喘息者）、氧疗（血氧小于92%）","重症：呼吸支持（鼻导管、面罩、高流量、无创通气、气管插管机械通气）、液体管理（避免过量致肺水肿）、糖皮质激素（重症肺炎合并喘息或休克，甲泼尼龙1-2mg/kg/d，短期）","胸腔积液/脓胸：胸腔穿刺引流，必要时胸腔闭式引流，抗生素疗程延长","预防：接种肺炎球菌疫苗（13价PCV13）、流感疫苗（6个月以上每年）、Hib疫苗；母乳喂养；避免被动吸烟；勤洗手","住院指征：小于3个月婴儿、重症肺炎、有基础疾病、门诊治疗无效、家庭护理条件差"],"drug_recommendations":[],"non_pharmacological":["休息和护理：保持室内空气流通，温度20-22℃，湿度50-60%，避免干燥和烟雾刺激","饮食：清淡易消化，多饮水，保证营养，拒食者少量多餐，婴儿继续母乳喂养","拍背排痰：勤翻身拍背（由下向上由外向内），帮助痰液排出，避免剧烈拍背","物理降温：发热时温水擦浴，减少衣物，避免酒精擦浴和捂汗","观察病情：密切观察呼吸、心率、体温、精神状态、尿量，出现呼吸困难加重、紫绀、意识改变立即就医","避免交叉感染：患病期间不去幼儿园和人群密集场所，戴口罩，勤洗手","雾化治疗：按医嘱雾化，雾化后洗脸漱口（减少激素残留），正确使用雾化器","恢复期：逐渐增加活动，避免剧烈运动，注意保暖预防感冒","营养支持：营养不良者补充蛋白质和维生素，促进恢复","疫苗接种：按程序接种肺炎球菌疫苗和流感疫苗，预防反复肺炎"],"complications":["呼吸衰竭：重症肺炎致低氧血症和高碳酸血症，需氧疗和机械通气，是主要死亡原因","心力衰竭：肺炎合并心衰（呼吸大于60、心率大于180、肝脏增大、水肿），需强心利尿","胸腔积液和脓胸：细菌感染致胸膜腔积液化脓，需穿刺引流，严重者手术","肺脓肿：坏死性肺炎致肺组织坏死空洞，需长疗程抗生素，必要时手术","气胸：肺大疱破裂致气胸，突发呼吸困难，需胸腔闭式引流","中毒性脑病：严重感染致意识障碍、抽搐，需降颅压和对症治疗","DIC和多器官功能障碍：极重症，死亡率高，需ICU综合治疗","支气管扩张：慢性或反复肺炎致支气管扩张，长期咳嗽咳痰，需长期管理","药物不良反应：抗生素致腹泻、皮疹、过敏；退热剂过量致肝损伤（对乙酰氨基酚）或肾损伤（布洛芬）；雾化激素致口腔念珠菌感染（漱口预防）","哮喘诱发：病毒感染诱发哮喘发作，需同时平喘治疗"],"monitoring":["门诊：诊断时查血常规、CRP、胸片（必要时），抗生素治疗48-72小时评估疗效（体温、呼吸、精神），无效需复诊或住院","住院：入院查血常规、CRP、降钙素原、胸片、血气分析（重症）、病原学（痰培养、呼吸道病毒抗原、支原体抗体）、血培养（重症）","治疗期间：每日评估体温、呼吸、心率、血氧、肺部体征、精神食欲，调整治疗","重症：持续监护生命体征和血氧，每4-6小时评估，复查血气和胸片（病情变化时）","出院标准：体温正常24小时以上、呼吸平稳、血氧正常、能口服进食、肺部体征改善","出院后：1-2周复诊，评估恢复情况，必要时复查胸片，迁延不愈者进一步检查（异物、结核、免疫缺陷、先心病）","反复肺炎者：排查基础疾病（先心病、免疫缺陷、支气管肺发育不良、异物、囊性纤维化）","疫苗接种记录：确认肺炎球菌疫苗和流感疫苗接种情况，未接种者建议接种"],"special_populations":["新生儿和小婴儿（小于3个月）：症状不典型（可无发热，表现为拒奶、吐奶、呼吸暂停、精神差），病情进展快，均需住院，抗生素覆盖B族链球菌和大肠杆菌","早产儿：肺发育不成熟，肺炎易合并呼吸衰竭，需呼吸支持，注意液体管理和支气管肺发育不良","先天性心脏病患儿：肺炎易诱发心衰，需同时强心利尿，抗生素疗程延长","免疫缺陷患儿：感染病原体多样（真菌、病毒、机会性感染），需广覆盖抗生素和免疫支持，病情重","哮喘患儿：肺炎诱发哮喘急性发作，需同时平喘治疗（雾化支气管扩张剂+激素）","营养不良患儿：恢复慢，需加强营养支持，补充蛋白质和维生素","支原体肺炎（5岁以上）：咳嗽剧烈，肺部体征轻，胸片重，用阿奇霉素，注意耐药和肝功能损害","流感病毒肺炎：流感季节高发，48小时内用奥司他韦，易合并细菌感染，重症需住院","过敏体质：抗生素选择需注意过敏史，青霉素过敏者用头孢类需交叉过敏评估"],"references":["中华医学会儿科学分会. 儿童社区获得性肺炎诊治指南（2024）","WHO儿童肺炎管理指南","AAP儿童社区获得性肺炎管理指南"]},{"name":"儿童腹泻病诊治指南（2024）","category":"儿科","scope":"儿童急性腹泻病的诊断、脱水评估、补液治疗和饮食管理。","diagnosis":["临床表现：大便次数增多（大于等于3次/天）和性状改变（稀便、水样便、黏液脓血便），可伴发热、呕吐、腹痛","脱水评估：轻度（精神稍差、口唇稍干、尿量略减、皮肤弹性正常，失水量3-5%）、中度（烦躁、口唇干、眼窝凹陷、皮肤弹性差、尿量明显减少，失水量5-10%）、重度（嗜睡昏迷、皮肤弹性极差、四肢凉、脉细弱、无尿、休克，失水量大于10%）","分型：急性腹泻（小于2周）、迁延性腹泻（2周-2个月）、慢性腹泻（大于2个月）","病原：病毒（轮状病毒、诺如病毒，最常见，秋冬季节）、细菌（大肠杆菌、沙门菌、志贺菌、弯曲菌，夏季多见，黏液脓血便）、寄生虫（贾第虫、阿米巴）、非感染性（饮食不当、过敏、乳糖不耐受、抗生素相关性）","辅助检查：大便常规+潜血、大便培养（细菌感染）、轮状病毒/诺如病毒抗原、血常规、电解质+血气（脱水时）","鉴别：生理性腹泻（6个月以内婴儿，虚胖湿疹，大便次数多但生长发育正常）、牛奶蛋白过敏（湿疹、呕吐、血便，回避牛奶后好转）、炎症性肠病（慢性腹泻血便、生长迟缓）、肠套叠（阵发性哭闹、果酱样便、腹部包块，急症）"],"staging":["按脱水程度：轻度脱水、中度脱水、重度脱水（休克）","按病程：急性（小于2周）、迁延性（2周-2个月）、慢性（大于2个月）","按病原：病毒性腹泻、细菌性腹泻、寄生虫性腹泻、非感染性腹泻","按严重程度：轻型（无脱水，可门诊）、中型（轻中度脱水，门诊或住院）、重型（重度脱水/休克，急诊住院）","按营养状况：营养正常、营养不良（腹泻更严重，恢复慢）"],"key_points":["补液是核心治疗，预防和纠正脱水","口服补液盐（ORS）：轻中度脱水首选，ORS III（低渗），用量=累计损失量+继续损失量+生理需要量；轻度50-80ml/kg，中度80-100ml/kg，4-6小时内补完，少量多次喂服","静脉补液：重度脱水或呕吐严重不能口服者，快速扩容（等渗含钠液20ml/kg，30-60分钟内），之后继续补液纠正累积损失和生理需要","补锌：所有腹泻儿童补锌（大于6个月20mg/d，小于6个月10mg/d），疗程10-14天，缩短病程减少复发","益生菌：布拉氏酵母菌、鼠李糖乳杆菌GG，可缩短病程12-24小时，早期使用","蒙脱石散：保护肠黏膜，减少排便次数，饭前服用，与其他药间隔1-2小时","抗生素：仅用于细菌性腹泻（黏液脓血便、高热、中毒症状、大便培养阳性），病毒性腹泻不用抗生素；大肠杆菌用头孢曲松/头孢噻肟，沙门菌用阿莫西林/头孢曲松，志贺菌用头孢曲松/阿奇霉素","止吐药：不常规使用，严重呕吐可短期用昂丹司琼（大于6个月），禁用胃复安（儿童锥体外系反应）","止泻药：禁用洛哌丁胺（儿童，尤其细菌感染可致中毒性巨结肠）","饮食：继续喂养，不禁食，母乳喂养继续，配方奶喂养可继续（怀疑乳糖不耐受换无乳糖配方），避免高糖高脂食物","预防：接种轮状病毒疫苗（口服，2-6月龄开始），勤洗手，注意饮食卫生，避免交叉感染"],"drug_recommendations":[],"non_pharmacological":["口服补液：少量多次喂ORS，每次10-20ml，间隔5-10分钟，避免一次大量喂服致呕吐","继续喂养：腹泻期间不禁食，母乳喂养继续，已添加辅食者给清淡易消化食物（米粥、面条、苹果泥），避免果汁、碳酸饮料、高糖食物（加重腹泻）","腹部护理：注意腹部保暖，避免受凉，可腹部热敷（注意温度防烫伤）","臀部护理：勤换尿布，每次便后温水清洗臀部，涂护臀膏，预防红臀和尿布疹","观察病情：密切观察精神状态、尿量、皮肤弹性、眼窝凹陷、体温、呕吐情况，出现脱水加重立即就医","消毒隔离：感染性腹泻需注意手卫生，粪便消毒处理，避免交叉感染（尤其轮状病毒诺如病毒传染性强）","补充水分：除ORS外可饮水、米汤、口服补液，避免含糖饮料和运动饮料","恢复期饮食：逐渐恢复正常饮食，由稀到稠，由少到多，不要急于进补","记录出入量：记录大便次数性状、尿量、呕吐量、进食量，评估脱水程度","家庭备药：家中常备ORS III、蒙脱石散、益生菌、退热剂，腹泻时及时使用"],"complications":["脱水和休克：严重腹泻致重度脱水、低血容量性休克，是儿童腹泻主要死亡原因，需紧急静脉补液","电解质紊乱：低钾血症（腹胀、肌无力、心律失常）、低钠血症（嗜睡、抽搐）、代谢性酸中毒（呼吸深快），需及时纠正","营养不良：迁延性慢性腹泻致蛋白质能量营养不良，影响生长发育，恶性循环","乳糖不耐受：腹泻后肠黏膜损伤致乳糖酶缺乏，腹泻迁延不愈，换无乳糖配方奶","牛奶蛋白过敏：腹泻伴血便湿疹，回避牛奶蛋白，用深度水解或氨基酸配方","惊厥：腹泻伴良性惊厥（轮状病毒相关），或电解质紊乱致惊厥，需止惊和纠正电解质","溶血尿毒综合征（HUS）：大肠杆菌O157:H7感染后，溶血性贫血、血小板减少、急性肾衰，需透析治疗","中毒性巨结肠：细菌性痢疾或炎症性肠病，禁用止泻药，需外科干预","药物不良反应：抗生素致肠道菌群紊乱和抗生素相关性腹泻；蒙脱石散过量致便秘；益生菌罕见真菌感染（免疫低下者）","生长迟缓：慢性腹泻影响营养吸收，致体重不增和身高增长缓慢"],"monitoring":["诊断时：大便常规+潜血、轮状病毒/诺如病毒抗原、血常规；脱水者查电解质+血气；细菌感染查大便培养","门诊治疗：4小时后复诊评估脱水纠正情况，调整补液量，指导饮食和用药","住院：入院查电解质、血气、血糖、肾功能，每4-6小时评估脱水和生命体征，记录出入量","补液后：评估脱水纠正情况（精神、尿量、皮肤弹性），调整补液速度和成分","腹泻持续：大于7天需排查乳糖不耐受、牛奶蛋白过敏、寄生虫感染、免疫缺陷，调整饮食","出院标准：脱水纠正、能口服进食、大便次数减少、精神食欲好转","出院后：继续补锌至10-14天，注意饮食卫生，观察大便情况，出现反复或加重及时就诊","反复腹泻者：排查基础疾病（免疫缺陷、囊性纤维化、食物过敏、乳糖酶缺乏、炎症性肠病）","生长发育监测：慢性腹泻儿童定期监测体重身高，评估营养状况"],"special_populations":["小于6个月婴儿：脱水进展快，需密切观察，ORS少量多次喂，母乳喂养继续，避免高渗液体，重度脱水立即住院","早产儿：腹泻易合并脱水和电解质紊乱，需住院治疗，注意营养支持","营养不良儿童：脱水程度易被低估（皮肤弹性差基线），补液需谨慎，同时营养支持","免疫缺陷儿童：感染病原体多样，病情重，需广覆盖抗生素和免疫支持，住院治疗","牛奶蛋白过敏：回避牛奶蛋白，用深度水解或氨基酸配方，母亲哺乳期也需回避牛奶","乳糖不耐受：换无乳糖配方奶或添加乳糖酶，一般2-4周后肠黏膜恢复可逐渐转回普通配方","细菌性痢疾：黏液脓血便、高热、里急后重，需抗生素（头孢曲松/阿奇霉素），隔离至大便培养阴性","抗生素相关性腹泻：长期用抗生素后腹泻，停用不必要抗生素，用益生菌（布拉氏酵母菌），难辨梭菌感染用甲硝唑/万古霉素","旅行相关腹泻：注意饮食卫生，可备ORS和益生菌，严重者就医","秋季腹泻（轮状病毒）：高发季节，接种疫苗预防，对症治疗为主，不用抗生素"],"references":["中华医学会儿科学分会. 儿童腹泻病诊治指南（2024）","WHO儿童腹泻病管理指南","AAP儿童急性胃肠炎管理指南"]},{"name":"静脉血栓栓塞症诊治指南（2024）","category":"心血管内科","scope":"深静脉血栓形成（DVT）和肺血栓栓塞症（PTE）的诊断、危险分层、抗凝治疗和长期管理。","diagnosis":["DVT表现：患肢肿胀、疼痛、皮温升高、浅静脉扩张、Homans征（可阳性但不推荐常规查）","PTE表现：不明原因呼吸困难、胸痛、咯血、晕厥、心动过速、烦躁，严重者休克猝死","D-二聚体：阴性可排除低危患者，阳性需进一步影像学检查","下肢静脉超声：DVT诊断首选，敏感性特异性高","CT肺动脉造影（CTPA）：PTE诊断金标准，可见肺动脉内充盈缺损","心电图：S1Q3T3（典型但少见）、右束支传导阻滞、T波倒置（V1-V4）","血气分析：低氧血症、低碳酸血症、肺泡-动脉氧分压差增大","超声心动图：右心室扩大、肺动脉高压、室间隔左移，评估右心功能","危险分层：高危（休克/低血压）、中危（右心功能不全+心肌损伤标志物升高）、低危","鉴别：急性冠脉综合征、主动脉夹层、肺炎、胸膜炎、心包炎、心衰"],"staging":["按部位：DVT（下肢近端/远端、上肢、内脏静脉）、PTE（大面积/次大面积/非大面积）","按危险分层：高危PTE（休克/低血压，死亡率大于15%）、中危（右心功能不全或心肌损伤，死亡率3-15%）、低危（无右心功能不全，死亡率小于1%）","按病程：急性（小于2周）、亚急性（2周-3个月）、慢性（大于3个月，慢性血栓栓塞性肺动脉高压CTEPH）","按病因：特发性、继发性（手术、创伤、肿瘤、妊娠、口服避孕药、卧床、易栓症）","DVT分型：中央型（髂股静脉）、周围型（小腿静脉）、混合型"],"key_points":["抗凝治疗是基础，所有确诊VTE患者均应立即启动抗凝（无禁忌）","胃肠外抗凝：低分子肝素（依诺肝素1mg/kg q12h或1.5mg/kg qd，按体重）、普通肝素（80U/kg负荷+18U/kg/h维持，监测APTT）、磺达肝癸钠（按体重5-10mg qd）","口服抗凝：直接口服抗凝药DOAC（利伐沙班15mg bid×21天后20mg qd、阿哌沙班10mg bid×7天后5mg bid、达比加群150mg bid、艾多沙班60mg qd），优先于华法林；华法林（起始2.5-3mg，监测INR目标2-3，需与胃肠外抗凝重叠至少5天）","溶栓治疗：高危PTE（休克/低血压），无禁忌者溶栓（阿替普酶50-100mg 2小时静滴，或尿激酶2万U/kg 2小时）；中高危PTE溶栓需权衡","介入/手术：高危PTE溶栓禁忌或失败，可行导管碎栓/取栓、外科肺动脉取栓；DVT介入溶栓/取栓用于髂股静脉DVT（减少血栓后综合征）","下腔静脉滤器：抗凝禁忌或抗凝中仍复发PTE者，首选可回收滤器，抗凝恢复后尽早取出","疗程：可逆性因素（手术创伤）3个月；特发性/持续性危险因素至少3-6个月，评估出血风险后决定是否延长；肿瘤患者至少3-6个月，活动性肿瘤无限期抗凝","DVT压力治疗：急性期后使用医用弹力袜（II级压力），减少血栓后综合征","CTEPH：肺动脉内膜剥脱术（首选）、球囊肺动脉成形术、靶向药物（利奥西呱）"],"drug_recommendations":[],"non_pharmacological":["急性期卧床休息：DVT急性期卧床1-2周，避免按摩挤压患肢（防血栓脱落致PTE），抬高患肢（高于心脏20-30cm）","早期活动：抗凝充分后可早期下床活动（不增加PTE风险），避免长期卧床","压力治疗：DVT恢复期穿医用弹力袜（晨起穿睡前脱），持续6-12个月，预防血栓后综合征","饮食：低脂高纤维，多饮水，避免脱水（增加血液黏稠），戒烟限酒","控制体重：肥胖是VTE危险因素","避免久坐久站：每1-2小时活动下肢，长途旅行定时活动脚踝，穿弹力袜","预防：手术患者评估VTE风险（Caprini评分），高危者药物预防（低分子肝素）+机械预防（间歇充气加压）；长期卧床者被动活动下肢","孕期管理：孕期VTE用低分子肝素（不通过胎盘），产后继续抗凝6周，避免DOAC和华法林（致畸）","肿瘤患者：活动性肿瘤是VTE高危，住院期间预防抗凝，Khorana评分评估风险","康复：DVT后逐渐增加活动量，避免剧烈运动，定期评估有无血栓后综合征（下肢肿胀、色素沉着、溃疡）"],"complications":["肺栓塞：DVT血栓脱落致PTE，是DVT最严重并发症，可猝死","血栓后综合征（PTS）：DVT后慢性静脉功能不全，下肢肿胀、疼痛、色素沉着、皮肤溃疡，发生率20-50%，压力治疗可预防","慢性血栓栓塞性肺动脉高压（CTEPH）：PTE后血栓未完全溶解，肺动脉高压，活动后呼吸困难，右心衰竭，需专科评估","出血：抗凝治疗最常见不良反应，严重出血（颅内、消化道）需停药+拮抗剂（DOAC用特异性拮抗剂，华法林用维生素K+PCC）","肝素诱导的血小板减少症（HIT）：普通肝素多见，血小板下降大于50%，需停用肝素换用阿加曲班","皮肤坏死：华法林治疗初期蛋白C缺乏者可出现皮肤坏死，需先肝素重叠","骨质疏松：长期肝素治疗（大于3个月）致骨质疏松，低分子肝素较少见","复发：抗凝不充分或易栓症者复发风险高，需评估疗程","下腔静脉滤器并发症：滤器移位、断裂、下腔静脉穿孔、血栓形成，可回收滤器需按时取出","死亡：高危PTE死亡率高，需紧急溶栓或取栓"],"monitoring":["诊断时：D-二聚体、血常规、凝血（APTT、PT、INR、纤维蛋白原）、肝肾功能、下肢静脉超声（DVT）、CTPA（PTE）、心电图、超声心动图、血气分析、心肌损伤标志物（肌钙蛋白、BNP/NT-proBNP）","抗凝初期：低分子肝素按体重给药不需常规监测；普通肝素监测APTT（目标1.5-2.5倍对照）；华法林监测INR（目标2-3，每周查至稳定后每月查）；DOAC不需常规监测","治疗期间：每3-6个月评估出血和复发风险，决定抗凝疗程；定期查血常规、肝肾功能、大便潜血","溶栓后：监测生命体征、出血征象、凝血功能，复查CTPA评估溶栓效果","滤器置入后：定期影像学复查，评估滤器位置和血栓，抗凝恢复后尽早取出可回收滤器","长期：定期评估VTE复发风险（D-二聚体、静脉超声），出血风险，调整抗凝方案","CTEPH筛查：PTE后3个月仍有呼吸困难者，查超声心动图和V/Q显像，必要时右心导管确诊"],"special_populations":["孕妇：禁用华法林（致畸）和DOAC，用低分子肝素抗凝，产后继续6周，哺乳期低分子肝素和华法林安全","肿瘤患者：VTE风险高，Khorana评分评估，首选低分子肝素（优于华法林），DOAC可用于胃肠道肿瘤以外的肿瘤，注意出血和药物相互作用","老年人：出血风险高，DOAC需根据肾功能调整剂量（利伐沙班、阿哌沙班、艾多沙班），华法林INR目标2-3，密切监测","肾功能不全：低分子肝素和DOAC需根据eGFR调整，eGFR小于30慎用DOAC，普通肝素可用（监测APTT）","肝功能不全：华法林和DOAC需谨慎，严重肝病禁用，低分子肝素相对安全","围手术期：术前根据血栓和出血风险决定是否桥接抗凝（高血栓风险用低分子肝素桥接），术后尽早恢复抗凝","易栓症患者：抗凝血酶、蛋白C、蛋白S缺乏，因子V Leiden、凝血酶原基因突变，需长期抗凝","活动性出血：暂停抗凝，处理出血，用特异性拮抗剂，出血控制后评估恢复抗凝时机"],"references":["中华医学会心血管病学分会. 肺血栓栓塞症诊治与预防指南（2024）","2024 ESC急性肺栓塞诊断和管理指南","ACCP静脉血栓栓塞症抗栓治疗指南（第10版）"]},{"name":"主动脉夹层诊治指南（2024）","category":"心血管内科","scope":"主动脉夹层（AD）的分型、急诊处理、药物治疗和手术指征。","diagnosis":["临床表现：突发剧烈胸背部撕裂样疼痛（最典型），可放射至背腹下肢，伴大汗、恶心呕吐、晕厥","体征：双上肢血压差大于20mmHg、脉搏不对称、主动脉瓣区舒张期杂音、心包摩擦音、胸腔积液","分型：Stanford A型（累及升主动脉，需急诊手术）、Stanford B型（仅累及降主动脉，药物治疗为主）","DeBakey分型：I型（升主动脉+降主动脉）、II型（仅升主动脉）、III型（仅降主动脉）","辅助检查：D-二聚体升高（阴性可排除低危）、心电图（排除心梗，可示左室肥厚、心肌缺血）、胸片（纵隔增宽、主动脉结增大）、超声心动图（经胸/经食管，发现内膜片、主动脉瓣反流、心包积液）、CTA（诊断金标准，明确分型和范围）、MRI（稳定期评估）","鉴别：急性心肌梗死（心电图和肌钙蛋白动态变化，CTA正常）、肺栓塞（CTPA）、急性心包炎、胸膜炎、急腹症、脑卒中","高危因素：高血压（最常见，控制不佳）、马凡综合征、主动脉瓣二叶畸形、主动脉缩窄、妊娠、创伤、医源性、炎症性疾病"],"staging":["Stanford分型：A型（累及升主动脉，无论远端范围，急诊手术）、B型（不累及升主动脉，药物治疗，有并发症时手术/介入）","按病程：急性期（小于14天）、亚急性期（15-90天）、慢性期（大于90天）","B型复杂夹层：合并脏器缺血、持续疼痛、高血压难以控制、夹层进展或破裂、动脉瘤样扩张（大于5.5cm或年增长大于5mm）","B型非复杂夹层：无上述并发症，药物治疗为主","按破口位置：近端破口（A型）、远端破口（B型）","合并症：主动脉瓣关闭不全、心包填塞、脏器缺血（冠脉、脑、肾、肠、下肢）、破裂"],"key_points":["急诊处理：绝对卧床、心电监护、吸氧、建立静脉通路、镇痛（吗啡2-4mg静推或哌替啶50-100mg肌注）","控制心率和血压是核心：目标心率60次/分以下，收缩压100-120mmHg（保证重要脏器灌注）","降心率降血压：β受体阻滞剂首选（美托洛尔5mg静推每5分钟，总量15mg；或艾司洛尔500μg/kg负荷+50-300μg/kg/min维持），心率达标后加用血管扩张剂（硝普钠0.5-1μg/kg/min起始，根据血压调整，注意硝普钠不可单独用（增加dp/dt加重夹层））","不能用β阻滞剂者：用非二氢吡啶类钙通道阻滞剂（地尔硫䓬、维拉帕米）","镇痛：阿片类镇痛药，注意血压下降","A型夹层：急诊外科手术（升主动脉置换+主动脉瓣修复/置换+孙氏手术），发病24小时内死亡率每小时增加1-2%","B型非复杂夹层：药物治疗，控制血压心率，密切监测","B型复杂夹层：胸主动脉腔内修复术（TEVAR，覆膜支架封堵破口），或外科手术","长期降压：目标血压小于130/80mmHg，长期用β受体阻滞剂+ACEI/ARB，避免剧烈运动和重体力劳动","随访：定期CTA或MRI评估夹层进展和动脉瘤形成"],"drug_recommendations":[],"non_pharmacological":["绝对卧床休息：急性期严格卧床，避免用力（咳嗽、排便、情绪激动），保持大便通畅（缓泻剂）","饮食：清淡易消化，低盐低脂，避免饱餐，急性期可流质或半流质","控制血压：长期严格控制血压（小于130/80），家庭自测血压，规律服药不可自行停药","避免剧烈活动：恢复期避免剧烈运动、重体力劳动、举重、潜水等增加胸腹腔压力的活动","戒烟限酒：吸烟加重动脉粥样硬化，酒精影响血压控制","控制体重：肥胖增加心脏负担和血压","心理调节：避免情绪激动和紧张，保持心情舒畅，必要时心理疏导","定期随访：按医嘱定期复查CTA/MRI，监测夹层变化，出现胸背痛立即就诊","遗传咨询：马凡综合征等遗传性疾病患者需家族筛查","孕期管理：主动脉夹层高危孕妇需产科和心外科共管，控制血压，选择合适分娩方式"],"complications":["主动脉破裂：最致命并发症，夹层外膜破裂致大出血、心包填塞、休克，猝死","心包填塞：A型夹层破入心包，血压下降、颈静脉怒张、心音遥远，急诊心包穿刺+手术","主动脉瓣关闭不全：A型夹层累及主动脉瓣，急性左心衰，需手术","脏器缺血：夹层累及分支动脉致冠脉缺血（心梗）、脑缺血（卒中）、肾缺血（肾衰）、肠缺血（肠坏死）、下肢缺血（肢体坏死）","动脉瘤形成：慢性期夹层假腔动脉瘤样扩张（大于5.5cm），破裂风险增加，需手术/介入","术后并发症：出血、感染、神经系统并发症（截瘫，B型手术/TEVAR后）、肾功能不全、内漏（TEVAR后）","药物不良反应：β阻滞剂致心动过缓、支气管痉挛；硝普钠致氰化物中毒（长期大剂量）、低血压；降压药致脏器灌注不足","死亡：A型夹层未手术48小时死亡率大于50%，B型药物治疗死亡率约10%，复杂B型更高"],"monitoring":["急诊：心电图、肌钙蛋白（排除心梗）、D-二聚体、血常规、凝血、肝肾功能、电解质、血型交叉配血、胸片、超声心动图、CTA（明确分型和范围）","急性期：持续心电血压血氧监护，每5-15分钟测血压心率，记录尿量、神志、肢体脉搏和感觉运动（评估脏器缺血）","药物调整期：根据血压心率调整药物剂量，目标心率小于60，收缩压100-120","术后/介入后：监护生命体征，复查CTA（评估手术效果和内漏），监测肾功能（造影剂肾病）、下肢活动（截瘫）","长期：每3-6个月复查CTA或MRI（评估夹层稳定、动脉瘤形成、支架位置），每年查心电图、超声心动图、肝肾功能","出现胸背痛、血压骤升、肢体麻木无力：立即就诊（夹层进展或破裂）","马凡综合征患者：每年心脏超声和主动脉CTA，监测主动脉根部直径，大于50mm考虑预防性手术"],"special_populations":["老年人：动脉硬化严重，合并症多，手术风险高，B型优先TEVAR，A型需评估手术耐受","孕妇：妊娠晚期夹层风险增加（马凡综合征主动脉根部大于40mm者风险高），需多学科管理，A型需急诊手术（兼顾胎儿），B型药物治疗为主","马凡综合征患者：主动脉根部扩张，预防性手术指征（根部大于50mm或年增长大于5mm），术后仍需随访全主动脉","主动脉瓣二叶畸形：易合并主动脉扩张和夹层，需定期随访主动脉直径","高血压患者：严格控制血压是预防关键，避免血压剧烈波动","慢性肾病：造影剂肾病风险，术前水化，根据肾功能调整药物","服用抗凝药者：夹层手术需逆转抗凝（华法林用维生素K+PCC，DOAC用特异性拮抗剂）","结缔组织病：系统性红斑狼疮、白塞病等可致主动脉炎和夹层，需同时治疗原发病"],"references":["中华医学会心血管病学分会. 主动脉夹层诊断和治疗指南（2024）","2024 ESC主动脉疾病诊断和治疗指南","AHA/ACC胸主动脉疾病指南"]},{"name":"肠易激综合征诊治指南（2024）","category":"消化内科","scope":"成人肠易激综合征（IBS）的诊断标准、分型、治疗和长期管理。","diagnosis":["诊断标准（罗马IV）：反复发作的腹痛，近3个月内平均每周至少1天，伴以下2项或以上：与排便相关、排便频率改变、粪便性状改变，症状持续大于6个月，近3个月符合标准","分型：IBS-D（腹泻型，排便次数增多稀便）、IBS-C（便秘型，排便困难干硬便）、IBS-M（混合型，腹泻便秘交替）、IBS-U（未定型）","报警症状（需排除器质性疾病）：年龄大于50岁新发、体重下降、消化道出血、贫血、发热、夜间腹泻、炎症性肠病或结直肠癌家族史","辅助检查：血常规、CRP/血沉、粪便常规+潜血、粪便钙卫蛋白（排除IBD）、甲状腺功能、乳糖不耐受检测、结肠镜（有报警症状或年龄大于50岁）","鉴别：炎症性肠病（克罗恩、溃疡性结肠炎，粪便钙卫蛋白升高、内镜异常）、乳糖不耐受、小肠细菌过度生长（SIBO）、甲状腺功能亢进、结直肠癌、慢性感染（寄生虫、艰难梭菌）、功能性腹泻/便秘","诱因：饮食（辛辣、生冷、乳制品、高脂、FODMAP食物）、精神心理因素（焦虑抑郁、压力）、肠道感染后（感染后IBS）、肠道菌群失调、内脏高敏感性"],"staging":["按主要症状：IBS-D（腹泻型）、IBS-C（便秘型）、IBS-M（混合型）、IBS-U（未定型）","按严重程度：轻度（症状轻，不影响生活）、中度（影响生活）、重度（严重影响生活和工作，常伴心理障碍）","按病因：感染后IBS、饮食相关IBS、心理因素相关IBS、特发性IBS","按肠道菌群：菌群失调型、正常型","合并症：焦虑抑郁、纤维肌痛、慢性疲劳综合征、间质性膀胱炎、胃食管反流"],"key_points":["个体化治疗，根据分型和症状选择药物","IBS-D：止泻药（洛哌丁胺2mg按需，最大16mg/d，注意便秘）、5-HT3受体拮抗剂（阿洛司琼，女性重度IBS-D，注意缺血性结肠炎）、利福昔明（肠道非吸收抗生素，550mg tid×14天，改善腹胀腹泻）、胆酸螯合剂（考来维仑，胆汁酸性腹泻）","IBS-C：促分泌药（利那洛肽290μg qd、普卡那肽3mg qd，增加肠道分泌）、渗透性泻药（聚乙二醇、乳果糖）、促动力药（普芦卡必利，女性）、5-HT4激动剂","腹痛：解痉药（匹维溴铵50mg tid、奥替溴铵40mg tid、山莨菪碱10mg tid按需，注意抗胆碱副作用）、薄荷油（0.2-0.4ml tid，解痉）、三环类抗抑郁药（阿米替林10-25mg qn，小剂量镇痛和改善内脏高敏）、SNRI（度洛西汀，合并抑郁）","腹胀：益生菌（双歧杆菌、乳酸杆菌，菌株特异性）、西甲硅油（消泡剂）、利福昔明（SIBO相关）","饮食治疗：低FODMAP饮食（限制发酵性寡糖双糖单糖和多元醇，2-6周后逐步重新引入），避免已知诱因食物","心理治疗：认知行为治疗（CBT）、催眠疗法、正念减压，对中重度IBS和合并心理障碍者有效","避免使用：刺激性泻药（IBS-C）、阿片类止泻药长期使用（依赖）、不必要的抗生素"],"drug_recommendations":[],"non_pharmacological":["饮食管理：记录饮食日记，识别诱因食物；低FODMAP饮食（在营养师指导下进行，避免长期严格限制致营养不良）；避免辛辣、生冷、油腻、过量咖啡因和酒精；乳糖不耐受者避免乳制品；规律进餐，细嚼慢咽，避免暴饮暴食","生活方式：规律作息，避免熬夜，适度运动（每周150分钟有氧运动，改善肠道蠕动和心理状态），戒烟","心理调节：减轻压力，放松训练（深呼吸、冥想、瑜伽），保持心情舒畅，必要时心理咨询","腹部护理：注意腹部保暖，避免受凉，腹痛时热敷（注意温度），避免腹部按压","排便习惯：定时排便，避免憋便，排便时专注（不看手机），避免过度用力","益生菌和益生元：可尝试含双歧杆菌、乳酸杆菌的益生菌或酸奶，观察个体反应","避免滥用药物：不要长期自行服用止泻药、泻药或抗生素，需在医生指导下使用","患者教育：解释IBS是功能性疾病（无器质性病变），不癌变，不影响寿命，减轻患者焦虑","社会支持：家人理解和支持，避免指责\"装病\"","定期随访：症状变化或出现报警症状及时就诊，调整治疗方案"],"complications":["营养不良：严格限制饮食或慢性腹泻致营养摄入不足，低FODMAP饮食需在营养师指导下进行","焦虑抑郁：IBS患者合并心理障碍比例高（30-50%），心理因素加重症状，形成恶性循环，需同时干预","肠道菌群失调：长期腹泻或抗生素使用致菌群紊乱，益生菌可辅助","便秘并发症：IBS-C长期便秘致痔疮、肛裂、粪嵌塞","腹泻并发症：IBS-D长期腹泻致电解质紊乱、脱水、肛周皮肤破损","药物不良反应：洛哌丁胺致便秘和腹胀；解痉药致口干、视物模糊、尿潴留（抗胆碱）；利那洛肽致腹泻；三环类抗抑郁药致嗜睡、口干、便秘","不典型表现：出现报警症状需排除器质性疾病，不可简单归为IBS","生活质量下降：慢性腹痛腹泻影响工作学习社交，是IBS主要危害","重叠综合征：IBS常合并胃食管反流、功能性消化不良、纤维肌痛等，需综合管理","医疗资源过度使用：反复检查和就医，需明确诊断后避免不必要的重复检查"],"monitoring":["诊断时：血常规、CRP/血沉、粪便常规+潜血+钙卫蛋白、甲状腺功能、必要时结肠镜（报警症状或大于50岁）、乳糖不耐受检测、SIBO呼气试验（必要时）","治疗初期：每2-4周随访，评估症状（IBS-SSS评分）、药物疗效和不良反应，调整方案","饮食干预：低FODMAP饮食2-6周后评估，逐步重新引入食物，确定个体诱因","长期：每3-6个月随访，评估症状控制、生活质量、心理状态，调整治疗","出现报警症状（体重下降、出血、贫血、发热、夜间腹泻）：及时复查结肠镜和相关检查，排除器质性疾病","益生菌使用：试用4-8周评估效果，无效则停用（不同菌株效果因人而异）","心理评估：中重度IBS常规筛查焦虑抑郁（PHQ-9、GAD-7），必要时心理科转诊","治疗效果评估：IBS-SSS量表（腹痛程度、腹痛天数、腹胀、排便满意度、生活影响）"],"special_populations":["老年人：新发IBS症状需警惕结直肠癌，结肠镜检查指征放宽，避免使用抗胆碱能解痉药（尿潴留、认知影响）","孕妇：IBS症状可能加重，避免使用利那洛肽、普芦卡必利、阿洛司琼，可用聚乙二醇（便秘）、洛哌丁胺（腹泻，相对安全），饮食调整为主","儿童：诊断标准不同（罗马IV儿科标准），以饮食和心理干预为主，药物需儿科评估","炎症性肠病缓解期：可合并IBS样症状，需鉴别疾病活动（粪便钙卫蛋白升高提示活动）","糖尿病患者：自主神经病变致胃肠功能紊乱，需控制血糖，鉴别糖尿病胃肠病","免疫低下者：慢性腹泻需排除感染（寄生虫、艰难梭菌、CMV），不可简单诊断IBS","服用抗生素后：抗生素相关性腹泻或艰难梭菌感染，需查粪便毒素","饮食失调者：避免过度饮食限制，需营养科和心理科共同管理"],"references":["中华医学会消化病学分会. 肠易激综合征诊治指南（2024）","罗马IV功能性胃肠病诊断标准","ACG肠易激综合征管理指南"]},{"name":"慢性便秘诊治指南（2024）","category":"消化内科","scope":"成人慢性便秘的诊断、分型、分级治疗和长期管理。","diagnosis":["诊断标准（罗马IV）：排便费力、干硬便、排便不尽感、肛门直肠堵塞感、需要手法辅助、每周排便少于3次，至少2项，持续大于3个月，近3个月符合，不用泻药时很少出现稀便，不符合IBS诊断","分型：慢传输型（结肠传输减慢，排便次数少、干硬便）、出口梗阻型（排便困难、不尽感、手法辅助，直肠肛门功能异常）、混合型、正常传输型","报警症状：便血、贫血、体重下降、腹痛、排便习惯明显改变、结直肠癌家族史、年龄大于50岁新发","辅助检查：结肠镜（排除器质性疾病，有报警症状或年龄大于50岁）、结肠传输试验（不透X线标志物，评估传输功能）、肛门直肠测压（评估出口梗阻）、球囊逼出试验、排粪造影、甲状腺功能、血糖、血钙","鉴别：器质性疾病（结直肠癌、肠梗阻、炎症性肠病、肛裂痔疮）、内分泌疾病（甲减、糖尿病）、神经系统疾病（帕金森、脊髓损伤）、药物性便秘（阿片类、抗胆碱药、钙通道阻滞剂、铁剂、抗抑郁药）、电解质紊乱（高钙、低钾）","危险因素：膳食纤维不足、饮水少、久坐少动、精神心理因素、年龄增长、女性、妊娠、药物"],"staging":["按病因：功能性便秘、器质性便秘（肠道疾病、内分泌代谢、神经系统、药物）","按分型：慢传输型、出口梗阻型（排便障碍型）、混合型、正常传输型","按严重程度：轻度（症状轻，不影响生活，可通过生活方式改善）、中度（影响生活，需药物治疗）、重度（严重影响生活，药物治疗效果差，需进一步检查和介入/手术）","按病程：急性便秘（小于3个月）、慢性便秘（大于3个月）","按是否合并报警症状：单纯性便秘、报警症状便秘（需进一步检查）"],"key_points":["基础治疗（所有患者）：增加膳食纤维（25-30g/d，逐步增加避免腹胀）、多饮水（1.5-2L/d）、规律运动（每周150分钟有氧运动）、建立良好排便习惯（晨起或餐后30分钟定时排便，专注不看手机，避免过度用力）","渗透性泻药（一线，长期使用安全）：聚乙二醇（10-20g qd，不被吸收不发酵，安全性高）、乳果糖（15-30ml qd，在结肠发酵，可能腹胀）、硫酸镁（急性便秘，短期用，注意电解质）","刺激性泻药（短期使用，不推荐长期）：比沙可啶5-10mg qd、番泻叶、酚酞（已禁用，致癌），长期用致结肠黑变病和依赖","促分泌药：利那洛肽290μg qd（IBS-C和慢性便秘，增加肠道分泌）、普卡那肽3mg qd","促动力药：普芦卡必利1-2mg qd（5-HT4激动剂，促进结肠传输，女性慢性便秘）、莫沙必利（全胃肠动力，效果有限）","微生态制剂：益生菌（双歧杆菌、乳酸杆菌）、益生元，辅助改善便秘","灌肠和栓剂：开塞露（甘油，急性便秘和粪便嵌塞）、生理盐水灌肠（粪便嵌塞），不推荐长期常规使用","出口梗阻型：生物反馈治疗（首选，训练盆底肌协调收缩，有效率70%以上），药物效果差","手术治疗：保守治疗无效的慢传输型便秘（结肠切除术）、出口梗阻型（直肠前突修补、耻骨直肠肌部分切除），需严格评估","药物性便秘：停用或更换致便秘药物，阿片类便秘用甲基纳曲酮（外周阿片受体拮抗剂）"],"drug_recommendations":[],"non_pharmacological":["饮食调整：增加膳食纤维（全谷物、蔬菜、水果、豆类），从少量开始逐步增加（避免突然大量致腹胀），多饮水（晨起空腹喝温水刺激肠蠕动），避免过度精细饮食，减少辛辣刺激和油炸食物","规律运动：每周至少150分钟中等强度有氧运动（快走、慢跑、游泳），避免久坐，每小时起身活动，腹部按摩（顺时针，促进肠蠕动）","排便习惯：每天固定时间排便（晨起或餐后，利用胃结肠反射），排便时专注（不看手机读书），时间不超过5-10分钟，有便意及时排便（不憋便），避免过度用力（防痔疮和肛裂）","心理调节：减轻压力，焦虑抑郁可加重便秘，放松训练、冥想，必要时心理治疗","避免滥用泻药：不要长期依赖刺激性泻药（番泻叶、大黄、芦荟），可致结肠黑变病、电解质紊乱和依赖","腹部按摩：顺时针方向按摩腹部，每次10-15分钟，每日2次，促进肠蠕动","盆底肌训练：出口梗阻型便秘进行生物反馈训练，学会排便时放松盆底肌","孕期管理：孕期便秘常见，增加膳食纤维和饮水，适度运动，必要时用聚乙二醇（安全），避免刺激性泻药和灌肠","老年护理：老年人便秘发生率高，增加活动，多饮水，规律排便，避免用力排便（防心脑血管意外）","定期随访：调整治疗方案，评估疗效，避免长期用药不良反应"],"complications":["粪便嵌塞：严重便秘致大量粪便积聚直肠，腹痛腹胀、溢出性腹泻（假性腹泻），需灌肠或手法取出，预防为主","痔疮和肛裂：长期用力排便致痔静脉淤血和肛管皮肤撕裂，便血疼痛，需治疗便秘+局部处理","直肠脱垂：长期用力排便致直肠黏膜脱出，需手术","结肠黑变病：长期服用蒽醌类刺激性泻药（番泻叶、大黄、芦荟）致结肠黏膜色素沉着，停药后可恢复，增加结肠癌风险（争议）","肠梗阻：严重便秘可致粪石性肠梗阻，尤其老年人，需禁食、胃肠减压、灌肠，必要时手术","心脑血管意外：老年人用力排便时血压骤升，诱发心梗、脑卒中、主动脉夹层，需避免用力，用缓泻剂保持大便通畅","药物不良反应：渗透性泻药过量致腹泻电解质紊乱；刺激性泻药致腹痛、结肠黑变病；促动力药致头痛、恶心","营养不良：严格限制饮食或腹胀致进食减少","心理负担：慢性便秘影响生活质量，焦虑加重便秘，恶性循环","尿潴留：粪便嵌塞压迫尿道致尿潴留，尤其老年人"],"monitoring":["诊断时：详细病史（排便频率、粪便性状、费力程度、用药史、伴随症状）、肛门指检（评估粪便嵌塞、肛门括约肌张力、直肠前突）、结肠镜（报警症状或大于50岁）、甲状腺功能、血糖、血钙、必要时结肠传输试验和肛门直肠测压","治疗初期：每2-4周评估排便情况（每周排便次数、粪便性状Bristol分型、费力程度、腹胀），调整药物剂量","药物治疗：评估疗效和不良反应，渗透性泻药可长期使用，刺激性泻药不超过1-2周","生物反馈治疗：出口梗阻型首选，每周1-2次，疗程4-8周，评估盆底肌协调功能改善","长期：每3-6个月随访，评估便秘控制情况、生活质量、药物使用，调整方案","出现报警症状（便血、贫血、体重下降、腹痛、排便习惯改变）：及时结肠镜检查排除肿瘤","术后随访：手术患者定期评估排便功能和并发症"],"special_populations":["老年人：便秘发生率高（约30-40%），合并用药多（致便秘药物），避免用力排便（心脑血管风险），首选渗透性泻药（聚乙二醇），避免刺激性泻药，定期肛门指检排查粪便嵌塞","孕妇：孕激素使肠蠕动减慢，子宫压迫直肠，便秘常见，增加膳食纤维和饮水，适度运动，可用聚乙二醇和乳果糖（安全），避免刺激性泻药、灌肠和手法排便","儿童：以饮食调整和排便训练为主，必要时用聚乙二醇，避免长期用刺激性泻药，排查先天性巨结肠","糖尿病患者：自主神经病变致胃肠动力减弱，控制血糖，促动力药可考虑","甲状腺功能减退：甲减致便秘，补充甲状腺素后可改善","帕金森病：盆底肌协同失调和运动减少致便秘，治疗原发病+促动力药+生物反馈","服用阿片类药物者：阿片类便秘常见，预防性用渗透性泻药，难治性用甲基纳曲酮（外周阿片受体拮抗剂，不影响镇痛）","长期卧床者：肠蠕动减慢，增加膳食纤维和饮水，腹部按摩，必要时用缓泻剂","肾功能不全：镁剂（硫酸镁）禁用（高镁血症），聚乙二醇安全"],"references":["中华医学会消化病学分会. 中国慢性便秘诊治指南（2024）","罗马IV功能性胃肠病诊断标准","ACG便秘管理指南"]},{"name":"尿路感染诊治指南（2024）","category":"泌尿外科","scope":"成人尿路感染（UTI）的分型、诊断、抗感染治疗和预防。","diagnosis":["临床表现：膀胱炎（尿频尿急尿痛、耻骨上不适、血尿，一般无发热）、肾盂肾炎（发热寒战、腰痛、恶心呕吐、尿频尿急尿痛）、无症状菌尿（尿培养阳性但无症状）","体征：膀胱炎耻骨上压痛；肾盂肾炎肾区叩击痛、发热","实验室：尿常规（白细胞酯酶阳性、亚硝酸盐阳性、白细胞大于5/HP）、尿培养（菌落计数大于10^5CFU/ml，清洁中段尿）、血常规（肾盂肾炎白细胞升高）、CRP/降钙素原","影像学：泌尿系超声（排除结石、梗阻、畸形、积水）、CT（复杂UTI、怀疑脓肿或梗阻）、静脉肾盂造影（反复UTI评估解剖异常）","鉴别：阴道炎（阴道分泌物、瘙痒，尿常规正常）、性传播疾病（尿道炎，淋球菌/衣原体）、间质性膀胱炎、膀胱过度活动症、泌尿系结核（反复UTI、抗菌效果差、血尿）","危险因素：女性（尿道短、性生活、妊娠、绝经）、男性（前列腺增生、前列腺炎）、泌尿系结石/梗阻、留置尿管、糖尿病、免疫抑制、泌尿系畸形、性生活"],"staging":["按部位：下尿路感染（膀胱炎、尿道炎）、上尿路感染（肾盂肾炎、肾脓肿、肾周脓肿）","按复杂程度：单纯性UTI（健康女性、无解剖/功能异常、非妊娠）、复杂性UTI（男性、妊娠、糖尿病、免疫抑制、泌尿系梗阻/畸形/结石、留置尿管、反复发作、肾功能不全）","按病程：急性UTI、反复发作UTI（1年内大于等于3次或6个月内大于等于2次）、慢性UTI","按症状：有症状UTI、无症状菌尿","特殊类型：导管相关性UTI（CAUTI）、尿源性脓毒症、泌尿系结核"],"key_points":["抗感染治疗是核心，根据分型和病原菌选择","单纯性膀胱炎：短程疗法，呋喃妥因100mg bid×5天、磷霉素氨丁三醇3g单剂、复方新诺明bid×3天（当地耐药率小于20%时）、左氧氟沙星bid×3天（避免作为一线，耐药和不良反应）、阿莫西林克拉维酸钾×3-5天","单纯性肾盂肾炎：口服氟喹诺酮（左氧氟沙星500mg qd×7天或环丙沙星500mg bid×7天）；或头孢曲松1g静推q24h×7-10天；重症住院用三代头孢（头孢曲松、头孢他啶）或哌拉西林他唑巴坦，热退后改口服，总疗程10-14天","复杂性UTI：根据尿培养和药敏选药，经验性用三代头孢或哌拉西林他唑巴坦，疗程7-14天，同时处理复杂因素（解除梗阻、拔尿管）","反复发作UTI：急性发作按膀胱炎治疗；预防用低剂量长期抑菌（呋喃妥因50mg qn、甲氧苄啶100mg qn、头孢氨苄125mg qn，连用6-12个月）；性生活相关者性交后单次剂量预防","导管相关性UTI：有症状才治疗（无症状菌尿不治疗），根据药敏选药，疗程7-14天，尽早拔除或更换导管","无症状菌尿：仅孕妇、接受泌尿系侵入性操作者需治疗，其他人不治疗（避免耐药）","尿源性脓毒症：急诊，液体复苏、广谱抗生素（三代头孢+甲硝唑或碳青霉烯）、感染源控制（解除梗阻、引流脓肿）、血管活性药","男性UTI：按复杂性UTI处理，疗程至少7-14天，排查前列腺和泌尿系异常","妊娠UTI：急性膀胱炎用阿莫西林、头孢氨苄、呋喃妥因（孕晚期避免），7天疗程；肾盂肾炎住院用头孢曲松，避免四环素、喹诺酮、磺胺（孕晚期）"],"drug_recommendations":[],"non_pharmacological":["多饮水：每日2000ml以上，勤排尿（每2-3小时一次），不憋尿，冲洗尿道","注意卫生：女性便后从前向后擦拭，避免阴道菌群进入尿道；性生活前后排尿和清洗；避免使用刺激性阴道洗液","棉质内衣：穿宽松透气的棉质内裤，勤换洗，避免紧身化纤内裤","避免久坐：每1-2小时起身活动，避免会阴部潮湿闷热","饮食：清淡，避免辛辣刺激、酒精、咖啡（刺激膀胱），蔓越莓汁/提取物可能有预防作用（证据有限，不推荐常规）","控制基础病：糖尿病患者控制血糖（高糖尿利于细菌繁殖），前列腺增生患者改善排尿","绝经后女性：局部雌激素软膏（恢复阴道乳酸杆菌，减少UTI复发），需妇科评估","避免不必要的尿管留置：尽早拔管，严格无菌操作，保持引流系统密闭","孕期护理：孕期定期查尿常规，无症状菌尿需治疗（防肾盂肾炎和早产），左侧卧位减轻子宫压迫输尿管","预防复发：反复发作患者注意诱因（性生活、避孕方式、卫生习惯），多饮水，必要时药物预防"],"complications":["肾盂肾炎并发症：肾脓肿、肾周脓肿（持续发热、腰痛加重，CT确诊，需穿刺引流+长疗程抗生素）、脓毒症/感染性休克（高危，急诊）、急性肾损伤（严重感染或梗阻致，需解除梗阻+抗感染）","慢性肾盂肾炎：反复感染致肾瘢痕、肾萎缩、慢性肾功能不全，需长期管理和随访","感染性结石：尿素酶阳性菌（变形杆菌、克雷伯菌）致磷酸镁铵结石，需碎石+抗感染","尿源性脓毒症：泌尿系感染扩散致全身炎症反应，死亡率高，需急诊液体复苏+广谱抗生素+感染源控制","导管相关并发症：长期留置尿管致尿道损伤、膀胱结石、反复感染，尽早拔管","抗生素耐药：反复不规范使用抗生素致耐药菌感染，需根据药敏选药，避免滥用","男性前列腺炎：UTI合并前列腺炎，疗程延长（4-6周），选择前列腺穿透力好的药物（氟喹诺酮、复方新诺明）","妊娠期并发症：无症状菌尿不治疗可进展为肾盂肾炎，增加早产、低体重儿风险，需筛查和治疗","肾功能损害：双侧慢性肾盂肾炎或梗阻性肾病致慢性肾衰，需早期干预"],"monitoring":["诊断时：尿常规（白细胞、亚硝酸盐、红细胞）、尿培养+药敏（清洁中段尿，复杂性UTI和反复发作必查）、血常规、CRP、肾功能、泌尿系超声（排除梗阻结石畸形）","治疗期间：48-72小时评估疗效（体温、症状、尿常规），无效则根据药敏调整抗生素","尿培养：复杂性UTI治疗前必查，治疗后复查（疗程结束后1-2周，确认治愈）","影像学：反复UTI、男性UTI、复杂性UTI需查泌尿系超声，必要时CT/IVP评估解剖异常","反复发作：排查诱因（结石、梗阻、畸形、糖尿病、免疫抑制），尿培养+药敏，评估预防方案","孕期：首次产检查尿常规，无症状菌尿需治疗，治疗后复查尿培养","导管相关：有症状才查尿培养，无症状不筛查不治疗","长期：慢性肾盂肾炎定期查肾功能、血压、尿常规，监测肾瘢痕和肾功能进展","出现高热不退、腰痛加重、意识改变：立即就诊（肾脓肿或脓毒症）"],"special_populations":["孕妇：无症状菌尿需治疗（2-10%进展为肾盂肾炎），避免喹诺酮、四环素、磺胺（孕晚期）、氨基糖苷类，首选青霉素/头孢类，治疗后复查","绝经后女性：UTI复发率高，局部雌激素可减少复发，需妇科评估，多饮水和卫生习惯","男性UTI：均按复杂性处理，疗程至少7-14天，排查前列腺增生、前列腺炎、泌尿系结石，前列腺按摩液检查","糖尿病患者：UTI风险高，易合并肾脓肿和气肿性肾盂肾炎，控制血糖，根据药敏选药，疗程延长","免疫抑制患者（激素、移植、HIV）：感染症状不典型，易严重感染，需积极抗感染，排查真菌和特殊病原体","留置尿管患者：无症状菌尿不治疗（增加耐药），有症状才治疗，尽早拔管，严格无菌操作","肾功能不全：根据eGFR调整抗生素剂量，避免肾毒性药物（氨基糖苷类），监测肾功能","泌尿系结石患者：结石是感染灶和梗阻原因，需同时处理结石（碎石或手术），感染性结石需长期抑菌","老年患者：症状不典型（可无发热尿痛，仅表现为意识模糊、乏力），尿培养确诊，避免肾毒性药物"],"references":["中华医学会泌尿外科学分会. 尿路感染诊断和治疗指南（2024）","IDSA成人单纯性膀胱炎和肾盂肾炎指南","EAU泌尿系感染指南"]},{"name":"缺铁性贫血诊治指南（2024）","category":"血液科","scope":"成人和儿童缺铁性贫血（IDA）的诊断、铁剂治疗和病因查找。","diagnosis":["临床表现：贫血症状（乏力、头晕、心悸、气短、面色苍白）、组织缺铁表现（异食癖、口角炎、舌炎、吞咽困难、指甲脆薄/反甲、皮肤干燥、脱发）、原发病表现（黑便、月经过多、腹痛）","实验室：小细胞低色素性贫血（MCV小于80fl、MCH小于27pg、MCHC小于320g/L）、血清铁降低、转铁蛋白饱和度降低（小于15%）、血清铁蛋白降低（小于15μg/L，伴炎症时小于30）、总铁结合力升高（大于64.4μmol/L）、网织红细胞正常或轻度升高","骨髓检查（必要时）：骨髓增生活跃，红系增生，细胞外铁消失，铁粒幼细胞减少（金标准）","鉴别：地中海贫血（小细胞低色素但铁蛋白正常/升高，血红蛋白电泳异常）、慢性病贫血（铁蛋白正常/升高，转铁蛋白降低）、铁粒幼细胞贫血（铁蛋白升高，骨髓环形铁粒幼细胞）、铅中毒","病因查找：慢性失血（消化道出血：溃疡、肿瘤、痔疮、月经过多、反复献血、血尿）、铁摄入不足（素食、营养不良）、铁吸收障碍（胃切除、萎缩性胃炎、乳糜泻、质子泵抑制剂长期使用）、需求增加（妊娠、哺乳、婴幼儿、青少年）","分期：铁减少期（ID，铁蛋白降低，无贫血）、缺铁性红细胞生成期（IDE，铁蛋白+转铁蛋白饱和度降低，无贫血）、缺铁性贫血期（IDA，小细胞低色素贫血）"],"staging":["按严重程度：轻度（Hb 90-正常下限）、中度（Hb 60-90g/L）、重度（Hb 30-60g/L）、极重度（Hb小于30g/L）","按病因：摄入不足型、吸收障碍型、慢性失血型、需求增加型","按病程：急性（急性失血后）、慢性（长期铁负平衡）","特殊人群：妊娠合并IDA、儿童IDA、老年人IDA、术后IDA","治疗反应：铁剂治疗有效（网织红细胞1周升高，Hb 2周升高，2个月恢复正常）、难治性IDA（铁剂无效，需排查病因和诊断）"],"key_points":["病因治疗是根本：查找并治疗失血原因（消化道肿瘤/溃疡、子宫肌瘤、痔疮），改善饮食，治疗吸收障碍","口服铁剂（首选）：硫酸亚铁0.3g tid（元素铁60mg/片）、富马酸亚铁0.2g tid、琥珀酸亚铁0.1-0.2g tid、多糖铁复合物150mg qd（胃肠道反应小）；元素铁150-200mg/d，分2-3次，空腹服（吸收好，胃肠道反应大可餐后），与维生素C同服促进吸收，避免与茶、咖啡、牛奶、抗酸药、四环素同服（间隔2小时）","口服铁剂疗程：Hb恢复正常后继续服用3-6个月（补充储存铁），或至铁蛋白大于50μg/L","静脉铁剂（口服不耐受、吸收障碍、失铁快于口服补充、需快速纠正）：蔗糖铁（最常用，过敏反应少，200mg/次，每周2-3次）、右旋糖酐铁（需皮试，过敏风险）、羧基麦芽糖铁（单次大剂量1000mg）；总需要量=体重×(目标Hb-实际Hb)×0.24+储存铁500mg","输血：重度贫血（Hb小于60g/L）或伴明显症状、急性失血、妊娠晚期重度贫血，输悬浮红细胞，目标Hb大于70g/L（心血管病者大于80）","辅助治疗：维生素C 0.2g tid（促进铁吸收）、叶酸（合并缺乏时）、维生素B12（合并缺乏时）","病因治疗：消化道出血查胃镜肠镜+治疗；月经过多妇科治疗；痔疮手术；胃切除后定期补铁","饮食补铁：增加红肉、动物肝脏、动物血（血红素铁吸收率高），植物铁（菠菜、木耳）吸收率低，与维生素C同服","难治性IDA：重新评估诊断（地中海贫血、慢性病贫血）、查找持续失血源、评估吸收障碍、检查依从性"],"drug_recommendations":[],"non_pharmacological":["饮食调整：增加富含铁的食物，血红素铁（红肉、动物肝脏、动物血，吸收率20-30%）优于非血红素铁（植物性食物，吸收率1-5%）；富含维生素C的食物（新鲜蔬菜水果）促进铁吸收；避免茶、咖啡、高钙食物与铁剂同服（抑制吸收）","口服铁剂注意：空腹服用吸收好，胃肠道反应大可餐后服；服用期间大便变黑（正常现象，非出血）；液体铁剂用吸管（防牙齿染色）；不要与抗酸药、质子泵抑制剂、四环素、喹诺酮同服（间隔2小时）","生活方式：规律作息，避免过度劳累，贫血严重时减少剧烈活动，预防跌倒（头晕）","孕期管理：孕期常规查血常规，孕中期开始预防性补铁（30-60mg元素铁/d），多胎或贫血者增加剂量","婴幼儿管理：4-6个月及时添加含铁辅食（强化铁米粉、肉泥、肝泥），母乳喂养母亲补铁，早产儿额外补铁","青少年管理：生长发育快需铁增加，注意饮食均衡，女孩月经过多需评估","原发病随访：消化道出血者定期胃肠镜，月经过多者妇科随访，避免持续失血","定期复查：铁剂治疗期间定期查血常规和铁蛋白，评估疗效，调整疗程","避免盲目补铁：诊断明确后再补，铁过载（血色病）有害，需监测铁蛋白","心理支持：慢性贫血影响生活和工作，需解释病情和治疗周期，增强依从性"],"complications":["铁剂不良反应：口服铁剂致恶心、呕吐、腹痛、便秘、腹泻（发生率约30%），餐后服或换用多糖铁可减轻；静脉铁剂致过敏反应（蔗糖铁少见，右旋糖酐铁需皮试）、输液反应、低血压","铁过载：长期大量补铁或误诊（地中海贫血、血色病）致铁过载，损伤肝脏、心脏、胰腺，需监测铁蛋白，避免盲目补铁","原发病漏诊：IDA是症状不是疾病，必须查找病因，尤其中老年男性和绝经后女性IDA需排查消化道肿瘤","治疗失败：未找到持续失血源、依从性差、吸收障碍、诊断错误（地中海贫血、慢性病贫血），需重新评估","妊娠并发症：严重IDA增加早产、低体重儿、产后出血风险，需积极纠正","儿童发育影响：长期IDA影响儿童智力发育和行为，需早期发现和治疗","心力衰竭：严重贫血（Hb小于50）致高输出量心衰，需输血和利尿","异食癖：缺铁致嗜食冰块、泥土、粉笔等，补铁后可恢复","反甲和舌炎：长期缺铁致指甲扁平凹陷、舌乳头萎缩，补铁后逐渐恢复","药物相互作用：铁剂与四环素、喹诺酮、左旋多巴、甲状腺素、二膦酸盐结合影响吸收，需间隔2小时以上"],"monitoring":["诊断时：血常规（MCV/MCH/MCHC）、血清铁、铁蛋白、转铁蛋白饱和度、总铁结合力、网织红细胞；必要时骨髓铁染色、血红蛋白电泳（排除地贫）、大便潜血、消化道内镜（查找失血原因）、妇科检查（女性月经过多）","铁剂治疗：2周后复查血常规（Hb应升高10-20g/L），评估疗效；1个月后复查Hb和铁蛋白；Hb正常后继续补铁3-6个月","静脉铁剂：用药前评估总需要量，用药中监测过敏反应，用药后4周复查铁蛋白","病因检查：中老年男性和绝经后女性IDA必须查胃镜和肠镜（排除消化道肿瘤），年轻女性查妇科","孕期：首次产检查血常规，孕24-28周复查，铁蛋白小于30μg/L开始补铁","儿童：6个月、12个月、1-5岁每年查血常规，高危儿（早产、低出生体重、母乳喂养未加辅食）提前查","治疗失败：重新评估诊断和依从性，查大便潜血、胃肠镜、乳糜泻抗体、幽门螺杆菌（可致铁吸收不良）","长期：治愈后定期复查，复发者重新查找病因"],"special_populations":["孕妇：孕期需铁量增加（胎儿+胎盘+分娩失血），孕中期开始预防性补铁，严重者静脉补铁，避免孕晚期重度贫血（输血风险），目标Hb大于110g/L","哺乳期：继续补铁，铁通过乳汁分泌少，不影响婴儿，但母亲需补充储存铁","婴幼儿和儿童：6个月后及时添加含铁辅食，早产儿和低出生体重儿2个月开始补铁，长期IDA影响智力发育（部分不可逆），需早期干预","老年人：IDA需警惕消化道肿瘤（胃癌、结肠癌），必须胃肠镜检查，不要简单归因于营养不良","胃切除术后：铁吸收障碍（胃酸减少+食物快速通过），需定期补铁，常需静脉铁剂","炎症性肠病：慢性失血+吸收障碍，口服铁剂可能加重肠道症状，常用静脉铁剂","慢性肾病：促红细胞生成素缺乏+铁利用障碍，需静脉铁剂+促红素，目标铁蛋白200-500μg/L","月经过多女性：妇科检查排查子宫肌瘤、腺肌症、内膜息肉，治疗原发病，同时补铁","素食者：非血红素铁吸收率低，需增加摄入和维生素C，必要时补充铁剂","服用质子泵抑制剂者：胃酸减少影响铁吸收，长期使用者需监测铁营养状态"],"references":["中华医学会血液学分会. 缺铁性贫血诊治指南（2024）","WHO缺铁性贫血管理指南","ACG胃肠道评估缺铁性贫血指南"]},{"name":"淋巴瘤诊治指南（2024）","category":"血液科","scope":"成人淋巴瘤（霍奇金和非霍奇金）的分类、诊断、分期、治疗和随访。","diagnosis":["临床表现：无痛性进行性淋巴结肿大（颈部、腋窝、腹股沟最常见）、发热（周期性发热Pel-Ebstein热）、盗汗、体重下降（6个月内大于10%）、皮肤瘙痒、乏力","B症状：发热大于38℃、盗汗、体重下降大于10%","结外受累：胃肠道（腹痛、肠梗阻、出血）、鼻咽部（鼻塞、鼻出血）、皮肤（结节、斑块）、中枢神经系统（头痛、颅神经麻痹）、骨骼（骨痛）、睾丸（肿大）","实验室：血常规（贫血、白细胞异常、血小板减少）、血沉增快、LDH升高（预后不良）、β2微球蛋白升高、肝肾功能异常","影像学：PET-CT（分期和疗效评估金标准，弥漫大B细胞淋巴瘤、霍奇金淋巴瘤）、增强CT、骨髓穿刺+活检（评估骨髓受累）","病理诊断（金标准）：淋巴结切除活检（不推荐穿刺活检，需完整结构），免疫组化和流式细胞术明确亚型","分类：霍奇金淋巴瘤（HL，结节硬化型、混合细胞型、淋巴细胞为主型、淋巴细胞消减型）、非霍奇金淋巴瘤（NHL，B细胞来源：弥漫大B细胞淋巴瘤DLBCL、滤泡性淋巴瘤FL、套细胞淋巴瘤MCL、边缘区淋巴瘤MZL、Burkitt淋巴瘤；T/NK细胞来源：外周T细胞淋巴瘤、NK/T细胞淋巴瘤、间变性大细胞淋巴瘤）","鉴别：淋巴结炎（有压痛，抗感染有效）、淋巴结结核（低热盗汗，PPD阳性，病理见干酪样坏死）、转移癌（中老年，有原发肿瘤）、Castleman病、结节病"],"staging":["按病理类型：霍奇金淋巴瘤（HL）、非霍奇金淋巴瘤（NHL，B细胞/T细胞/NK细胞）","按Ann Arbor分期：I期（单一淋巴结区或结外器官）、II期（横膈同侧2个以上淋巴结区或局部结外+淋巴结）、III期（横膈两侧淋巴结区或脾受累）、IV期（弥漫性结外器官受累，如骨髓、肝、肺）","按B症状：A组（无B症状）、B组（有B症状）","按侵袭性：惰性淋巴瘤（滤泡性、边缘区、小淋巴细胞淋巴瘤/慢淋，进展慢，部分可观察等待）、侵袭性淋巴瘤（弥漫大B、套细胞、外周T，需积极化疗）、高度侵袭性（Burkitt、淋巴母细胞淋巴瘤，需高强度化疗+中枢预防）","按IPI预后指数（DLBCL）：年龄大于60、LDH升高、III/IV期、ECOG大于等于2、结外受累大于1处，0-1低危，2低中危，3高中危，4-5高危"],"key_points":["病理诊断和分期明确后开始治疗，根据亚型和分期选择方案","霍奇金淋巴瘤：ABVD方案（阿霉素+博来霉素+长春花碱+达卡巴嗪），I-II期2-4周期+放疗，III-IV期6-8周期，PET-CT评估疗效调整","弥漫大B细胞淋巴瘤（DLBCL）：R-CHOP方案（利妥昔单抗+环磷酰胺+阿霉素+长春新碱+泼尼松），6-8周期，I-II期可4周期+放疗，高危者可考虑大剂量化疗+自体造血干细胞移植","滤泡性淋巴瘤（惰性）：I-II期放疗；III-IV期无症状可观察等待（watch and wait），有症状用利妥昔单抗±化疗（苯达莫司汀、CHOP），复发后可用PI3K抑制剂、CAR-T","套细胞淋巴瘤：年轻患者用高强度方案（R-HyperCVAD）+自体移植；老年用R-CHOP或苯达莫司汀+利妥昔单抗，BTK抑制剂（伊布替尼、泽布替尼）用于复发难治","Burkitt淋巴瘤：高强度短疗程化疗（CODOX-M/IVAC），强烈中枢预防（鞘内注射+大剂量甲氨蝶呤），肿瘤溶解综合征预防（水化、别嘌醇/拉布立酶）","外周T/NK细胞淋巴瘤：CHOP方案（加依托泊苷为CHOEP），疗效较差，复发后用西达本胺、PD-1抑制剂、自体移植","复发难治：大剂量化疗+自体造血干细胞移植（敏感复发）、CAR-T细胞治疗（CD19阳性B细胞淋巴瘤，如阿基仑赛、瑞基奥仑赛）、靶向药（BTK抑制剂、PI3K抑制剂、BCL-2抑制剂维奈克拉、PD-1/PD-L1抑制剂）","支持治疗：化疗止吐（5-HT3拮抗剂+地塞米松）、预防肿瘤溶解综合征（水化+别嘌醇）、粒细胞缺乏发热（广谱抗生素）、成分输血、生长因子（G-CSF）","中枢预防：高危患者（Burkitt、淋巴母细胞、DLBCL中枢高危）鞘内注射甲氨蝶呤+阿糖胞苷"],"drug_recommendations":[],"non_pharmacological":["治疗期间：加强营养，高蛋白高热量饮食，多饮水（化疗期间每日2000ml以上，促进尿酸排泄），避免生冷不洁食物（粒细胞缺乏期防感染）","预防感染：粒细胞缺乏期避免去人群密集场所，戴口罩，注意口腔和肛周卫生，避免接触感冒患者，必要时预防性抗感染","休息与活动：化疗期间注意休息，避免劳累，缓解期可适度活动（散步、太极），避免剧烈运动","心理支持：淋巴瘤治疗周期长，患者易焦虑恐惧，需心理疏导，家人支持，加入病友团体","皮肤护理：放疗区域皮肤保持清洁干燥，避免摩擦、暴晒、刺激性护肤品，穿宽松棉质衣物","口腔护理：化疗期间用软毛牙刷，生理盐水或碳酸氢钠漱口，预防口腔溃疡和真菌感染","定期复查：按医嘱定期查血常规、肝肾功能、LDH、影像学（PET-CT或CT），评估疗效和复发","疫苗接种：化疗期间避免活疫苗，缓解期可接种灭活疫苗（流感、肺炎球菌），咨询医生","生育保护：年轻患者化疗前可考虑精子/卵子冷冻，化疗期间避孕，治疗结束后在医生指导下备孕","避免劳累和感染：淋巴瘤患者免疫功能低下，感染风险高，注意保暖和个人卫生"],"complications":["化疗不良反应：骨髓抑制（白细胞/血小板/红细胞减少，最常见，需G-CSF支持和成分输血）、恶心呕吐（5-HT3拮抗剂预防）、脱发（可逆）、黏膜炎、肝肾功能损害、心脏毒性（阿霉素，需监测心功能）、肺纤维化（博来霉素）、神经毒性（长春新碱、硼替佐米）、出血性膀胱炎（环磷酰胺，需美司钠预防）","肿瘤溶解综合征：高度侵袭性淋巴瘤化疗后大量细胞破坏，高尿酸、高钾、高磷、低钙、肾衰，需预防（水化、别嘌醇/拉布立酶）","感染：粒细胞缺乏期发热，需立即广谱抗生素，严重时可致脓毒症","第二肿瘤：化疗放疗后远期发生白血病、肺癌、乳腺癌等风险增加，需长期随访","不孕不育：化疗和放疗影响生育，年轻患者需提前生育保护","甲状腺功能减退：颈部放疗后常见，需定期查甲状腺功能","心血管疾病：纵隔放疗和蒽环类化疗增加远期心血管疾病风险，需长期监测心功能","复发：部分患者治疗后复发，需挽救治疗（二线化疗+自体移植/CAR-T）","CAR-T相关不良反应：细胞因子释放综合征CRS（发热、低血压、缺氧，托珠单抗治疗）、免疫效应细胞相关神经毒性ICANS（头痛、意识障碍、癫痫，支持治疗）","治疗相关死亡：高强度化疗和移植相关死亡率约1-5%"],"monitoring":["诊断时：血常规、血沉、LDH、β2微球蛋白、肝肾功能、乙肝丙肝HIV、淋巴结切除活检（病理+免疫组化+流式）、PET-CT（分期）、骨髓穿刺+活检、心电图、心脏超声（阿霉素前）","化疗期间：每周期前查血常规、肝肾功能；化疗后每3-5天查血常规（骨髓抑制低谷），发热时查血常规+血培养；每2-4周期评估疗效（PET-CT或CT）","疗效评估：化疗2-4周期后PET-CT评估，完全缓解（CR）、部分缓解（PR）、稳定（SD）、进展（PD），根据疗效调整方案","治疗结束：全面评估（PET-CT、骨髓、血常规、生化），制定随访计划","随访：治疗结束后2年内每3个月复查（体检、血常规、生化、LDH、CT），2-5年每6个月，5年后每年；PET-CT不常规用于随访（有症状或怀疑复发时）","远期并发症监测：甲状腺功能（颈部放疗后）、心脏超声（蒽环类/纵隔放疗）、乳腺检查（女性纵隔放疗后）、肺功能（博来霉素/放疗）","出现新的淋巴结肿大、发热、盗汗、体重下降：及时就诊（怀疑复发）"],"special_populations":["老年患者（大于60岁）：化疗耐受性差，需调整剂量（R-CHOP中阿霉素减量），选择毒性小的方案，加强支持治疗，评估合并症和认知功能","年轻患者：考虑生育保护（精子/卵子冷冻），治愈后可正常生育，治疗期间严格避孕","HIV相关淋巴瘤：高效抗逆转录病毒治疗（HAART）联合化疗，预后改善，需感染科和血液科共管","乙肝病毒携带者：化疗前查乙肝DNA，阳性者预防性抗病毒（恩替卡韦），化疗期间监测，防乙肝激活","妊娠合并淋巴瘤：根据孕周和淋巴瘤类型决定，妊娠早期可考虑治疗性流产，中晚期可化疗（避免妊娠早期），多学科管理","原发中枢神经系统淋巴瘤：大剂量甲氨蝶呤为基础的方案，全脑放疗（远期神经毒性），自体移植（年轻高危）","胃肠道淋巴瘤：注意出血、穿孔、梗阻风险，化疗期间密切观察，手术用于并发症","自身免疫病相关淋巴瘤：干燥综合征、类风湿、桥本甲状腺炎增加淋巴瘤风险，需警惕","免疫缺陷患者：HIV、器官移植后淋巴瘤发生率高，EB病毒相关多见，治疗需兼顾基础病"],"references":["中华医学会血液学分会. 淋巴瘤诊治指南（2024）","CSCO淋巴瘤诊疗指南（2024）","NCCN非霍奇金淋巴瘤临床实践指南"]},{"name":"强直性脊柱炎诊治指南（2024）","category":"风湿免疫科","scope":"成人强直性脊柱炎（AS）/中轴型脊柱关节炎的诊断、评估、治疗和康复。","diagnosis":["临床表现：炎性腰背痛（40岁前起病、隐匿起病、夜间痛、晨僵大于30分钟、活动后改善、休息不缓解）、外周关节炎（髋膝踝，非对称）、附着点炎（足跟痛、胸肋痛）、指（趾）炎","关节外表现：急性前葡萄膜炎（眼红痛畏光视力下降，反复发作）、炎症性肠病、银屑病、心血管病变（主动脉瓣关闭不全、传导阻滞）、肺上叶纤维化","体征：骶髂关节压痛、脊柱活动受限（前屈、后伸、侧屈）、胸廓活动度减小（小于2.5cm）、枕墙距增大（大于0）、Schober试验阳性（小于5cm）、4字试验阳性","实验室：HLA-B27阳性（约90%患者，阴性不能排除）、血沉和CRP升高（活动期）、类风湿因子阴性、抗CCP阴性","影像学：骶髂关节X线（晚期可见关节间隙狭窄、侵蚀、硬化、强直）、骶髂关节MRI（早期诊断金标准，骨髓水肿/骨炎、滑膜炎、附着点炎）、脊柱X线（椎体方形变、韧带骨赘、竹节样变）","诊断标准（ASAS）：腰背痛大于等于3个月+发病年龄小于45岁，且影像学骶髂关节炎+HLA-B27或≥2项SpA特征","鉴别：腰椎间盘突出（根性痛，活动加重，无晨僵）、弥漫性特发性骨肥厚（DISH，老年人，无骶髂关节炎）、银屑病关节炎、反应性关节炎、炎症性肠病相关关节炎、致密性骨炎（女性，骶髂关节髂侧硬化）"],"staging":["按疾病类型：强直性脊柱炎（AS，符合纽约标准，放射学骶髂关节炎）、放射学阴性中轴型脊柱关节炎（nr-axSpA，有症状和MRI炎症但X线正常）、外周型脊柱关节炎","按病程：早期（nr-axSpA，无放射学改变）、中期（骶髂关节炎，脊柱活动受限）、晚期（脊柱强直，竹节样变）","按活动度：ASDAS评分（CRP和患者评分，小于1.3非活动，1.3-2.1中等，2.1-3.5高活动，大于3.5极高活动）、BASDAI评分（大于4为活动）","按关节受累：中轴型（脊柱骶髂为主）、外周型（四肢关节为主）、混合型","合并症：葡萄膜炎、炎症性肠病、银屑病、心血管病、骨质疏松"],"key_points":["治疗目标：缓解症状、控制炎症、防止脊柱强直、维持功能、提高生活质量","非甾体抗炎药（NSAIDs，一线）：塞来昔布200mg bid、双氯芬酸75mg qd、美洛昔康15mg qd、依托考昔120mg qd（急性发作短期），连续使用2-4周评估，有效可长期使用，注意胃肠道和心血管风险","生物制剂（NSAIDs无效或有禁忌）：TNF-α抑制剂（阿达木单抗40mg每2周、依那西普50mg每周、英夫利昔单抗5mg/kg每6-8周）、IL-17A抑制剂（司库奇尤单抗150mg每周4次后每4周、依奇珠单抗），用药前筛查结核和乙肝","JAK抑制剂：托法替布5mg bid、乌帕替尼15mg qd，用于生物制剂无效或不能使用，注意感染和血栓风险","外周关节炎：柳氮磺吡啶2-3g/d（对外周关节有效，对中轴无效）、甲氨蝶呤（对外周关节，对中轴无效）、局部糖皮质激素注射（附着点炎和单关节炎）","糖皮质激素：不推荐全身长期使用，急性葡萄膜炎局部激素滴眼，严重者球后注射或短期全身激素","手术治疗：晚期髋关节强直/严重畸形行人工髋关节置换；脊柱严重后凸畸形可行脊柱截骨矫形术","康复锻炼（贯穿全程）：游泳（最佳）、瑜伽、太极、脊柱伸展运动，维持脊柱活动度和姿势，避免久坐和弯腰负重","物理治疗：热疗、超声波、经皮神经电刺激，缓解疼痛和僵硬","合并症治疗：葡萄膜炎眼科会诊（散瞳+激素滴眼）；炎症性肠病消化科治疗；骨质疏松补钙+维生素D+双膦酸盐"],"drug_recommendations":[],"non_pharmacological":["姿势管理：保持正确姿势（站立挺胸收腹、坐姿挺直、睡硬板床低枕），避免长期弯腰驼背，防止脊柱强直在畸形位","康复锻炼：每日规律锻炼，游泳是最佳运动（全身关节活动，不负重），也可做瑜伽、普拉提、太极、脊柱伸展操，重点保持脊柱前屈后伸侧屈活动度和胸廓扩张度","避免久坐：每小时起身活动，做伸展运动，避免长时间低头看手机电脑","饮食：均衡营养，增加钙和维生素D（预防骨质疏松），避免吸烟（吸烟加重病情和降低药物疗效），限制酒精","戒烟：吸烟是AS不良预后因素，加重脊柱强直和肺功能损害，必须戒烟","心理调节：慢性病长期疼痛和功能受限易致抑郁，需心理疏导，保持积极心态，加入病友团体","定期评估：定期用ASDAS/BASDAI评估疾病活动度，调整治疗方案","避免剧烈运动和重体力劳动：尤其脊柱负重和弯腰搬重物，防止脊柱骨折（强直脊柱脆性增加）","眼部护理：出现眼红痛畏光及时眼科就诊（葡萄膜炎），不要自行滴眼药水","疫苗接种：使用生物制剂和JAK抑制剂前筛查结核乙肝，治疗期间避免活疫苗，可接种灭活疫苗（流感、肺炎球菌）"],"complications":["脊柱强直：晚期脊柱韧带骨赘形成，椎体融合呈竹节样变，脊柱活动完全丧失，驼背畸形，不可逆，早期控制炎症可延缓","骨质疏松和骨折：AS患者骨质疏松发生率高，强直脊柱脆性增加，轻微外伤可致脊柱骨折（三柱损伤，神经损伤风险高），需预防和早期发现","髋关节受累：约30-50%患者累及髋关节，疼痛、活动受限、强直，严重影响行走，晚期需人工髋关节置换","急性前葡萄膜炎：约25-30%患者反复发作，眼红痛畏光视力下降，需眼科紧急处理，反复发作者可用TNF-α抑制剂预防","心血管病变：主动脉根炎致主动脉瓣关闭不全、心脏传导阻滞，需定期心脏检查","肺上叶纤维化：少见晚期并发症，咳嗽呼吸困难，需与结核鉴别","炎症性肠病：约5-10%合并克罗恩病或溃疡性结肠炎，腹泻腹痛便血，需消化科评估","银屑病：约10%合并皮肤银屑病，需皮肤科治疗","药物不良反应：NSAIDs致胃肠道溃疡出血、心血管事件、肾损伤；生物制剂致感染（结核激活、真菌感染）、注射反应；JAK抑制剂致感染、血栓、肝酶升高","抑郁焦虑：慢性疼痛和功能受限影响心理健康，需关注和干预"],"monitoring":["诊断时：血常规、血沉、CRP、HLA-B27、类风湿因子、抗CCP、骶髂关节X线和MRI、脊柱X线、眼科检查（葡萄膜炎）、骨密度","治疗初期：NSAIDs使用2-4周评估疗效（疼痛、晨僵、ESR/CRP），生物制剂使用12周评估（ASDAS评分）","活动期：每1-3个月评估ASDAS/BASDAI、ESR/CRP，调整药物剂量和方案","稳定期：每3-6个月复查，评估疾病活动度、脊柱活动度、药物不良反应、骨密度","影像学：每1-2年复查脊柱和骶髂关节X线，评估结构进展；MRI用于评估炎症活动和早期诊断","生物制剂治疗前：筛查结核（PPD/IGRA、胸片）、乙肝、丙肝、HIV，排除感染和肿瘤","长期随访：定期评估脊柱活动度（Schober试验、胸廓活动度、枕墙距）、功能状态（BASFI）、生活质量，监测远期并发症","出现眼红痛、严重腰背痛加重、下肢麻木无力：及时就诊（葡萄膜炎、脊柱骨折或神经压迫）"],"special_populations":["年轻男性（20-30岁高发）：早期表现为炎性腰背痛，易被误诊为腰椎间盘突出或腰肌劳损，HLA-B27和骶髂MRI有助于早期诊断","女性患者：症状较轻，外周关节和颈椎受累多见，易漏诊，需注意","老年起病：少见，需与DISH、骨关节炎鉴别，HLA-B27和骶髂MRI帮助诊断","妊娠患者：妊娠期间症状可能减轻，产后可能加重，NSAIDs孕晚期禁用，生物制剂需评估（TNF抑制剂孕中晚期可通过胎盘，需停药），哺乳期部分生物制剂可用","合并葡萄膜炎：反复发作者优先用TNF-α抑制剂（阿达木单抗），避免使用可能诱发葡萄膜炎的药物（如依那西普效果较差）","合并炎症性肠病：优先用抗TNF单抗（阿达木单抗、英夫利昔单抗）或IL-17抑制剂，避免NSAIDs加重肠病","合并银屑病：优先用IL-17抑制剂或TNF抑制剂，对皮肤和关节均有效","心血管高危患者：NSAIDs需谨慎（心血管风险），选择塞来昔布等COX-2选择性抑制剂，控制心血管危险因素","骨质疏松患者：AS本身和长期活动减少致骨质疏松，需补钙+维生素D+双膦酸盐，避免跌倒","使用生物制剂者：定期筛查感染，出现发热咳嗽及时就诊（结核或真菌感染）"],"references":["中华医学会风湿病学分会. 强直性脊柱炎诊治指南（2024）","2023 ASAS-EULAR中轴型脊柱关节炎管理指南","ACR/SPARTAN强直性脊柱炎治疗指南"]},{"name":"干燥综合征诊治指南（2024）","category":"风湿免疫科","scope":"成人原发性干燥综合征（pSS）的诊断、系统评估、治疗和长期管理。","diagnosis":["临床表现：口干（进食干性食物需水送、猖獗龋、腮腺反复肿大）、眼干（眼干涩、异物感、泪少、畏光）、皮肤干燥、鼻干、阴道干","系统表现：乏力、低热、关节痛（非侵蚀性）、皮疹（紫癜样皮疹，高球蛋白血症相关）、雷诺现象、肺间质病变、肾小管酸中毒（低钾性麻痹）、周围神经病变、血液系统损害（白细胞减少、血小板减少）、淋巴瘤（风险增加）","实验室：抗核抗体ANA阳性（90%以上）、抗SSA/Ro抗体阳性（最特异）、抗SSB/La抗体阳性、类风湿因子阳性、高球蛋白血症（多克隆）、血沉增快、白细胞/血小板减少","眼科检查：Schirmer试验（泪液分泌，小于5mm/5min阳性）、泪膜破裂时间（BUT小于10秒）、角膜荧光素染色（角膜损伤）","口腔科检查：唾液流率降低（小于0.5ml/15min）、腮腺造影、唇腺活检（灶性淋巴细胞浸润，灶性指数≥1，金标准）","影像学：胸部CT（肺间质病变）、肾脏超声、唾液腺超声/核素显像","诊断标准（ACR-EULAR 2016）：总分≥4分（唇腺活检灶性指数≥1=3分、抗SSA=3分、Schirmer≤5mm=1分、唾液流率≤0.1ml/min=1分、角膜染色≥3=1分），排除颈头面部放疗、丙肝、AIDS、结节病、淀粉样变、IgG4相关疾病、移植物抗宿主病","鉴别：老年性口干、糖尿病口干、药物性口干（抗胆碱药、抗抑郁药）、Mikulicz病（IgG4相关）、结节病、淋巴瘤"],"staging":["按类型：原发性干燥综合征（pSS，单独存在）、继发性干燥综合征（合并其他结缔组织病，如类风湿、红斑狼疮、硬皮病）","按系统受累：单纯外分泌腺型（仅口干眼干）、系统受累型（肺、肾、神经、血液、血管炎等）","按疾病活动度：ESSDAI评分（评估12个系统，0-4非活动，5-13中度活动，≥14高活动）","按严重程度：轻度（仅外分泌症状，不影响生活）、中度（系统受累，需免疫抑制治疗）、重度（严重内脏受累，如肺间质纤维化、中枢神经病变、严重血小板减少）","并发症：肺间质病变、肾小管酸中毒、淋巴瘤、自身免疫性肝病、甲状腺疾病"],"key_points":["对症治疗（外分泌症状）：口干用人工唾液、毛果芸香碱（5mg tid，促分泌，注意出汗腹痛）、西维美林；眼干用人工泪液（玻璃酸钠、羧甲基纤维素，按需使用）、泪小点栓塞（严重干眼）、环孢素滴眼液（中重度干眼）","系统受累治疗：根据受累器官和活动度选择","羟氯喹（基础用药）：200-400mg/d，改善关节痛、皮疹、疲劳，降低淋巴瘤风险，注意眼底筛查（每年）","糖皮质激素：系统受累（肺间质病变、肾炎、神经病变、血管炎、严重血小板减少）用泼尼松0.5-1mg/kg/d，控制后逐渐减量，避免长期大剂量","免疫抑制剂：甲氨蝶呤（关节痛、皮疹）、硫唑嘌呤（肺、血液系统）、吗替麦考酚酯（肺间质病变、肾炎）、环磷酰胺（严重系统受累，如中枢神经、肺出血、血管炎）、环孢素（难治性血小板减少）","生物制剂：利妥昔单抗（抗CD20，用于难治性系统受累、淋巴瘤前期、冷球蛋白血症）、贝利尤单抗（抗BAFF，部分国家批准用于pSS）、伊佩利尤单抗（抗CD40，新药）","肾小管酸中毒：补钾（枸橼酸钾）、碳酸氢钠纠正酸中毒，严重者用激素","肺间质病变：激素+免疫抑制剂（吗替麦考酚酯、环磷酰胺），抗纤维化（吡非尼酮、尼达尼布，进展性肺纤维化）","淋巴瘤：pSS患者淋巴瘤风险是正常人的10-20倍，持续腮腺肿大、单克隆球蛋白、白细胞减少、新发淋巴结肿大需警惕，按淋巴瘤方案治疗","对症：关节痛用NSAIDs或对乙酰氨基酚；皮肤干燥用润肤剂；阴道干用润滑剂"],"drug_recommendations":[],"non_pharmacological":["口腔护理：勤漱口，保持口腔清洁，使用含氟牙膏，定期口腔检查（每6个月），及时治疗龋齿，避免含糖食物和饮料，咀嚼无糖口香糖刺激唾液分泌","眼部护理：避免长时间看屏幕（减少瞬目），保持室内湿度，避免风沙和空调直吹，按需使用人工泪液，戴防风眼镜，不要揉眼","饮食：多饮水，清淡饮食，避免辛辣刺激、过咸、过干食物，多吃滋阴润燥食物（银耳、百合、梨），避免咖啡酒精（加重干燥）","皮肤护理：使用温和沐浴露，避免过度清洁，洗澡后涂润肤剂，穿棉质宽松衣物","环境：保持室内湿度50-60%，使用加湿器，避免干燥环境","避免致干药物：抗组胺药、抗抑郁药、抗胆碱药、利尿剂等（如必须用需注意口干加重）","戒烟：吸烟加重口干和肺损伤，必须戒烟","定期复查：定期查血常规、血沉、免疫球蛋白、补体、肝肾功能、尿常规，监测疾病活动和淋巴瘤迹象","心理支持：慢性病长期不适影响生活质量，易焦虑抑郁，需心理疏导","运动：适度有氧运动（散步、游泳、太极），避免过度劳累，关节痛患者避免剧烈运动"],"complications":["淋巴瘤：最严重并发症，pSS患者淋巴瘤发生率约5-10%（是正常人10-20倍），持续腮腺肿大、单克隆免疫球蛋白、白细胞减少、新发淋巴结肿大、脾大需警惕，及时淋巴结活检","肺间质病变：约10-20%患者，干咳活动后气短，CT见磨玻璃影和网格影，可进展为肺纤维化，需激素+免疫抑制剂+抗纤维化","肾小管酸中毒（I型）：约20-30%患者，远端肾小管泌氢障碍，低钾血症（肌无力、周期性麻痹）、高氯性酸中毒、肾钙化/结石，需长期补钾和碱剂","自身免疫性肝病：约20%合并原发性胆汁性胆管炎（PBC）或自身免疫性肝炎，需查肝功能和自身抗体，用熊去氧胆酸","甲状腺疾病：约15-20%合并桥本甲状腺炎或甲减，需查甲状腺功能","血液系统损害：白细胞减少、血小板减少、贫血，严重血小板减少需激素+免疫抑制剂","神经系统：周围神经病变（感觉异常、麻木）、自主神经病变、罕见中枢神经病变，需激素+免疫抑制剂","血管炎：皮肤紫癜、荨麻疹样血管炎，与冷球蛋白血症相关，严重者需激素+环磷酰胺","药物不良反应：羟氯喹致眼底损害（每年筛查）、皮疹；激素致骨质疏松、高血糖、感染；免疫抑制剂致骨髓抑制、感染、肝损伤；毛果芸香碱致出汗、腹痛、尿频","感染：免疫抑制治疗增加感染风险，需预防和监测"],"monitoring":["诊断时：血常规、血沉、CRP、免疫球蛋白（IgG/IgA/IgM）、补体、ANA、抗SSA/SSB、类风湿因子、抗CCP、肝肾功能、尿常规、血气+电解质（排查肾小管酸中毒）、甲状腺功能、眼科检查（Schirmer、BUT、角膜染色）、唾液流率、唇腺活检、胸部CT","治疗初期：每1-3个月评估症状（口干眼干VAS评分）、ESSDAI系统活动度、血常规、生化、免疫球蛋白，调整药物","羟氯喹：用药前和每年查眼底（视网膜病变），剂量不超过5mg/kg/d","激素和免疫抑制剂：每2-4周查血常规、肝肾功能，稳定后每1-3个月查，监测感染和不良反应","肺间质病变：每3-6个月查胸部CT和肺功能（FVC、DLco），评估进展","肾小管酸中毒：定期查血气、电解质（钾）、尿常规、肾脏超声，调整补钾剂量","淋巴瘤筛查：每年体检（淋巴结、腮腺、脾脏），持续腮腺肿大或淋巴结肿大及时活检，监测免疫球蛋白（单克隆峰）","长期：每3-6个月全面评估，监测疾病活动、系统受累、药物不良反应、淋巴瘤迹象","出现持续腮腺肿大、新发淋巴结肿大、体重下降、单克隆球蛋白：立即就诊（排查淋巴瘤）"],"special_populations":["老年患者：口干眼干需与老年性腺体萎缩鉴别，用药注意药物相互作用和肝肾功能，激素和免疫抑制剂需减量","孕妇：羟氯喹孕期可继续（相对安全），激素和免疫抑制剂需评估（甲氨蝶呤、吗替麦考酚酯、环磷酰胺致畸，需停药），利妥昔单抗孕期避免","儿童：罕见，需与IgG4相关疾病、遗传性干燥鉴别，儿科和风湿科共管","合并淋巴瘤：按淋巴瘤方案治疗，pSS本身治疗需调整，预后取决于淋巴瘤类型","合并肺间质纤维化：除激素免疫抑制剂外，加用抗纤维化药物（吡非尼酮、尼达尼布），长期氧疗","合并肾小管酸中毒：长期补钾和碱剂，定期监测电解质和肾功能，避免肾毒性药物","合并PBC：熊去氧胆酸13-15mg/kg/d，定期查肝功能和免疫球蛋白","使用生物制剂者：用药前筛查结核乙肝，治疗期间监测感染和血常规","反复腮腺肿大：需警惕淋巴瘤，及时活检，不要简单归因于干燥活动","严重血小板减少：可用激素+丙种球蛋白+利妥昔单抗，避免使用可能加重血小板减少的药物"],"references":["中华医学会风湿病学分会. 干燥综合征诊治指南（2024）","2023 EULAR-ACR干燥综合征管理指南","ACR干燥综合征临床实践指南"]},{"name":"肺结节诊治指南（2024）","category":"呼吸内科","scope":"成人肺结节的评估、良恶性鉴别、随访策略和干预指征。","diagnosis":["定义：肺结节为影像学上直径小于等于30mm的类圆形或不规则形病灶，影像学表现为密度增高的阴影，可单发或多发，不伴肺不张、肺门肿大和胸腔积液","分类：按大小（微小结节小于5mm、小结节5-10mm、结节10-30mm）、按密度（实性结节、部分实性结节/混合磨玻璃结节、纯磨玻璃结节）、按数量（孤立性、多发性）","恶性风险评估：年龄（大于40岁风险增加）、吸烟史（包年数）、肺癌家族史、职业暴露（石棉、氡、铀）、既往癌症史、结节大小（越大恶性率越高）、结节形态（分叶、毛刺、胸膜牵拉、空泡征、血管集束征提示恶性）、结节密度（部分实性恶性率最高，纯磨玻璃恶性率低但多为腺癌）、生长速度（倍增时间30-400天提示恶性，小于30天多为感染，大于400天多为良性）","影像学：胸部CT（薄层CT，1mm层厚，是评估肺结节的金标准）、PET-CT（大于8mm实性结节，评估代谢活性，假阴性见于腺癌和类癌，假阳性见于感染炎症）、增强CT（评估强化程度，恶性结节强化大于15HU）","有创检查：CT引导下经皮肺穿刺活检（外周结节）、支气管镜活检（中央结节，含导航支气管镜）、胸腔镜手术活检（同时诊断和治疗）","肿瘤标志物：CEA、CYFRA21-1、NSE、SCC、ProGRP，辅助参考，不能单独作为诊断依据","鉴别：良性（炎性结节、结核球、错构瘤、肺内淋巴结、硬化性肺细胞瘤、真菌感染）、恶性（肺腺癌、鳞癌、转移瘤）","肺癌筛查：高危人群（50-74岁、吸烟≥20包年、戒烟不足15年）每年低剂量CT筛查"],"staging":["按大小：微小结节（小于5mm，恶性率小于1%）、小结节（5-10mm，恶性率约5-10%）、结节（10-30mm，恶性率约10-30%以上）","按密度：实性结节（恶性率与大小相关）、部分实性结节（恶性率最高，约30-60%，实性成分大于5mm需警惕）、纯磨玻璃结节（恶性率约10-30%，多为原位腺癌或微浸润腺癌，生长缓慢）","按数量：孤立性肺结节（SPN）、多发性肺结节（转移瘤、多原发肺癌、感染、肉芽肿）","按恶性风险：低危（小于5%）、中危（5-65%）、高危（大于65%）","按Fleischner学会指南：根据结节类型、大小、数量和危险因素制定随访间隔"],"key_points":["随访观察（多数小结节）：根据Fleischner或Lung-RADS指南定期CT随访，观察结节大小、密度、形态变化，不急于有创检查","良性结节：炎性结节可抗感染治疗后复查（2-4周），结核球抗结核治疗，错构瘤等良性肿瘤可定期随访或手术切除","恶性或高度怀疑恶性：手术切除（胸腔镜下肺楔形切除/肺段切除/肺叶切除，早期肺癌5年生存率大于90%），不能手术者立体定向放疗（SBRT）或射频消融","纯磨玻璃结节：小于5mm不需常规随访；5-6mm 3-6个月复查，稳定后每年；大于6mm 6-12个月复查，持续存在大于10mm或实性成分增加考虑手术（多为原位腺癌/微浸润腺癌，生长缓慢，过度手术也有风险）","部分实性结节：小于6mm 6-12个月复查；大于6mm 3-6个月复查，实性成分大于5mm或持续存在考虑手术/活检（恶性率高，多为浸润性腺癌）","实性结节：小于6mm低危不需常规随访，高危12个月复查；6-8mm 6-12个月复查；大于8mm考虑PET-CT、活检或手术，3个月复查","多发结节：评估每个结节，按最大或最可疑结节随访，怀疑转移瘤需查找原发灶","抗感染试验：怀疑感染的实性结节，可经验性抗感染（覆盖细菌和非典型病原体）2-4周后复查CT，缩小或消失支持感染","术前评估：心肺功能、手术耐受、结节定位（CT定位、Hookwire）、手术方式选择（楔形/段切/叶切）","肺癌筛查：高危人群每年低剂量CT，发现结节按指南管理，筛查可降低肺癌死亡率20%"],"drug_recommendations":[],"non_pharmacological":["戒烟：吸烟是肺癌首要危险因素，戒烟可降低肺癌风险，任何时候戒烟都有益，避免二手烟和三手烟","避免职业暴露：石棉、氡、铀、砷、铬、镍等职业暴露需防护，定期体检","饮食：均衡饮食，多吃蔬菜水果，避免过度饮酒，不推荐常规补充维生素预防肺癌","运动：规律有氧运动，增强体质，提高免疫力","心理调节：发现肺结节不要过度焦虑（多数为良性），但也不能忽视，按医嘱定期随访，必要时心理疏导","避免反复CT辐射：按指南间隔随访，不要短期内频繁复查CT（增加辐射暴露），低剂量CT辐射量低","记录随访：保存每次CT报告和影像，便于对比结节变化（建议在同一家医院随访，便于影像对比）","出现症状：咳嗽、咯血、胸痛、气短、体重下降及时就诊（可能提示结节进展或肺癌）","术后康复：肺手术后早期呼吸功能锻炼（缩唇呼吸、腹式呼吸、有效咳嗽），适度活动，定期复查","预防感染：接种流感疫苗和肺炎球菌疫苗，减少肺部感染（感染可致结节增大，干扰随访判断）"],"complications":["漏诊肺癌：随访间隔过长或未按指南随访，致早期肺癌进展为晚期，影响预后，需严格按指南随访","过度诊断和过度治疗：部分纯磨玻璃结节为惰性腺癌（原位腺癌），生长极慢，过度手术致肺功能损失，需多学科评估（胸外科、呼吸、影像、病理）","良性结节手术：术前未明确诊断，手术后病理为良性（炎性假瘤、结核球、错构瘤），虽手术安全但非必要，术前需充分评估","穿刺并发症：CT引导下穿刺可致气胸（约10-20%，多数少量可吸收）、出血（咯血）、肿瘤针道种植（罕见），需严格掌握指征","PET-CT假阴性：磨玻璃结节、类癌、低代谢腺癌可呈假阴性，不能仅凭PET-CT阴性排除恶性","PET-CT假阳性：炎性结节、结核、真菌感染可呈高代谢，需结合临床和抗感染后复查","多发结节处理困难：多原发肺癌与转移瘤鉴别困难，需结合影像、病理、分子检测，多学科讨论","术后并发症：肺手术后出血、感染、肺不张、持续漏气、心律失常，需术后监护和康复","放疗并发症：SBRT可致放射性肺炎、食管炎、肋骨骨折，需精确放疗","心理负担：肺结节患者焦虑抑郁发生率高，\"结节恐惧症\"，需科普和心理疏导，避免不必要的恐慌"],"monitoring":["首次发现：详细病史（吸烟史、职业暴露、肿瘤史、家族史）、薄层CT（1mm层厚）、肿瘤标志物、必要时PET-CT（大于8mm实性结节）","随访CT：根据结节类型和大小按指南间隔（3、6、12、24个月），薄层低剂量CT，对比大小密度形态变化","抗感染后复查：怀疑感染的结节，抗感染2-4周后复查CT，评估变化","术前：心肺功能（心电图、心脏超声、肺功能）、凝血、传染病筛查、结节定位（CT引导Hookwire）","术后：病理报告明确诊断和分期，早期肺癌术后定期复查（每3-6个月胸部CT、肿瘤标志物，2年后每年）","长期随访：良性结节稳定2年以上可延长间隔；磨玻璃结节需长期随访（5年以上，部分可在多年后进展）","肺癌筛查人群：每年低剂量CT，发现结节按Lung-RADS分类管理（1类阴性、2类良性、3类可能良性、4A/4B/4X可疑恶性）","出现结节增大、实性成分增加、形态变不规则：缩短随访间隔或考虑手术/活检","多发结节：每次随访评估所有结节，记录最大和最可疑结节的变化"],"special_populations":["吸烟者：肺癌风险显著增加，戒烟是最有效的预防，高危人群（50-74岁，≥20包年）每年低剂量CT筛查","老年人：肺结节发生率高，恶性风险随年龄增加，手术需评估心肺功能和预期寿命，不能手术者考虑SBRT","孕妇：避免CT辐射，如必须检查需告知风险并腹部防护，MRI可作为替代（但对肺结节评估有限）","儿童：肺结节少见，多为感染或良性肿瘤，CT辐射需谨慎，尽量用低剂量，避免过度检查","有肺癌家族史者：风险增加，筛查年龄可提前，密切随访","既往癌症史者：肺结节需排除转移瘤，结合原发癌类型和病史，必要时PET-CT或活检","免疫抑制者（移植、HIV、激素）：感染性结节（真菌、结核）风险增加，需鉴别感染和肿瘤","间质性肺病患者：合并肺癌风险增加（尤其肺纤维化），结节需密切随访，手术需评估肺功能","磨玻璃结节患者：多为惰性病变，避免过度焦虑和过度手术，需多学科评估和长期随访","不能手术者（心肺功能差、高龄）：SBRT或射频消融可作为根治性替代，效果接近手术（早期周围型肺癌）"],"references":["中华医学会呼吸病学分会. 肺结节诊治指南（2024）","Fleischner学会肺结节管理指南（2017更新）","Lung-RADS肺癌筛查报告和数据系统"]},{"name":"甲状腺结节诊治指南（2024）","category":"内分泌科","scope":"成人甲状腺结节的评估、良恶性鉴别、随访和治疗。","diagnosis":["临床表现：多数无症状，体检发现；结节大可致颈部肿块、压迫症状（呼吸困难、吞咽困难、声音嘶哑）、甲亢症状（高功能腺瘤）","体征：甲状腺触及结节（大小、质地、活动度、压痛、有无颈部淋巴结肿大）","实验室：甲功（TSH、FT3、FT4）、甲状腺自身抗体（TPOAb、TgAb）、降钙素（怀疑髓样癌）、甲状腺球蛋白（Tg，术后随访）","影像学：甲状腺超声（首选，TI-RADS分级评估恶性风险）、超声造影、弹性成像","细针穿刺活检（FNA）：超声引导下FNA，Bethesda分级，是术前诊断金标准","核素扫描：TSH降低时行甲状腺核素扫描（高功能腺瘤多为良性）","CT/MRI：评估结节与周围组织关系、胸骨后甲状腺、淋巴结转移","鉴别：结节性甲状腺肿、甲状腺腺瘤、甲状腺癌（乳头状、滤泡状、髓样、未分化）、桥本甲状腺炎、亚急性甲状腺炎","恶性危险因素：儿童期头颈部放疗史、甲状腺癌家族史、男性、年龄小于20或大于70岁、结节短期内增大、声音嘶哑、颈部淋巴结肿大、结节质硬固定"],"staging":["按TI-RADS分级：1类（正常）、2类（良性，恶性率0）、3类（可能良性，恶性率小于2%）、4类（可疑恶性，4A 2-10%、4B 10-50%、4C 50-90%）、5类（高度怀疑恶性，大于90%）、6类（活检证实恶性）","按Bethesda分级：I类（标本不满意）、II类（良性）、III类（意义不明确的细胞非典型病变）、IV类（滤泡性肿瘤/可疑滤泡性肿瘤）、V类（可疑恶性）、VI类（恶性）","按大小：微小结节（小于1cm）、小结节（1-2cm）、大结节（2-4cm）、巨大结节（大于4cm）","按功能：高功能结节（甲亢）、正常功能结节、低功能结节","按良恶性：良性结节（90-95%）、恶性结节（5-10%，乳头状癌最常见）"],"key_points":["良性结节：定期随访（超声+甲功），不需特殊治疗；有压迫症状或巨大结节可手术；高功能腺瘤用放射性碘或手术","甲状腺素抑制治疗：不常规推荐（对缩小结节效果有限，增加心血管和骨质疏松风险），仅在特定情况考虑","恶性结节：手术治疗（甲状腺全切或近全切+中央区淋巴结清扫，根据病理类型和分期）；乳头状癌微小癌（小于1cm，无高危因素）可考虑主动监测或腺叶切除","术后管理：分化型甲状腺癌（乳头状/滤泡状）术后TSH抑制治疗（左甲状腺素，根据复发风险调整TSH目标：高危小于0.1，中危0.1-0.5，低危0.5-2）；放射性碘治疗（中高危患者术后清甲/清灶）；定期复查Tg和TgAb、颈部超声","髓样癌：甲状腺全切+淋巴结清扫，术后监测降钙素和CEA，RET基因检测，家族筛查","未分化癌：预后极差，多学科综合治疗（手术+放疗+化疗+靶向）","FNA Bethesda III/IV类：可重复FNA、分子检测（BRAF、RAS、RET/PTC）或诊断性手术","囊性结节：可穿刺抽液，反复复发可硬化治疗（无水乙醇）","中医中药：部分中成药（夏枯草、小金丸）可辅助缩小结节，疗效因人而异","随访：良性结节每6-12个月超声复查，增大或可疑恶性缩短间隔或FNA"],"drug_recommendations":[],"non_pharmacological":["饮食：适碘饮食，避免长期大量摄入高碘食物（海带紫菜），碘缺乏地区适当补碘","避免颈部放射线暴露：儿童期避免头颈部放疗，职业暴露防护","定期自查：注意颈部肿块变化，出现声音嘶哑、呼吸困难、吞咽困难及时就诊","术后护理：甲状腺全切者需终身服用左甲状腺素，不可自行停药，定期复查甲功调整剂量","放射性碘治疗后：隔离（避免接触孕妇儿童），多饮水促排泄，避孕（女性6个月，男性3个月）","心理支持：甲状腺结节患者易焦虑（担心癌变），需解释良性可能性大，避免过度检查和治疗","避免过度医疗：多数良性结节不需手术，避免不必要的甲状腺切除","术后颈部功能锻炼：术后早期进行颈部伸展和肩部活动，预防粘连和僵硬","戒烟限酒：吸烟增加甲状腺癌风险，限制酒精","定期体检：每年甲状腺超声筛查（高危人群）"],"complications":["甲状腺癌：约5-10%结节为恶性，乳头状癌预后好（5年生存率大于95%），未分化癌预后差（中位生存期6个月）","术后并发症：出血（术后24小时内，颈部血肿压迫气道，急诊处理）、喉返神经损伤（声音嘶哑，双侧损伤致呼吸困难）、喉上神经损伤（饮水呛咳、音调降低）、甲状旁腺功能减退（低钙血症，手足麻木抽搐，需补钙和维生素D）、甲状腺功能减退（全切后，需终身替代）","放射性碘治疗并发症：颈部肿胀、唾液腺损伤（口干）、味觉改变、骨髓抑制（少见）、继发性肿瘤风险（长期大剂量）","TSH抑制治疗并发症：长期亚临床甲亢致心律失常（房颤）、骨质疏松（尤其绝经后女性），需权衡获益风险","结节内出血：囊性结节突然增大伴疼痛，多可自行吸收，严重压迫需穿刺引流","气管食管压迫：巨大结节或胸骨后甲状腺肿致呼吸困难、吞咽困难，需手术","甲亢危象：高功能腺瘤手术或碘治疗前未控制甲亢可诱发，需术前充分准备","术后复发：甲状腺癌术后复发，需定期监测Tg和超声，及时发现处理","声音嘶哑：喉返神经损伤或肿瘤侵犯，需评估神经功能","心理负担：结节患者焦虑抑郁发生率高，\"甲状腺结节恐惧症\"，需科普和心理疏导"],"monitoring":["诊断时：甲功（TSH/FT3/FT4）、甲状腺自身抗体、甲状腺超声（TI-RADS分级）、必要时FNA（Bethesda分级）、降钙素（怀疑髓样癌）、核素扫描（TSH降低时）","FNA指征：TI-RADS 4类以上结节、结节短期内增大、有恶性危险因素、颈部淋巴结肿大","随访：良性结节每6-12个月超声复查，增大超过20%或出现可疑征象缩短间隔或重复FNA","术后：每3-6个月查甲功（调整左甲状腺素剂量）、Tg和TgAb（分化型癌）、颈部超声（复发监测），每年胸片或CT（高危者）","放射性碘治疗后：全身显像（评估清甲效果和转移灶）、Tg监测","TSH抑制治疗：定期查甲功，维持目标TSH水平，监测骨密度（长期抑制者）、心电图","髓样癌术后：定期查降钙素和CEA，升高提示复发，需影像学检查","出现结节迅速增大、声音嘶哑、颈部淋巴结肿大、呼吸困难：立即就诊（怀疑恶性或进展）"],"special_populations":["孕妇：孕期发现甲状腺结节，FNA可在孕中期进行（安全），避免放射性碘检查和治疗，TSH控制在孕期特异范围，产后重新评估","儿童青少年：甲状腺结节恶性率高于成人（约20-25%），需更积极评估，避免放射性暴露，FNA安全","老年人：未分化癌多见于老年人，预后差，结节短期内增大需警惕，手术需评估全身情况","男性：男性甲状腺结节恶性率高于女性，需更积极评估","有头颈部放疗史者：结节恶性率高，需密切随访，必要时预防性FNA","甲状腺癌家族史者：遗传相关（髓样癌RET突变、乳头状癌家族史），需基因检测和家族筛查","桥本甲状腺炎患者：合并结节恶性风险可能增加（淋巴瘤风险），需鉴别","肾功能不全：造影剂（增强CT）需谨慎，避免肾毒性，用超声和无造影剂MRI","服用胺碘酮者：可致甲状腺功能异常和结节，需定期查甲功"],"references":["中华医学会内分泌学分会. 甲状腺结节诊治指南（2024）","2023 ATA甲状腺结节和分化型甲状腺癌指南","NCCN甲状腺癌临床实践指南"]},{"name":"急性阑尾炎诊治指南（2024）","category":"外科","scope":"成人和儿童急性阑尾炎的诊断、分型、手术和非手术治疗。","diagnosis":["临床表现：转移性右下腹痛（始于上腹或脐周，数小时后转移并固定于右下腹，最典型）、胃肠道症状（厌食、恶心、呕吐、腹泻或便秘）、全身症状（发热、乏力）","体征：右下腹压痛（麦氏点最明显）、反跳痛、肌紧张、结肠充气试验（Rovsing征）阳性、腰大肌试验阳性（盲肠后位）、闭孔内肌试验阳性（盆腔位）、直肠指检右前方压痛（盆腔位）","实验室：白细胞升高（10-20×10^9/L）、中性粒细胞比例升高、CRP升高、尿常规（排除泌尿系感染，输尿管结石可有血尿）","影像学：腹部超声（首选儿童和孕妇，阑尾增粗大于6mm、壁增厚、周围渗出）、腹部CT（成人首选，准确率高，阑尾增粗、粪石、周围脂肪间隙模糊、脓肿）、MRI（孕妇，无辐射）","分型：急性单纯性阑尾炎、急性化脓性阑尾炎、坏疽穿孔性阑尾炎、阑尾周围脓肿","鉴别：消化性溃疡穿孔、右侧输尿管结石、急性胆囊炎、急性胃肠炎、梅克尔憩室炎、肠套叠（儿童）、异位妊娠破裂、卵巢囊肿蒂扭转、盆腔炎（女性）、肠系膜淋巴结炎（儿童）","Alvarado评分：转移性腹痛1、厌食1、恶心呕吐1、右下腹压痛2、反跳痛1、体温升高1、白细胞升高2、中性粒左移1，大于等于7分高度怀疑"],"staging":["按病理分型：急性单纯性阑尾炎（早期，黏膜充血水肿）、急性化脓性阑尾炎（壁层脓肿，腔内积脓）、坏疽穿孔性阑尾炎（血运障碍坏死穿孔，弥漫性腹膜炎）、阑尾周围脓肿（穿孔后被大网膜包裹，右下腹包块）","按临床严重程度：单纯性（无穿孔，局限）、复杂性（穿孔、脓肿、腹膜炎）","按病程：急性（小于72小时）、迁延性（大于72小时）、慢性（反复发作）","特殊类型：小儿急性阑尾炎（症状不典型，穿孔率高）、老年急性阑尾炎（症状轻病理重，穿孔率高）、妊娠期急性阑尾炎（压痛点上移，腹膜炎不易局限）、异位阑尾炎（肝下、盆腔、盲肠后位）"],"key_points":["手术治疗是急性阑尾炎的主要治疗方法","腹腔镜阑尾切除术（首选，创伤小、恢复快、并发症少）：三孔法或单孔法，适用于大多数急性阑尾炎","开腹阑尾切除术：腹腔镜禁忌或设备条件不足时，右下腹麦氏切口或经腹直肌切口","非手术治疗：适用于单纯性阑尾炎早期、患者拒绝手术、有手术禁忌证；禁食、静脉补液、广谱抗生素（覆盖革兰阴性菌和厌氧菌，如头孢类+甲硝唑）、密切观察，24-48小时无效或加重转手术","阑尾周围脓肿：病程超过72小时、右下腹包块、B超/CT证实脓肿，先非手术治疗（抗生素+必要时穿刺引流），炎症消退后6-8周择期行阑尾切除术；脓肿扩大或中毒症状重需手术引流","术前准备：禁食、静脉补液、抗生素（术前30分钟给药）、镇痛","术后处理：早期下床活动（促进肠蠕动，预防肠粘连）、禁食至肠蠕动恢复（排气）后逐步进食、抗生素（单纯性术后24小时，穿孔/脓肿3-5天）、切口护理","抗生素方案：三代头孢（头孢曲松/头孢他啶）+甲硝唑，或哌拉西林他唑巴坦，或厄他培南（复杂阑尾炎）","保守治疗失败：腹痛加重、发热不退、白细胞升高、出现腹膜炎体征，立即手术","预防：术后早期活动预防肠粘连，切口感染预防（无菌操作、抗生素）"],"drug_recommendations":[],"non_pharmacological":["术前：禁食水，备皮，签署手术同意书，解释手术方式和风险","术后6小时：半卧位（减少毒素吸收，减轻腹痛），生命体征监测","饮食：术后禁食至肠蠕动恢复（排气），先流质（米汤、藕粉），半流质（粥、面条），逐渐过渡到普食，避免辛辣刺激和油腻食物","活动：术后6小时可床上翻身，24小时后下床活动（促进肠蠕动，预防肠粘连和深静脉血栓），避免剧烈运动和重体力劳动1个月","切口护理：保持切口清洁干燥，腹腔镜切口1周拆线（或可吸收线不需拆），开腹切口7-9天拆线，出现红肿渗液及时就诊","疼痛管理：术后镇痛（非甾体抗炎药或阿片类），鼓励早期活动减轻腹胀","观察：注意腹痛、发热、排气排便情况，出现持续腹痛、高热、腹胀不排气及时就诊（并发症）","饮食调理：术后1个月内清淡易消化，少量多餐，避免暴饮暴食，戒烟酒","预防肠粘连：早期活动是关键，腹部手术后肠粘连是常见远期并发症","定期复查：术后1个月门诊复查，评估恢复情况"],"complications":["切口感染：最常见并发症，表现为切口红肿热痛、渗液、发热，需拆线引流、换药、抗生素，肥胖和糖尿病患者风险高","腹腔脓肿：穿孔性阑尾炎术后，表现为持续发热、腹痛、直肠刺激征，B超/CT确诊，穿刺引流或手术引流","粘连性肠梗阻：术后远期并发症，腹痛腹胀呕吐停止排气，保守治疗（禁食、胃肠减压、补液），无效手术","粪瘘：阑尾残端瘘，表现为切口或引流口流出粪样物，多可保守愈合，长期不愈需手术","门静脉炎（pylephlebitis）：罕见但严重，阑尾感染经门静脉扩散，寒战高热、黄疸、肝脓肿，需大剂量抗生素和抗凝","出血：术后腹腔内出血（血管结扎脱落），表现为腹痛腹胀休克，需急诊手术；切口出血加压包扎","肠梗阻：早期麻痹性肠梗阻（腹胀不排气），晚期粘连性肠梗阻","阑尾残株炎：阑尾残端保留过长（大于1cm），术后反复右下腹痛，需再次手术","深静脉血栓和肺栓塞：术后长期卧床，早期活动预防，高危者抗凝","死亡：罕见，多见于穿孔性阑尾炎合并脓毒症、老年人延误诊治"],"monitoring":["术前：血常规、CRP、凝血、肝肾功能、电解质、血型、传染病筛查、心电图、腹部超声/CT、尿常规（女性加尿HCG排除妊娠）","术后：每4-6小时监测生命体征（体温、脉搏、呼吸、血压），观察腹痛、排气、切口情况","术后1天：复查血常规、CRP，评估炎症控制情况","出院前：评估体温、腹痛、排气排便、切口愈合，复查血常规（必要时）","术后1个月：门诊复查，评估切口愈合、消化功能、有无粘连症状","保守治疗期间：每4-6小时评估腹痛、体温、腹部体征，每24小时复查血常规，24-48小时评估疗效，无效转手术","阑尾周围脓肿：保守治疗期间定期超声/CT评估脓肿大小，炎症消退后6-8周择期手术","出现持续高热、腹痛加重、腹胀不排气、切口渗液：及时就诊（并发症）"],"special_populations":["儿童：症状不典型（高热、呕吐、腹泻为主），大网膜发育不全穿孔率高，需尽早手术，术前注意脱水和电解质紊乱","老年人：症状和体征轻（反应差），病理改变重，穿孔率和死亡率高，合并症多，需积极手术，加强围手术期管理","孕妇：压痛点上移（子宫增大推盲肠），腹膜炎不易局限（大网膜被推开），炎症刺激子宫致流产早产，需尽早手术（孕中期腹腔镜相对安全），术后保胎","肥胖患者：腹腔镜视野和操作困难，切口感染风险高，可考虑开腹或经腹直肌切口","糖尿病患者：感染不易控制，切口愈合差，术前控制血糖（小于11.1mmol/L），术后监测血糖，加强抗感染","免疫抑制患者（激素、移植、HIV）：症状不典型，感染进展快，需积极手术和广谱抗生素","心肺功能不全者：手术风险高，需评估麻醉耐受，选择创伤小的腹腔镜，加强监护","服用抗凝药者：术前评估血栓和出血风险，决定是否桥接抗凝，术后尽早恢复抗凝","异位阑尾炎：诊断困难（肝下位误诊胆囊炎，盆腔位误诊盆腔炎），需仔细查体和影像学"],"references":["中华医学会外科学分会. 急性阑尾炎诊治指南（2024）","WSES急性阑尾炎诊疗指南","ACG急性阑尾炎管理指南"]},{"name":"急性胆囊炎诊治指南（2024）","category":"外科","scope":"成人急性胆囊炎的诊断、严重程度分级、手术时机和非手术治疗。","diagnosis":["临床表现：右上腹疼痛（持续性，可向右肩背放射，油腻饮食诱发）、发热、恶心呕吐","体征：右上腹压痛、肌紧张、Murphy征阳性（吸气时按压胆囊点致吸气中断）、可触及肿大胆囊、黄疸（合并胆管炎或Mirizzi综合征）","实验室：白细胞升高、中性粒细胞比例升高、CRP升高、肝功能异常（ALT/AST/ALP/GGT升高，胆红素升高提示胆管梗阻）","影像学：腹部超声（首选，胆囊增大、壁增厚大于3mm、双边征、胆囊结石、超声Murphy征阳性）、CT/MRI（评估并发症和胆管情况）、MRCP（怀疑胆管结石或胆管炎）","严重程度分级（东京指南TG18）：I级（轻度，无器官功能障碍，无中重度炎症表现）、II级（中度，白细胞大于18×10^9、右上腹可及包块、病程大于72小时、局部炎症重）、III级（重度，合并心血管/神经/呼吸/肾/肝/凝血功能障碍）","鉴别：消化性溃疡穿孔、急性胰腺炎、肝脓肿、右侧胸膜炎/肺炎、急性阑尾炎（高位）、心绞痛/心梗、右侧肾结石/肾盂肾炎、带状疱疹","危险因素：胆囊结石（最常见，90-95%）、女性、40岁以上、肥胖、多产、口服避孕药、快速减重、全胃肠外营养"],"staging":["按病因：结石性胆囊炎（90-95%，胆囊结石嵌顿致胆囊管梗阻）、非结石性胆囊炎（5-10%，危重患者、术后、创伤、脓毒症，胆囊缺血致，易穿孔）","按严重程度：轻度（I级）、中度（II级）、重度（III级，合并器官功能障碍）","按病程：急性（小于72小时）、亚急性（72小时-2周）、慢性（反复发作，胆囊壁增厚萎缩）","按并发症：单纯性胆囊炎、化脓性胆囊炎、坏疽性胆囊炎、胆囊穿孔、胆囊周围脓肿、胆囊肠瘘（胆石性肠梗阻）","特殊类型：气肿性胆囊炎（产气荚膜梭菌感染，胆囊积气，糖尿病患者，易穿孔）、黄色肉芽肿性胆囊炎（慢性炎症，易与胆囊癌混淆）"],"key_points":["手术治疗是根本治疗方法","腹腔镜胆囊切除术（LC，首选）：创伤小、恢复快、并发症少，适用于大多数急性胆囊炎","手术时机：轻度（I级）尽早手术（发病72小时内最佳，超过72小时炎症水肿重手术难度增加但仍可尝试）；中度（II级）早期手术（72小时内）或抗感染后择期；重度（III级）先器官支持和抗感染，病情稳定后早期手术，或胆囊造瘘减压（不能耐受手术者）","开腹胆囊切除术：腹腔镜禁忌或中转开腹（炎症重、粘连重、出血、胆管损伤风险），右肋缘下切口或经腹直肌切口","非手术治疗：适用于不能耐受手术、发病超过72小时炎症局限、患者拒绝手术；禁食、胃肠减压（严重呕吐腹胀）、静脉补液纠正电解质、广谱抗生素（覆盖革兰阴性菌和厌氧菌）、镇痛解痉（山莨菪碱、哌替啶，避免吗啡致Oddi括约肌痉挛）、密切观察","胆囊造瘘术：高危患者不能耐受胆囊切除，经皮经肝胆囊穿刺引流（PTGBD）或手术造瘘，减压引流，二期切除胆囊","抗生素方案：轻度用头孢唑林/头孢呋辛；中重度用哌拉西林他唑巴坦、头孢哌酮舒巴坦、厄他培南；合并胆管炎用三代头孢+甲硝唑或碳青霉烯类","术后处理：早期下床活动、禁食至肠蠕动恢复后逐步进食、抗生素（单纯性术后24小时，化脓坏疽3-5天）、切口护理","胆总管结石：术前MRCP或术中胆道造影发现，需同时行胆总管探查取石或术前ERCP取石","胆囊癌：术中发现胆囊壁增厚变硬或肿物，需术中冰冻病理，按胆囊癌根治"],"drug_recommendations":[],"non_pharmacological":["术前：禁食水，备皮，签署手术同意书，解释手术方式和胆管损伤风险","术后6小时：半卧位，生命体征监测，观察腹痛和腹部体征","饮食：腹腔镜术后6小时可进流质，次日半流质，逐渐普食；开腹术后禁食至排气后逐步进食，避免油腻食物","活动：腹腔镜术后6-12小时可下床活动，开腹术后24小时下床，促进肠蠕动和预防血栓","切口护理：腹腔镜切口1周拆线，开腹切口7-9天拆线，保持清洁干燥","疼痛管理：腹腔镜术后疼痛轻，必要时非甾体抗炎药；开腹术后可用PCA镇痛","观察：注意腹痛、发热、黄疸（胆管损伤或胆管结石）、排气排便，出现持续腹痛、高热、黄疸及时就诊","饮食调理：术后1个月内低脂饮食（避免肥肉、油炸、蛋黄），少量多餐，逐渐恢复正常饮食，戒烟酒","预防：规律饮食（避免空腹时间过长）、控制体重、避免快速减重、定期体检发现胆囊结石","定期复查：术后1个月复查，有胆管结石或黄疸者定期查肝功能和超声"],"complications":["胆管损伤：最严重并发症，腹腔镜胆囊切除术发生率约0.3-0.5%，表现为术后黄疸、腹痛、发热、胆汁性腹膜炎，需及时发现处理（ERCP支架或手术修复），延误可致胆汁性肝硬化","出血：术后腹腔内出血（胆囊动脉结扎脱落），表现为腹痛腹胀休克，需急诊手术；切口出血加压","胆瘘：胆囊管残端瘘或副肝管损伤，表现为腹痛、发热、腹腔积液，需引流+ERCP支架，多可保守愈合","切口感染：开腹手术多见，红肿渗液，拆线引流换药","术后胰腺炎：Oddi括约肌痉挛或结石排入胆总管，腹痛血尿淀粉酶升高，保守治疗","胆总管残留结石：术前未发现，术后黄疸腹痛，ERCP取石","胆囊切除术后综合征：术后仍有右上腹不适、消化不良，多为胆管功能紊乱或残留结石，需检查排除","肠粘连：开腹手术后，早期活动预防","深静脉血栓和肺栓塞：术后卧床，早期活动预防，高危者抗凝","非结石性胆囊炎穿孔：危重患者非结石性胆囊炎易穿孔（约20-40%），需早期识别和干预","死亡：重度胆囊炎合并脓毒症和多器官功能衰竭，死亡率高，需积极治疗"],"monitoring":["术前：血常规、CRP、凝血、肝肾功能、电解质、胆红素、淀粉酶、血型、传染病筛查、心电图、胸片、腹部超声、必要时MRCP/CT","术后：每4-6小时监测生命体征，观察腹痛、黄疸、排气、切口、引流管（如有）","术后1天：复查血常规、CRP、肝功能（评估炎症和胆管损伤）","出院前：评估体温、腹痛、黄疸、排气、切口，复查血常规和肝功能（必要时）","术后1个月：门诊复查，评估消化功能，查肝功能和腹部超声（必要时）","保守治疗期间：每4-6小时评估腹痛、体温、腹部体征，每24小时复查血常规和肝功能，24-48小时评估疗效，无效或加重转手术","重度胆囊炎：ICU监护器官功能，每日常规评估，稳定后尽早手术或引流","出现术后持续腹痛、高热、黄疸、腹胀不排气：及时就诊（胆管损伤、胆瘘、感染等并发症）"],"special_populations":["老年人：症状不典型（可无发热，仅表现为乏力、意识模糊），合并症多，穿孔率和死亡率高，需积极手术，加强围手术期管理","孕妇：急性胆囊炎是孕期第二常见急腹症（仅次于阑尾炎），孕中期腹腔镜手术相对安全，避免孕早期和晚期，保守治疗无效需手术，注意保胎","糖尿病患者：感染不易控制，易发生气肿性胆囊炎和坏疽穿孔，术前控制血糖，加强抗感染","肥胖患者：腹腔镜操作困难，切口感染风险高，可考虑开腹或加长器械","非结石性胆囊炎：危重患者（术后、创伤、脓毒症、长期TPN），易穿孔，需高度警惕，超声或CT诊断，早期胆囊造瘘或切除","肝硬化患者：凝血功能障碍、门静脉高压、胆囊静脉曲张，手术出血风险高，需术前纠正凝血，备血","心肺功能不全者：手术风险高，评估麻醉耐受，选择创伤小的腹腔镜，加强监护","服用抗凝药者：术前评估血栓出血风险，桥接抗凝，术后尽早恢复","既往腹部手术史：腹腔粘连，腹腔镜难度增加，可能需开腹"],"references":["中华医学会外科学分会. 急性胆囊炎诊治指南（2024）","东京指南（TG18）急性胆囊炎诊疗指南","WSES急性胆囊炎诊疗指南"]},{"name":"肠梗阻诊治指南（2024）","category":"外科","scope":"成人肠梗阻的分类、诊断、保守治疗和手术指征。","diagnosis":["临床表现：腹痛（阵发性绞痛，机械性肠梗阻；持续性胀痛，麻痹性肠梗阻）、呕吐（高位梗阻呕吐早且频繁，低位梗阻呕吐晚且有粪臭味）、腹胀（高位不明显，低位明显）、停止排气排便（完全性梗阻）","体征：腹部膨隆、可见肠型和蠕动波、压痛（单纯性轻，绞窄性重伴反跳痛肌紧张）、肠鸣音亢进（机械性，气过水声金属音）或减弱消失（麻痹性或绞窄晚期）","实验室：血常规（绞窄性白细胞和中性粒升高）、电解质（低钾低钠低氯性碱中毒，高位呕吐）、酸碱失衡、乳酸升高（绞窄性肠缺血）、淀粉酶可升高","影像学：立位腹平片（肠管扩张积气、多个液平面，呈阶梯状）、腹部CT（首选，明确梗阻部位、原因、有无绞窄，表现为肠管扩张、移行带、肠壁增厚、腹水、肠系膜血管扭转）","分类：按病因（机械性、动力性/麻痹性、血运性）、按肠壁血运（单纯性、绞窄性）、按梗阻程度（完全性、不完全性）、按部位（高位小肠、低位小肠、结肠）","常见原因：粘连（腹部手术后最常见，约60%）、肿瘤（结直肠癌，老年人）、疝（腹股沟疝、切口疝嵌顿）、肠套叠（儿童）、肠扭转（乙状结肠扭转、小肠扭转）、粪石、炎症性肠病、肠结核、蛔虫（儿童）","鉴别：急性胰腺炎、急性胆囊炎、消化性溃疡穿孔、急性阑尾炎、肠系膜血管栓塞、卵巢囊肿蒂扭转、宫外孕"],"staging":["按病因：机械性肠梗阻（器质性阻塞，最常见）、动力性肠梗阻（麻痹性，腹腔感染、术后、电解质紊乱；痉挛性少见）、血运性肠梗阻（肠系膜血管栓塞或血栓形成，肠缺血坏死）","按肠壁血运：单纯性肠梗阻（肠管通畅受阻，血运正常）、绞窄性肠梗阻（梗阻伴肠壁血运障碍，需急诊手术）","按梗阻程度：完全性肠梗阻（完全停止排气排便）、不完全性肠梗阻（仍有少量排气排便）","按部位：高位小肠梗阻（空肠上段，呕吐早频繁，腹胀轻）、低位小肠梗阻（回肠末端，呕吐晚有粪臭，腹胀重）、结肠梗阻（腹胀重，呕吐晚，回盲瓣作用致闭袢性梗阻风险）","按病程：急性肠梗阻、慢性肠梗阻（反复发作，肿瘤或粘连）","绞窄性肠梗阻征象：持续性剧烈腹痛、腹膜刺激征、休克、呕吐物/肛门排出血性液、腹部不对称包块、肠鸣音消失、白细胞显著升高、乳酸升高、CT示肠壁积气/门静脉积气/腹水"],"key_points":["基础治疗（所有肠梗阻均需）：禁食水、胃肠减压（留置胃管，吸出胃肠道气体液体，减轻腹胀，改善肠壁血运）、静脉补液纠正水电解质酸碱失衡、营养支持（长期不能进食者肠外营养）、抗生素（单纯性可不用，绞窄性或手术前需用，覆盖革兰阴性菌和厌氧菌）","保守治疗：适用于单纯性粘连性肠梗阻、麻痹性肠梗阻、不完全性肠梗阻、蛔虫/粪石性肠梗阻；方法包括基础治疗+生长抑素（减少胃肠分泌，奥曲肽0.1mg q8h）、灌肠（低位肠梗阻/粪石，生理盐水或肥皂水灌肠，怀疑绞窄或穿孔禁忌）、腹部按摩（肠扭转早期可尝试，需谨慎）；密切观察24-48小时，无效或出现绞窄征象转手术","手术治疗指征：绞窄性肠梗阻（急诊手术）、完全性肠梗阻保守治疗24-48小时无效、结肠梗阻（闭袢性，易穿孔，多需手术）、肿瘤性肠梗阻、先天性畸形、肠套叠/肠扭转复位失败、反复发作者","手术方式：粘连松解术（粘连性）、肠切除肠吻合术（绞窄坏死、肿瘤、炎性狭窄）、肠造瘘术（病情危重不能耐受根治手术，如结肠梗阻一期造瘘二期切除）、肠套叠复位术（手术或空气灌肠）、肠扭转复位术","腹腔镜手术：适用于粘连性肠梗阻（腹胀不严重、无绞窄），创伤小、再粘连少，但腹胀严重或绞窄性需开腹","肠扭转：乙状结肠扭转可试行结肠镜复位（无绞窄征象），失败或绞窄手术；小肠扭转需急诊手术","肠套叠（儿童）：空气灌肠复位（发病48小时内、一般情况好），失败或绞窄手术","术后处理：禁食胃肠减压至肠蠕动恢复、早期下床活动（促进肠蠕动，预防再粘连）、抗生素、营养支持","预防：腹部手术后早期活动预防粘连性肠梗阻，规律饮食避免暴饮暴食"],"drug_recommendations":[],"non_pharmacological":["保守治疗期间：半卧位，禁食水，保持胃管通畅（观察引流液量和性状），记录出入量","胃肠减压护理：固定胃管，保持负压吸引，观察引流液（血性液提示绞窄），口腔护理（防止感染和溃疡）","补液护理：监测生命体征、尿量、皮肤弹性，定期复查电解质，准确记录出入量","观察病情：每1-2小时评估腹痛性质（阵发性还是持续性）、腹胀、呕吐、排气排便、肠鸣音变化，出现绞窄征象立即报告医生准备手术","饮食：保守治疗期间禁食，梗阻解除（排气排便、腹胀腹痛消失、肠鸣音正常）后先流质（米汤、藕粉），逐渐半流质、普食，避免暴饮暴食和难消化食物","活动：保守治疗期间可床上活动，手术后早期下床活动（促进肠蠕动，预防肠粘连），避免剧烈运动","腹部按摩：单纯性粘连性肠梗阻可顺时针轻柔按摩，配合体位变化，促进梗阻解除，绞窄性禁忌","灌肠护理：低位肠梗阻灌肠时观察排出物，出现血性液或剧烈腹痛停止","心理支持：肠梗阻患者腹痛腹胀痛苦，需解释治疗方案和观察要点，减轻焦虑","预防复发：规律饮食，细嚼慢咽，避免暴饮暴食和不易消化食物（柿子、黑枣致粪石），腹部手术后早期活动，有腹痛及时就诊"],"complications":["肠绞窄和肠坏死：最严重并发症，梗阻致肠壁血运障碍，肠坏死穿孔，弥漫性腹膜炎、脓毒症、死亡，需早期识别急诊手术","水电解质酸碱失衡：高位肠梗阻呕吐致低钾低氯性碱中毒，低位肠梗阻致脱水和代谢性酸中毒，严重者休克和心律失常","感染和脓毒症：肠屏障功能障碍致细菌移位，绞窄性肠坏死致腹腔感染和脓毒症，需抗生素和手术","肠穿孔：绞窄性肠梗阻肠壁坏死穿孔，弥漫性腹膜炎，需急诊手术","短肠综合征：广泛小肠切除后（残留小肠小于100cm），营养吸收障碍，需长期肠外营养或肠康复","粘连性肠梗阻复发：腹部手术后粘连是最常见原因，反复发作，每次手术增加再粘连风险，需预防（早期活动、防粘连材料）","切口感染和切口疝：手术后并发症，肥胖和感染风险高","肠瘘：术后肠吻合口瘘，表现为腹痛、发热、肠内容物从引流口流出，需引流、营养支持，部分需手术","麻痹性肠梗阻：术后或腹腔感染致肠蠕动消失，腹胀明显，肠鸣音消失，保守治疗（胃肠减压、补液、纠正电解质、促进肠蠕动药物）","死亡：绞窄性肠梗阻延误诊治死亡率高，需高度警惕绞窄征象"],"monitoring":["诊断时：血常规、电解质、肾功能、乳酸、淀粉酶、凝血、立位腹平片、腹部CT（首选，明确部位原因和绞窄）、必要时腹腔穿刺（抽出血性液提示绞窄）","保守治疗期间：每1-2小时评估生命体征、腹痛、腹胀、呕吐、排气排便、肠鸣音；每4-6小时复查血常规、电解质；24-48小时复查CT评估","胃肠减压：记录引流液量和性状，血性液提示绞窄","手术前：备皮、配血、抗生素、纠正水电解质紊乱、签署手术同意书","术后：监测生命体征，观察腹痛、排气排便、引流液，复查血常规和电解质","出院前：评估排气排便、饮食恢复、切口愈合","术后1个月：门诊复查，评估消化功能，有肠切除者评估营养状况","出现剧烈持续腹痛、腹膜刺激征、休克、呕吐血性液、高热：立即就诊（绞窄性肠梗阻，急诊手术）","反复发作者：评估手术指征，腹腔镜粘连松解可考虑"],"special_populations":["儿童：肠套叠是最常见原因（2岁以下，阵发性哭闹、果酱样便、腹部包块），空气灌肠复位首选；嵌顿疝也常见，需及时手法复位或手术","老年人：肿瘤性肠梗阻多见（结直肠癌），症状不典型，易延误，需CT检查，手术需评估全身情况","孕妇：增大子宫压迫肠管，粘连性肠梗阻和肠扭转风险增加，诊断困难（X线辐射），用MRI或超声，手术需兼顾胎儿","腹部手术后患者：粘连性肠梗阻最常见，先保守治疗，无效或绞窄手术，避免轻易再手术（增加粘连）","肿瘤患者：结肠梗阻多为肿瘤所致，需手术（一期切除吻合或造瘘），恶性肿瘤晚期可支架置入（姑息）","疝嵌顿患者：腹股沟疝或切口疝嵌顿致肠梗阻，需紧急手法复位（无绞窄征象）或手术（绞窄或复位失败）","肠系膜血管疾病患者：血运性肠梗阻（房颤致肠系膜上动脉栓塞），剧烈腹痛与体征不符，需CTA确诊，急诊取栓或肠切除","炎症性肠病患者：克罗恩病致肠狭窄梗阻，保守治疗无效需手术，术后复发率高","长期便秘老年人：粪石性肠梗阻，灌肠或手法取出，避免手术"],"references":["中华医学会外科学分会. 肠梗阻诊治指南（2024）","WSES急性小肠梗阻诊疗指南","ESCP粘连性肠梗阻管理指南"]},{"name":"腹股沟疝诊治指南（2024）","category":"外科","scope":"成人腹股沟疝（斜疝、直疝、股疝）的诊断、手术方式和术后管理。","diagnosis":["临床表现：腹股沟区可复性包块（站立、咳嗽、用力时出现，平卧可回纳），局部坠胀感，可伴消化不良、便秘","斜疝：经腹股沟管突出，可进入阴囊，呈梨形，回纳后压住深环不再突出，嵌顿机会多","直疝：经直疝三角突出，不进入阴囊，呈半球形，基底宽，回纳后压住深环仍可突出，嵌顿少","股疝：经股管突出，位于腹股沟韧带下方卵圆窝处，女性多见，极易嵌顿（约60%）","嵌顿疝：包块突然增大、紧张发硬、明显疼痛、不能回纳，可伴肠梗阻表现（腹痛、呕吐、停止排气排便）","绞窄疝：嵌顿时间过长致肠管血运障碍，持续性剧烈腹痛、腹膜刺激征、发热、休克，肠管可坏死穿孔","体征：腹股沟区包块、咳嗽冲击感、透光试验阴性（与鞘膜积液鉴别）、肠鸣音（疝内容物为肠管时可闻及）","辅助检查：超声（首选，可明确疝内容物和疝囊颈）、CT（复杂疝、隐匿疝、鉴别诊断）","鉴别：睾丸鞘膜积液（透光阳性，不能回纳）、精索鞘膜积液、隐睾、腹股沟淋巴结肿大、脂肪瘤、精索静脉曲张、髂腰部寒性脓肿","危险因素：腹压增高（慢性咳嗽、便秘、前列腺增生排尿困难、腹水、妊娠、重体力劳动）、腹壁薄弱（老年人、肥胖、吸烟、胶原代谢异常、家族史）"],"staging":["按解剖类型：斜疝（最常见，经腹股沟管，可入阴囊）、直疝（经直疝三角，不入阴囊）、股疝（经股管，女性多，易嵌顿）","按复杂程度：可复性疝（平卧可回纳）、难复性疝（不能完全回纳，无血运障碍）、嵌顿疝（疝内容物被卡住不能回纳，伴肠梗阻）、绞窄疝（嵌顿伴血运障碍，肠坏死）","按疝环大小：小型（小于1.5cm）、中型（1.5-3cm）、大型（3-5cm）、巨大型（大于5cm）","按复发：初发疝、复发疝（手术后复发，手术难度增加）","特殊类型：滑动疝（盲肠、乙状结肠或膀胱成为疝囊壁一部分）、Richter疝（肠管壁部分嵌顿，可无肠梗阻表现，易漏诊）、Littre疝（嵌顿内容物为Meckel憩室）"],"key_points":["手术治疗是成人腹股沟疝的唯一根治方法","无张力疝修补术（主流）：使用人工补片加强腹股沟管后壁，复发率低（小于1-2%），包括李金斯坦（Lichtenstein，平片修补，最常用）、疝环充填式（Rutkow，网塞+平片）、PHS/UHS（双层修补）","腹腔镜疝修补术（TAPP经腹腔腹膜前、TEP完全腹膜外）：创伤小、恢复快、疼痛轻、可同时处理双侧疝和复发疝，需全麻和设备，费用较高","传统疝修补术（有张力）：Bassini、McVay、Halsted法，将自身组织缝合加强，复发率高（10-15%），术后疼痛重，现已少用，仅在感染或小儿使用","疝囊高位结扎术：适用于儿童（先天性斜疝，不需补片）","嵌顿疝处理：手法复位（嵌顿3-4小时内、无绞窄征象、年老体弱不能手术者，复位后观察24-48小时，择期手术）；急诊手术（嵌顿超过4小时、有绞窄征象、手法复位失败），术中判断肠管活力（色泽、蠕动、动脉搏动），坏死则肠切除吻合，活力可疑可热敷后观察或肠切除","股疝：确诊后应尽早手术（极易嵌顿），常用McVay法或补片修补","术后处理：平卧6小时，沙袋压迫切口6-8小时（止血），次日可下床活动，术后6小时可进流质，避免剧烈运动和重体力劳动3个月","围手术期：控制腹压增高因素（止咳、通便、排尿困难），戒烟，控制血糖，预防性抗生素（补片植入术前30分钟）","复发疝：手术难度大，首选腹腔镜修补（避免原入路粘连）或Lichtenstein"],"drug_recommendations":[],"non_pharmacological":["术前：戒烟（至少2周，减少术后肺部并发症和补片感染）、控制咳嗽便秘排尿困难、治疗前列腺增生、备皮、签署手术同意书","术后6小时：平卧，膝下垫软枕（松弛腹股沟），沙袋压迫切口","饮食：术后6小时可进流质，次日半流质或普食，多吃蔬菜水果保持大便通畅","活动：术后6-12小时可床上翻身，次日可下床活动（腹腔镜术后更早），避免久站久蹲，3个月内避免剧烈运动、重体力劳动、提重物（大于5kg）","切口护理：保持切口清洁干燥，腹腔镜切口1周拆线，开腹7天拆线，出现红肿渗液及时就诊","疼痛管理：术后切口疼痛可用非甾体抗炎药，慢性疼痛（神经损伤或补片刺激）需评估处理","预防复发：控制腹压增高（慢性咳嗽、便秘、前列腺增生），戒烟，控制体重，避免重体力劳动","性生活：术后2-4周可恢复（无不适），避免剧烈","定期复查：术后1个月、3个月复查，评估切口愈合和有无复发","自查：注意腹股沟区有无再次出现包块，出现包块、疼痛及时就诊"],"complications":["嵌顿和绞窄：最严重并发症，疝内容物（肠管）被卡住不能回纳，时间长致肠坏死穿孔，弥漫性腹膜炎、脓毒症、死亡，需急诊处理","术后出血：切口血肿或阴囊血肿（止血不彻底），小血肿可吸收，大血肿需引流","切口感染：补片感染是严重并发症（需取出补片），表现为切口红肿热痛渗液、发热，需抗生素，严重者取出补片","慢性疼痛：术后持续疼痛大于3个月（发生率约5-10%），多为神经损伤（髂腹股沟神经、生殖股神经）或补片刺激，需保守治疗（镇痛、神经阻滞），严重者手术探查神经松解或补片取出","疝复发：无张力修补复发率1-2%，传统修补10-15%，复发原因包括腹压增高未控制、补片移位、手术技术，需再次手术","睾丸萎缩：术中损伤精索血管（罕见），术后睾丸疼痛缩小","阴囊血肿和水肿：斜疝术后常见，抬高阴囊，多可自行吸收","肠管损伤：滑动疝或嵌顿疝手术中误伤肠管，需修补","膀胱损伤：滑动疝（膀胱为疝囊壁）或直疝手术中误伤，术中发现立即修补，术后留置尿管","补片相关并发症：补片移位、挛缩、侵蚀（罕见，侵蚀肠管或膀胱需手术）"],"monitoring":["诊断时：体格检查（站立位咳嗽试验）、超声（明确疝类型和内容物）、必要时CT（隐匿疝、复杂疝、鉴别）","术前：血常规、凝血、肝肾功能、心电图、胸片（老年或心肺疾病）、血糖、前列腺评估（老年男性）","术后：观察切口出血、阴囊血肿、体温、排尿情况","术后1个月：门诊复查，评估切口愈合、疼痛、活动恢复，有无复发","术后3个月：复查，评估能否恢复正常活动和体力劳动","术后6个月-1年：评估远期复发和慢性疼痛","嵌顿疝急诊：快速评估有无绞窄（腹痛性质、腹膜刺激征、心率、白细胞、乳酸），决定手法复位还是急诊手术","术后出现腹股沟区包块、持续疼痛、切口红肿渗液、睾丸肿痛：及时就诊（复发、感染、血肿等）"],"special_populations":["儿童：先天性斜疝多见，1岁以上不愈需手术（疝囊高位结扎，不需补片），嵌顿发生率高，需及时处理","老年人：腹壁肌肉萎缩，腹压增高因素多（前列腺增生、慢性支气管炎、便秘），双侧疝多见，手术需评估全身情况，局麻下Lichtenstein适合高龄高危患者","孕妇：孕期腹压增高可诱发或加重疝，孕期不建议择期手术，嵌顿需紧急处理，产后3-6个月手术","肥胖患者：复发率和切口感染率高，腹腔镜或Lichtenstein均可，控制体重","肝硬化腹水患者：腹水增加腹压，疝修补复发率高，需先控制腹水，手术需谨慎","吸烟患者：影响胶原代谢和切口愈合，增加补片感染风险，术前必须戒烟（至少2周）","糖尿病患者：切口感染和补片感染风险高，术前控制血糖（小于8.3mmol/L），加强抗感染","凝血功能障碍/服用抗凝药：术后血肿风险高，术前评估是否停药或桥接","复发疝：原入路粘连重，首选腹腔镜TEP/TAPP（腹膜前间隙，避开原瘢痕），或Lichtenstein","巨大疝：组织缺损大，需用大补片或组织结构分离技术，术后复发率较高"],"references":["中华医学会外科学分会. 腹股沟疝诊治指南（2024）","2023 EHS腹股沟疝管理指南","NCCN腹股沟疝临床实践指南"]},{"name":"下肢静脉曲张诊治指南（2024）","category":"外科","scope":"成人下肢浅静脉曲张的诊断、分级、微创治疗和手术治疗。","diagnosis":["临床表现：下肢浅静脉迂曲扩张（蚯蚓状），久站后下肢沉重、酸胀、水肿，踝部皮肤色素沉着、湿疹、溃疡（老烂腿）","体征：浅静脉迂曲扩张、踝部水肿、皮肤营养障碍（色素沉着、脱屑、湿疹、脂质硬皮病、溃疡）、血栓性浅静脉炎（局部红肿痛条索）","辅助检查：下肢静脉超声（首选，明确深静脉通畅、瓣膜功能、反流部位和时间）、静脉造影（有创，少用）、光电容积描记（PPG）、空气容积描记（APG）","CEAP分级：C0（无可见体征）、C1（毛细血管扩张/网状静脉）、C2（静脉曲张）、C3（水肿）、C4a（色素沉着/湿疹）、C4b（脂质硬皮病/白色萎缩）、C5（愈合溃疡）、C6（活动性溃疡）","鉴别：原发性深静脉瓣膜功能不全、深静脉血栓后综合征、动静脉瘘、Klippel-Trenaunay综合征、生理性静脉曲张（孕妇、久站职业）","危险因素：久站久坐职业（教师、护士、售货员）、遗传（静脉壁薄弱、瓣膜缺陷）、肥胖、妊娠、年龄增长、便秘、重体力劳动","并发症：血栓性浅静脉炎、曲张静脉破裂出血、小腿溃疡（静脉性溃疡）、深静脉血栓（罕见）"],"staging":["按CEAP临床分级：C0-C6（见诊断）","按病因：原发性（最常见，浅静脉瓣膜功能不全）、继发性（深静脉血栓后综合征、外伤）、先天性（KTS等）","按解剖：大隐静脉曲张（最常见，内侧）、小隐静脉曲张（后侧）、穿通静脉功能不全","按严重程度：轻度（C1-C2，仅影响美观）、中度（C3-C4，有症状和皮肤改变）、重度（C5-C6，溃疡）","按血流动力学：单纯浅静脉反流、浅静脉反流合并穿通静脉功能不全、合并深静脉瓣膜功能不全"],"key_points":["保守治疗（适用于C1-C2轻度、妊娠期、不能耐受手术者）：医用弹力袜（梯度压力袜，晨起穿睡前脱，II级压力20-30mmHg）、避免久站久坐、间歇抬高患肢、药物（迈之灵、地奥司明、草木犀流浸液片，改善静脉张力减轻水肿）、硬化剂注射（毛细血管扩张和小静脉曲张，聚多卡醇泡沫硬化剂）","微创治疗（主流）：腔内热消融（激光EVLT、射频RFA，闭合病变大隐静脉，创伤小恢复快，局麻可做）、泡沫硬化剂注射（联合或单独，适合小静脉和残留静脉）、机械化学消融（Clarivein，无热损伤）","手术治疗：大隐静脉高位结扎+剥脱术（传统，创伤较大，现已少用，适合粗大曲张或合并血栓）、点式抽剥术（微小切口切除曲张静脉团）、腔镜下穿通静脉离断术（SEPS，治疗穿通静脉功能不全）","穿通静脉功能不全：超声引导下硬化、腔内热消融或SEPS手术","静脉性溃疡：加压治疗（弹力袜或绷带）+清创换药+改善静脉回流（手术处理反流），难愈性溃疡可用皮肤移植","血栓性浅静脉炎：抗凝（低分子肝素）、抗炎、局部热敷，蔓延至深静脉入口处需手术或抗凝","破裂出血：立即抬高患肢、加压包扎，必要时缝扎止血","术后处理：弹力袜加压1-3个月，早期下床活动，避免久站，定期复查超声","预防：久站久坐者定时活动脚踝（促进肌泵），穿医用弹力袜，控制体重，避免便秘"],"drug_recommendations":[],"non_pharmacological":["生活方式：避免久站久坐，每1小时活动下肢（踮脚、走动、踝泵运动），休息时抬高患肢（高于心脏），促进静脉回流","医用弹力袜：正确穿戴（晨起平卧时穿，睡前脱），选择合适尺寸和压力，注意皮肤护理，破损及时更换，夏季可选用薄款","饮食：清淡饮食，多吃蔬菜水果保持大便通畅（避免便秘增加腹压），控制体重，戒烟","运动：适度有氧运动（快走、游泳、骑行），避免剧烈运动和重体力劳动，加强小腿肌肉锻炼（肌泵作用）","皮肤护理：有皮肤色素沉着和湿疹时保持皮肤清洁，避免搔抓（防破溃感染），使用润肤剂，溃疡处定期换药","孕期管理：孕期穿医用弹力袜，避免久站，产后多数可缓解，持续不愈产后手术","术后护理：术后立即穿弹力袜，早期下床活动（预防深静脉血栓），1周内避免剧烈运动，1个月内避免重体力劳动","定期自查：观察曲张静脉变化，出现红肿痛（血栓性静脉炎）、破溃、出血及时就诊","避免高温：避免用热水长时间泡脚（扩张静脉加重淤血），避免桑拿","职业防护：久站职业工作时穿弹力袜，定时休息活动下肢"],"complications":["血栓性浅静脉炎：曲张静脉内血栓形成，局部红肿痛、可触及条索，有蔓延至深静脉风险，需抗凝和抗炎，必要时手术","曲张静脉破裂出血：静脉壁薄弱、内压高，轻微外伤即可破裂，出血量大不易自止，需立即抬高患肢加压包扎，必要时缝扎","静脉性溃疡（老烂腿）：长期静脉高压致皮肤营养障碍，踝部溃疡，经久不愈，反复发作，需加压+改善静脉回流+创面处理","深静脉血栓：术后或长期卧床可发生，表现为下肢肿胀疼痛，需抗凝治疗，早期活动预防","肺栓塞：深静脉血栓脱落致肺栓塞，罕见但严重，术后早期活动预防","术后并发症：皮下血肿、瘀斑、皮肤感觉异常（隐神经损伤，小腿内侧麻木）、静脉炎、色素沉着、复发（约5-10%）、烧伤（激光热损伤）","硬化剂并发症：过敏、皮肤坏死、色素沉着、深静脉血栓（罕见）、肺栓塞（罕见）","溃疡感染：静脉性溃疡合并细菌感染，红肿渗液，需清创和抗生素","肢体肿胀：术后早期常见，弹力袜加压和抬高患肢可缓解","慢性静脉功能不全进展：不治疗可从C2进展至C6溃疡，早期干预可预防"],"monitoring":["诊断时：下肢静脉超声（深静脉通畅性、大隐/小隐静脉瓣膜功能、反流时间大于0.5秒、穿通静脉功能）、必要时静脉造影","术前：血常规、凝血、传染病筛查、下肢静脉超声（标记病变静脉走行）、心电图（老年或心肺疾病）","术后：观察切口/穿刺点出血、下肢肿胀、皮肤感觉、足背动脉搏动","术后1周：复查，评估恢复情况，调整弹力袜使用","术后1个月：复查静脉超声（评估闭合效果和深静脉通畅），评估症状改善","术后3-6个月：复查超声，评估有无复发和残留静脉","保守治疗期间：每6-12个月评估症状和CEAP分级进展","静脉性溃疡：定期创面评估（大小、渗出、感染），调整换药和治疗方案","出现下肢突然肿胀疼痛、胸闷气短（深静脉血栓/肺栓塞）、曲张静脉破裂出血、溃疡不愈或扩大：及时就诊"],"special_populations":["孕妇：孕期静脉曲张常见（子宫压迫髂静脉、激素使静脉壁松弛），以保守治疗为主（弹力袜、抬高患肢），避免手术和硬化剂，产后3-6个月评估是否需要手术","老年人：多合并深静脉瓣膜功能不全和动脉硬化，手术需评估全身情况，微创治疗（激光/射频）创伤小适合高龄","肥胖患者：静脉曲张发生率高，术后复发率较高，需同时控制体重，选择合适尺寸弹力袜","深静脉血栓后综合征：深静脉血栓后静脉瓣膜破坏，浅静脉代偿性曲张，手术需谨慎（深静脉回流不畅时剥脱浅静脉可加重肿胀），以保守和加压为主","合并动脉疾病：需评估踝肱指数（ABI），严重下肢动脉缺血（ABI小于0.5）禁用高压弹力袜","长期站立职业者：预防为主，工作时穿弹力袜，定时活动，早期干预","糖尿病患者：皮肤愈合差，溃疡不易愈合，需控制血糖，加强创面护理","服用抗凝药者：术后血肿风险高，术前评估是否调整抗凝","复发患者：再次手术难度大，需详细超声评估，选择合适方案（再次消融或手术）","活动期溃疡患者：先处理溃疡（加压+换药），感染控制后再手术处理静脉反流"],"references":["中华医学会外科学分会. 下肢静脉曲张诊治指南（2024）","2023 ESVS慢性静脉疾病管理指南","AVF下肢静脉曲张治疗指南"]},{"name":"乳腺结节诊治指南（2024）","category":"外科","scope":"成人乳腺结节的评估、良恶性鉴别、随访和治疗。","diagnosis":["临床表现：乳房肿块（可触及或体检发现）、乳房疼痛（周期性与月经相关，多为良性）、乳头溢液（血性溢液需警惕导管内乳头状瘤或癌）、乳头内陷、皮肤改变（橘皮样、酒窝征提示恶性）","体征：乳房触诊（肿块大小、质地、边界、活动度、压痛、与皮肤/胸肌粘连）、腋窝淋巴结（肿大、质硬、固定提示转移）","影像学：乳腺超声（首选，BI-RADS分级，适合年轻女性和致密乳腺）、乳腺X线钼靶（40岁以上筛查，钙化灶敏感）、乳腺MRI（高危人群、术前评估、鉴别困难）","实验室：肿瘤标志物（CA15-3、CEA，辅助参考，不能单独诊断）","病理：空心针穿刺活检（CNB，术前确诊金标准）、麦默通微创旋切活检（同时可切除小结节）、手术切除活检","BI-RADS分级：0类（需进一步检查）、1类（阴性）、2类（良性）、3类（可能良性，恶性率小于2%，短期随访）、4类（可疑恶性，4A 2-10%、4B 10-50%、4C 50-95%，需活检）、5类（高度怀疑恶性，大于95%）、6类（活检证实恶性）","鉴别：乳腺增生（周期性胀痛，多发结节质软）、乳腺纤维腺瘤（年轻女性，光滑活动质韧）、乳腺囊肿（超声无回声，可随月经变化）、导管内乳头状瘤（乳头溢液）、乳腺炎（红肿热痛）、乳腺癌（无痛性肿块，质硬固定，腋窝淋巴结肿大）","乳腺癌高危因素：月经初潮早、绝经晚、未生育或晚育、未哺乳、乳腺癌家族史（BRCA突变）、乳腺不典型增生、胸部放疗史、肥胖、饮酒"],"staging":["按BI-RADS分级：1-2类（良性，常规随访）、3类（可能良性，6个月随访）、4类（可疑恶性，穿刺活检）、5类（高度恶性，穿刺+手术）、6类（确诊恶性，治疗）","按病理类型：良性（纤维腺瘤、增生结节、囊肿、导管内乳头状瘤、脂肪瘤、错构瘤）、恶性（浸润性导管癌最常见、浸润性小叶癌、导管原位癌、髓样癌、黏液癌）","按大小：微小结节（小于5mm）、小结节（5-10mm）、中结节（10-20mm）、大结节（大于20mm）","按数量：单发结节、多发结节","按乳腺癌分期：0期（原位癌）、I期（肿瘤小于2cm无转移）、II期（2-5cm或腋窝淋巴结转移）、III期（局部晚期）、IV期（远处转移）"],"key_points":["良性结节（BI-RADS 2-3类）：定期随访（每6-12个月超声），不需特殊治疗；有疼痛症状可用中药（逍遥丸、乳癖消）或他莫昔芬（严重疼痛短期）；较大结节（大于2cm）或生长迅速可手术切除","乳腺囊肿：单纯囊肿不需处理，较大囊肿可穿刺抽液，反复复发可手术切除","纤维腺瘤：年轻女性、小于2cm、生长缓慢可随访；大于2cm、生长迅速、备孕前、心理负担大可手术切除（麦默通微创旋切或开放手术）","可疑恶性结节（BI-RADS 4-5类）：空心针穿刺活检明确病理，恶性者按乳腺癌治疗","乳腺癌治疗：手术（乳腺癌根治术、改良根治术、保乳手术+放疗）+化疗（蒽环类+紫杉类方案）+放疗（保乳术后或淋巴结转移）+内分泌治疗（ER/PR阳性者，他莫昔芬或芳香化酶抑制剂5-10年）+靶向治疗（HER2阳性者，曲妥珠单抗）","术前新辅助治疗：局部晚期乳腺癌先化疗/靶向/内分泌治疗缩小肿瘤后手术","术后辅助治疗：根据病理分期和分子分型（Luminal A/B、HER2过表达、三阴性）选择化疗、放疗、内分泌、靶向","随访：良性结节每6-12个月超声；乳腺癌术后每3-6个月复查（体检、超声、钼靶、肿瘤标志物、胸片/CT），5年后每年","乳腺增生：调整生活方式，避免含雌激素食物和药物，定期复查，不典型增生需密切随访或手术","预防：高危人群（BRCA突变、家族史）加强筛查，可考虑预防性切除或他莫昔芬化学预防"],"drug_recommendations":[],"non_pharmacological":["乳房自查：每月月经后7-10天自查（看外形、触摸肿块、挤压乳头有无溢液），发现异常及时就诊","定期体检：20-39岁每3年临床检查，40岁以上每年超声+钼靶（高危人群提前）","饮食：低脂高纤维饮食，多吃蔬菜水果，避免含雌激素的保健品（蜂王浆、雪蛤、避孕药滥用），限制酒精（酒精增加乳腺癌风险）","生活方式：规律作息，避免熬夜，适度运动，控制体重，戒烟限酒","内衣：选择合适尺码，避免过紧钢圈内衣，睡觉时不穿内衣","情绪管理：保持心情舒畅，避免长期焦虑抑郁（内分泌紊乱加重乳腺增生）","避免不必要的雌激素暴露：不滥用含雌激素化妆品和保健品，更年期激素替代需评估乳腺风险","术后护理：保持切口清洁干燥，术后早期进行上肢功能锻炼（爬墙运动，预防瘢痕粘连和上肢水肿），避免患侧上肢提重物和测血压输液","放疗护理：放疗期间保持皮肤清洁干燥，避免摩擦和暴晒，穿宽松棉质衣物，皮肤反应对症处理","化疗护理：注意口腔卫生，预防感染，加强营养，监测血常规（骨髓抑制），脱发可准备假发"],"complications":["乳腺癌：约10-15%乳腺结节为恶性，早期发现5年生存率大于90%，晚期预后差，需规范筛查和及时活检","术后并发症：出血、血肿、血清肿、切口感染、皮瓣坏死（根治术）、上肢水肿（腋窝淋巴结清扫后，淋巴回流障碍）、上肢功能障碍、疼痛","化疗不良反应：骨髓抑制（白细胞/血小板减少）、恶心呕吐、脱发、肝肾功能损害、心脏毒性（蒽环类）、神经毒性（紫杉类）","放疗不良反应：放射性皮炎（红斑、脱屑、溃疡）、放射性肺炎、乳房纤维化、上肢水肿","内分泌治疗不良反应：他莫昔芬致潮热、子宫内膜增厚、血栓、子宫内膜癌风险（需定期妇科超声）；芳香化酶抑制剂致骨质疏松、关节痛、潮热","靶向治疗不良反应：曲妥珠单抗心脏毒性（监测心功能）、过敏反应","良性结节恶变：不典型增生和导管内乳头状瘤有恶变风险，需密切随访或手术","囊肿感染：乳腺囊肿合并感染，红肿热痛，需抗感染和穿刺引流","乳头溢液：血性溢液需警惕导管内乳头状瘤或癌，需乳管镜检查和手术","心理负担：乳腺结节患者焦虑恐惧（担心乳腺癌），需科普和心理疏导，避免过度检查"],"monitoring":["诊断时：乳腺超声（BI-RADS分级）、必要时钼靶（40岁以上或高危）、MRI（高危或鉴别困难）、肿瘤标志物（CA15-3、CEA）、可疑结节穿刺活检（CNB或麦默通）","随访：BI-RADS 3类每6个月超声复查，2类每年复查，观察大小形态变化，升级则穿刺","术前：血常规、凝血、传染病筛查、心电图、胸片，恶性者加查胸部CT、腹部超声、骨扫描（分期）","术后：观察切口出血、感染、皮瓣血运、上肢水肿和活动","乳腺癌术后：每3-6个月复查（体检、乳腺超声、钼靶、CA15-3/CEA、胸片/CT、腹部超声），每年骨密度（内分泌治疗者）","化疗期间：每周期前查血常规、肝肾功能，化疗后监测骨髓抑制，出现发热立即查血常规","内分泌治疗：他莫昔芬每年妇科超声（子宫内膜）；芳香化酶抑制剂每1-2年骨密度","出现结节迅速增大、质地变硬固定、乳头血性溢液、皮肤橘皮样改变、腋窝淋巴结肿大：及时就诊（怀疑恶性）"],"special_populations":["年轻女性（小于40岁）：乳腺致密，超声首选，纤维腺瘤多见，恶性率低，避免过度钼靶辐射，BI-RADS 3类可随访","孕妇哺乳期：孕期乳腺增生结节增大，哺乳期积乳囊肿和乳腺炎常见，避免钼靶辐射，用超声，哺乳期乳腺癌易误诊为乳腺炎需警惕","绝经后女性：乳腺萎缩，结节恶性风险增加，钼靶敏感，发现结节需积极评估","男性乳腺结节：男性乳腺癌少见（约1%），但恶性程度高，男性乳房发育需与肿瘤鉴别，发现硬结及时就诊","有乳腺癌家族史/BRCA突变者：高危人群，筛查提前（25-30岁），每年MRI+钼靶，可考虑预防性切除或他莫昔芬预防","乳腺致密型女性：钼靶敏感性低，需联合超声或MRI","假体植入者：结节评估需注意假体影响，超声和MRI更准确","服用激素替代治疗者：增加乳腺癌风险，需定期乳腺检查，评估获益风险","既往乳腺不典型增生者：恶变风险增加，需密切随访（每6个月），可考虑他莫昔芬预防","哺乳期乳腺炎：红肿热痛伴发热，需与乳腺癌鉴别，抗感染+排空乳汁，无效或肿块持续需穿刺排除炎性乳癌"],"references":["中华医学会外科学分会. 乳腺结节诊治指南（2024）","2023 NCCN乳腺癌筛查和诊断指南","中国抗癌协会乳腺癌诊治指南"]},{"name":"原发性醛固酮增多症诊治指南（2024）","category":"内分泌科","scope":"成人原发性醛固酮增多症（原醛症）的筛查、确诊、分型和治疗。","diagnosis":["临床表现：高血压（最常见，可呈难治性高血压，三种降压药仍不达标）、低血钾（乏力、肌无力、周期性麻痹、多尿夜尿增多，约30-60%患者血钾正常）、碱中毒（手足搐搦）、心律失常（低钾致早搏、室速）","筛查对象：持续性血压大于150/100mmHg、难治性高血压（3种药含利尿剂仍不达标）、高血压合并自发性或利尿剂诱导的低血钾、高血压合并肾上腺意外瘤、早发高血压（小于40岁）或脑血管意外家族史、原醛症患者一级亲属","筛查试验：血浆醛固酮/肾素活性比值（ARR，首选筛查），ARR大于30且醛固酮大于550pmol/L（20ng/dl）提示阳性","确诊试验：生理盐水负荷试验（静滴2000ml生理盐水4小时，醛固酮大于277pmol/L确诊）、卡托普利试验、口服高钠试验、氟氢可的松抑制试验","分型：肾上腺CT（腺瘤/增生/癌）、肾上腺静脉取血（AVS，分型金标准，区分单侧腺瘤和双侧增生）、基因检测（家族性原醛）","鉴别：原发性高血压、继发性醛固酮增多（肾动脉狭窄、肾素瘤、心衰、肝硬化）、库欣综合征、先天性肾上腺增生、药物（利尿剂、ACEI/ARB影响ARR）","并发症：左心室肥厚、心力衰竭、脑卒中、肾功能损害、心律失常（低钾致恶性心律失常）"],"staging":["按病因：醛固酮瘤（APA，约35%，单侧腺瘤，手术可治愈）、特发性醛固酮增多症（IHA，约60%，双侧肾上腺增生，药物治疗）、原发性肾上腺增生（UNAH，约2%，单侧增生，手术有效）、肾上腺皮质癌（小于1%，分泌醛固酮的癌，预后差）、家族性原醛（GRA等，糖皮质激素可治疗）、异位醛固酮分泌瘤（罕见）","按血钾：低钾型、正常血钾型（约30-60%原醛血钾正常，不能因血钾正常排除）","按严重程度：轻度（血压轻中度升高，无低钾）、中度（血压明显升高，间断低钾）、重度（难治性高血压，持续低钾，靶器官损害）","按手术可行性：手术可治愈型（单侧腺瘤/增生）、药物治疗型（双侧增生、不能手术）"],"key_points":["手术治疗：单侧醛固酮瘤或单侧增生首选腹腔镜肾上腺切除术（微创，治愈率高，术后血压改善率约70-90%）","药物治疗：特发性醛固酮增多症、不能手术或不愿手术者","盐皮质激素受体拮抗剂（MRA，一线）：螺内酯25-400mg/d（起始12.5-25mg qd，逐渐加量，注意高钾和男性乳房发育）、依普利酮（选择性MRA，50-200mg/d，副作用少，无抗雄激素作用，首选）","其他降压药：氨苯蝶啶、阿米洛利（保钾利尿剂，辅助）、钙通道阻滞剂（硝苯地平，部分有效）、ACEI/ARB（对IHA部分有效）、糖皮质激素（GRA型，地塞米松0.5-1mg qn抑制ACTH）","术前准备：螺内酯或依普利酮纠正低血钾和高血压（至少2-4周），补钾，控制血压","术后处理：监测血压和血钾，术后可能出现暂时性低醛固酮（对侧肾上腺抑制），需短期用氟氢可的松，逐渐减停降压药","随访：术后1个月、3个月、6个月复查血压、血钾、醛固酮、肾素、肌酐","难治性高血压：联合多种降压药（MRA+CCB+ACEI/ARB+利尿剂），目标血压小于130/80mmHg","低血钾处理：口服或静脉补钾（严重低钾静脉补钾，监测心电图），同时用MRA减少钾丢失","肾上腺皮质癌：手术切除+米托坦+化疗，预后差"],"drug_recommendations":[],"non_pharmacological":["饮食：低钠饮食（小于5g/d，减少水钠潴留和血压），避免高盐食物（腌制品、加工肉），适当增加钾摄入（新鲜蔬菜水果，肾功能正常者）","休息与活动：血压高和低钾时注意休息，避免剧烈运动和劳累（防肌无力跌倒），血压控制后适度运动","监测血压：家庭自测血压，记录血压变化，调整降压药，目标小于130/80mmHg","监测血钾：定期复查血钾，出现乏力、肌无力、心悸及时查血钾，避免低钾致心律失常","用药依从性：MRA需长期服用（IHA），不可自行停药，定期复查血钾和肾功能调整剂量","避免使用致低钾药物：利尿剂（噻嗪类、袢利尿剂）、甘草制剂（假性醛固酮增多），如必须用需监测血钾","术前准备：术前用螺内酯纠正低钾和高血压2-4周，补钾至正常，血压控制良好","术后护理：腹腔镜术后早期活动，监测血压和血钾，注意有无肾上腺皮质功能不全（乏力、低血压、低钠）","定期复查：按医嘱定期查血压、血钾、醛固酮、肾素、肌酐、心电图，评估疗效和调整方案","心理支持：继发性高血压病因明确，患者易焦虑，解释治疗方案和预后，增强依从性"],"complications":["低钾性心律失常：严重低钾（小于2.5mmol/L）致室性早搏、室速甚至室颤，需紧急补钾和心电监护","周期性麻痹：低钾致四肢无力，严重者呼吸肌麻痹，需急诊补钾","高血压靶器官损害：长期高血压致左心室肥厚、冠心病、心衰、脑卒中、慢性肾病，原醛的心脑血管风险高于原发性高血压（同等血压水平）","肾功能损害：醛固酮过多致肾小球硬化和蛋白尿，可进展为慢性肾病","术后肾上腺皮质功能不全：单侧腺瘤术后对侧肾上腺长期被抑制，出现低钠、高钾、低血压、乏力，需短期糖皮质激素替代","螺内酯不良反应：高钾血症（最需监测）、男性乳房发育、阳痿、女性月经紊乱、胃肠道反应，依普利酮副作用少但价格高","手术并发症：腹腔镜肾上腺切除出血、感染、周围脏器损伤（胰腺、脾脏），罕见","肾上腺皮质癌：分泌醛固酮的肾上腺癌预后差，5年生存率小于30%，需根治手术和辅助治疗","耐药性高血压：部分患者多种药物仍难控制，需排查依从性、继发因素、药物相互作用","妊娠：原醛合并妊娠风险高（先兆子痫、胎儿生长受限），MRA孕期禁用（致畸），用甲基多巴或拉贝洛尔控制血压"],"monitoring":["筛查：ARR（醛固酮/肾素比值），筛查前停利尿剂4周、ACEI/ARB 2周（如不能停需解释结果），血钾纠正至正常","确诊：生理盐水负荷试验（金标准之一）、卡托普利试验、氟氢可的松抑制试验，至少一项确诊","分型：肾上腺CT（发现腺瘤/增生）、肾上腺静脉取血（AVS，区分单侧/双侧，CT正常也需AVS，因为CT可能漏诊小腺瘤或误判）","术前：血压、血钾、肾功能、心电图、肾上腺CT/AVS结果、凝血、传染病筛查","术后：监测血压、血钾、血钠、肌酐、醛固酮/肾素，评估手术效果","药物治疗期间：每2-4周查血压、血钾、肌酐，调整MRA剂量，稳定后每3-6个月复查","术后随访：1个月、3个月、6个月、1年复查血压、血钾、醛固酮、肾素、肌酐，评估是否治愈（血压正常不需降压药、血钾正常、ARR正常）","出现肌无力、心悸、多尿、血压突然升高：及时查血钾和心电图（低钾危象）"],"special_populations":["孕妇：原醛合并妊娠少见但风险高，MRA（螺内酯、依普利酮）有致畸作用禁用，用甲基多巴、拉贝洛尔、硝苯地平控制血压，必要时孕中期手术，产后重新评估","儿童：原醛少见，多为家族性或肾上腺肿瘤，需基因检测，治疗方案同成人但剂量按体重","老年人：多合并动脉硬化和心脑血管病，血压目标个体化，MRA注意高钾和肾功能，依普利酮耐受性好","肾功能不全：MRA易致高钾血症，eGFR小于30慎用或减量，密切监测血钾和肌酐，必要时透析","糖尿病患者：原醛增加糖尿病风险（低钾影响胰岛素分泌），需同时控制血糖，MRA不影响血糖","服用ACEI/ARB者：可降低ARR致假阴性，筛查前需停药2周（如安全），不停药需结合醛固酮绝对值判断","肾上腺意外瘤患者：约5-10%意外瘤为原醛，所有肾上腺意外瘤均应筛查ARR","难治性高血压患者：原醛在难治性高血压中约占20%，均应筛查","低钾患者：所有自发性低钾或利尿剂诱导低钾的高血压患者均应筛查原醛","一级亲属有原醛者：遗传倾向，需筛查"],"references":["中华医学会内分泌学分会. 原发性醛固酮增多症诊治指南（2024）","2023 ESE原发性醛固酮增多症指南","ACC原醛症管理共识"]},{"name":"库欣综合征诊治指南（2024）","category":"内分泌科","scope":"成人库欣综合征（皮质醇增多症）的病因诊断、定位诊断和治疗。","diagnosis":["临床表现：向心性肥胖（满月脸、水牛背、锁骨上脂肪垫、四肢纤细）、皮肤改变（紫纹宽大于1cm、皮肤变薄、瘀斑、痤疮、多毛）、肌肉骨骼（肌无力、肌萎缩、骨质疏松、病理性骨折）、心血管（高血压、左心室肥厚、易血栓）、代谢（糖耐量异常/糖尿病、低钾性碱中毒、血脂异常）、精神症状（情绪不稳、焦虑、抑郁、失眠、严重者精神病）、免疫抑制（易感染、伤口愈合差）、性功能异常（女性月经紊乱/闭经、男性阳痿）、儿童生长迟缓","筛查对象：有典型临床表现（尤其向心性肥胖+紫纹+肌无力）、年轻患者骨质疏松/高血压/糖尿病、肾上腺意外瘤、垂体意外瘤、分泌ACTH的肿瘤","筛查试验：24小时尿游离皮质醇（UFC，至少2次）、午夜唾液皮质醇（至少2次）、过夜1mg地塞米松抑制试验（DST，皮质醇大于50nmol/L不抑制）","确诊：至少两项筛查试验异常，进一步行小剂量地塞米松抑制试验（LDDST，2mg/d×48小时，不抑制确诊）","病因鉴别：血浆ACTH水平（ACTH依赖性：ACTH正常/升高，垂体瘤或异位ACTH；ACTH非依赖性：ACTH降低，肾上腺腺瘤/癌/增生）、大剂量地塞米松抑制试验（HDDST，垂体瘤可被抑制，异位ACTH不抑制）、CRH兴奋试验","定位：垂体MRI（库欣病，微腺瘤多见）、肾上腺CT（肾上腺腺瘤/癌/增生）、岩下窦取血（BIPSS，鉴别垂体和异位ACTH，金标准）、全身影像学（异位ACTH肿瘤：肺类癌、胸腺肿瘤、胰腺肿瘤）","鉴别：假性库欣（肥胖、酗酒、抑郁症、妊娠，皮质醇轻度升高但无典型表现，LDDST可鉴别）","并发症：感染、心血管事件、骨折、糖尿病、精神障碍、血栓"],"staging":["按病因：ACTH依赖性（库欣病，垂体ACTH腺瘤，约70%；异位ACTH综合征，约15%，肺癌/胸腺类癌等）、ACTH非依赖性（肾上腺腺瘤，约10%；肾上腺皮质癌，约5%；双侧肾上腺增生，少见）","按严重程度：轻型（症状轻，皮质醇轻度升高）、典型（向心性肥胖+多系统受累）、重型（严重肌无力、低血钾、感染、精神症状）、周期性库欣（皮质醇周期性升高，诊断困难）","按肿瘤良恶性：良性（垂体微腺瘤、肾上腺腺瘤）、恶性（肾上腺皮质癌、异位ACTH的小细胞肺癌）","按部位：垂体性、肾上腺性、异位性","特殊类型：亚临床库欣（肾上腺意外瘤，皮质醇轻度升高无典型表现）、食源性库欣（外源性糖皮质激素）"],"key_points":["病因治疗是根本","库欣病（垂体ACTH瘤）：经鼻蝶垂体瘤切除术（首选，治愈率约70-80%）；术后未愈或复发可行垂体放疗、双侧肾上腺切除（难治性）、药物治疗（酮康唑、美替拉酮、米托坦、帕瑞肽）","肾上腺腺瘤：腹腔镜肾上腺切除术（首选，治愈率高，术后需糖皮质激素替代至下丘脑-垂体-肾上腺轴恢复，约6-12个月）","肾上腺皮质癌：根治性手术切除+米托坦辅助治疗，预后差（5年生存率约30-50%）","异位ACTH综合征：手术切除原发肿瘤（良性类癌可治愈）；不能切除者用肾上腺阻断药（酮康唑、美替拉酮、氨鲁米特）或双侧肾上腺切除","药物治疗：肾上腺阻断药（酮康唑400-1200mg/d，注意肝毒性；美替拉酮500-4000mg/d；米托坦用于肾上腺癌）、糖皮质激素受体拮抗剂（米非司酮，用于高血糖和高血压）、生长抑素类似物（帕瑞肽，用于库欣病）","围手术期：肾上腺腺瘤术后需糖皮质激素替代（氢化可的松20-30mg/d，逐渐减量），监测皮质醇和ACTH评估HPA轴恢复","对症治疗：控制血压（ACEI/ARB+CCB）、血糖（二甲双胍/胰岛素）、补钾、抗骨质疏松（双膦酸盐）、预防感染","术后随访：定期查皮质醇、ACTH、UFC，评估治愈和复发，库欣病复发率约15-20%","健康教育：解释长期高皮质醇的危害和治疗周期，术后激素替代不可自行停药"],"drug_recommendations":[],"non_pharmacological":["饮食：高蛋白、高维生素、低热量、低盐饮食，纠正负氮平衡，控制血糖血压，补充钾（新鲜蔬菜水果）","休息与活动：肌无力和骨质疏松时注意休息，避免剧烈活动和外伤（防骨折），病情稳定后适度运动","皮肤护理：皮肤薄易瘀斑和破损，避免摩擦和外伤，保持皮肤清洁，预防感染","预防感染：免疫力低下，注意保暖，避免去人群密集场所，出现发热及时就诊（感染可较重）","心理支持：情绪不稳、抑郁、焦虑常见，需心理疏导，严重精神症状需精神科会诊，家人理解和支持","术后激素替代：肾上腺术后需长期糖皮质激素替代（氢化可的松），不可自行停药，遇感染手术创伤时需加量（应激剂量），随身携带急救卡","监测血压血糖：家庭自测血压血糖，记录变化，调整药物，目标血压小于130/80，血糖HbA1c小于7%","骨健康：补充钙和维生素D，使用双膦酸盐，避免跌倒，定期骨密度检查","定期复查：按医嘱定期查皮质醇、ACTH、UFC、血糖、电解质、骨密度，评估疗效和HPA轴恢复","避免使用含激素药物：不滥用糖皮质激素（可致药物性库欣），必须使用时在医生指导下"],"complications":["术后急性肾上腺皮质功能不全（Addison危象）：双侧肾上腺切除或单侧腺瘤术后对侧肾上腺抑制，出现低血压、休克、低钠高钾、低血糖、意识障碍，需紧急静脉氢化可的松100mg+补液","感染：高皮质醇抑制免疫，感染（皮肤、尿路、呼吸道）易扩散且症状不典型，需及时抗感染","心血管事件：高血压、糖尿病、血栓栓塞风险增加，可致心梗、脑卒中、肺栓塞，是主要死亡原因之一","骨质疏松和骨折：皮质醇促进骨吸收抑制骨形成，椎体压缩骨折常见，需抗骨质疏松治疗","低钾性碱中毒：严重库欣（尤其异位ACTH和肾上腺癌）皮质醇具盐皮质激素活性，致低钾，需补钾和螺内酯","精神障碍：抑郁、焦虑、躁狂、精神病样症状，严重者自杀倾向，需精神科干预","糖尿病：皮质醇致胰岛素抵抗，约60%患者糖耐量异常，20-30%糖尿病，需控制血糖","手术并发症：经鼻蝶手术致脑脊液漏、尿崩症、垂体功能减退；肾上腺手术出血、感染","肿瘤复发：库欣病术后复发率15-20%，需长期随访，肾上腺癌复发率高","米托坦不良反应：胃肠道反应、中枢神经毒性（嗜睡、头晕）、肾上腺皮质功能不全、肝毒性，需监测血药浓度"],"monitoring":["筛查：24小时UFC（至少2次）、午夜唾液皮质醇（至少2次）、1mg过夜DST，至少两项异常","确诊：LDDST（0.5mg q6h×48h），皮质醇不抑制（大于50nmol/L）确诊","病因：血浆ACTH（晨8点），ACTH升高/正常为依赖性，降低为非依赖性；HDDST、CRH试验鉴别垂体和异位","定位：垂体MRI（增强，微腺瘤）、肾上腺CT（腺瘤/癌/增生）、BIPSS（鉴别垂体和异位，ACTH依赖性均应做）、全身影像学（异位ACTH：胸部CT、奥曲肽显像、68Ga-DOTATATE PET-CT）","术前：全面评估心肺功能、血糖、血压、电解质、凝血、感染灶，控制血压血糖补钾","术后：监测皮质醇、ACTH、电解质、血糖，评估HPA轴功能，调整激素替代剂量","激素替代期间：每4-8周评估症状和皮质醇，逐渐减量，HPA轴恢复需6-12个月甚至更长","长期随访：库欣病术后每3-6个月查UFC、午夜皮质醇、ACTH，5年后每年，监测复发；肾上腺腺瘤术后评估HPA轴恢复，可停替代后定期复查","出现低血压、乏力加重、恶心呕吐、低钠、意识模糊：立即就诊（肾上腺危象，需紧急激素治疗）"],"special_populations":["孕妇：孕期皮质醇生理性升高，诊断困难，UFC升高3倍以上或典型表现提示库欣，肾上腺腺瘤多见，治疗需兼顾胎儿，孕中期可手术，禁用米托坦和酮康唑（致畸）","儿童：生长迟缓是重要线索（皮质醇抑制生长激素），多为肾上腺肿瘤或库欣病，治疗后需关注生长发育","老年人：症状不典型，骨质疏松、高血压、糖尿病更突出，易被误诊为老年常见病，需警惕","肾上腺意外瘤：约5-10%为亚临床库欣，均应行1mg DST筛查，亚临床库欣也增加心血管和骨折风险","抑郁症患者：假性库欣，皮质醇轻度升高，LDDST可鉴别（抑郁症可被抑制），需精神科评估","酗酒者：酒精性假性库欣，戒酒后可恢复，需戒酒","服用糖皮质激素者：药物性库欣最常见，询问用药史（口服、注射、吸入、外用大面积），逐渐减停","异位ACTH肿瘤：小细胞肺癌病情重（低钾、肌无力、色素沉着），类癌病情慢症状轻，需仔细查找原发灶","垂体瘤术后：可能出现垂体功能减退（甲状腺、性腺、肾上腺），需全面评估和替代","肾上腺癌：年轻患者、肿瘤大于6cm、皮质醇升高伴雄激素升高，需根治手术+米托坦"],"references":["中华医学会内分泌学分会. 库欣综合征诊治指南（2024）","2023 ESE库欣综合征管理指南","Endocrine Society库欣综合征临床实践指南"]},{"name":"特发性炎性肌病诊治指南（2024）","category":"风湿免疫科","scope":"成人皮肌炎（DM）和多发性肌炎（PM）的诊断、分型、治疗和长期管理。","diagnosis":["临床表现：对称性近端肌无力（上楼、梳头、举物困难，可伴肌痛）、皮肌炎特征性皮疹（向阳疹、Gottron征、披肩征、V字征、甲周红斑、技工手）、间质性肺病（干咳、活动后气短，是主要死因）、吞咽困难（误吸风险）、发音障碍、关节痛、雷诺现象、发热、体重下降","肌炎特异性抗体：抗Jo-1（抗合成酶综合征，间质性肺病+关节炎+技工手+雷诺）、抗Mi-2（皮肌炎，预后好）、抗MDA5（皮肌炎，快速进展性间质性肺病，预后差）、抗TIF1-γ（肿瘤相关肌炎）、抗NXP2、抗SAE","实验室：肌酶升高（CK、LDH、ALT/AST，PM/DM活动期）、肌炎特异性抗体、血沉CRP升高、自身抗体（ANA阳性约80%）","肌电图：肌源性损害（纤颤电位、正锐波、短时限多相运动单位电位）","肌肉MRI：肌肉水肿、脂肪浸润，评估炎症范围和活检定位","肌肉活检：诊断金标准，PM见肌纤维坏死和炎细胞浸润（CD8+T细胞），DM见束周萎缩和微血管病变（CD4+T细胞、补体沉积）","间质性肺病评估：胸部HRCT（磨玻璃影、网格影、蜂窝肺）、肺功能（FVC、DLco降低）、血气分析","肿瘤筛查：DM患者肿瘤发生率高（卵巢癌、肺癌、胃癌、鼻咽癌、淋巴瘤），尤其是抗TIF1-γ阳性和40岁以上患者","诊断标准（Bohan/Peter或ENMC）：对称性近端肌无力、肌酶升高、肌电图肌源性损害、肌活检异常、皮肌炎特征性皮疹，符合前4项为PM，加皮疹为DM","鉴别：进行性肌营养不良、代谢性肌病、内分泌肌病（甲减、甲亢）、药物性肌病（他汀、激素）、重症肌无力、 Lambert-Eaton综合征、病毒性肌炎"],"staging":["按临床分型：多发性肌炎（PM，无皮疹）、皮肌炎（DM，有特征皮疹）、临床无肌病性皮肌炎（CADM，有皮疹无肌无力，易合并快速进展性间质性肺病）、抗合成酶综合征（抗Jo-1等，肌炎+间质性肺病+关节炎+技工手+雷诺+发热）、免疫介导的坏死性肌病（IMNM，抗HMGCR或抗SRP，肌无力重肌酶高，坏死为主炎症少）、包涵体肌炎（IBM，老年男性，远端肌无力，吞咽困难，对激素不敏感）","按严重程度：轻度（肌无力轻，无内脏受累）、中度（明显肌无力，影响生活）、重度（呼吸肌/吞咽肌受累、间质性肺病、心肌受累）","按病程：急性、亚急性、慢性","按肌炎抗体：抗Jo-1、抗Mi-2、抗MDA5、抗TIF1-γ、抗HMGCR、抗SRP等（不同抗体对应不同临床表型和预后）","合并症：间质性肺病、肿瘤、吞咽困难/误吸、心肌受累、关节痛、雷诺现象"],"key_points":["糖皮质激素（一线）：泼尼松1mg/kg/d（约60mg/d），重症用甲泼尼龙冲击（500-1000mg/d×3天）后改口服，病情控制后逐渐减量（每1-2周减10%），维持量5-10mg/d，总疗程1-2年以上","免疫抑制剂（激素联合，减少激素用量和复发）：甲氨蝶呤（10-25mg/w，首选，注意肝毒性和肺毒性）、硫唑嘌呤（1-2mg/kg/d）、吗替麦考酚酯（1-2g/d，间质性肺病首选之一）、环磷酰胺（重症/快速进展性间质性肺病，0.5-1g/m²每月冲击或口服）、环孢素A（3-5mg/kg/d，间质性肺病）、他克莫司（0.05-0.1mg/kg/d）","生物制剂：利妥昔单抗（抗CD20，用于难治性肌炎和间质性肺病）、静脉用免疫球蛋白（IVIG，2g/kg分2-5天，用于难治性和吞咽困难）、抗TNF（英夫利昔单抗，部分有效）","间质性肺病治疗：激素+免疫抑制剂（吗替麦考酚酯、环磷酰胺、环孢素、他克莫司），抗MDA5阳性快速进展性间质性肺病需强化治疗（激素冲击+环磷酰胺/他克莫司+利妥昔单抗），必要时肺移植","吞咽困难：禁食或鼻饲防误吸，IVIG和激素治疗，吞咽功能训练，必要时胃造瘘","对症治疗：补钙+维生素D+双膦酸盐（激素致骨质疏松）、胃黏膜保护（PPI）、控制血压血糖、康复训练","肿瘤相关肌炎：治疗肿瘤（手术/化疗），部分患者肿瘤切除后肌炎缓解","包涵体肌炎：对激素和免疫抑制剂反应差，以康复和对症为主，西罗莫司可能有效","皮疹治疗：防晒（广谱防晒霜、避光衣物）、局部激素、他克莫司软膏，抗疟药（羟氯喹），顽固皮疹可用利妥昔单抗或IVIG","长期管理：定期评估肌力、肌酶、肺功能、HRCT，调整免疫抑制剂，预防感染和激素副作用"],"drug_recommendations":[],"non_pharmacological":["休息与活动：急性期卧床休息，避免过度活动（加重肌损伤），病情稳定后逐步进行康复训练（被动活动→主动活动→肌力训练），避免剧烈运动","皮肤护理：皮肌炎皮疹对光敏感，严格防晒（SPF大于30广谱防晒霜、帽子、长袖），避免暴晒，使用温和护肤品，避免刺激性化妆品","饮食：高蛋白饮食（促进肌肉修复，1.2-1.5g/kg/d），吞咽困难者流质或半流质、糊状食物，缓慢进食防误吸，必要时鼻饲，避免辛辣刺激","预防感染：免疫抑制治疗期间免疫力低下，避免去人群密集场所，戴口罩，注意口腔和会阴卫生，接种灭活疫苗（流感、肺炎球菌），避免活疫苗","用药依从性：激素和免疫抑制剂需长期服用，不可自行停药或减量，定期复查调整，注意药物不良反应","监测：定期查肌力、肌酶（CK）、血沉、CRP、血常规、肝肾功能、血糖、血压，评估疾病活动和药物副作用","呼吸功能：有间质性肺病者注意保暖防感冒，出现干咳气短加重及时就诊，家庭氧疗（低氧血症者）","吞咽护理：进食时坐直，细嚼慢咽，避免干硬食物，进食后保持坐位30分钟，出现呛咳及时处理","心理支持：慢性病长期治疗，肌无力影响生活，皮疹影响容貌，易焦虑抑郁，需心理疏导，家人支持","定期肿瘤筛查：DM患者（尤其40岁以上、抗TIF1-γ阳性）定期肿瘤筛查（妇科、胃肠、肺、鼻咽、淋巴瘤），出现不明原因消瘦、疼痛及时就诊"],"complications":["间质性肺病（ILD）：最常见和最严重的内脏受累，约30-50%患者，抗Jo-1和抗MDA5阳性者高发，快速进展性间质性肺病（抗MDA5）可在数周内呼吸衰竭死亡，需早期识别和强化治疗","吞咽困难和误吸：约30-50%患者，可致吸入性肺炎、营养不良，严重者需鼻饲或胃造瘘，IVIG治疗有效","呼吸肌受累：膈肌和肋间肌无力致呼吸困难、低氧血症、CO2潴留，需呼吸支持，是急性期死亡原因之一","心肌受累：心肌炎、心律失常、心衰，需查心电图、心脏超声、肌钙蛋白，及时治疗","肿瘤：DM患者肿瘤发生率约15-30%（是正常人3-5倍），抗TIF1-γ阳性者更高，需定期筛查","激素不良反应：长期大剂量激素致骨质疏松、高血糖、高血压、库欣貌、感染、消化道溃疡、白内障、精神症状","免疫抑制剂不良反应：骨髓抑制（甲氨蝶呤、硫唑嘌呤、环磷酰胺）、肝毒性（甲氨蝶呤）、出血性膀胱炎（环磷酰胺）、肾毒性（环孢素）、感染（所有免疫抑制剂）、继发肿瘤","钙化：皮肌炎儿童和慢性患者可出现皮肤和软组织钙化，影响活动和外观","激素性肌病：长期大剂量激素可致肌无力加重，需与肌炎活动鉴别（CK正常、肌电图无活动提示激素性肌病，减少激素后改善）","死亡原因：间质性肺病呼吸衰竭、感染、肿瘤、心肌受累、吞咽困难误吸"],"monitoring":["诊断时：肌力评估（MRC评分）、肌酶（CK、LDH、ALT/AST）、肌炎特异性抗体谱、ANA、血沉CRP、肌电图、肌肉MRI、肌肉活检（金标准）、胸部HRCT+肺功能（间质性肺病筛查）、肿瘤筛查（DM患者）、心电图心脏超声（心肌受累）","治疗初期：每2-4周评估肌力、肌酶、血沉CRP，每1-2个月查血常规、肝肾功能、血糖、血压，调整激素和免疫抑制剂剂量","间质性肺病：每3-6个月查HRCT和肺功能（FVC、DLco），活动期每1-3个月复查，评估治疗反应","激素减量：病情稳定（肌力改善、CK正常）后每1-2周减泼尼松10%，减至20mg后更慢减量，维持5-10mg/d至少1年","免疫抑制剂：甲氨蝶呤用药前查乙肝丙肝、血常规、肝功能，用药后每2-4周查血常规肝功能，稳定后每1-3个月；环磷酰胺冲击前查血常规、尿常规（出血性膀胱炎）","长期随访：每3-6个月全面评估（肌力、肌酶、肺功能、HRCT、心脏、肿瘤筛查），调整治疗，监测副作用","出现肌无力加重、吞咽困难、干咳气短、发热、皮疹加重：及时就诊（疾病活动或并发症）","肿瘤筛查：DM患者每年全面肿瘤筛查（至少3-5年），抗TIF1-γ阳性者更频繁"],"special_populations":["老年患者：包涵体肌炎多见（对激素不敏感），肿瘤发生率高，心肺合并症多，激素和免疫抑制剂需谨慎，注意感染和骨质疏松","儿童皮肌炎：钙化常见，治疗反应较好，需关注生长发育和钙化，长期激素影响生长","孕妇：激素相对安全（泼尼松不通过胎盘），甲氨蝶呤、吗替麦考酚酯、环磷酰胺致畸需停药，利妥昔单抗需评估，孕期肌炎活动风险增加，需风湿科和产科共管","抗MDA5阳性者：快速进展性间质性肺病风险极高，预后差，需早期强化治疗（激素冲击+他克莫司/环磷酰胺+利妥昔单抗），密切监测肺功能和HRCT","抗合成酶综合征（抗Jo-1）：间质性肺病、关节炎、雷诺、技工手，易复发，需长期免疫抑制，吗替麦考酚酯和环孢素有效","抗TIF1-γ阳性者：肿瘤相关肌炎，必须全面肿瘤筛查，治疗肿瘤后肌炎可缓解","包涵体肌炎：对激素和免疫抑制剂反应差，以康复训练和对症为主，避免过度免疫抑制带来感染风险","合并间质性肺病者：避免使用可致肺纤维化的药物（甲氨蝶呤、胺碘酮），吗替麦考酚酯、环磷酰胺、环孢素对间质性肺病有效","吞咽困难严重者：需鼻饲或胃造瘘保证营养，IVIG对吞咽困难有效，预防误吸性肺炎","使用激素和免疫抑制剂者：定期筛查感染（结核、乙肝、真菌），接种灭活疫苗，出现发热及时就诊"],"references":["中华医学会风湿病学分会. 多发性肌炎和皮肌炎诊治指南（2024）","2023 EULAR/ACR特发性炎性肌病分类标准","ENMC多发性肌炎和皮肌炎诊疗共识"]},{"name":"眩晕诊治指南（2024）","category":"耳鼻喉科","scope":"成人眩晕的病因诊断、鉴别诊断、急性期处理和康复治疗。","diagnosis":["临床表现：眩晕（自身或周围物体旋转感，真性眩晕）、头晕（头昏沉、不稳感）、伴恶心呕吐、眼球震颤、平衡障碍","病史采集：眩晕性质（旋转/非旋转）、持续时间（秒/分/小时/天）、诱发因素（头位变化、体位、压力、声音）、伴随症状（耳鸣听力下降、头痛、神经系统症状）","分类：外周性眩晕（前庭周围，良性阵发性位置性眩晕BPPV最常见、梅尼埃病、前庭神经炎、迷路炎）、中枢性眩晕（前庭中枢，后循环缺血/梗死、脑出血、多发性硬化、偏头痛性眩晕）、其他（精神心理性、颈性、低血压、贫血、药物）","辅助检查：Dix-Hallpike试验（BPPV确诊）、Roll试验（水平半规管BPPV）、前庭功能检查（冷热试验、视频头脉冲试验vHIT、前庭诱发肌源性电位VEMP）、听力学检查（纯音测听、声导抗）、头颅MRI/MRA（怀疑中枢性眩晕，尤其伴神经系统体征）、经颅多普勒（TCD）","BPPV诊断：头位变化诱发短暂眩晕（小于1分钟），Dix-Hallpike或Roll试验阳性，无神经系统体征","梅尼埃病诊断：发作性眩晕（20分钟至12小时）、波动性听力下降、耳鸣、耳闷胀感，至少2次发作","前庭神经炎：急性持续性眩晕（大于24小时），伴恶心呕吐、水平眼震，无听力下降和神经系统体征，多有前驱上感史","中枢性眩晕警示征：复视、构音障碍、吞咽困难、肢体无力麻木、共济失调、霍纳综合征、意识改变，需紧急影像学检查","鉴别：晕厥（短暂意识丧失）、头晕（非旋转性）、偏头痛性眩晕、精神心理性头晕"],"staging":["按病因：外周性眩晕（BPPV约20-30%、梅尼埃病、前庭神经炎、迷路炎、药物性）、中枢性眩晕（后循环缺血/梗死、脑出血、多发性硬化、肿瘤、偏头痛性眩晕）、其他原因（颈性、精神心理性、全身疾病）","按持续时间：数秒（BPPV）、数分钟至数小时（梅尼埃病、TIA）、数天（前庭神经炎、中枢性）、持续性（慢性头晕、精神心理性）","按严重程度：轻度（不影响生活）、中度（影响生活，需扶持）、重度（不能站立行走，伴频繁呕吐脱水）","按病程：急性（小于1个月）、亚急性（1-3个月）、慢性（大于3个月，持续性姿势知觉性头晕PPPD）","BPPV分型：后半规管BPPV（最常见约80%）、水平半规管BPPV（约15%）、前半规管BPPV（少见）、多半规管BPPV"],"key_points":["急性期对症治疗：前庭抑制剂（异丙嗪25mg肌注/口服、地芬尼多25mg tid、倍他司汀12mg tid），不超过3天（长期用抑制前庭代偿）；止吐（甲氧氯普胺10mg肌注、昂丹司琼）；补液（呕吐严重者静脉补液纠正电解质）","BPPV：耳石复位治疗（首选，Epley法用于后半规管，Barbecue翻滚法用于水平半规管，Gufoni法），复位后避免剧烈头部活动24-48小时，可配合家庭训练，复位无效或反复发作者可手术（半规管阻塞术）","梅尼埃病：急性期前庭抑制剂+止吐；间歇期低盐饮食（小于1.5g/d）、倍他司汀、利尿剂（氢氯噻嗪+氨苯蝶啶）、鼓室注射糖皮质激素或庆大霉素（化学迷路切除，用于难治性）、手术（内淋巴囊减压、前庭神经切断）","前庭神经炎：急性期前庭抑制剂（不超过3天）+糖皮质激素（甲泼尼龙1mg/kg/d×1-2周逐渐减量，可改善预后）+抗病毒（怀疑疱疹病毒时用阿昔洛韦/伐昔洛韦）+早期前庭康复","中枢性眩晕：按病因治疗（脑梗死溶栓/抗血小板/他汀、脑出血降颅压/手术、多发性硬化激素/疾病修饰治疗），紧急转诊神经科","偏头痛性眩晕：偏头痛预防治疗（氟桂利嗪、托吡酯、普萘洛尔、阿米替林），避免诱因","持续性姿势知觉性头晕（PPPD）：前庭康复、认知行为治疗、SSRI/SNRI（舍曲林、文拉法辛）","前庭康复训练（所有眩晕恢复期均应早期开始）：凝视稳定训练（VOR训练）、平衡训练、步态训练、习服训练，促进中枢代偿","药物性眩晕：停用耳毒性药物（氨基糖苷类、袢利尿剂、顺铂），用营养神经药物（甲钴胺、银杏叶提取物）","手术治疗：药物难治性BPPV（半规管阻塞术）、梅尼埃病（内淋巴囊手术、前庭神经切断、迷路切除术）"],"drug_recommendations":[],"non_pharmacological":["急性期：卧床休息，避免头部剧烈活动和体位骤变，防止跌倒，保持环境安静，避免强光和噪音刺激","饮食：清淡易消化，呕吐严重者暂禁食或流质，少量多餐，避免辛辣刺激和过咸食物（梅尼埃病低盐）","补液：呕吐频繁者多饮水或口服补液盐，脱水者静脉补液","防跌倒：眩晕发作时立即坐下或扶住固定物，避免独自外出、登高、游泳、驾驶，家中安装扶手和防滑垫","前庭康复训练：眩晕减轻后尽早开始（发病后24-48小时即可开始床上训练），循序渐进，包括凝视稳定（头部转动时注视固定目标）、平衡训练（单腿站立、足跟对足尖走）、习服训练（反复诱发眩晕的动作至症状减轻），每天2-3次，每次15-30分钟","生活方式：规律作息，避免熬夜、过度劳累、精神紧张，梅尼埃病避免咖啡因、酒精、烟草","避免诱因：BPPV避免快速转头和仰头；梅尼埃病避免高盐、压力、疲劳；偏头痛性眩晕避免巧克力、奶酪、红酒、强光","心理支持：慢性眩晕患者易焦虑恐惧，需解释病情和预后，鼓励积极康复，必要时心理治疗","定期复查：BPPV复位后1周复查，梅尼埃病定期查听力，中枢性眩晕按病因随访","驾驶安全：眩晕未控制前禁止驾驶和操作危险机械"],"complications":["跌倒和外伤：眩晕发作时易跌倒致骨折、颅脑外伤，需预防","脱水和电解质紊乱：频繁呕吐致脱水、低钾低钠，需补液纠正","听力下降：梅尼埃病反复发作致永久性听力下降，需早期干预","慢性头晕和PPPD：急性眩晕后部分患者发展为持续性姿势知觉性头晕，表现为站立和行走时头晕，视觉刺激加重，需前庭康复和心理治疗","中枢性眩晕漏诊：后循环梗死可仅表现为眩晕（尤其小脑梗死），伴神经系统体征或血管危险因素者需紧急MRI，漏诊可致病情进展甚至死亡","BPPV复位失败：耳石复位成功率约80-90%，失败可能为手法不当、耳石黏附、多半规管受累、中枢性病变误诊","药物不良反应：前庭抑制剂致嗜睡、口干，老年人注意跌倒；庆大霉素鼓室注射致听力下降（化学迷路切除）","梅尼埃病难治性：约10-20%患者药物治疗无效，需手术或化学迷路切除","前庭功能丧失：双侧前庭功能损害致振荡性视幻觉（头动时视物模糊）和平衡障碍，康复训练改善","心理障碍：慢性眩晕患者焦虑抑郁发生率高，可加重头晕，形成恶性循环"],"monitoring":["诊断时：详细病史（眩晕性质、持续时间、诱因、伴随症状）、体格检查（神经系统检查、Dix-Hallpike/Roll试验、Romberg试验、过指试验、眼球震颤）、听力检查、前庭功能检查、头颅MRI（怀疑中枢性）","急性期：监测生命体征、意识、瞳孔、神经系统体征，呕吐者监测电解质","BPPV复位后：1周复查，评估复位效果，必要时重复复位或家庭训练","梅尼埃病：定期查纯音测听（监测听力变化）、声导抗，评估发作频率和严重程度","前庭神经炎：发病后1-3个月复查前庭功能，评估代偿情况，未代偿者加强康复","中枢性眩晕：按脑血管病或神经科疾病随访，定期MRI/MRA、血管危险因素管理","慢性头晕（大于3个月）：评估PPPD，进行前庭康复和心理评估","出现复视、肢体无力麻木、言语不清、吞咽困难、意识改变、剧烈头痛：立即急诊（中枢性眩晕，可能为脑梗死或出血）","眩晕频繁发作或持续不缓解：及时就诊调整治疗方案"],"special_populations":["老年人：中枢性眩晕比例增加（后循环缺血），BPPV也常见，前庭抑制剂慎用（嗜睡跌倒），需仔细排查中枢性病变，防跌倒","孕妇：避免使用前庭抑制剂和抗组胺药（致畸），以休息和前庭康复为主，BPPV可手法复位","儿童：眩晕少见，多为BPPV、前庭神经炎、偏头痛性眩晕，需排除先天性内耳畸形和中枢肿瘤，药物按体重计算","脑血管病高危人群（高血压、糖尿病、高血脂、房颤、吸烟）：眩晕需警惕后循环梗死，及时MRI，抗血小板/抗凝/他汀治疗","服用耳毒性药物者：氨基糖苷类、顺铂、袢利尿剂可致前庭和耳蜗损害，需监测听力和前庭功能，出现眩晕耳鸣及时停药","偏头痛患者：偏头痛性眩晕常见，需按偏头痛预防治疗，避免诱因","头部外伤后：外伤后BPPV和前庭功能损害常见，需前庭功能检查和康复","慢性焦虑患者：PPPD和精神心理性头晕，需心理评估和SSRI治疗，避免过度检查","梅尼埃病患者：记录发作日记（时间、诱因、持续时间、听力变化），帮助调整治疗","前庭功能丧失者：双侧前庭功能损害需长期康复训练，避免在黑暗中行走和驾驶"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 眩晕诊治指南（2024）","2023 EAN眩晕和头晕指南","Bárány学会前庭疾病分类共识"]},{"name":"突发性聋诊治指南（2024）","category":"耳鼻喉科","scope":"成人突发性聋（突聋）的诊断、分型、治疗和预后评估。","diagnosis":["诊断标准：72小时内突然发生的、原因不明的感音神经性听力损失，至少在相邻2个频率听力下降大于等于20dBHL","临床表现：突然发生的听力下降（多单侧）、耳鸣（约90%）、耳闷胀感、眩晕或头晕（约30%）、听觉过敏或重听","分型（按听力曲线）：低频下降型（125-250Hz下降）、高频下降型（4-8kHz下降）、平坦下降型（所有频率下降）、全聋型（所有频率重度下降）","辅助检查：纯音测听（确诊和分型）、声导抗（排除中耳病变）、耳声发射、听性脑干反应（ABR，排除听神经瘤）、内耳MRI（排除听神经瘤、脑血管病变，尤其单耳全聋伴眩晕）、血常规、生化、凝血、免疫相关检查","鉴别：分泌性中耳炎（传导性聋，声导抗异常）、梅尼埃病（反复发作伴眩晕耳鸣耳闷）、听神经瘤（进行性听力下降，MRI增强可见内听道占位）、脑血管病、自身免疫性内耳病、药物性聋","危险因素：血管性疾病（高血压、糖尿病、高血脂）、感染（病毒感染）、免疫性疾病、精神压力、劳累、饮酒","治疗时机：发病后2周内开始治疗效果较好，越早越好（黄金期72小时内）"],"staging":["按听力曲线分型：低频下降型（预后好，多为膜迷路积水）、高频下降型（预后较差，多为毛细胞损伤）、平坦下降型（中等预后）、全聋型（预后最差，多为血管栓塞或严重损伤）","按严重程度：轻度（26-40dB）、中度（41-55dB）、中重度（56-70dB）、重度（71-90dB）、极重度（大于90dB）","按病程：急性期（发病2周内，积极治疗）、亚急性期（2-4周，仍可尝试治疗）、慢性期（大于4周，治疗效果有限，以康复和助听为主）","按预后：预后良好型（低频、轻中度、无眩晕、年轻、治疗早）、预后不良型（全聋、高龄、伴眩晕、治疗晚、糖尿病高血压）","特殊类型：双侧突发性聋、儿童突发性聋、伴眩晕的突聋"],"key_points":["治疗原则：早期综合治疗，根据分型选择方案，发病2周内为黄金治疗期","糖皮质激素（核心用药）：甲泼尼龙1mg/kg/d（或泼尼松1mg/kg/d）口服，或地塞米松10mg静滴×3-5天后改口服，逐渐减量，总疗程1-2周；有全身禁忌者行鼓室注射激素（地塞米松或甲泼尼龙经鼓膜穿刺注入鼓室，每周2次，2-3周）","改善微循环：银杏叶提取物（金纳多，70mg tid口服或静滴）、前列地尔（前列腺素E1，10μg静滴qd）、巴曲酶（降纤，全聋型和平坦型，首次10BU，隔日5BU，监测纤维蛋白原）、甲钴胺（营养神经，0.5mg tid）","抗凝/抗血小板：全聋型可考虑阿司匹林100mg qd或低分子肝素（高凝状态），注意出血风险","高压氧治疗：发病2周内可联合，提高血氧分压，改善内耳缺氧，每日1-2次，10次为一疗程","抗病毒：怀疑病毒感染（前驱上感史）可用阿昔洛韦或伐昔洛韦（证据有限）","低钠饮食：低频下降型（膜迷路积水）按梅尼埃病处理，低盐饮食+利尿剂","治疗疗程：急性期治疗2周，有效者继续至1个月，无效者可考虑第二疗程（鼓室注射激素、巴曲酶、高压氧）","康复和助听：治疗无效且听力稳定（发病3个月后），根据听力损失程度选配助听器或人工耳蜗（重度以上）","随访和预后评估：治疗后1周、2周、1个月、3个月复查纯音测听，评估恢复情况"],"drug_recommendations":[],"non_pharmacological":["休息：急性期注意休息，避免劳累、熬夜、精神紧张，保证充足睡眠","饮食：清淡饮食，低盐（尤其低频下降型），避免辛辣刺激、酒精、咖啡、浓茶，戒烟","避免噪声：避免接触强噪声，不戴耳机听音乐，保护残余听力","情绪管理：突聋易致焦虑，需解释病情和治疗方案，保持心情舒畅，避免情绪激动","观察听力变化：注意患耳听力和耳鸣变化，出现加重及时就诊","眩晕护理：伴眩晕者卧床休息，防跌倒，眩晕明显时用前庭抑制剂（不超过3天）","用药依从性：激素需按医嘱逐渐减量，不可自行停药或长期服用，注意激素副作用（血糖血压升高、胃肠道不适、失眠）","高压氧护理：治疗前避免饱食和饮酒，治疗中配合调压动作（吞咽、捏鼻鼓气），治疗后观察有无耳痛、气压伤","定期复查：按医嘱定期复查纯音测听，评估疗效，调整治疗方案","患耳保护：避免使用耳毒性药物，避免头部外伤和剧烈运动，感冒时避免用力擤鼻"],"complications":["永久性听力损失：约1/3患者完全恢复，1/3部分恢复，1/3治疗无效（全聋型和治疗晚者），重度以上听力损失影响交流和生活质量","耳鸣：约90%患者伴耳鸣，部分患者听力恢复后耳鸣仍持续，影响睡眠和情绪，需耳鸣习服治疗或声治疗","眩晕：约30%患者伴眩晕，多为前庭受累，一般数天至数周恢复，少数遗留前庭功能障碍","焦虑抑郁：突聋和耳鸣致心理压力，易合并焦虑抑郁，需心理干预","治疗失败：发病超过2周才治疗、全聋型、高龄、伴眩晕、糖尿病微血管病变者预后差，需尽早干预助听","激素副作用：全身激素致血糖血压升高、胃肠道不适、失眠、电解质紊乱，有禁忌者用鼓室注射（局部副作用小）","巴曲酶出血风险：降纤治疗需监测纤维蛋白原（小于0.8g/L停药），有出血倾向者禁用","听神经瘤漏诊：单耳突聋需MRI排除听神经瘤（约1-3%突聋为听神经瘤首发表现），尤其伴眩晕和ABR异常者","双侧突聋：少见，多为全身疾病（自身免疫、血管炎、感染），需全面检查和积极治疗","儿童突聋：少见，多为病毒感染或先天性，需排除大前庭导水管综合征，治疗同成人但剂量按体重"],"monitoring":["诊断时：纯音测听（确诊和分型）、声导抗、耳声发射、ABR、必要时内耳MRI（排除听神经瘤）、血常规、生化、凝血、免疫指标","治疗期间：每周复查纯音测听，评估听力变化，调整治疗方案；监测血压血糖（激素治疗者）、纤维蛋白原（巴曲酶治疗者）","治疗后：1个月、3个月复查纯音测听，评估最终恢复情况，稳定后决定是否助听","高压氧治疗：治疗前检查外耳道和鼓膜（排除气压伤禁忌），治疗中观察耳痛","激素治疗：监测血压、血糖、电解质、胃肠道反应，糖尿病患者调整降糖药","鼓室注射：注射后保持患耳朝上体位20-30分钟，避免立即擤鼻，观察有无感染和穿孔","助听评估：发病3个月听力稳定后，根据听力损失程度选配助听器（中度以上）或人工耳蜗（重度以上言语识别率差者）","出现听力再次下降、眩晕加重、剧烈头痛：及时就诊（排除听神经瘤、脑血管病）","耳鸣持续不缓解：进行耳鸣评估和习服治疗，避免安静环境（增加耳鸣感知），用背景声掩蔽"],"special_populations":["老年人：多合并高血压糖尿病高血脂，血管因素为主，预后较差，激素需注意血糖血压，巴曲酶注意出血和肾功能","儿童：需排除大前庭导水管综合征（CT可见前庭导水管扩大）、腮腺炎病毒感染、外伤，治疗需积极，影响言语发育者尽早干预","孕妇：避免全身激素和巴曲酶，可考虑鼓室注射激素和高压氧，需产科评估","糖尿病患者：激素升高血糖，需调整降糖方案，密切监测血糖，可优先鼓室注射激素","高血压患者：激素可升高血压，需监测调整降压药，巴曲酶注意出血风险","肾功能不全：巴曲酶和某些改善循环药需调整剂量，避免肾毒性药物","凝血功能障碍/服用抗凝药：巴曲酶和抗凝治疗禁忌或谨慎，需评估出血风险","听神经瘤可疑者：单耳突聋伴眩晕、ABR异常、MRI增强可见内听道占位，需神经外科评估手术","全聋型患者：预后最差，需向患者充分告知，积极综合治疗，治疗无效尽早助听干预","有眩晕者：前庭受累提示预后较差，需同时治疗眩晕，防跌倒"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 突发性聋诊断和治疗指南（2024）","2023 EAN突发性聋指南","AAO-HNS突发性聋临床实践指南"]},{"name":"梅尼埃病诊治指南（2024）","category":"耳鼻喉科","scope":"成人梅尼埃病的诊断标准、分期、阶梯治疗和长期管理。","diagnosis":["临床表现：发作性旋转性眩晕（20分钟至12小时）、波动性听力下降（早期低频，后期全频）、耳鸣、耳闷胀感，发作间期症状可缓解","诊断标准（AAO-HNS 2015）：2次以上自发性眩晕发作，每次持续20分钟至12小时，至少1次纯音测听证实患耳低频至中频感音神经性听力下降，伴波动性耳部症状（听力下降、耳鸣、耳闷），排除其他疾病","分期（按患耳0.5、1、2、3kHz平均听阈）：一期（小于等于25dB）、二期（26-40dB）、三期（41-70dB）、四期（大于70dB）","辅助检查：纯音测听（波动性低频下降）、声导抗、耳声发射、耳蜗电图（SP/AP比值增大）、前庭功能检查（冷热试验患侧半规管功能减退）、VEMP、内耳MRI钆造影（内淋巴积水，辅助诊断）","鉴别：良性阵发性位置性眩晕（头位诱发短暂眩晕，无听力下降）、前庭神经炎（持续性眩晕大于24小时，无听力下降）、突发性聋（听力下降为主，眩晕可有可无，不反复发作）、听神经瘤（进行性听力下降，MRI确诊）、偏头痛性眩晕（无听力下降，有偏头痛史）、自身免疫性内耳病（双侧快速进展）","诱因：劳累、精神紧张、情绪波动、睡眠障碍、不良生活事件、高盐饮食、天气变化","病理：内耳膜迷路积水（内淋巴产生和吸收失衡）"],"staging":["按病程分期：早期（发作性眩晕+波动性低频听力下降，间期正常）、中期（发作频繁，听力下降进展，耳鸣持续）、晚期（眩晕发作减少，但听力严重下降，平衡障碍，耳鸣持续）","按听力分期：一期（小于等于25dB）、二期（26-40dB）、三期（41-70dB）、四期（大于70dB，重度以上）","按发作频率：偶发型（每年小于3次）、频发型（每年大于等于3次或每月发作）、难治型（药物治疗无效，严重影响生活）","按侧别：单侧（最常见）、双侧（约10-15%，多为自身免疫或家族性）","特殊类型：Tumarkin耳石危象（突然倾倒而无意识丧失，前庭终末器急性功能障碍）、前庭型梅尼埃病（以眩晕为主，听力症状不明显）、耳蜗型梅尼埃病（以听力下降耳鸣为主，眩晕不明显）"],"key_points":["阶梯治疗（从保守到有创）","第一阶段（生活方式干预）：低盐饮食（小于1.5g/d）、避免咖啡因酒精烟草、规律作息、避免诱因，是所有患者的基础治疗","第二阶段（药物治疗）：倍他司汀（12-48mg/d，改善内耳微循环，减少发作）、利尿剂（氢氯噻嗪12.5-25mg/d+氨苯蝶啶，减少内淋巴积水）、银杏叶提取物、发作期前庭抑制剂（异丙嗪、地芬尼多，不超过3天）+止吐","第三阶段（鼓室注射）：鼓室注射糖皮质激素（地塞米松或甲泼尼龙，每月1次，3次为一疗程，控制眩晕发作）；鼓室注射庆大霉素（化学迷路切除，用于难治性眩晕，低剂量滴定法，保留听力，需监测听力和前庭功能）","第四阶段（手术治疗）：内淋巴囊手术（减压/分流，保存听力，适用于药物无效仍有实用听力者）、前庭神经切断术（经颅中窝或乙状窦后入路，眩晕控制率高，保存听力）、迷路切除术（经乳突，适用于无实用听力的难治性患者，眩晕控制率最高但牺牲听力）","急性发作期：卧床休息，前庭抑制剂（异丙嗪25mg肌注、地芬尼多25mg口服）、止吐（甲氧氯普胺）、补液（呕吐严重者），不超过3天（避免抑制代偿）","鼓室注射庆大霉素：低剂量滴定法，每次注射后1周复查前庭功能，眩晕控制即停止，目标是化学迷路切除而不损伤听力，听力下降风险约10-30%","助听器：晚期听力下降影响交流者选配助听器，双侧重度以上可考虑人工耳蜗","康复：前庭功能丧失者进行前庭康复训练，促进代偿","患者教育：解释疾病性质（良性但反复发作），避免过度医疗，记录发作日记"],"drug_recommendations":[],"non_pharmacological":["饮食管理：严格低盐饮食（每日钠小于1.5g，约等于食盐3.75g），避免腌制食品、加工肉、方便面、酱油过量，多吃新鲜蔬菜水果，避免咖啡因、酒精、烟草（可诱发发作）","生活方式：规律作息，避免熬夜、过度劳累、精神紧张、情绪波动，保证充足睡眠，记录发作日记（时间、诱因、持续时间、症状）帮助识别和避免诱因","发作期护理：卧床休息，避免强光和噪音，防跌倒，呕吐时侧卧位防误吸，少量多次饮水或补液","间歇期：适度活动，进行前庭康复训练（尤其手术或化学迷路切除后），避免剧烈头部活动和高空作业","心理支持：反复发作影响生活质量，易焦虑抑郁，需心理疏导，加入病友团体","避免诱因：已知诱因（压力、疲劳、高盐、某些食物）尽量避免，但不必过度限制饮食（保证营养）","听力保护：避免强噪声，不戴耳机大声听音乐，保护残余听力","定期复查：每3-6个月复查纯音测听，监测听力变化，评估治疗效果，调整治疗方案","家庭环境：安装扶手和防滑垫，眩晕发作时防跌倒","驾驶安全：眩晕未控制前禁止驾驶和高空作业，发作频繁者避免独自外出"],"complications":["听力下降：反复发作致永久性感音神经性听力下降，从低频进展至全频，晚期重度以上，影响交流和生活质量","顽固性眩晕：约10-20%患者药物治疗无效，频繁发作严重影响生活和工作，需鼓室注射或手术","耳鸣：约80%患者伴耳鸣，晚期持续存在，影响睡眠和情绪，耳鸣习服治疗","平衡障碍：晚期前庭功能丧失，行走不稳，尤其黑暗中，易跌倒","Tumarkin耳石危象：突然倾倒无意识丧失，可致外伤，是手术指征之一","双侧梅尼埃病：约10-15%患者对侧耳受累，双侧听力下降和前庭功能损害，严重影响生活","鼓室注射庆大霉素并发症：听力下降（10-30%）、鼓膜穿孔、感染，需低剂量滴定和监测","手术并发症：内淋巴囊手术效果不确切（部分无效）；前庭神经切断术致脑脊液漏、面瘫、听力下降（少见）；迷路切除术牺牲听力","焦虑抑郁：慢性反复发作疾病，心理负担重，需同时干预","药物不良反应：利尿剂致电解质紊乱（低钾低钠）、高尿酸；倍他司汀致头痛恶心；前庭抑制剂致嗜睡"],"monitoring":["诊断时：纯音测听（确诊和分期）、声导抗、耳声发射、前庭功能检查（冷热试验、vHIT）、耳蜗电图、必要时内耳MRI钆造影（内淋巴积水）、排除其他疾病的检查","发作期：监测生命体征、意识、呕吐量、电解质，评估脱水情况","治疗随访：每3-6个月复查纯音测听（监测听力进展）、前庭功能，记录发作频率和严重程度，评估治疗效果","鼓室注射后：1周复查听力和前庭功能，观察有无鼓膜穿孔、感染，庆大霉素注射后监测听力变化","手术后：定期复查听力、前庭功能、平衡功能，进行前庭康复评估","晚期：评估听力损失程度，适时选配助听器或人工耳蜗","出现听力快速下降、眩晕持续不缓解、剧烈头痛、神经系统体征：及时就诊（排除听神经瘤、脑血管病）","发作频率增加或药物无效：评估升级治疗（鼓室注射或手术）"],"special_populations":["老年人：听力下降和平衡障碍更突出，跌倒风险高，前庭抑制剂慎用（嗜睡跌倒），手术需评估全身情况","孕妇：利尿剂和倍他司汀需谨慎，以生活方式干预为主，发作期用相对安全的止吐药，孕期可能发作减少","儿童：少见，多为家族性或先天性，需排除大前庭导水管综合征，治疗以低盐和倍他司汀为主，手术需谨慎","双侧梅尼埃病：手术选择需慎重（避免双侧前庭功能丧失致振荡视幻觉和严重平衡障碍），优先鼓室注射和内淋巴囊手术","有实用听力者：优先选择保存听力的治疗（内淋巴囊手术、前庭神经切断、低剂量庆大霉素），避免迷路切除","无实用听力者：迷路切除术眩晕控制率最高，可作为首选","偏头痛合并者：部分梅尼埃病与偏头痛相关，可加用偏头痛预防药（氟桂利嗪、托吡酯）","自身免疫性内耳病：双侧快速进展，需激素和免疫抑制剂治疗，与梅尼埃病鉴别","服用利尿剂者：定期查电解质（钾钠尿酸），避免电解质紊乱","焦虑抑郁患者：需心理科共同管理，SSRI类药物可同时改善耳鸣和焦虑"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 梅尼埃病诊断和治疗指南（2024）","2023 EAONO/JOS梅尼埃病指南","AAO-HNS梅尼埃病诊断标准"]},{"name":"白癜风诊治指南（2024）","category":"皮肤科","scope":"成人和儿童白癜风的诊断、分型、治疗和长期管理。","diagnosis":["临床表现：皮肤出现局限性或泛发性色素脱失斑（乳白色），边界清楚，白斑内毛发可变白，无自觉症状（不痛不痒），好发于暴露部位（面颈、手背）、摩擦部位（腰腹）、黏膜（口唇、外阴）","分型：节段型（沿皮节分布，单侧，儿童多见，早期快速进展后稳定）、非节段型（最常见，对称分布，包括散发型、泛发型、面肢端型、黏膜型）、混合型、未定类型","辅助检查：伍德灯（Wood灯，白癜风呈亮蓝白色荧光，与周围正常皮肤对比明显，可发现早期浅色斑）、皮肤镜（毛囊周围色素残留）、皮肤CT（反射式共聚焦显微镜，观察色素环缺失）、皮肤活检（必要时，基底层黑素细胞减少或消失）、甲状腺功能和自身抗体（常合并甲状腺疾病）","鉴别：白色糠疹（儿童面部，细碎鳞屑，可自愈）、花斑癣（真菌感染，真菌镜检阳性）、贫血痣（摩擦后周围发红白斑不红，终生不变）、无色素痣（出生即有，沿皮节，稳定）、炎症后色素减退（有原发皮肤病史）、斑驳病（先天性，额部白发，家族史）、硬萎（皮肤萎缩变薄）","分期：进展期（白斑扩大增多，边界模糊，同形反应阳性）、稳定期（白斑停止发展，边界清楚，色素岛出现，持续6个月以上）","同形反应：皮肤外伤部位出现白斑（进展期），是活动标志","合并症：甲状腺疾病（甲亢、甲减、桥本甲状腺炎，约20-30%）、糖尿病、斑秃、银屑病、恶性贫血、Addison病等自身免疫病"],"staging":["按分型：节段型（单侧皮节，儿童多，早期进展快，后期稳定）、非节段型（对称，成人多，慢性进展，包括散发型、泛发型、面肢端型、黏膜型）、混合型、未定类型","按分期：进展期（活动，白斑扩大增多，同形反应阳性）、稳定期（静止，6个月以上无变化，出现色素岛）","按面积：轻度（体表面积小于1%）、中度（1-5%）、重度（5-50%）、极重度（大于50%，泛发型）","按部位：暴露部位（面颈手背，影响美观，治疗需求高）、非暴露部位、黏膜部位（口唇外阴，治疗困难）、毛发部位（毛发变白，治疗困难）","按疗效反应：治疗反应好型（面颈部、早期、节段型早期）、治疗抵抗型（肢端、黏膜、毛发变白、病程长）"],"key_points":["治疗原则：早期治疗、综合治疗、个体化治疗，进展期控制发展，稳定期促进色素恢复","外用药物（局限性白斑首选）：糖皮质激素软膏（糠酸莫米松、卤米松，面部用弱效，连续不超过3个月，注意皮肤萎缩）、钙调磷酸酶抑制剂（他克莫司软膏、吡美莫司乳膏，面部和黏膜首选，可长期用，注意局部刺激）、维生素D3衍生物（卡泊三醇、他卡西醇，与激素或光疗联合）、氮芥乙醇（外用，注意局部刺激和致癌风险，少用）","光疗：窄谱中波紫外线（NB-UVB，311nm，泛发型首选，每周2-3次，需数十次）、308nm准分子光/激光（局限性白斑，效果好，起效快）、光化学疗法（PUVA，口服或外用补骨脂素+UVA，注意眼和皮肤癌风险，现已少用）","系统治疗（进展期泛发型）：糖皮质激素（泼尼松10-20mg/d或甲泼尼龙8mg/d，连用1-3个月控制进展后减量，注意副作用）、复方甘草酸苷（抗炎免疫调节，辅助）、中医中药（白癜风丸、白灵片等，辅助）","外科治疗（稳定期局限型，药物和光疗无效者）：自体表皮移植（负压吸疱移植，最常用）、微小皮片移植、黑素细胞培养移植（大面积）、毛囊移植（毛发部位），稳定期6个月以上方可手术","遮盖疗法：美容遮盖剂（白斑遮盖液、粉底），改善外观，提高生活质量，尤其暴露部位","脱色治疗：泛发型（体表面积大于95%），患者要求美观时，用氢醌单苯醚将残余正常皮肤脱色（不可逆，需充分告知）","辅助治疗：补充维生素B、维生素E、叶酸、铜锌制剂（辅助，证据有限）、抗氧化剂","心理治疗：白癜风影响容貌和心理，需心理疏导，认知行为治疗，必要时精神科","随访：每3个月评估白斑变化和治疗反应，调整方案，治疗疗程至少3-6个月评估疗效"],"drug_recommendations":[],"non_pharmacological":["防晒：白斑处皮肤缺乏黑素保护，易晒伤和光老化，外出涂防晒霜（SPF大于30）、戴帽子、穿长袖，避免暴晒（晒伤可诱发同形反应和进展）","避免外伤：进展期避免皮肤外伤（抓伤、烫伤、手术切口），外伤可诱发同形反应（白斑扩大）","饮食：均衡饮食，无需严格忌口，可适当补充含酪氨酸和铜锌的食物（瘦肉、蛋、动物肝脏、坚果、豆类），避免大量摄入维生素C（争议，不建议过量补充）","生活方式：规律作息，避免熬夜、过度劳累、精神紧张（精神因素可诱发和加重），戒烟限酒","皮肤护理：避免使用刺激性强的化妆品和外用药，保持皮肤滋润，避免过度清洁","心理调节：接受疾病，学习遮盖技巧，加入病友团体，避免因容貌产生自卑和社交回避，必要时心理咨询","治疗依从性：白癜风治疗周期长（3-6个月以上才见效），需坚持治疗，不可急于求成或频繁更换方案","避免诱因：避免接触酚类化合物（橡胶手套、染发剂、消毒液，可诱发或加重）","定期自查：每月观察白斑变化（大小、颜色、新发病灶），拍照记录便于对比","家庭支持：家人理解和支持，避免指责和过度关注，帮助患者坚持治疗"],"complications":["同形反应：进展期皮肤外伤部位出现新白斑，搔抓、摩擦、手术、晒伤均可诱发，需避免外伤和暴晒","治疗抵抗：肢端、黏膜、毛发变白、病程长（大于5年）的白斑治疗效果差，需向患者说明，避免过度治疗","激素副作用：长期外用激素致皮肤萎缩、毛细血管扩张、多毛、痤疮；系统用激素致血糖血压升高、骨质疏松、感染，需监测和逐渐减量","光疗不良反应：NB-UVB致皮肤干燥、瘙痒、红斑、水疱，长期大量光疗增加皮肤癌风险（需保护眼睛和生殖器）；308nm相对安全","移植并发症：感染、色素不均（过深或过浅）、皮片存活不良、瘢痕，需严格无菌和术后护理","心理障碍：白癜风影响容貌，尤其面颈部，患者易自卑、焦虑、抑郁、社交回避，青少年影响更大，需心理干预","合并自身免疫病：约20-30%合并甲状腺疾病，需定期筛查甲状腺功能和抗体，及时治疗","泛发型进展：部分患者白斑快速泛发，需早期系统用激素控制","脱色治疗不可逆：泛发型脱色后永久失去色素，需充分告知和心理准备，术后严格防晒","儿童白癜风：节段型多见，治疗反应较好，但需注意药物对生长发育的影响，心理影响需关注"],"monitoring":["诊断时：伍德灯检查（确诊和发现浅色斑）、皮肤镜/皮肤CT（辅助）、甲状腺功能+抗体（常规筛查合并症）、血常规、肝肾功能（用药前）、必要时皮肤活检","治疗初期：每2-4周评估药物不良反应（激素、钙调磷酸酶抑制剂），光疗者观察皮肤红斑水疱反应","治疗3个月：评估疗效（白斑缩小、色素岛出现），有效则继续，无效调整方案（联合光疗或换药）","治疗6-12个月：评估整体疗效，稳定期无效者考虑外科移植，泛发型评估光疗或系统治疗","长期随访：每3-6个月复查，监测白斑进展、治疗反应、合并症（甲状腺），调整治疗","光疗期间：每次治疗记录剂量和皮肤反应，定期查眼底（PUVA），保护眼睛和生殖器","外科移植后：1周、2周、1个月复查皮片存活和色素生长情况，避免摩擦和沾水","出现白斑快速扩大、新发大量白斑、明显同形反应：及时就诊（进展期，需系统治疗控制）","甲状腺相关症状（心慌、怕冷、体重变化）：查甲状腺功能，及时治疗合并症"],"special_populations":["儿童：节段型多见，治疗反应较好，外用激素选择弱中效（面部用氢化可的松或钙调磷酸酶抑制剂），避免长期强效激素，光疗需保护眼睛和生殖器，关注心理和学习影响","孕妇：避免系统激素和光疗（PUVA），以外用钙调磷酸酶抑制剂和遮盖为主，分娩后再积极治疗","面颈部：治疗效果好，首选钙调磷酸酶抑制剂+308nm准分子光，避免长期强效激素（皮肤萎缩）","肢端（手足）：治疗效果差，可尝试强效激素+钙调磷酸酶抑制剂+光疗，无效者遮盖或移植（效果有限）","黏膜部位（口唇外阴）：治疗困难，首选钙调磷酸酶抑制剂，避免激素，可尝试308nm光，无效用遮盖","毛发变白：治疗困难，药物和光疗效果差，可考虑毛囊移植，或染发/纹眉改善外观","稳定期6个月以上：可考虑外科移植（表皮移植），效果较好，进展期禁忌移植","泛发型：NB-UVB光疗+系统激素（进展期）+遮盖，体积极大且患者要求可考虑脱色治疗","合并甲状腺疾病：同时治疗甲状腺疾病，甲功控制后白癜风可能稳定","服用免疫抑制剂者：白癜风可能加重，需皮肤科评估调整"],"references":["中华医学会皮肤性病学分会. 白癜风诊疗指南（2024）","2023 EADV白癜风管理指南","AAD白癜风治疗指南"]},{"name":"玫瑰痤疮诊治指南（2024）","category":"皮肤科","scope":"成人玫瑰痤疮（酒渣鼻）的分型、诊断、治疗和长期管理。","diagnosis":["临床表现：面中部（鼻、两颊、眉间、颏部）阵发性潮红、持续性红斑、毛细血管扩张、丘疹脓疱，晚期鼻赘（组织增生肥大），伴灼热、刺痛、干燥、瘙痒","分型：红斑毛细血管扩张型（面中部红斑+毛细血管扩张，潮红）、丘疹脓疱型（红斑基础上丘疹脓疱，类似痤疮但无粉刺）、鼻赘型（鼻部组织增生肥大，男性多见）、眼型（睑缘炎、结膜炎、角膜炎、干眼，可单独或合并皮肤表现）","辅助检查：皮肤镜（观察血管形态）、蠕形螨检查（部分患者蠕形螨增多）、皮肤活检（必要时，排除其他疾病）、眼科检查（眼型）","鉴别：寻常痤疮（有粉刺，分布不限于面中部，青少年多）、脂溢性皮炎（油腻性鳞屑，好发鼻翼眉弓头皮，瘙痒明显）、接触性皮炎（有接触史，边界清楚，瘙痒）、红斑狼疮（蝶形红斑，系统症状，自身抗体阳性）、激素依赖性皮炎（长期外用激素史）、类癌综合征（阵发性潮红伴腹泻哮喘）","诱因：日晒、高温、辛辣食物、酒精、热饮、情绪激动、运动、寒冷、某些护肤品、蠕形螨","分期：根据严重程度分为轻中重度，或按治疗反应分阶段","并发症：眼部受累（睑缘炎、结膜炎、角膜血管翳，严重影响视力）、心理障碍（面部红斑影响容貌）"],"staging":["按分型：红斑毛细血管扩张型、丘疹脓疱型、鼻赘型、眼型（可混合）","按严重程度：轻度（偶发潮红，少量毛细血管扩张，不影响生活）、中度（持续性红斑，反复丘疹脓疱，影响生活）、重度（广泛红斑毛细血管扩张，大量丘疹脓疱，鼻赘，严重影响生活）","按病程：早期（阵发性潮红）、中期（持续性红斑+毛细血管扩张+丘疹脓疱）、晚期（鼻赘增生，不可逆）","按部位：面中部型、眼型、局限型","特殊类型：肉芽肿型玫瑰痤疮、爆发型玫瑰痤疮（严重暴发，女性产后多见）"],"key_points":["治疗原则：个体化、阶梯治疗，避免诱因是基础，修复皮肤屏障，长期维持","一般治疗：避免诱因（日晒、高温、辛辣、酒精、热饮、情绪激动）、温和护肤（温和洁面、保湿修复霜、广谱防晒霜SPF大于30，避免刺激性护肤品和去角质）、防晒（物理防晒+防晒霜）","红斑毛细血管扩张型：外用溴莫尼定（α2受体激动剂，收缩血管，临时改善红斑，每日1次，注意反弹潮红）、外用壬二酸（15%凝胶，抗炎抗菌，改善红斑丘疹）、伊维菌素乳膏（1%，杀蠕形螨抗炎）、激光/强脉冲光（IPL，封闭扩张的毛细血管，改善红斑，需多次，效果持久）","丘疹脓疱型：外用壬二酸、伊维菌素、甲硝唑（0.75%凝胶/乳膏，抗厌氧菌和蠕形螨）；中重度口服多西环素（40mg缓释亚抗菌剂量，抗炎，首选）或米诺环素（50-100mg/d）、大环内酯类（阿奇霉素，不能用四环素者）；严重者口服异维A酸（10-20mg/d，小剂量，注意致畸和干燥）","鼻赘型：手术治疗（切割术、磨削术）、激光（CO2激光、铒激光）、电灼，去除增生组织，术后护理防感染和瘢痕","眼型：人工泪液（干眼）、热敷清洁睑缘、外用红霉素眼膏、严重者口服多西环素或异维A酸，眼科会诊","爆发型玫瑰痤疮：口服异维A酸+短期糖皮质激素（控制炎症），局部护理","维持治疗：症状控制后继续外用药物维持（壬二酸、甲硝唑、伊维菌素），避免诱因，定期激光改善毛细血管扩张","中医中药：丹参酮、当归苦参丸等辅助（清热凉血活血）","心理支持：面部红斑影响容貌，易焦虑，需解释和疏导"],"drug_recommendations":[],"non_pharmacological":["皮肤护理：温和洁面（温水，无皂基洁面乳，每日不超过2次），避免过度清洁、去角质、刷酸、热水洗脸；保湿修复（含神经酰胺、透明质酸的修复霜，每日2次，修复皮肤屏障）；防晒（物理防晒帽子口罩+广谱防晒霜，避免化学防晒剂刺激）","避免诱因：记录诱因日记，避免日晒、高温环境、辛辣食物、酒精、热饮（咖啡热茶）、情绪激动、剧烈运动（可适度）、寒冷刺激，选择温和无刺激的护肤品（不含酒精、香精、防腐剂）","饮食：清淡饮食，避免辛辣、过烫食物、酒精（尤其红酒）、热饮，多吃蔬菜水果，保持大便通畅","生活方式：规律作息，避免熬夜，保持心情舒畅，避免情绪激动，戒烟","面部护理：避免按摩、热敷、蒸脸（加重潮红），避免使用含酒精、香精、薄荷、樟脑的护肤品，不要频繁更换护肤品","化妆：选择温和无刺激的矿物质化妆品，避免厚重粉底和卸妆油，彻底但温和卸妆","眼部护理：眼型患者注意眼部清洁（热敷+睑缘清洁），使用人工泪液，避免揉眼，出现眼痛视力下降及时眼科就诊","心理调节：接受疾病（慢性但可控），学习遮盖技巧（绿色修容霜中和红斑），避免因容貌焦虑，必要时心理治疗","定期复查：按医嘱定期复诊，评估疗效和调整方案，治疗周期长需坚持","避免滥用激素：不要自行长期外用糖皮质激素（可致激素依赖性皮炎，加重玫瑰痤疮），需在医生指导下短期使用"],"complications":["眼型并发症：睑缘炎、结膜炎、角膜炎、角膜血管翳、角膜溃疡，严重者视力下降甚至失明，需眼科评估和积极治疗","鼻赘：晚期鼻部组织增生肥大，不可逆，需手术或激光治疗，影响容貌和呼吸","持久红斑和毛细血管扩张：长期不治疗可致持续性红斑和明显毛细血管扩张，激光治疗可改善但需多次","丘疹脓疱反复发作：影响容貌和生活，需长期维持治疗预防复发","治疗不良反应：溴莫尼定致潮红反弹、红斑加重；外用壬二酸/甲硝唑致局部刺激干燥；口服四环素致胃肠道反应、光敏、头晕；异维A酸致畸、皮肤黏膜干燥、血脂升高、情绪变化","激光治疗不良反应：紫癜、水疱、色素沉着、瘢痕（少见），需选择合适参数和术后护理","激素依赖性皮炎：长期外用激素可诱发或加重玫瑰痤疮，需逐渐停用激素，用钙调磷酸酶抑制剂替代","心理障碍：面部红斑和丘疹影响社交，易焦虑抑郁，需心理干预","爆发型玫瑰痤疮：严重暴发，大量丘疹脓疱结节，可伴全身症状，需积极治疗（异维A酸+激素）","合并脂溢性皮炎：部分患者合并，需同时治疗（抗真菌洗发水、外用抗真菌药）"],"monitoring":["诊断时：详细病史（诱因、症状、病程）、体格检查（分型和严重程度）、皮肤镜、蠕形螨检查（必要时）、眼科检查（有眼部症状）、排除其他疾病（狼疮查自身抗体）","治疗初期：每2-4周评估外用药物耐受性（刺激、干燥），口服药物者查血常规、肝肾功能（四环素、异维A酸）","治疗3个月：评估疗效（红斑、丘疹脓疱数量），调整方案，有效则继续，无效则升级治疗","激光治疗后：1周、2周复查皮肤恢复情况，观察紫癜、色素沉着，间隔4-8周进行下一次","眼型：每1-3个月眼科复查，评估睑缘炎、角膜情况，调整治疗","长期维持：每3-6个月复查，评估维持治疗效果，调整外用药和激光频率","异维A酸治疗：每月查肝功能、血脂，育龄女性严格避孕（致畸），停药后3个月方可怀孕","出现眼痛、视力下降、畏光：立即眼科就诊（角膜受累）","出现面部严重肿胀、大量脓疱结节、发热：及时就诊（爆发型或继发感染）"],"special_populations":["孕妇：避免口服四环素（致畸）、异维A酸（严重致畸）、溴莫尼定，以外用壬二酸、甲硝唑、温和护肤和防晒为主，分娩后再系统治疗","哺乳期：四环素和异维A酸避免使用，可外用甲硝唑、壬二酸（相对安全），需医生评估","儿童：少见，多为眼型或红斑型，治疗以温和护肤和避免诱因为主，口服药物需儿科评估，避免四环素（影响牙齿骨骼）","男性：鼻赘型多见，早期治疗可避免鼻赘，已形成鼻赘需手术或激光","眼型患者：需眼科共同管理，不要忽视眼部症状（可能致视力损害）","敏感肌/屏障受损者：先修复皮肤屏障（温和洁面+保湿修复），再逐步加用治疗药物（从低浓度小面积开始）","服用血管扩张剂者：可能加重潮红，需评估是否调整药物","蠕形螨多者：伊维菌素乳膏效果好，可配合茶树油清洁","面部潮红严重者：溴莫尼定临时改善（社交前使用），注意反弹，激光改善持久","焦虑抑郁患者：需心理科共同管理，SSRI类药物可能改善潮红和情绪"],"references":["中华医学会皮肤性病学分会. 玫瑰痤疮诊疗指南（2024）","2023 EADV玫瑰痤疮管理指南","AAD玫瑰痤疮治疗指南"]},{"name":"异常子宫出血诊治指南（2024）","category":"妇产科","scope":"育龄期女性异常子宫出血（AUB）的病因分类（PALM-COEIN）、诊断和治疗。","diagnosis":["定义：与正常月经的周期频率、规律性、经期长度、经期出血量任何一项不符的、源自子宫腔的异常出血","临床表现：月经频发（周期小于21天）、月经稀发（周期大于35天）、经期延长（大于7天）、月经过多（大于80ml或影响生活）、不规则出血、经间出血、接触性出血、绝经后出血","病因分类（PALM-COEIN）：P子宫内膜息肉、A子宫腺肌病、L子宫肌瘤、L子宫内膜恶变和不典型增生、C全身凝血相关疾病、O排卵障碍、E子宫内膜局部异常、I医源性、N未分类","辅助检查：妇科检查（宫颈、子宫、附件）、妊娠试验（所有育龄女性必查，排除妊娠相关出血）、血常规（贫血）、凝血功能（怀疑凝血障碍）、性激素六项（排卵障碍）、甲状腺功能、盆腔超声（评估子宫大小、肌瘤、腺肌病、内膜厚度、卵巢）、宫腔镜+内膜活检（绝经后出血、不规则出血、内膜增厚、药物治疗无效，排除内膜癌）、基础体温测定（判断排卵）、宫颈防癌筛查（TCT+HPV，接触性出血）","鉴别：妊娠相关出血（流产、宫外孕、葡萄胎、产后出血）、生殖道外伤、泌尿道或直肠出血（非子宫来源）","急症：大量出血致失血性休克（头晕、乏力、心率快、血压低、Hb进行性下降），需紧急处理"],"staging":["按PALM-COEIN分类：P息肉、A腺肌病、L肌瘤、L内膜恶变/不典型增生、C凝血障碍、O排卵障碍、E内膜局部异常、I医源性、N未分类","按出血量：少量（点滴，不影响生活）、中量（多于正常月经，需用卫生巾）、大量（湿透卫生巾/血块，致贫血或休克）","按病程：急性（大量出血，需紧急止血）、慢性（6个月内至少3次异常出血）","按年龄：青春期（下丘脑-垂体-卵巢轴未成熟，多为排卵障碍）、育龄期（妊娠相关、肌瘤、息肉、排卵障碍）、围绝经期（排卵障碍多见，需排除内膜癌）、绝经后（需警惕内膜癌，必做内膜活检）","按排卵情况：排卵型AUB（月经过多、经期延长、经间出血，有排卵）、无排卵型AUB（周期紊乱、长短不一，围青春期和围绝经期多见）"],"key_points":["急症处理（大量出血）：血红蛋白大于80g/L且一般情况好：性激素止血（子宫内膜脱落法：黄体酮20mg肌注qd×3-5天或地屈孕酮10mg bid×10天；子宫内膜修复法：雌激素戊酸雌二醇2-4mg q6-8h，血止后逐渐减量）；血红蛋白小于70g/L或休克：诊断性刮宫（快速止血+病理）、输血补液、静脉雌激素（苯甲酸雌二醇或戊酸雌二醇），必要时宫腔镜检查","慢性AUB治疗（根据病因）：排卵障碍（青春期/围绝经期）：孕激素周期治疗（地屈孕酮10mg bid×10天，每月后半周期）或短效口服避孕药（育龄期，调经+避孕）；有生育要求者促排卵（克罗米芬/来曲唑）","子宫内膜息肉：有症状或大于1cm行宫腔镜息肉切除，术后孕激素或曼月乐预防复发","子宫肌瘤：月经过多致贫血者药物（氨甲环酸止血、NSAIDs、短效避孕药、曼月乐、GnRH-a）或手术（肌瘤剔除、子宫切除，根据年龄生育要求）","子宫腺肌病：曼月乐（首选，减少出血缓解痛经）、GnRH-a（术前缩小子宫）、手术（子宫切除，无生育要求）、地诺孕素","子宫内膜不典型增生/癌：不典型增生用高效孕激素（甲地孕酮、甲羟孕酮）或曼月乐（年轻有生育要求），无生育要求行子宫切除；内膜癌按癌症分期手术","凝血障碍：血液科共管，补充凝血因子、氨甲环酸、复方口服避孕药、曼月乐，严重者子宫切除","医源性AUB：激素治疗初期突破性出血（观察或调整剂量）、IUD出血（取出或观察）、抗凝药相关（评估抗凝必要性，氨甲环酸）","对症止血：氨甲环酸1g tid（经期，减少出血40-50%）、NSAIDs（布洛芬，减少出血+止痛）、铁剂（纠正贫血，硫酸亚铁/琥珀酸亚铁+维生素C）","手术治疗：药物治疗无效、无生育要求、怀疑内膜病变者行诊断性刮宫/宫腔镜检查+内膜活检，必要时子宫内膜去除术或子宫切除术","长期管理：排卵障碍需长期周期治疗（孕激素或避孕药）至绝经，避免内膜长期受雌激素刺激致增生甚至癌变"],"drug_recommendations":[],"non_pharmacological":["休息与营养：出血期间注意休息，避免剧烈运动和重体力劳动，加强营养（高蛋白、富含铁食物：瘦肉、动物肝脏、菠菜、红枣），纠正贫血","个人卫生：出血期间保持外阴清洁，勤换卫生巾，避免盆浴和性生活（防感染）","观察记录：记录出血日期、量、持续时间、伴随症状（腹痛、头晕），便于医生判断病情和疗效","贫血护理：头晕乏力者防跌倒，改变体位时缓慢，严重贫血需输血，服用铁剂时避免与茶咖啡同服（影响吸收），可与维生素C同服促进吸收","用药依从性：性激素治疗需按医嘱规律服用，不可漏服或自行停药（漏服致突破性出血，突然停药致撤退性出血），注意药物不良反应","心理支持：异常出血易致焦虑，需解释病因和治疗方案，增强信心，围绝经期女性关注情绪变化","避孕指导：有生育要求者指导受孕时机，无生育要求者选择合适避孕方式（短效避孕药可同时调经）","定期复查：按医嘱定期复查血常规、性激素、超声，评估治疗效果，调整方案","避免诱因：排卵障碍者避免过度劳累、精神紧张、体重急剧变化（过胖过瘦均可影响排卵）","绝经后出血：必须就诊排查内膜癌，不可认为是\"返老还童\"而忽视"],"complications":["失血性休克：急性大量出血致头晕、心慌、血压下降、意识模糊，需紧急止血、输血、补液，诊断性刮宫","贫血：长期慢性出血致缺铁性贫血，乏力、心悸、面色苍白，需补铁，严重者输血","子宫内膜癌：围绝经期和绝经后出血需警惕内膜癌，不规则出血、内膜增厚者必须内膜活检，早期发现预后好","感染：出血时间长、贫血、免疫力低下致生殖道感染（子宫内膜炎、盆腔炎），需抗生素","不孕：排卵障碍致不孕，需促排卵治疗，肌瘤/息肉影响着床需手术","药物不良反应：性激素致恶心、乳房胀痛、情绪变化、血栓风险（避孕药35岁以上吸烟女性禁忌）；孕激素致水肿、情绪低落；GnRH-a致潮热、骨质疏松（不超过6个月，反向添加）","手术并发症：刮宫致子宫穿孔、感染、宫腔粘连（Asherman综合征，致闭经不孕）；子宫切除有手术一般风险","内膜增生进展：长期无排卵致子宫内膜增生，不治疗可进展为不典型增生甚至内膜癌，需长期孕激素管理","妊娠相关出血误诊：育龄女性异常出血必须查妊娠试验，宫外孕破裂可致腹腔内大出血休克，危及生命","心理障碍：长期出血和疾病困扰致焦虑抑郁，尤其围绝经期，需心理干预"],"monitoring":["诊断时：妊娠试验（必查）、血常规、凝血功能、盆腔超声、性激素六项（月经第2-4天）、甲状腺功能、宫颈TCT+HPV（接触性出血）、必要时宫腔镜+内膜活检（绝经后、不规则出血、内膜增厚）","急性出血期：每4-8小时监测生命体征、出血量、血红蛋白，评估止血效果，调整药物剂量","药物治疗后：1-3个月经周期后评估出血改善情况，复查血常规（贫血纠正）、超声（肌瘤/息肉/内膜变化）","性激素治疗：定期评估疗效和不良反应，调整剂量，避孕药使用者每年评估血栓风险、血压、乳腺","手术后：病理结果回报（关键，排除恶性），术后1个月复查恢复情况，刮宫术后注意月经恢复情况（警惕宫腔粘连）","长期随访：排卵障碍患者每3-6个月复查，调整周期治疗方案，监测内膜情况","绝经后出血：内膜活检病理结果是关键，良性者定期随访，恶性者按内膜癌治疗随访","出现出血量突然增多、血块大、头晕心慌、血压下降：立即急诊（失血性休克）","出现停经后出血、绝经后出血、不规则出血伴腹痛：及时就诊（排除宫外孕、内膜癌等）"],"special_populations":["青春期（小于18岁）：多为下丘脑-垂体-卵巢轴未成熟致无排卵，以性激素止血和周期治疗为主，避免过度检查和手术，注意心理和学习影响","育龄期：必须先排除妊娠相关出血（宫外孕、流产），根据生育要求选择治疗（有生育要求促排卵/手术，无生育要求避孕药/曼月乐）","围绝经期（45-55岁）：排卵障碍多见，但需首先排除内膜癌（不规则出血必做内膜活检），治疗以孕激素周期或曼月乐为主，过渡至绝经","绝经后：任何出血均需警惕内膜癌，必做超声和内膜活检，良性者观察，恶性者手术","孕妇：异常出血需产科评估（先兆流产、宫外孕、胎盘问题），不可自行用药","哺乳期：月经紊乱常见，但需排除妊娠和器质性病变，避孕选择避孕套或曼月乐，避免含雌激素避孕药","凝血障碍患者：需血液科共管，避免宫腔操作（出血风险），以药物和曼月乐为主，严重者子宫切除","服用抗凝药者：评估抗凝必要性，可加氨甲环酸，必要时调整抗凝方案","肥胖/多囊卵巢综合征患者：长期无排卵致内膜增生风险高，需长期孕激素管理，控制体重改善排卵","35岁以上吸烟女性：避免使用复方口服避孕药（血栓风险），选择孕激素或曼月乐"],"references":["中华医学会妇产科学分会. 异常子宫出血诊治指南（2024）","FIGO异常子宫出血分类系统（PALM-COEIN）","ACOG异常子宫出血管理指南"]},{"name":"盆腔炎性疾病诊治指南（2024）","category":"妇产科","scope":"女性盆腔炎性疾病（PID，子宫内膜炎、输卵管炎、输卵管卵巢脓肿、盆腔腹膜炎）的诊断、治疗和随访。","diagnosis":["临床表现：下腹痛（持续性，活动或性交后加重）、发热、阴道分泌物增多（脓性、有臭味）、不规则出血、性交痛、经量增多；严重者寒战高热、恶心呕吐、腹胀","体征：宫颈举痛、子宫压痛、附件区压痛（最低诊断标准）；体温大于38.3℃、宫颈或阴道脓性分泌物、白细胞升高、CRP/血沉升高（附加标准）；输卵管增粗/积液/脓肿（特异标准，超声/腹腔镜）","辅助检查：血常规（白细胞升高、中性粒比例升高）、CRP/血沉升高、宫颈分泌物涂片（革兰染色见白细胞）、宫颈/阴道核酸检测（淋病奈瑟菌、沙眼衣原体）、妊娠试验（排除宫外孕）、盆腔超声（输卵管增粗积液、输卵管卵巢脓肿、盆腔积液）、腹腔镜（金标准，同时可取分泌物培养，但非必需）","诊断标准（CDC）：性活跃女性有下腹痛+宫颈举痛/子宫压痛/附件压痛，排除其他病因，即可经验性治疗；附加标准增加特异性；特异标准（超声/腹腔镜）确诊","鉴别：急性阑尾炎（转移性右下腹痛，麦氏点压痛）、异位妊娠（停经、腹痛、阴道出血，妊娠试验阳性，超声附件包块）、卵巢囊肿蒂扭转/破裂（突发一侧腹痛，超声囊肿）、子宫内膜异位症（慢性痛经，无发热）、泌尿系感染（尿频尿急尿痛）、胃肠炎（呕吐腹泻）","高危因素：年轻（15-25岁）、性活跃、多性伴、无保护性交、性传播疾病史、宫内节育器放置（术后3周内）、阴道冲洗、细菌性阴道病","并发症：不孕（输卵管堵塞）、异位妊娠、慢性盆腔痛、输卵管卵巢脓肿、肝周围炎（Fitz-Hugh-Curtis综合征）"],"staging":["按病情严重程度：轻症（一般情况好，能口服，无脓肿）、重症（高热、剧烈腹痛、不能口服、输卵管卵巢脓肿、妊娠、免疫低下）","按部位：子宫内膜炎、输卵管炎、输卵管卵巢脓肿（TOA）、盆腔腹膜炎、盆腔结缔组织炎","按病程：急性盆腔炎、慢性盆腔炎（急性后遗症，慢性盆腔痛、不孕）","按病原体：性传播病原体（淋病奈瑟菌、沙眼衣原体、支原体）、内源性病原体（厌氧菌、需氧菌，如大肠杆菌、链球菌、拟杆菌）、混合感染（多数为混合感染）","特殊类型：宫内节育器相关PID、妊娠期PID、产后/术后PID、肝周围炎"],"key_points":["治疗原则：及时、广谱、足量、个体化抗生素治疗，必要时手术，性伴同治，预防后遗症","门诊治疗（轻症）：头孢曲松250mg肌注单次+多西环素100mg bid×14天+甲硝唑500mg bid×14天；或头孢西丁2g肌注+丙磺舒1g口服单次+多西环素+甲硝唑；或氧氟沙星400mg bid+甲硝唑500mg bid×14天（不能耐受头孢者）","住院治疗（重症、不能口服、诊断不明确、脓肿、妊娠）：静脉抗生素，方案A：头孢替坦2g静滴q12h或头孢西丁2g静滴q6h+多西环素100mg口服/静滴q12h；方案B：克林霉素900mg静滴q8h+庆大霉素（负荷2mg/kg后1.5mg/kg q8h）；临床改善后继续静脉至少24小时，改口服多西环素+甲硝唑至总疗程14天","输卵管卵巢脓肿：抗生素治疗48-72小时无效或脓肿破裂（急腹症休克）需手术（腹腔镜脓肿切开引流/患侧附件切除，年轻尽量保留卵巢）；脓肿可经阴道或超声引导穿刺引流","性伴治疗：PID患者出现症状前60天内的性伴均应检查和治疗（覆盖淋病和衣原体），治疗期间避免性生活，防止重复感染","宫内节育器：PID治疗时是否取出IUD尚有争议，若治疗48-72小时无效或严重感染可考虑取出","妊娠合并PID：需住院静脉用头孢类+阿奇霉素/克拉霉素（避免多西环素和喹诺酮），必要时终止妊娠","手术治疗指征：脓肿破裂、抗生素治疗无效的TOA、严重粘连致慢性盆腔痛、不孕需腹腔镜评估","对症支持：卧床休息（半卧位利于引流）、补液纠正电解质、退热止痛、营养支持","随访：治疗72小时内评估疗效（体温、腹痛、体征改善），无效需重新评估诊断或手术；治疗结束后4-6周复查，筛查性传播疾病，3个月后复查衣原体/淋病（再感染率高）","预防：安全性行为（避孕套）、避免多性伴、及时治疗下生殖道感染（宫颈炎、阴道炎）、避免阴道冲洗、IUD放置前筛查STD"],"drug_recommendations":[],"non_pharmacological":["休息：急性期卧床休息，半卧位（使炎症局限于盆腔，利于引流），避免劳累和性生活","饮食：高热量、高蛋白、高维生素流质或半流质，多饮水，避免辛辣刺激，发热时补充水分","个人卫生：保持外阴清洁，勤换内裤，避免阴道冲洗（破坏菌群），经期卫生","疼痛护理：下腹痛可热敷（急性期发热时避免热敷，可能加重炎症扩散），遵医嘱用止痛药","发热护理：体温大于38.5℃物理降温（温水擦浴）或退热药，监测体温变化，出汗后及时更换衣物","用药依从性：抗生素需足量足疗程（14天），不可症状好转就停药（致耐药和慢性盆腔炎），注意药物不良反应","性生活管理：治疗期间禁止性生活，性伴同时检查治疗，治愈后坚持使用避孕套，避免多性伴","观察病情：注意腹痛、体温、阴道分泌物变化，出现腹痛加重、高热不退、血压下降及时报告（脓肿破裂或脓毒症）","心理支持：PID可能致不孕和慢性盆腔痛，患者易焦虑，需解释治疗和预后，鼓励积极配合","定期复查：按医嘱72小时复诊评估疗效，疗程结束后复查，筛查性传播疾病，不孕者尽早评估输卵管功能"],"complications":["不孕：输卵管炎症致粘连堵塞，PID后不孕发生率约10-20%，发作次数越多风险越高，需早期规范治疗减少后遗症","异位妊娠：输卵管炎症致通而不畅，异位妊娠风险增加6-10倍，有PID史者怀孕后尽早超声排除宫外孕","慢性盆腔痛：约20%PID患者遗留慢性盆腔痛（粘连、输卵管积水），影响生活，需综合治疗（物理治疗、止痛药、腹腔镜粘连松解）","输卵管卵巢脓肿（TOA）：严重并发症，抗生素治疗无效需手术，脓肿破裂致弥漫性腹膜炎和脓毒症，危及生命","肝周围炎（Fitz-Hugh-Curtis综合征）：淋病或衣原体感染致肝包膜炎症，右上腹痛，需与胆囊炎鉴别，抗生素治疗有效","脓毒症/感染性休克：严重PID或脓肿破裂致全身感染，需急诊抢救（广谱抗生素+手术+支持）","宫腔粘连（Asherman综合征）：子宫内膜炎致宫腔粘连，闭经和不孕，需宫腔镜分离","输卵管积水：输卵管伞端闭锁积水，影响受孕，需手术（输卵管造口或切除后IVF）","药物不良反应：头孢类过敏、胃肠道反应；多西环素致胃肠道反应、光敏、食管炎（需多饮水）；甲硝唑致恶心、金属味、戒酒（双硫仑反应）；庆大霉素致肾毒性和耳毒性（监测）","反复感染：性伴未治疗或无保护性生活致再感染，需性伴同治和避孕套预防"],"monitoring":["诊断时：妊娠试验、血常规、CRP/血沉、宫颈分泌物淋病/衣原体核酸检测、盆腔超声、必要时腹腔镜","治疗72小时：必须复诊评估（体温、腹痛、腹部压痛、白细胞），临床改善则继续，无效则住院/手术/重新诊断","住院患者：每日监测体温、脉搏、腹痛、腹部体征，复查血常规，静脉用药至热退、症状改善后24小时改口服","抗生素疗程：总疗程14天，不可提前停药，口服者注意依从性","TOA抗生素治疗：48-72小时评估，无效或脓肿增大需手术或引流","治疗结束后：4-6周复查（症状、体征、病原学），3个月复查衣原体/淋病（再感染率高），不孕者行输卵管通畅检查（子宫输卵管造影或腹腔镜）","性伴：通知前60天内性伴检查治疗，治疗期间禁性生活","出现腹痛突然加剧、高热不退、血压下降、意识改变：立即急诊（脓肿破裂或脓毒症）","治疗后不孕：尽早到生殖科评估，输卵管堵塞者可考虑IVF","慢性盆腔痛：需长期管理，物理治疗+止痛药+心理治疗，严重粘连可腹腔镜手术"],"special_populations":["青少年：性活跃青少年PID风险高，需重视性教育和避孕，治疗同成人，注意心理和生育保护","孕妇：PID可致流产、早产、脓毒症，需住院静脉用安全抗生素（头孢类+阿奇霉素），避免多西环素（影响胎儿牙齿骨骼）和喹诺酮（软骨毒性），必要时终止妊娠","宫内节育器使用者：IUD放置后3周内PID风险高，放置前筛查STD，治疗PID时IUD是否取出需个体化（治疗无效或严重感染考虑取出）","HIV感染者：PID症状可能不典型，免疫低下感染易严重，需更积极治疗和住院","免疫抑制患者（激素、移植、糖尿病）：感染易扩散，需住院广谱抗生素，密切观察","反复发作者：排查性伴治疗情况、依从性、是否有输卵管积水或脓肿，必要时手术","有生育要求者：尽早规范治疗减少输卵管损伤，治疗后评估输卵管通畅性，不孕者尽早辅助生殖","无生育要求、反复发作者：可考虑根治性手术（全子宫+双附件切除），但需充分告知","服用抗凝药者：PID致出血风险，需评估，抗生素注意与抗凝药相互作用","性工作者/多性伴：STD筛查和治疗，鼓励避孕套，定期体检"],"references":["中华医学会妇产科学分会. 盆腔炎性疾病诊治指南（2024）","CDC性传播感染治疗指南（盆腔炎部分）","NICE盆腔炎诊断和管理指南"]},{"name":"慢性咽炎诊治指南（2024）","category":"耳鼻喉科","scope":"成人慢性咽炎的分型、诊断、治疗和长期管理。","diagnosis":["临床表现：咽部不适（异物感、干燥、灼热、痒感、微痛）、刺激性咳嗽、清嗓动作、晨起恶心（尤其刷牙时）、黏痰附着感，全身症状不明显","分型：慢性单纯性咽炎（黏膜充血，小血管扩张）、慢性肥厚性咽炎（黏膜肥厚，淋巴滤泡增生，咽后壁颗粒状隆起）、萎缩性/干燥性咽炎（黏膜萎缩变薄，干燥，可有痂皮）、反流性咽喉炎（LPR，胃食管反流致，声嘶、清嗓、球部异物感）、过敏性咽炎（咽痒、阵发性咳嗽，伴过敏史）","辅助检查：喉镜（间接喉镜或电子喉镜，观察咽部黏膜、淋巴滤泡、会厌、声带，排除肿瘤）、血常规（一般正常，急性发作时白细胞升高）、咽拭子培养（必要时，排除特殊感染）、胃镜/24小时食管pH监测（怀疑反流性咽喉炎）、过敏原检测（怀疑过敏性）","鉴别：慢性扁桃体炎（扁桃体肥大、隐窝脓栓、反复急性发作）、咽喉部肿瘤（中老年、吸烟饮酒、进行性吞咽困难、痰中带血、声音嘶哑，喉镜+活检排除）、食管癌（进行性吞咽困难，胃镜排除）、茎突过长综合征（咽部刺痛，转头加重，触诊茎突）、甲状腺疾病（甲状腺肿大压迫，超声）、舌咽神经痛（阵发性剧痛，触发点）、干燥综合征（口干眼干，自身抗体）","诱因：急性咽炎反复发作、鼻腔鼻窦疾病（鼻后滴漏）、烟酒过度、用嗓过度、辛辣刺激食物、空气污染、胃食管反流、过敏、职业因素（教师、歌手、粉尘环境）、全身因素（贫血、消化不良、内分泌紊乱、免疫低下）","并发症：一般无严重并发症，长期不适影响生活质量，可伴慢性喉炎、声音嘶哑"],"staging":["按病理分型：慢性单纯性咽炎、慢性肥厚性咽炎、萎缩性/干燥性咽炎","按病因分型：感染后慢性咽炎、鼻后滴漏相关性、反流性咽喉炎（LPR）、过敏性咽炎、干燥性咽炎、职业相关性","按严重程度：轻度（偶发不适，不影响生活）、中度（经常不适，影响生活）、重度（持续不适，频繁清嗓咳嗽，严重影响生活和睡眠）","按病程：慢性（大于3个月）、亚急性（1-3个月）","特殊类型：反流性咽喉炎（LPR，日益受到重视，需抗反流治疗）、过敏性咽炎（需抗过敏治疗）"],"key_points":["治疗原则：病因治疗为主，综合治疗，避免滥用抗生素（慢性咽炎非细菌感染，抗生素无效）","病因治疗：治疗鼻腔鼻窦疾病（鼻炎鼻窦炎，鼻后滴漏是重要原因）、胃食管反流（PPI）、过敏、口腔疾病，戒烟酒，避免辛辣刺激，改善工作环境","局部治疗：含漱液（复方硼砂溶液、呋喃西林、生理盐水，保持口腔清洁）、含片（西地碘、溶菌酶、西瓜霜、金嗓子，缓解症状）、咽部涂药（2%碘甘油、5%硝酸银，收敛消炎，肥厚性咽炎）、雾化吸入（布地奈德雾化，急性发作或干燥明显时）、物理治疗（激光、冷冻、电凝、射频，用于肥厚性咽炎淋巴滤泡增生，需严格掌握，避免过度治疗致萎缩）","反流性咽喉炎（LPR）：质子泵抑制剂（PPI，奥美拉唑20mg bid或雷贝拉唑10mg bid，餐前30分钟，疗程8-12周）、H2受体拮抗剂（夜间反流）、促动力药（莫沙必利）、生活方式调整（见非药物），诊断性PPI治疗有效支持诊断","过敏性咽炎：抗组胺药（氯雷他定、西替利嗪）、白三烯受体拮抗剂（孟鲁司特）、鼻用激素（合并过敏性鼻炎）、避免过敏原","萎缩性咽炎：咽部灌洗（清除痂皮）、局部涂碘甘油（促进分泌）、口服维生素A/B2/C/E（促进黏膜上皮修复）、少量多次饮水","中医中药：辨证施治（阴虚火旺、痰湿阻滞、肝郁气滞），中成药（咽炎片、清喉利咽颗粒、蒲地蓝、蓝芩口服液，辅助）","急性发作：按急性咽炎处理（抗病毒/抗生素根据病原，对症治疗）","避免过度医疗：慢性咽炎不需要长期用抗生素，不需要反复输液，淋巴滤泡增生不盲目激光（过度治疗致萎缩性咽炎和干燥）","心理治疗：部分患者有恐癌心理，需解释病情（良性），必要时抗焦虑治疗","预防：增强体质，预防感冒，及时治疗急性咽炎和鼻、口腔、全身疾病"],"drug_recommendations":[],"non_pharmacological":["饮食：清淡易消化，多饮水（少量多次，保持咽部湿润），避免辛辣刺激、过烫、过冷食物，戒烟酒，避免咖啡浓茶（反流者），反流者避免巧克力、薄荷、高脂食物、睡前3小时禁食","生活方式：规律作息，避免熬夜，保持室内空气湿润（加湿器，湿度50-60%），避免干燥、粉尘、有害气体环境，戴口罩（雾霾或粉尘环境）","用嗓卫生：避免过度用嗓、大声喊叫、长时间说话，教师歌手注意用嗓方法（腹式呼吸、嗓音训练），说话时多喝水","口腔卫生：早晚刷牙，饭后漱口，治疗龋齿、牙龈炎等口腔疾病（口腔感染蔓延致咽炎）","鼻部护理：治疗鼻炎鼻窦炎，避免鼻后滴漏（鼻涕倒流刺激咽部），生理盐水洗鼻","反流管理：抬高床头15-20cm（夜间反流）、避免紧身衣、减轻体重、少食多餐、睡前3小时不进食、避免诱发反流的食物","过敏管理：避免接触过敏原（花粉、尘螨、宠物），过敏季节戴口罩，规律使用抗过敏药","避免诱因：记录诱发因素（某些食物、环境、情绪），尽量避免","心理调节：慢性咽炎病程长、易反复，需接受（良性疾病），避免过度关注和焦虑，保持心情舒畅，必要时心理疏导","定期自查：注意症状变化，出现进行性吞咽困难、声音嘶哑、痰中带血、颈部肿块、体重下降及时就诊（排除肿瘤）"],"complications":["慢性喉炎/声音嘶哑：炎症蔓延至喉部，致声带充血肥厚，声音嘶哑，需喉镜检查，嗓音训练","萎缩性咽炎进展：过度治疗（激光、电凝）或自身免疫致黏膜萎缩，咽部干燥、痂皮、臭味，治疗困难","睡眠呼吸障碍：咽部肥厚、舌后坠致打鼾和睡眠呼吸暂停，需睡眠监测","焦虑抑郁/躯体化障碍：长期咽部异物感致患者反复就医、恐癌，部分合并焦虑抑郁，需心理干预，抗焦虑药可改善症状","急性发作：慢性咽炎基础上合并急性感染，咽痛加重、发热，需按急性咽炎治疗","治疗无效/症状加重：需重新评估，排除咽喉部肿瘤（下咽癌、喉癌、食管癌）、甲状腺疾病、茎突过长、胃食管反流、过敏等，不可一直按慢性咽炎治疗","药物不良反应：含片长期用致口腔菌群失调和碘过量（西地碘）；PPI长期用致骨质疏松、维生素B12缺乏、肠道菌群紊乱；抗过敏药致嗜睡","过度医疗：不必要的抗生素、输液、激光治疗，增加患者负担和不良反应，需规范治疗","口臭：咽部细菌繁殖和分泌物致口臭，影响社交，需口腔护理和治疗咽炎","营养不良/脱水：萎缩性咽炎和吞咽不适致进食减少，需注意营养和水分摄入"],"monitoring":["诊断时：详细病史（症状、诱因、病程、伴随症状、胃食管反流/过敏史）、喉镜检查（排除肿瘤，评估黏膜和淋巴滤泡）、必要时血常规、咽拭子、过敏原检测、胃镜（怀疑反流）","治疗随访：2-4周评估疗效，调整方案，病因治疗需8-12周（尤其反流性咽喉炎PPI疗程）","PPI治疗反流性咽喉炎：8-12周评估，有效则逐渐减量维持，无效需重新评估诊断（非反流或需调整方案）","肥厚性咽炎物理治疗后：1周、2周复查咽部恢复，观察有无感染、出血、过度干燥","长期随访：慢性咽炎易反复，每3-6个月评估，调整治疗，避免长期滥用药物","喉镜复查：症状持续不缓解或加重（尤其声音嘶哑、吞咽困难、痰血），需复查喉镜排除肿瘤","出现进行性吞咽困难、声音嘶哑持续不缓解、痰中带血、颈部肿块、体重下降、咯血：及时就诊（排除咽喉部和食管肿瘤）","反流症状（反酸、烧心、嗳气、夜间咳嗽）：评估LPR，PPI诊断性治疗","过敏症状（咽痒、阵发性咳嗽、打喷嚏、流清涕）：评估过敏性咽炎，抗过敏治疗"],"special_populations":["老年人：需警惕咽喉部和食管肿瘤，症状持续不缓解必须喉镜+胃镜检查，萎缩性咽炎多见，注意营养和水分","儿童：慢性咽炎少见，多与鼻后滴漏、腺样体肥大、过敏、反复呼吸道感染有关，治疗原发病为主，避免刺激性药物和含片（误吸风险）","孕妇：避免使用碘含片、某些中成药，以生活方式调整和安全的局部治疗为主，PPI需医生评估（相对安全）","用嗓职业者（教师、歌手、销售）：注意嗓音训练和用嗓卫生，避免过度用嗓，定期喉镜检查","胃食管反流患者：LPR是慢性咽炎重要原因，需规范PPI治疗8-12周，同时生活方式调整，不可只按普通咽炎治疗","过敏体质者：合并过敏性鼻炎、哮喘，需同时抗过敏治疗，避免过敏原","吸烟饮酒者：烟酒是慢性咽炎重要诱因，且增加咽喉肿瘤风险，必须戒烟限酒，症状持续需排查肿瘤","免疫低下者（糖尿病、激素、HIV）：感染易反复，需控制基础病，增强免疫","焦虑抑郁患者：咽部异物感可能与心理因素相关，需心理评估，抗焦虑治疗有效，避免反复检查和过度医疗","长期在粉尘/有害气体环境工作者：职业防护（口罩、净化器），定期体检，必要时调整工作环境"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 慢性咽炎诊治指南（2024）","2023 EAN慢性咳嗽和咽喉反流指南","AAO-HNS嗓音疾病指南"]},{"name":"急性会厌炎诊治指南（2024）","category":"耳鼻喉科","scope":"成人和儿童急性会厌炎（急性声门上喉炎）的诊断、气道管理和治疗。","diagnosis":["临床表现：剧烈咽痛（吞咽时加重，致吞咽困难、流涎）、呼吸困难（吸气性呼吸困难，伴喘鸣）、声音改变（含糊不清，如\"含物音\"，但声音嘶哑不明显）、发热（高热）、烦躁不安（儿童）、颈淋巴结肿大","体征：急性病容、流涎、张口呼吸、吸气性三凹征（胸骨上窝、锁骨上窝、肋间隙凹陷）、发绀（严重缺氧）、颈部压痛（舌骨和甲状软骨处）","辅助检查：间接喉镜/电子喉镜（会厌红肿如樱桃，或苍白水肿，杓会厌襞肿胀，是确诊关键，但儿童检查可能诱发窒息，需做好气道准备）、颈部侧位X线（会厌肿大呈\"拇指征\"，咽腔缩小，不适合呼吸困难严重者）、血常规（白细胞升高、中性粒比例升高）、血气分析（评估缺氧和CO2潴留）、血培养（可能阳性，流感嗜血杆菌等）","诊断：剧烈咽痛+吞咽困难+呼吸困难+含物音，喉镜见会厌红肿即可确诊，是耳鼻喉科急症","鉴别：急性喉气管支气管炎（儿童，声嘶犬吠样咳嗽，喉镜见声带和声门下肿胀）、咽后壁脓肿（儿童，张口受限、颈部后仰、咽后壁隆起）、白喉（假膜，现已少见）、异物吸入（突发呛咳，异物史）、扁桃体周围脓肿（张口受限、扁桃体周围隆起）、过敏/血管神经性水肿（突发，无发热，有过敏史）、喉痉挛","高危因素：儿童（2-6岁多见，流感嗜血杆菌B型，疫苗普及后减少）、成人（近年增多，多为链球菌、葡萄球菌、病毒）、免疫缺陷、糖尿病、外伤（异物、热损伤）、吸烟","并发症：窒息（最危险，会厌肿胀堵塞气道）、纵隔炎、颈深部感染、肺炎、脓毒症、死亡"],"staging":["按病情严重程度：轻度（咽痛吞咽困难，无呼吸困难）、中度（有吸气性呼吸困难，能平卧，烦躁）、重度（明显呼吸困难，发绀，不能平卧，意识改变，需紧急气道）","按年龄：儿童急性会厌炎（起病急，进展快，易窒息）、成人急性会厌炎（症状相对轻，但也可突然恶化）","按病因：感染性（细菌：流感嗜血杆菌、链球菌、葡萄球菌；病毒）、非感染性（过敏、外伤、热损伤、化学刺激）","按病程：急性（数小时至数天）、暴发性（数小时内迅速进展致窒息）","气道梗阻分度：I度（安静时无呼吸困难，活动后有）、II度（安静时有吸气性呼吸困难，无烦躁）、III度（呼吸困难+烦躁发绀）、IV度（严重缺氧+昏迷/濒死）"],"key_points":["气道管理是首要任务（关键！）：所有患者均需做好紧急气管插管/气管切开准备，密切观察呼吸","轻度（I-II度呼吸困难）：密切监护（心电血氧）、半卧位、吸氧、雾化吸入（布地奈德+肾上腺素，减轻水肿）、静脉抗生素+糖皮质激素，做好气道准备，可在床旁备气管插管包和气管切开包","中重度（III度以上）：立即气管插管（首选，经口或经鼻，选择较细导管，避免刺激会厌），插管困难时紧急环甲膜穿刺或气管切开，不可因检查延误气道建立","儿童：避免刺激（不要强行喉镜检查、不要让患儿平卧、不要抽血挣扎），保持坐位或半卧位，吸氧，立即请麻醉科和耳鼻喉科准备气道，必要时直接入手术室插管","抗生素：广谱抗生素覆盖流感嗜血杆菌、链球菌、葡萄球菌，三代头孢（头孢曲松、头孢噻肟）+阿莫西林克拉维酸，或根据药敏调整，疗程7-10天","糖皮质激素：地塞米松10-20mg静推（成人）或0.3-0.5mg/kg（儿童），或甲泼尼龙40-80mg静滴，减轻会厌水肿，可重复，是治疗重要组成部分","雾化吸入：布地奈德2mg+肾上腺素1mg雾化，每15-30分钟一次，快速减轻水肿，适用于轻度至中度","补液和营养：吞咽困难者静脉补液，纠正脱水和电解质，必要时鼻饲（气道建立后）","对症：退热（对乙酰氨基酚，避免阿司匹林）、镇静（烦躁者，避免抑制呼吸，可用水合氯醛）、避免使用镇静剂（可能抑制呼吸，除非已建立人工气道）","手术：会厌脓肿形成者在气道保护下切开引流；紧急气管切开（插管失败或窒息时）","住院监护：所有急性会厌炎均应住院（最好ICU），至少观察24-48小时，因病情可能突然恶化","预防：流感嗜血杆菌B型疫苗（Hib，儿童常规接种，显著降低儿童会厌炎），成人高危者可考虑"],"drug_recommendations":[],"non_pharmacological":["体位：半卧位或坐位（减轻呼吸困难），避免平卧（加重气道阻塞），儿童保持舒适体位（家长怀抱），避免哭闹挣扎（加重缺氧）","保持气道通畅：专人看护，密切观察呼吸频率、节律、血氧、面色、意识，床旁备气管插管包、气管切开包、吸引器、氧气，避免一切可能刺激患者的操作（强行检查、抽血、约束）","吸氧：湿化氧气吸入，维持血氧饱和度大于95%，避免高浓度氧导致CO2麻醉（COPD者）","饮食：急性期禁食（吞咽困难+误吸风险），静脉补液保证营养和水分，气道建立后可鼻饲，症状缓解后逐渐进温凉流质","口腔护理：禁食期间口腔护理，保持清洁，预防感染","用药护理：抗生素按时足量，激素注意不良反应（血糖、血压、胃肠道），雾化后清洁面部（激素）","观察病情：每15-30分钟评估呼吸、心率、血氧、意识，出现呼吸困难加重、烦躁、发绀、大汗、意识改变立即报告（需紧急气道）","心理护理：患者和家属紧张恐惧，需解释病情和治疗，安抚情绪，避免患者激动（加重耗氧）","出院指导：按医嘱完成抗生素疗程，戒烟酒，避免辛辣刺激，增强体质预防感冒，出现咽痛加重、呼吸困难立即就诊（可能复发）","疫苗接种：儿童按程序接种Hib疫苗，成人有基础病者可咨询医生接种"],"complications":["窒息/气道梗阻：最严重并发症，会厌肿胀迅速堵塞声门，可在数分钟内致窒息死亡，是急性会厌炎的主要死因，需紧急气道建立","纵隔炎：感染向下蔓延至纵隔，高热、胸痛、呼吸困难，CT确诊，需广谱抗生素和引流","颈深部脓肿/咽旁间隙感染：感染扩散，颈部肿胀压痛，需切开引流","肺炎：分泌物误吸或感染下行，咳嗽咳痰，需抗生素和排痰","脓毒症/感染性休克：严重感染致全身炎症反应，低血压、多器官功能障碍，需抢救（液体复苏、广谱抗生素、血管活性药）","会厌脓肿：会厌局部化脓，需在气道保护下切开引流，脓肿破裂可致窒息和误吸","声带肉芽肿/粘连：炎症和插管后并发症，影响发声","气管切开并发症：出血、气胸、纵隔气肿、套管脱出、皮下气肿、感染、拔管困难","药物不良反应：激素致血糖血压升高、感染扩散、胃肠道出血；抗生素致过敏、肠道菌群紊乱","死亡：延误气道管理是主要原因，所有急性会厌炎均应按急症处理，做好气道准备"],"monitoring":["急诊评估：立即评估气道（呼吸困难程度、血氧、意识），不要因检查（喉镜、X线、抽血）延误气道，床旁备气道设备","确诊后：立即住院（ICU或耳鼻喉重症病房），心电血氧监护，建立静脉通路，抗生素+激素+雾化","治疗期间：每15-30分钟监测生命体征和血氧，每4-6小时评估会厌肿胀（喉镜，气道保护下），复查血常规、CRP","气道建立后：呼吸机管理，镇静镇痛，气道湿化，吸痰，预防感染，定期评估拔管时机（会厌水肿消退，自主呼吸好）","拔管前：喉镜评估会厌肿胀消退，堵管试验，拔管后继续观察24-48小时（可能再水肿）","出院前：评估吞咽功能、发声、呼吸，完成抗生素疗程，复查血常规","出院后：1-2周复查喉镜（评估会厌恢复），有基础病者控制基础病，接种疫苗","出现咽痛剧烈、吞咽困难、流涎、呼吸不畅、含物音：立即急诊（急性会厌炎可能，不要在家观察）","治疗后仍有吞咽困难、声音改变：复查喉镜（排除脓肿、粘连、肿瘤）"],"special_populations":["儿童（2-6岁）：起病急进展快，易窒息，避免刺激（不强行检查、不平卧、不挣扎抽血），保持坐位，立即准备气道，Hib疫苗普及后发病率显著下降","老年人：症状不典型，反应差，呼吸困难可能不明显但病情重，需密切监护，合并症多（糖尿病、心肺病），预后差","糖尿病患者：感染不易控制，易形成脓肿，需控制血糖，广谱抗生素，密切观察","免疫抑制患者（激素、移植、HIV）：感染进展快，病原体多样（包括真菌），需更积极治疗和广覆盖，预后差","孕妇：用药需考虑胎儿安全（头孢类安全，激素需评估），气道管理需产科和麻醉科协作","成人会厌炎：近年增多，多为链球菌/葡萄球菌，症状相对轻但也可突然恶化，不可轻视，均应住院观察","已行气管插管/切开者：按人工气道护理，预防感染和并发症，尽早拔管","过敏/血管神经性水肿所致：无发热，突发，需肾上腺素（肌注）+抗组胺药+激素，避免过敏原","有异物/热损伤史者：会厌损伤致水肿，按会厌炎处理，同时处理异物","呼吸困难已缓解者：仍需住院观察至少24-48小时，因会厌水肿可能反复"],"references":["中华医学会耳鼻咽喉头颈外科学分会. 急性会厌炎诊治指南（2024）","2023 EAN急性上气道梗阻指南","AAO-HNS急性会厌炎管理指南"]},{"name":"手足口病诊治指南（2024）","category":"儿科","scope":"儿童手足口病（HFMD）的诊断、分型、治疗和重症识别。","diagnosis":["临床表现：发热（多为中低热，部分高热）、口腔黏膜疱疹/溃疡（舌、颊黏膜、硬腭，疼痛致流涎拒食）、手足臀皮疹（斑丘疹→疱疹，圆形椭圆形，周围红晕，疱内液体少，不痛不痒，结痂后不留瘢痕）","潜伏期：2-10天，平均3-5天","病程：一般7-10天自愈，皮疹消退不留瘢痕","重症警示征（3岁以下、病程5天内高危）：持续高热（大于39℃超过3天）、神经系统症状（精神差、嗜睡、易惊、头痛、呕吐、肢体抖动、肌无力、颈项强直）、呼吸异常（呼吸增快、减慢或节律不齐）、循环障碍（心率增快、出冷汗、四肢末梢发凉、血压升高或降低）、外周血白细胞升高（大于15×10^9/L）、血糖升高（大于8.3mmol/L）","病原：肠道病毒（柯萨奇病毒A16、A6、A10，肠道病毒71型EV71），EV71易致重症","辅助检查：血常规（白细胞正常或升高，重症白细胞和中性粒升高）、血生化（血糖升高、心肌酶升高、肝酶升高）、血气分析（重症代谢性酸中毒）、脑脊液（重症神经系统受累，白细胞轻度升高，蛋白正常或轻度升高，糖正常）、病原学（咽拭子/粪便/疱疹液核酸检测，EV71阳性提示重症风险）、胸片（重症肺水肿/肺炎，双肺纹理增多、斑片影）、心电图/心脏超声（重症心肌损害、心功能不全）、脑电图（重症脑炎异常）","鉴别：疱疹性咽峡炎（仅口腔疱疹，无手足皮疹）、水痘（向心性分布，瘙痒，四世同堂）、丘疹性荨麻疹（瘙痒，风团样，无口腔疱疹）、口蹄疫（动物接触史，成人，罕见）、脓疱疹（细菌感染，脓疱蜜黄色痂）","传播：粪-口途径、呼吸道飞沫、接触患者分泌物/疱疹液，托幼机构易暴发，5岁以下儿童高发"],"staging":["按病情：普通型（发热+手足口腔疱疹，精神好，无重症征象，占90%以上）、重型（出现神经系统受累，如脑炎、脑膜炎、脊髓炎）、危重型（出现心肺功能衰竭，肺水肿、循环衰竭，可致死）","按病程：出疹期（1-3天，发热皮疹）、神经系统受累期（1-5天，重症）、心肺功能衰竭前期（心率快、血压高、血糖高、四肢凉）、心肺功能衰竭期（肺水肿、休克、昏迷）、恢复期","按病原：EV71型（重症率高，需警惕）、柯萨奇A16型（多为普通型）、其他型（A6、A10等，A6可致大疱和脱甲）","按年龄：小于3岁（重症高危）、3-5岁、大于5岁（重症少）","特殊表现：EV71相关重症（脑干脑炎、神经源性肺水肿、循环衰竭，死亡率高）、A6相关重症（大疱性皮损、脱甲、发热时间长）"],"key_points":["治疗原则：普通型对症支持治疗，重症早期识别及时转诊，危重型积极抢救","普通型：隔离（自发病起隔离2周，避免去托幼机构）、休息、多饮水、清淡温凉流质/半流质（避免辛辣烫刺激，口腔痛）、对症退热（对乙酰氨基酚10-15mg/kg/次或布洛芬5-10mg/kg/次，避免阿司匹林）、口腔护理（生理盐水漱口，口腔溃疡用康复新液、锡类散，疼痛明显者餐前用利多卡因凝胶涂抹）、皮疹护理（保持清洁，避免搔抓，疱疹破溃涂碘伏）、不推荐常规抗病毒（利巴韦林不常规用，可考虑干扰素α喷雾/雾化）","重症（神经系统受累）：立即住院，降颅压（甘露醇0.5-1g/kg q4-8h，注意水电解质）、糖皮质激素（甲泼尼龙1-2mg/kg/d，重症冲击10-20mg/kg/d×3天）、静脉用免疫球蛋白（IVIG，1g/kg/d×2天或2g/kg单次，用于重症）、密切监测生命体征、控制入量","危重型（心肺功能衰竭）：ICU抢救，保持呼吸道通畅、吸氧/机械通气（肺水肿时正压通气）、循环支持（扩容、血管活性药如米力农/多巴胺/去甲肾上腺素）、控制颅内压、抑制交感风暴（米力农、酚妥拉明）、保护重要脏器、纠正酸中毒和电解质紊乱、监测血糖（高血糖用胰岛素）","抗病毒：EV71感染重症可考虑早期使用利巴韦林（证据有限），干扰素α喷雾/雾化（早期，抑制病毒复制），不推荐阿昔洛韦（对肠道病毒无效）","抗生素：仅在合并细菌感染时使用，不常规预防","中医中药：清热解毒类中成药（蒲地蓝、蓝芩、小儿豉翘清热颗粒，辅助），需辨证","预防：EV71灭活疫苗（6月龄-5岁儿童接种，预防EV71所致重症手足口病，保护率90%以上，基础免疫2剂间隔1个月）、勤洗手、注意饮食卫生、流行期避免去人群密集场所、托幼机构发现病例及时隔离报告","恢复期：逐渐恢复正常饮食和活动，脱甲（A6感染后1-2月出现指甲脱落，可自愈，补充维生素），无需特殊治疗"],"drug_recommendations":[],"non_pharmacological":["隔离：自发病起隔离2周（至症状消失、皮疹结痂），避免去幼儿园、学校和人群密集场所，避免与其他儿童接触，家中注意通风和消毒","饮食：因口腔疱疹疼痛，给予温凉、细软、清淡的流质或半流质（牛奶、米汤、粥、蛋羹），避免辛辣、过烫、酸性、坚硬食物，少量多餐，保证水分和营养，拒食脱水者需静脉补液","口腔护理：饭后用温水或生理盐水漱口，婴幼儿用棉签蘸生理盐水清洁口腔，口腔溃疡可涂康复新液、锡类散或利多卡因凝胶（餐前15分钟涂，减轻疼痛利于进食），避免使用刺激性漱口水","皮疹护理：保持皮肤清洁干燥，穿宽松柔软棉质衣物，勤剪指甲（避免抓破疱疹），疱疹未破不需涂药，破溃后涂碘伏或抗生素软膏预防感染，臀部皮疹及时更换尿布保持干燥","发热护理：物理降温（温水擦浴，避免酒精擦浴），体温大于38.5℃或因发热不适用退热药（对乙酰氨基酚或布洛芬），多饮水，监测体温，高热不退及时就诊","观察病情：密切观察精神状态、体温、呼吸、心率、面色、四肢温度，尤其发病5天内（重症高发期），出现重症警示征立即急诊","用药护理：按医嘱用药，不自行用抗生素和抗病毒药，注意药物不良反应，退热药间隔4-6小时，24小时不超过4次","消毒：患者粪便、疱疹液、呼吸道分泌物具传染性，玩具、餐具、衣物煮沸或含氯消毒剂消毒，照顾者接触患儿后洗手","预防接种：6月龄-5岁儿童接种EV71疫苗，可有效预防EV71所致重症手足口病，鼓励适龄儿童接种","心理护理：患儿因口腔疼痛和发热易烦躁，家长需耐心安抚，避免焦虑，解释疾病自限性和重症识别"],"complications":["重症/危重症：神经系统受累（脑炎、脑干脑炎、无菌性脑膜炎、急性弛缓性麻痹）、心肺功能衰竭（神经源性肺水肿、循环衰竭），是手足口病主要死亡原因，EV71感染重症率和死亡率高","神经源性肺水肿：重症EV71感染致交感神经兴奋，肺毛细血管通透性增加，突发呼吸困难、发绀、粉红色泡沫痰，需正压通气和抑制交感","循环衰竭：面色苍灰、四肢发凉、指（趾）端发绀、血压下降、心率快或慢，需循环支持","脑炎/脑干脑炎：精神差、嗜睡、易惊、肢体抖动、肌无力、眼球运动障碍、吞咽困难，严重者昏迷呼吸停止","急性弛缓性麻痹：类似脊髓灰质炎，肢体无力，需与脊髓炎鉴别，部分遗留后遗症","心肌损害：心肌酶升高、心电图异常、心功能不全，需保护心肌","脱水/电解质紊乱：口腔痛拒食致摄入不足，发热呕吐致丢失，需补液纠正","继发细菌感染：疱疹破溃后皮肤感染、肺炎，需抗生素","脱甲病：A6型感染后1-2月出现指甲/趾甲脱落，无痛，可自愈（数月后新甲长出），不需特殊治疗，补充维生素","死亡：危重型心肺功能衰竭若抢救不及时可致死，EV71流行年死亡率较高，早期识别重症是关键"],"monitoring":["诊断时：血常规、血生化（血糖、心肌酶、肝酶）、C反应蛋白、病原学（咽拭子/粪便核酸，明确型别）、必要时脑脊液（神经系统受累）、胸片/心电图（重症）","普通型：居家隔离观察，每日评估精神、体温、饮食、皮疹，出现重症警示征立即就诊","重症住院：持续心电血氧监护，每1-4小时评估意识、瞳孔、呼吸、心率、血压、四肢末梢温度、尿量，复查血气、血糖、电解质、心肌酶","甘露醇治疗：监测肾功能、电解质、渗透压，避免外渗（组织坏死），注意出入量","IVIG治疗：观察过敏反应（发热、皮疹、过敏性休克），输注速度先慢后快","危重型ICU：持续监测生命体征、有创血压、中心静脉压、血气、血糖，机械通气者监测气道和呼吸机参数","恢复期：1-2周复查精神、食欲、皮疹消退、肢体活动（有无肌无力），脱甲者观察指甲恢复","出院后：隔离至发病后2周，休息1-2周，逐渐恢复正常活动和饮食，有神经系统受累者定期随访神经功能","出现持续高热不退、精神差嗜睡、易惊肢体抖动、呼吸心率快、出冷汗四肢凉、面色苍灰、呕吐频繁：立即急诊（重症警示，不要拖延）","接种疫苗后：观察局部和全身反应（发热、接种部位红肿），一般轻微，严重过敏及时就诊"],"special_populations":["小于3岁婴幼儿：重症高危，发病5天内需密切观察，出现精神差、易惊、肢体抖动、呼吸心率快立即就诊，不要在家观察","3-5岁儿童：重症相对少，但仍需观察，托幼机构发现病例及时隔离报告","新生儿/小婴儿：少见但病情重，可无典型皮疹，表现为发热、精神差、吃奶差，需警惕，及时就医","成人：多为隐性感染或轻症，可照顾患儿，但免疫低下者也可重症，注意防护","孕妇：感染后对胎儿影响有限，但需避免接触患儿，注意手卫生","免疫低下儿童（激素、免疫抑制、HIV）：重症风险高，需更积极治疗和住院观察","有基础疾病儿童（先心病、肺病、神经系统疾病）：重症风险高，需密切观察，及时住院","EV71阴性但有重症表现：仍按重症处理（其他型别也可致重症），不要因病原阴性放松警惕","A6型感染：皮疹较重（大疱、广泛分布）、发热时间长、后期脱甲，但重症率低，需皮肤护理，不必过度紧张","托幼机构聚集性发病：及时隔离患儿、消毒环境、报告疾控，必要时停课，密切接触儿童观察"],"references":["中华医学会儿科学分会. 手足口病诊疗指南（2024）","国家卫健委手足口病诊疗指南（2018版）","WHO手足口病临床管理指南"]},{"name":"脓毒症与脓毒症休克诊治指南（2024）","category":"急诊科","scope":"成人脓毒症、脓毒症休克的早期识别、集束化治疗和器官功能支持。","diagnosis":["脓毒症：感染引起的危及生命的器官功能障碍，SOFA评分≥2分","脓毒症休克：脓毒症+需血管活性药维持MAP≥65mmHg+乳酸>2mmol/L","qSOFA快速筛查：呼吸≥22次/分、意识改变、收缩压≤100mmHg","血乳酸≥2mmol/L提示组织低灌注，需重复检测","感染源：肺部最常见（约40%），其次腹腔、泌尿系、皮肤软组织、导管相关"],"staging":["脓毒症：感染+SOFA≥2","脓毒症休克：脓毒症+血管活性药+乳酸>2","多器官功能障碍综合征（MODS）：2个以上器官功能障碍","按严重程度：普通脓毒症、严重脓毒症（旧称）、脓毒症休克"],"key_points":["1小时集束化（1-hour bundle）：测乳酸、留取血培养、广谱抗生素、晶体液30ml/kg（低血压或乳酸≥4）、血管活性药（低血压不纠正时）","抗生素：留取培养后1小时内使用，经验性广谱覆盖G+G-厌氧菌，降钙素原指导降阶梯","液体复苏：晶体液首选（平衡盐液），30ml/kg于3小时内输入，避免过量","血管活性药：去甲肾上腺素首选（0.05-1μg/kg/min），目标MAP≥65mmHg","糖皮质激素：充分液体复苏+血管活性药后仍休克，加氢化可的松200mg/d","控制感染源：6-12小时内明确并控制感染源（引流、清创、拔管）","器官支持：机械通气（肺保护策略VT6-8ml/kg）、肾替代治疗、血糖控制8-10mmol/L"],"drug_recommendations":["经验性抗生素：哌拉西林他唑巴坦4.5g q6h、美罗培南1g q8h、头孢吡肟2g q8h","MRSA高危：加万古霉素15mg/kg q12h或利奈唑胺600mg q12h","念珠菌高危：加卡泊芬净70mg负荷后50mg/d或米卡芬净100mg/d","去甲肾上腺素：0.05-1μg/kg/min静脉泵入，首选升压药","血管加压素：0.03U/min，可减少去甲肾上腺素用量","氢化可的松：200mg/d静脉泵入，休克纠正后逐渐减量","多巴酚丁胺：心功能不全或心输出量低时加用2-20μg/kg/min"],"non_pharmacological":["早期识别：qSOFA筛查，高危患者立即启动集束化治疗","监测：有创动脉压、中心静脉压、心输出量、乳酸动态监测","感染源控制：脓肿引流、坏死组织清创、感染导管拔除、梗阻解除","营养支持：血流动力学稳定后24-48小时内启动肠内营养","血糖控制：目标8-10mmol/L，避免低血糖","深静脉血栓预防：低分子肝素+机械预防"],"complications":["急性呼吸窘迫综合征（ARDS）：肺保护通气，PEEP滴定，俯卧位通气（PaO2/FiO2<150）","急性肾损伤：避免肾毒性药物，液体复苏，必要时CRRT","弥散性血管内凝血（DIC）：补充凝血因子，血小板<1万或<5万伴出血输注","应激性溃疡：PPI预防，有出血风险者使用","多器官功能衰竭：综合器官支持，必要时ECMO"],"monitoring":["生命体征：持续心电监护，每15-30分钟测血压心率","乳酸：初始、2小时、6小时复查，目标2小时下降≥20%","尿量：目标≥0.5ml/kg/h","血气分析：定期复查，评估氧合和酸碱平衡","降钙素原：指导抗生素降阶梯和停药","SOFA评分：每日评估器官功能"],"special_populations":["老年：临床表现不典型，体温可能不高，白细胞可能不高，注意意识改变","免疫抑制：感染表现隐匿，尽早经验性广谱抗感染","孕妇：注意胎儿安全，避免致畸药物，感染可诱发早产","肿瘤化疗后：粒缺伴发热，立即广谱抗生素，G-CSF支持"]},{"name":"急性心力衰竭诊治指南（2024）","category":"急诊科","scope":"成人急性心力衰竭（急性左心衰、急性右心衰、心源性休克）的诊断和抢救治疗。","diagnosis":["典型表现：突发呼吸困难、端坐呼吸、咳粉红色泡沫痰、大汗、烦躁","体征：双肺湿啰音、心率增快、S3奔马律、血压升高或降低、颈静脉怒张","BNP/NT-proBNP：BNP<100pg/ml或NT-proBNP<300pg/ml基本排除心衰","心电图：排查急性心梗、心律失常","胸片：肺淤血、肺水肿、心影增大","心脏超声：评估LVEF、瓣膜功能、舒张功能","鉴别：急性呼吸窘迫综合征、重症肺炎、哮喘急性发作、肺栓塞"],"staging":["Killip分级：I级无心衰、II级肺部啰音<50%、III级肺水肿、IV级心源性休克","按分型：急性左心衰（最常见）、急性右心衰、全心衰","按血压：高血压型（血压高，最常见）、正常血压型、低血压型（心源性休克）","按病程：急性新发、慢性心衰急性失代偿"],"key_points":["体位：端坐位，双腿下垂，减少回心血量","吸氧：鼻导管或面罩，SpO2目标≥90%，必要时无创通气（BiPAP）或气管插管","利尿：呋塞米20-40mg静推，既往用利尿剂者加倍，注意电解质和肾功能","扩血管：硝酸甘油0.5mg舌下或5-10μg/min静泵（收缩压>110mmHg时），降低前后负荷","吗啡：3mg静推，镇静减少耗氧（低血压、呼吸抑制慎用）","正性肌力药：低血压或低灌注时用多巴酚丁胺2-20μg/kg/min或米力农","血管活性药：心源性休克用去甲肾上腺素0.05-1μg/kg/min维持MAP≥65","病因治疗：急性心梗急诊PCI，高血压急症降压，心律失常转复","超滤：利尿剂抵抗或肾功能不全时可用"],"drug_recommendations":["呋塞米：20-40mg静推，最大单次160-200mg，可持续泵入5-40mg/h","硝酸甘油：5-10μg/min起始，每5分钟增加5-10μg，目标收缩压下降10-20%","硝普钠：0.3-1μg/kg/min，适用于高血压合并心衰，避光使用，<72小时防氰化物中毒","吗啡：2.5-5mg静推，必要时15分钟重复，总量<15mg","多巴酚丁胺：2-20μg/kg/min，适用于低心排血量","米力农：50μg/kg负荷10min，后0.375-0.75μg/kg/min，适用于难治性心衰","去甲肾上腺素：0.05-1μg/kg/min，心源性休克首选升压药","重组人脑利钠肽（新活素）：1.5μg/kg负荷，后0.0075-0.015μg/kg/min，扩血管利尿"],"non_pharmacological":["无创通气：BiPAP模式，IPAP15-25cmH2O，EPAP5-10cmH2O，适用于呼吸窘迫","气管插管：呼吸衰竭、意识障碍、无创通气无效时","IABP：心源性休克、急性心梗合并机械并发症","ECMO：难治性心源性休克，作为桥梁过渡","血液超滤：利尿剂抵抗、容量过负荷","限制液体入量，记24小时出入量"],"complications":["心源性休克：收缩压<90mmHg+组织低灌注，正性肌力药+血管活性药，必要时IABP/ECMO","恶性心律失常：室速室颤立即电除颤，胺碘酮抗心律失常","急性肾损伤：利尿剂抵抗，调整剂量，必要时CRRT","电解质紊乱：低钾低镁易诱发心律失常，及时纠正","呼吸衰竭：无创或有创通气支持"],"monitoring":["生命体征：持续心电监护，每15分钟测血压心率呼吸","尿量：目标≥0.5ml/kg/h，评估灌注","BNP/NT-proBNP：动态监测评估疗效","电解质：每日监测钾钠氯钙镁","肾功能：每日监测肌酐尿素氮","体重：每日同一时间称重，评估容量状态"],"special_populations":["老年：肾功能减退，利尿剂从小剂量开始，注意电解质","右心衰为主：慎用利尿剂和扩血管药，注意补液维持前负荷","瓣膜病：二尖瓣狭窄慎用扩血管药，主动脉瓣狭窄禁用扩血管药","肥厚型心肌病：禁用硝酸甘油和正性肌力药"]},{"name":"急性ST段抬高型心肌梗死诊治指南（2024）","category":"急诊科","scope":"成人急性ST段抬高型心肌梗死（STEMI）的早期识别、再灌注治疗和二级预防。","diagnosis":["典型症状：胸骨后压榨样疼痛>20分钟，向左肩背下颌放射，含服硝酸甘油不缓解，伴大汗、恶心、濒死感","心电图：相邻2个导联ST段抬高（胸导≥0.2mV，肢导≥0.1mV），或新发左束支传导阻滞","心肌损伤标志物：肌钙蛋白（cTnI/cTnT）升高，肌红蛋白早期升高，CK-MB有动态变化","定位诊断：前壁（V1-V4）、下壁（II III aVF）、高侧壁（I aVL）、正后壁（V7-V9）、右室（V3R-V5R）","鉴别：主动脉夹层、肺栓塞、急性心包炎、急腹症、张力性气胸"],"staging":["按时间：超急性期（<2h）、急性期（2h-7d）、亚急性期（7d-28d）、陈旧期（>28d）","按Killip分级：I-IV级（评估心衰程度）","按梗死部位：前壁、下壁、后壁、右室、高侧壁、广泛前壁","按再灌注策略：直接PCI、溶栓、CABG"],"key_points":["时间就是心肌：首次医疗接触（FMC）到导丝通过病变≤90分钟（直接PCI），或FMC到溶栓≤30分钟","再灌注治疗：发病12小时内直接PCI首选；12-24小时仍有症状或血流动力学不稳定也可PCI；>24小时稳定者择期PCI","溶栓：无法在120分钟内PCI时，发病<12小时无禁忌证可溶栓（尿激酶150万U/30min，阿替普酶50mg/60min）","抗血小板：阿司匹林300mg嚼服+替格瑞洛180mg或氯吡格雷600mg负荷","抗凝：普通肝素60U/kg负荷后12U/kg/h，或低分子肝素（依诺肝素1mg/kg q12h）","镇痛：吗啡2-4mg静推，注意低血压和呼吸抑制","吸氧：SpO2<90%时吸氧","β阻滞剂：无禁忌24小时内口服美托洛尔，降低死亡率","ACEI/ARB：无禁忌24小时内开始，前壁心梗或LVEF≤40%强烈推荐","他汀：高强度他汀（阿托伐他汀40-80mg或瑞舒伐他汀20-40mg）"],"drug_recommendations":["阿司匹林：300mg嚼服负荷，后75-100mg qd长期","替格瑞洛：180mg负荷，后90mg bid，至少12个月","氯吡格雷：600mg负荷，后75mg qd（替格瑞洛禁忌时）","普通肝素：60U/kg静推（最大4000U），后12U/kg/h泵入，APTT目标1.5-2倍","依诺肝素：1mg/kg皮下q12h（eGFR≥30），eGFR<30减为qd","吗啡：2-4mg静推，必要时5-15分钟重复","美托洛尔：25-50mg q6-8h口服，稳定后改缓释片95mg qd","阿托伐他汀：40-80mg qn，或瑞舒伐他汀20-40mg qn","硝酸甘油：5-10μg/min泵入，下壁右室心梗慎用（依赖前负荷）"],"non_pharmacological":["绝对卧床休息，心电监护，建立静脉通路","直接PCI：球囊扩张+支架植入，首选桡动脉入路","溶栓后PCI：溶栓成功后2-24小时内行冠脉造影+PCI","CABG：左主干病变、三支病变、PCI失败或机械并发症","IABP：心源性休克、机械并发症（室间隔穿孔、乳头肌断裂）","临时起搏：高度房室传导阻滞、症状性心动过缓"],"complications":["心律失常：室颤立即非同步电除颤，室速同步电复律，房室传导阻滞临时起搏","心力衰竭：Killip II-III级利尿扩血管，IV级心源性休克升压+IABP","心脏破裂：游离壁破裂（猝死）、室间隔穿孔（新杂音+心衰）、乳头肌断裂（急性二尖瓣返流）","心室壁瘤：左室重构，附壁血栓，抗凝","梗死后综合征（Dressler）：发热、心包炎、胸膜炎，NSAIDs或激素","血栓栓塞：附壁血栓脱落致脑栓塞、肾栓塞等"],"monitoring":["持续心电监护：警惕恶性心律失常","心肌标志物：入院、6h、12h、24h动态监测","BNP/NT-proBNP：评估心功能","心脏超声：评估LVEF、室壁运动、瓣膜、并发症","血压心率：每15-30分钟监测，稳定后每小时","尿量：评估灌注和心功能"],"special_populations":["老年：症状不典型，出血风险高，抗栓药物减量","糖尿病：症状可能不典型（无痛性心梗），血糖控制目标7.8-10mmol/L","肾功能不全：造影剂肾病风险，术前术后水化，调整抗凝抗血小板剂量","女性：发病年龄晚，症状不典型，预后较差"]},{"name":"急性缺血性脑卒中诊治指南（2024）","category":"急诊科","scope":"成人急性缺血性脑卒中（脑梗死）的早期识别、溶栓取栓治疗和二级预防。","diagnosis":["典型表现：突发一侧肢体无力/麻木、言语不清、口角歪斜、意识障碍、视力丧失、眩晕共济失调","FAST识别：Face面瘫、Arm肢体无力、Speech言语障碍、Time立即就医","NIHSS评分：评估神经功能缺损程度（0-42分）","头颅CT：首选，排除脑出血，脑梗死24小时内可能正常","头颅MRI：DWI序列早期显示梗死灶，弥散受限","CTA/MRA：评估大血管闭塞，指导取栓","鉴别：脑出血、蛛网膜下腔出血、脑肿瘤、低血糖、癔症、偏头痛先兆"],"staging":["按时间：超早期（<6h）、急性期（6h-72h）、恢复期（72h-6月）、后遗症期（>6月）","按OCSP分型：全前循环、部分前循环、后循环、腔隙性","按TOAST分型：大动脉粥样硬化、心源性、小血管、其他原因、不明原因","按严重程度：轻型（NIHSS<5）、中型（5-15）、重型（>15）"],"key_points":["时间就是大脑：发病4.5小时内静脉溶栓（阿替普酶0.9mg/kg，10%静推，90%泵入1h）","大血管闭塞：发病6小时内机械取栓，部分可延长至16-24小时（影像评估）","抗血小板：未溶栓者尽早阿司匹林150-300mg/d，溶栓后24小时复查CT无出血后开始","抗凝：心源性栓塞（房颤）发病后4-14天开始抗凝（华法林或新型口服抗凝药）","他汀：高强度他汀（阿托伐他汀40-80mg），稳定斑块","血压管理：溶栓前<185/110，溶栓后<180/105；未溶栓者>220/120才降压，目标15-20%","血糖：7.8-10mmol/L，避免低血糖","体温：>38℃退热，查找感染源","氧疗：SpO2<94%吸氧","脑水肿：大面积梗死24-72小时高峰，甘露醇降颅压，必要时去骨瓣减压"],"drug_recommendations":["阿替普酶（rt-PA）：0.9mg/kg（最大90mg），10%静推1min，90%泵入1h，发病4.5h内","尿激酶：100-150万U溶于生理盐水100-200ml，30min静滴，发病6h内","替奈普酶：0.25mg/kg静推（最大25mg），适合院前和转运","阿司匹林：150-300mg/d口服或鼻饲，未溶栓者尽早，溶栓后24h开始","氯吡格雷：75mg/d，阿司匹林禁忌或联合（轻型卒中/TIA双抗21天）","阿托伐他汀：40-80mg qn，或瑞舒伐他汀20-40mg qn","甘露醇：125ml q6-8h静滴，脑水肿降颅压，注意肾功能和电解质","依达拉奉：30mg bid静滴，脑保护","丁基苯酞：0.2g tid口服，改善侧支循环"],"non_pharmacological":["机械取栓：大血管闭塞（颈内动脉、大脑中动脉M1/M2），发病6h内，DAWN/DEFUSE3标准可延至16-24h","颈动脉内膜剥脱/支架：症状性颈动脉狭窄>70%，2周内评估","早期康复：生命体征稳定后24-48小时开始，肢体功能位、被动活动","吞咽评估：饮水试验，吞咽困难者鼻饲防误吸","预防深静脉血栓：气压治疗+低分子肝素（卧床者）","心电监护：排查房颤等心律失常"],"complications":["出血转化：溶栓/取栓后症状加重立即复查CT，出血后停用抗栓，必要时手术","脑水肿与脑疝：大面积梗死，甘露醇+高渗盐水，去骨瓣减压","癫痫：卒中后癫痫，左乙拉西坦或丙戊酸钠","肺部感染：吞咽困难误吸，抗感染+排痰","深静脉血栓/肺栓塞：预防为主，低分子肝素","应激性溃疡：PPI预防","肩手综合征：早期康复，避免患肢输液"],"monitoring":["生命体征：每小时监测血压心率呼吸体温","NIHSS评分：入院、溶栓后2h、24h、7天、出院","头颅CT：溶栓/取栓后24h复查，症状加重随时复查","血糖：每4-6小时监测","电解质：每日监测","心电图：持续监护，排查房颤和心肌缺血"],"special_populations":["老年：溶栓出血风险高，严格评估，取栓优先","轻型卒中：NIHSS<5，症状轻微但致残也可溶栓，双抗21天","后循环梗死：取栓时间窗可放宽，预后较差","醒后卒中：DWI-FLAIR不匹配可考虑溶栓（发病<4.5h可能）"]},{"name":"过敏性休克诊治指南（2024）","category":"急诊科","scope":"成人及儿童过敏性休克的识别、抢救治疗和预防。","diagnosis":["接触过敏原后数分钟至数小时内发病，常见过敏原：药物（青霉素、头孢、造影剂）、食物（花生、海鲜、鸡蛋）、昆虫叮咬、乳胶","皮肤黏膜：潮红、瘙痒、荨麻疹、血管性水肿（喉头水肿致声音嘶哑、呼吸困难）","呼吸系统：喉头水肿、支气管痉挛、胸闷、喘息、发绀、呼吸停止","循环系统：血压骤降（收缩压<90mmHg或较基础下降>30%）、 tachycardia、晕厥、心跳骤停","消化系统：恶心呕吐、腹痛腹泻","神经系统：头晕、意识模糊、抽搐、昏迷","诊断标准：接触过敏原+急性起病+皮肤黏膜表现+呼吸/循环受累，或血压下降即可诊断"],"staging":["轻度：皮肤黏膜表现，无呼吸循环受累","中度：轻度呼吸困难或血压下降，意识清楚","重度：严重呼吸困难、发绀、意识障碍、休克","极重度：呼吸心跳骤停"],"key_points":["立即停用/移除过敏原，停止输注可疑药物，更换输液器","肾上腺素：首选！大腿前外侧肌注0.3-0.5mg（成人），儿童0.01mg/kg，5-15分钟可重复","体位：平卧位，下肢抬高，呼吸困难者半卧位","保持气道通畅：高流量吸氧，喉头水肿致窒息立即环甲膜穿刺或气管切开","建立静脉通路：快速补液（生理盐水或乳酸林格液1-2L，10-20ml/kg快速输入）","支气管痉挛：沙丁胺醇雾化吸入","抗组胺药：苯海拉明25-50mg静推或异丙嗪25-50mg肌注（辅助，不能替代肾上腺素）","糖皮质激素：甲泼尼龙125-250mg静推或地塞米松10-20mg静推（预防迟发反应）","升压药：补液后血压仍低，去甲肾上腺素或多巴胺静脉泵入","心跳骤停：立即心肺复苏，肾上腺素1mg静推每3-5分钟"],"drug_recommendations":["肾上腺素：0.3-0.5mg大腿前外侧肌注（成人），5-15分钟重复；静脉1mg（心跳骤停时）","生理盐水：1-2L快速静滴，10-20ml/kg于10-20分钟输入","苯海拉明：25-50mg静推或肌注，H1受体拮抗剂","西咪替丁：300mg静推，H2受体拮抗剂（辅助）","甲泼尼龙：125-250mg静推，或地塞米松10-20mg静推","沙丁胺醇：2.5-5mg雾化吸入，支气管痉挛","去甲肾上腺素：0.05-1μg/kg/min泵入，难治性低血压","多巴胺：5-20μg/kg/min泵入，升压+正性肌力","葡萄糖酸钙：10%葡萄糖酸钙10-20ml缓慢静推（钙过敏时）"],"non_pharmacological":["立即停止接触过敏原，更换输液器和液体","高流量吸氧（8-10L/min），SpO2目标≥94%","气管插管：严重喉头水肿、呼吸衰竭","环甲膜穿刺/切开：窒息且插管困难时紧急开放气道","心电监护，记录生命体征","观察24小时：双相反应（症状缓解后8-10小时复发），留观至少4-6小时"],"complications":["窒息：喉头水肿，紧急气道管理","心跳骤停：立即CPR，肾上腺素静推","急性呼吸窘迫综合征：严重过敏致肺损伤，机械通气","急性肾损伤：休克致肾灌注不足，补液维持","弥散性血管内凝血：严重过敏诱发，补充凝血因子"],"monitoring":["持续心电监护：血压、心率、呼吸、SpO2","每5-15分钟测血压：评估复苏效果","血气分析：评估氧合和酸碱平衡","心电图：排查心肌缺血（过敏可诱发冠脉痉挛）","尿量：评估灌注","血清类胰蛋白酶：发作后1-2小时检测，辅助诊断"],"special_populations":["儿童：肾上腺素0.01mg/kg肌注（最大0.3mg），补液20ml/kg","孕妇：左侧卧位，肾上腺素仍为首选，注意胎儿监测","服用β阻滞剂者：肾上腺素效果差，可加用胰高血糖素1-2mg静推","哮喘患者：支气管痉挛更严重，积极雾化沙丁胺醇"]},{"name":"急性呼吸窘迫综合征（ARDS）诊治指南（2024）","category":"重症医学科","scope":"成人急性呼吸窘迫综合征的诊断、机械通气策略和综合治疗。","diagnosis":["柏林定义：发病1周内、急性起病的呼吸系统症状","胸部影像：双肺浸润影，不能完全用胸腔积液、肺不张或结节解释","肺水肿：不能完全用心衰或液体过负荷解释（无危险因素时需客观评估如心脏超声）","氧合指数（PaO2/FiO2）：轻度200-300（PEEP≥5）、中度100-200、重度<100","常见诱因：肺炎（最常见）、脓毒症、误吸、创伤、胰腺炎、输血相关、溺水","鉴别：心源性肺水肿、重症肺炎、弥漫性肺泡出血、间质性肺病急性加重"],"staging":["轻度：PaO2/FiO2 200-300mmHg（PEEP≥5cmH2O）","中度：PaO2/FiO2 100-200mmHg","重度：PaO2/FiO2 <100mmHg","按病程：渗出期（1-7天）、增生期（7-21天）、纤维化期（>21天）"],"key_points":["肺保护性通气：潮气量6-8ml/kg理想体重，平台压≤30cmH2O","PEEP滴定：根据FiO2-PEEP对照表，或食道压指导，重度ARDS可较高PEEP","俯卧位通气：PaO2/FiO2<150mmHg，每天≥16小时，改善氧合和死亡率","肺复张：中重度ARDS可尝试，注意血流动力学影响","保守液体策略：血流动力学稳定后限制液体，目标CVP<4，减轻肺水肿","神经肌肉阻滞剂：重度ARDS早期（PaO2/FiO2<150）短期使用（<48h），顺阿曲库铵","糖皮质激素：中重度ARDS早期（发病72h内），地塞米松20mg qd×5天后减量，或甲泼尼龙1mg/kg/d","ECMO：重度ARDS常规治疗无效（PaO2/FiO2<80或pH<7.25），VV-ECMO","病因治疗：控制感染、引流、处理原发病","营养支持：早期肠内营养，目标25-30kcal/kg/d"],"drug_recommendations":["顺阿曲库铵：0.3-0.6mg/kg/h泵入，重度ARDS短期使用","地塞米松：20mg qd静推×5天，后10mg qd×3天，中重度ARDS早期","甲泼尼龙：1mg/kg/d静推，逐渐减量，疗程2-4周","丙泊酚：0.5-4mg/kg/h泵入，镇静镇痛，RASS目标-2到-4","右美托咪定：0.2-0.7μg/kg/h，轻度镇静，减少谵妄","芬太尼：0.7-10μg/kg/h泵入，镇痛优先","去甲肾上腺素：0.05-1μg/kg/min，感染性休克合并ARDS","吸入一氧化氮：5-20ppm，难治性低氧血症（不改善死亡率）","前列环素：吸入10-50ng/kg/min，肺血管扩张"],"non_pharmacological":["有创机械通气：肺保护性策略，VT6-8ml/kg，平台压≤30","无创通气：轻度ARDS可尝试，失败及时插管","高流量氧疗（HFNC）：轻度ARDS，FiO2可调节，温湿化","俯卧位通气：中重度ARDS，每天≥16小时","ECMO：VV-ECMO用于重度难治性低氧血症","血液净化：CRRT用于合并肾衰或液体过负荷","气道引流：充分吸痰，预防VAP"],"complications":["呼吸机相关肺损伤（VILI）：气压伤、容积伤、萎陷伤、生物伤","呼吸机相关肺炎（VAP）：每日评估拔管，抬高床头30-45°，口腔护理","气压伤：气胸、纵隔气肿，及时胸腔闭式引流","深静脉血栓：机械通气+卧床高危，低分子肝素预防","谵妄：每日唤醒，减少镇静，早期活动","ICU获得性肌无力：减少神经肌肉阻滞剂和激素，早期康复","肺纤维化：晚期ARDS，预后差"],"monitoring":["血气分析：每4-6小时，评估氧合和酸碱","呼吸力学：潮气量、平台压、PEEP、顺应性、驱动压","血流动力学：有创动脉压、CVP、心输出量、ScvO2","胸片/CT：每日或病情变化时复查","液体平衡：每小时记录，目标负平衡（稳定后）","镇静评分：RASS评分，目标-2到-4"],"special_populations":["老年：肺储备差，预后较差，注意容量管理","免疫抑制：感染诱因多见，预后差，积极抗感染","创伤后ARDS：合并多发伤，注意容量和输血管理","孕产妇：注意胎儿安全，俯卧位受限，必要时终止妊娠"]},{"name":"机械通气临床应用指南（2024）","category":"重症医学科","scope":"成人有创机械通气的指征、模式选择、参数设置、撤机流程和并发症防治。","diagnosis":["通气指征：意识障碍、呼吸频率>35或<8、呼吸肌疲劳、辅助呼吸肌参与、胸腹矛盾运动","氧合指征：面罩吸氧后PaO2<60mmHg或SpO2<90%、PaO2/FiO2<200","酸碱失衡：呼吸性酸中毒pH<7.25","气道保护：咳嗽反射减弱、误吸风险、大量分泌物","常用模式：A/C（辅助控制）、SIMV（同步间歇指令通气）、PSV（压力支持通气）、CPAP","无创通气指征：COPD急性加重、心源性肺水肿、免疫抑制合并呼衰、术后呼衰"],"staging":["按阶段：初始化（参数设置）、稳定期（优化参数）、撤机期（逐渐减参数）、拔管","按通气模式：控制通气、辅助通气、支持通气、自主通气","按氧合状态：轻度、中度、重度呼衰"],"key_points":["插管指征：意识障碍、呼吸衰竭、气道保护能力下降、心跳呼吸骤停","初始参数：潮气量6-8ml/kg理想体重，呼吸频率12-20次/分，FiO2初始100%后下调，PEEP5cmH2O起","目标：SpO2 92-96%（COPD 88-92%），pH 7.30-7.45，平台压≤30，PaCO2逐渐下降（允许性高碳酸血症）","PEEP滴定：根据FiO2-PEEP表，或食道压，ARDS可较高PEEP","触发灵敏度：压力触发-1到-3cmH2O，流量触发1-3L/min","吸呼比：1:1.5到1:2，阻塞性肺病可延长呼气（1:3），限制性可缩短呼气","镇静镇痛：RASS目标-2到0，镇痛优先，每日唤醒","撤机筛查：原发病控制、FiO2≤40%、PEEP≤5、血流动力学稳定、有自主呼吸、咳嗽反射好","SBT试验：PSV 5-8cmH2O或T管，30-120分钟，成功标准：呼吸频率<35、SpO2>90%、心率<140、无辅助呼吸肌","拔管：SBT成功后拔管，高危患者拔管后无创通气序贯"],"drug_recommendations":["丙泊酚：0.5-4mg/kg/h泵入，镇静，起效快，苏醒快","右美托咪定：0.2-0.7μg/kg/h，轻度镇静，减少谵妄，无呼吸抑制","咪达唑仑：0.02-0.1mg/kg/h，长期镇静易蓄积","芬太尼：0.7-10μg/kg/h，镇痛首选","瑞芬太尼：0.05-2μg/kg/min，短效镇痛，适合每日唤醒","顺阿曲库铵：0.3-0.6mg/kg/h，肌松，ARDS或人机对抗","罗库溴铵：0.6-1.2mg/kg静推，插管时用","氢化可的松：应激剂量，撤机困难或肾上腺功能不全"],"non_pharmacological":["气管插管：经口首选，经鼻用于颌面损伤或长期通气","气管切开：预计通气>14天，早期切开（7-10天）可减少VAP和住院时间","气道湿化：加热湿化器或热湿交换器，保证37℃ 44mg/L绝对湿度","吸痰：按需吸痰，密闭式吸痰减少感染","VAP预防：抬高床头30-45°、每日唤醒+拔管评估、口腔护理氯己定、消化性溃疡预防、深静脉血栓预防","早期活动：血流动力学稳定后开始，减少ICU获得性肌无力"],"complications":["呼吸机相关肺炎（VAP）：发热、脓性痰、白细胞升高、新浸润影，经验性抗感染","气压伤：气胸、纵隔气肿、皮下气肿，降低潮气量和平台压，胸腔闭式引流","人机对抗：镇静不足、参数不当、气道阻塞，调整参数、镇静、排查原因","氧中毒：FiO2>60%超过24-48小时，尽快下调FiO2","呼吸机依赖：原发病未控制、呼吸肌萎缩、心理依赖，逐步撤机，康复训练","气管损伤：插管过久致声带麻痹、气管狭窄，气囊压力25-30cmH2O","深静脉血栓：卧床+高凝，低分子肝素预防"],"monitoring":["生命体征：持续心电监护，每小时记录","血气分析：初始每30-60分钟，稳定后每4-8小时","呼吸力学：潮气量、平台压、PEEP、顺应性、auto-PEEP","胸片：插管后立即，之后每日或病情变化","气囊压力：每4小时监测，维持25-30cmH2O","镇静评分：RASS每4小时，调整镇静深度"],"special_populations":["COPD：小潮气量、长呼气、低氧目标（88-92%），避免过度通气致呼碱","ARDS：肺保护性通气6-8ml/kg，俯卧位，高PEEP","哮喘：小潮气量、长呼气、允许性高碳酸血症，避免高气道压","神经外科：维持脑灌注，避免高碳酸血症（增加脑血流），轻度过度通气（PaCO2 30-35）临时降颅压","老年：肺顺应性差，注意气压伤，撤机困难"]},{"name":"脓毒症休克血流动力学管理指南（2024）","category":"重症医学科","scope":"脓毒症休克的血流动力学评估、液体复苏、血管活性药和器官灌注管理。","diagnosis":["脓毒症休克：脓毒症+充分液体复苏后仍需血管活性药维持MAP≥65mmHg+血乳酸>2mmol/L","组织低灌注表现：皮肤花斑、毛细血管再充盈>3秒、意识改变、尿量<0.5ml/kg/h、乳酸升高","血流动力学分型：高动力型（暖休克，心输出量高外周阻力低，最常见）、低动力型（冷休克，心输出量低）","评估手段：有创动脉压、中心静脉压（CVP）、心输出量（脉搏指示连续心输出量PiCCO、超声）、ScvO2、乳酸","液体反应性评估：被动抬腿试验（PLR）、补液试验、脉压变异率（PPV>13%提示有反应）"],"staging":["代偿期：血压正常，心率增快，皮肤湿冷，乳酸轻度升高","失代偿期：血压下降，组织低灌注，乳酸>2mmol/L","难治性休克：大剂量血管活性药仍低血压，多器官功能衰竭","恢复期：血流动力学稳定，逐渐减停血管活性药"],"key_points":["1小时集束化：测乳酸、血培养、广谱抗生素、晶体液30ml/kg、血管活性药（低血压时）","液体复苏：晶体液首选（平衡盐液），30ml/kg于3小时内，评估液体反应性避免过量","MAP目标：≥65mmHg，老年或高血压病史可适当提高","血管活性药：去甲肾上腺素首选，0.05-1μg/kg/min，目标MAP≥65","正性肌力药：心功能不全或低心排时加多巴酚丁胺2-20μg/kg/min","血管加压素：0.03U/min，可减少去甲肾上腺素用量","糖皮质激素：充分液体+血管活性药后仍休克，氢化可的松200mg/d","液体负平衡：组织灌注恢复后（6-12小时），限制液体，目标负平衡","输血：Hb<7g/dl输注，目标7-9g/dl（心梗或不稳定心绞痛<10）","控制感染源：6-12小时内明确并控制"],"drug_recommendations":["去甲肾上腺素：0.05-1μg/kg/min泵入，首选升压药，α受体激动为主","血管加压素：0.03U/min，补充去甲肾上腺素，减少用量","多巴胺：5-20μg/kg/min，心律失常风险高，不推荐首选","多巴酚丁胺：2-20μg/kg/min，正性肌力，低心排时加用","肾上腺素：0.05-0.5μg/kg/min，难治性休克或过敏休克","氢化可的松：200mg/d泵入或50mg q6h，休克纠正后逐渐减量","平衡盐液：乳酸林格液或醋酸林格液，首选复苏液体","白蛋白：大量晶体液后低蛋白血症，可补充4%白蛋白","羟乙基淀粉：不推荐（增加肾损伤和出血风险）"],"non_pharmacological":["有创动脉压监测：持续血压监测，准确指导用药","中心静脉置管：监测CVP，输注血管活性药","被动抬腿试验：评估液体反应性，PLR后心输出量增加>10%提示有反应","PiCCO/超声：评估心功能和容量状态，指导精准治疗","血液净化：CRRT用于合并急性肾损伤或液体过负荷","ECMO：难治性心源性休克或严重呼吸衰竭"],"complications":["急性肾损伤：肾灌注不足+肾毒性药物，避免肾毒性，维持灌注，必要时CRRT","急性呼吸窘迫综合征：炎症反应+液体过负荷，肺保护通气，限制液体","弥散性血管内凝血：补充凝血因子和血小板，低分子肝素预防","应激性心肌病：儿茶酚胺过量，心脏超声评估","肢端缺血坏死：大剂量血管活性药致外周灌注不足，调整剂量","高血糖：应激性高血糖，目标7.8-10mmol/L"],"monitoring":["生命体征：持续有创动脉压、心率、呼吸、SpO2","乳酸：初始、2h、6h复查，目标2h下降≥20%","CVP：目标8-12mmHg（机械通气），指导补液","ScvO2：目标≥70%，评估氧供氧耗平衡","尿量：目标≥0.5ml/kg/h","心输出量：PiCCO或超声监测，指导正性肌力药","毛细血管再充盈时间：<3秒，评估外周灌注"],"special_populations":["老年：动脉硬化，MAP目标可适当提高（70-75），注意心律失常","高血压病史：基础血压高，MAP目标需个体化，避免相对低血压","心源性休克：区别于分布性休克，正性肌力药+IABP/ECMO，避免过度补液","低血容量休克：优先快速补液，血管活性药为辅"]},{"name":"肺癌诊疗指南（2024）","category":"肿瘤科","scope":"原发性支气管肺癌（非小细胞肺癌和小细胞肺癌）的诊断、分期、治疗和随访。","diagnosis":["临床表现：咳嗽（刺激性干咳）、咯血、胸痛、呼吸困难、声音嘶哑、上腔静脉综合征、体重下降","影像学：胸部CT（首选，低剂量CT筛查）、PET-CT（分期）、头颅MRI（排查脑转移）、骨扫描（排查骨转移）","病理诊断：痰脱落细胞、支气管镜活检、经皮肺穿刺、胸腔积液细胞学、淋巴结活检","肿瘤标志物：CEA、CYFRA21-1、NSE、SCC、ProGRP（辅助诊断和监测）","分子检测：EGFR、ALK、ROS1、KRAS、BRAF、MET、RET、HER2、PD-L1表达（指导靶向和免疫治疗）","分期：TNM分期（第8版），非小细胞肺癌I-IV期，小细胞肺癌局限期/广泛期","鉴别：肺结核、肺炎、肺脓肿、纵隔肿瘤、肺转移瘤"],"staging":["非小细胞肺癌：I期（T1-2N0M0）、II期（T1-2N1或T3N0）、III期（T3-4或N2-3）、IV期（任何T任何N M1）","小细胞肺癌：局限期（病变限于一侧胸腔，可纳入一个放疗野）、广泛期（超出局限期）","按病理类型：腺癌（最常见，约40%）、鳞癌（约30%）、大细胞癌、小细胞癌（约15%）","按驱动基因：EGFR突变、ALK融合、ROS1融合、KRAS突变、野生型"],"key_points":["筛查：高危人群（年龄50-74岁，吸烟≥20包年，戒烟<15年）每年低剂量CT","I-II期非小细胞肺癌：手术治疗为主（肺叶切除+淋巴结清扫），IA期高危可辅助化疗","III期非小细胞肺癌：可切除者新辅助化疗/免疫+手术，不可切除者同步放化疗+度伐利尤单抗巩固","IV期非小细胞肺癌：驱动基因阳性靶向治疗，阴性化疗+免疫治疗，姑息放疗","EGFR突变：奥希替尼80mg qd一线（19del/L858R），或一代吉非替尼/厄洛替尼","ALK融合：阿来替尼600mg bid或洛拉替尼100mg qd一线","PD-L1≥50%：帕博利珠单抗单药一线；PD-L1 1-49%或阴性：化疗+免疫","小细胞肺癌局限期：同步放化疗（依托泊苷+顺铂+胸部放疗），预防性脑照射","小细胞肺癌广泛期：化疗+免疫（依托泊苷+卡铂+阿替利珠单抗/度伐利尤单抗）","脑转移：有症状全脑放疗，无症状可靶向治疗（EGFR/ALK阳性）或SRS"],"drug_recommendations":["奥希替尼：80mg qd口服，EGFR 19del/L858R一线，T790M阳性二线","阿来替尼：600mg bid口服，ALK融合一线","洛拉替尼：100mg qd口服，ALK融合一线或耐药后","帕博利珠单抗：200mg q3w或400mg q6w静滴，PD-L1≥50%单药或联合化疗","卡瑞利珠单抗：200mg q3w静滴，联合化疗一线","培美曲塞：500mg/m2静滴，非鳞癌化疗，联合顺铂/卡铂","紫杉醇：175mg/m2或白蛋白紫杉醇100-125mg/m2，鳞癌化疗","依托泊苷：100mg/m2 d1-3静滴，小细胞肺癌化疗","顺铂：75-80mg/m2 d1静滴，联合化疗，注意水化和止吐"],"non_pharmacological":["手术治疗：肺叶切除+系统性淋巴结清扫，早期首选，VATS微创","放射治疗：根治性放疗（I期不耐受手术）、同步放化疗（III期）、姑息放疗（骨转移、脑转移、上腔静脉压迫）","介入治疗：支气管动脉灌注化疗、射频消融、微波消融（不耐受手术的早期）","姑息治疗：止痛（三阶梯）、营养支持、心理支持、胸腔穿刺引流","戒烟：诊断后戒烟可改善预后","康复训练：术后呼吸功能锻炼，提高生活质量"],"complications":["上腔静脉综合征：面颈部水肿、颈静脉怒张，放疗或支架","恶性胸腔积液：反复穿刺或胸腔闭式引流，胸膜固定术","咯血：大咯血危及生命，支气管动脉栓塞，垂体后叶素","脑转移：头痛呕吐偏瘫，甘露醇降颅压，放疗或靶向","骨转移：骨痛、病理性骨折、高钙血症，双膦酸盐（唑来膦酸）或地舒单抗，放疗","副癌综合征：杵状指、肥大性骨关节病、SIADH、库欣综合征（小细胞）"],"monitoring":["治疗期间：每2-3周期复查胸腹部CT、头颅MRI、肿瘤标志物","术后随访：前2年每3个月，3-5年每6个月，5年后每年","靶向治疗：监测皮疹、腹泻、间质性肺炎、肝功能","免疫治疗：监测免疫相关不良反应（肺炎、结肠炎、肝炎、内分泌）","化疗：血常规每周期前，肝肾功能，恶心呕吐评估","症状评估：疼痛、呼吸困难、体重、生活质量评分"],"special_populations":["老年：PS评分差，单药化疗或靶向，避免高强度联合","EGFR罕见突变：G719X、L861Q、S768I对阿法替尼敏感，20ins对Amivantamab敏感","KRAS G12C突变：Sotorasib或Adagrasib","脑转移：EGFR/ALK阳性优先靶向（奥希替尼/洛拉替尼透过血脑屏障好），有症状放疗"]},{"name":"乳腺癌诊疗指南（2024）","category":"肿瘤科","scope":"女性乳腺癌的筛查、诊断、分期、综合治疗和随访。","diagnosis":["临床表现：乳房无痛性肿块（质硬、边界不清、活动差）、乳头溢液（血性）、皮肤凹陷（酒窝征）、橘皮样变、乳头内陷、腋窝淋巴结肿大","影像学：乳腺超声（BI-RADS分类）、钼靶X线（钙化灶）、乳腺MRI（高危人群或术前评估）","病理诊断：空芯针穿刺活检（首选）、手术切除活检，明确病理类型和分级","免疫组化：ER、PR、HER2、Ki-67，指导分型和治疗","分子分型：Luminal A（ER+PR+HER2-Ki67低）、Luminal B（ER+HER2-但Ki67高或PR低，或ER+HER2+）、HER2过表达（ER-PR-HER2+）、三阴性（ER-PR-HER2-）","分期：TNM分期，I-IV期，腋窝淋巴结状态最重要","鉴别：乳腺纤维腺瘤、乳腺增生、乳腺炎、乳腺囊肿、叶状肿瘤"],"staging":["0期：原位癌（导管原位癌DCIS、小叶原位癌LCIS）","I期：肿瘤≤2cm，无淋巴结转移","II期：肿瘤2-5cm或1-3枚腋窝淋巴结转移","III期：肿瘤>5cm或≥4枚淋巴结转移或局部晚期","IV期：远处转移（骨、肺、肝、脑等）","分子分型：Luminal A、Luminal B、HER2过表达、三阴性"],"key_points":["筛查：40岁以上女性每年乳腺超声+钼靶，高危人群提前至35岁，MRI补充","0期（原位癌）：手术（保乳或全切），DCIS保乳后放疗，ER阳性内分泌治疗5年","I-II期：手术（保乳手术+放疗或乳房全切+重建），前哨淋巴结活检，根据分型辅助治疗","Luminal型：内分泌治疗5-10年（他莫昔芬或芳香化酶抑制剂），高危加化疗","HER2阳性：曲妥珠单抗+帕妥珠单抗靶向治疗1年，联合化疗","三阴性：化疗为主（蒽环+紫杉），早期可加卡铂，PD-L1阳性加免疫","III期：新辅助化疗（HER2阳性加靶向，三阴性加免疫），术后辅助治疗","IV期：全身治疗为主，内分泌/靶向/化疗/免疫，局部放疗姑息，骨转移双膦酸盐","腋窝处理：前哨淋巴结阴性不清扫，阳性则腋窝淋巴结清扫","乳房重建：全切后可一期或二期重建（假体或自体）"],"drug_recommendations":["他莫昔芬：20mg qd口服，绝经前内分泌治疗，5-10年","阿那曲唑：1mg qd或来曲唑2.5mg qd，绝经后芳香化酶抑制剂","曲妥珠单抗：6mg/kg q3w（首剂8mg/kg）静滴，HER2阳性，1年","帕妥珠单抗：420mg q3w（首剂840mg）静滴，联合曲妥珠单抗","T-DM1：3.6mg/kg q3w，HER2阳性新辅助后non-pcr辅助或晚期","多柔比星：60mg/m2静滴，蒽环类化疗，注意心脏毒性","紫杉醇：80mg/m2每周或175mg/m2 q3w，紫杉类","卡培他滨：1000mg/m2 bid口服d1-14，三阴性或晚期","帕博利珠单抗：200mg q3w，三阴性PD-L1阳性联合化疗"],"non_pharmacological":["保乳手术：肿瘤切除+腋窝前哨淋巴结活检，术后必须放疗","乳房全切：单纯乳房切除或改良根治术，适合多中心、大肿瘤、患者意愿","腋窝淋巴结清扫：前哨淋巴结阳性时，I-II水平清扫","放射治疗：保乳术后全乳放疗，全切后高危（淋巴结≥4枚、肿瘤>5cm）胸壁放疗","乳房重建：假体植入或自体组织（背阔肌、腹直肌皮瓣）","姑息治疗：止痛、营养、心理支持，提高生活质量"],"complications":["术后并发症：皮下积液、皮瓣坏死、上肢水肿（腋窝清扫后）、感觉异常","化疗不良反应：骨髓抑制、脱发、恶心呕吐、心脏毒性（蒽环）、神经毒性（紫杉）","内分泌治疗：潮热、骨质疏松、子宫内膜癌（他莫昔芬）、关节痛（AI）","靶向治疗：曲妥珠单抗心脏毒性（LVEF下降），监测心超","上肢淋巴水肿：腋窝清扫后，避免患肢输液抽血，功能锻炼，压力袖套","复发转移：局部复发、区域淋巴结转移、远处转移（骨、肺、肝、脑）"],"monitoring":["治疗期间：每2-3周期复查超声、CT、肿瘤标志物（CA153、CEA）","术后随访：前2年每3个月，3-5年每6个月，5年后每年","内分泌治疗：每年乳腺超声、妇科超声（他莫昔芬）、骨密度（AI）","靶向治疗：每3个月心超（LVEF），曲妥珠单抗心脏毒性","化疗：每周期前血常规、肝肾功能","症状评估：疼痛、体重、生活质量"],"special_populations":["年轻患者（<35岁）：预后较差，化疗指征放宽，生育力保存（卵巢抑制、卵子冷冻）","妊娠期乳腺癌：孕中期可手术和化疗（蒽环+紫杉），避免内分泌和靶向，终止妊娠需个体化","男性乳腺癌：少见，多为Luminal型，治疗原则同女性，他莫昔芬","BRCA突变：奥拉帕利维持治疗，预防性对侧切除和卵巢切除可考虑"]},{"name":"结直肠癌诊疗指南（2024）","category":"肿瘤科","scope":"结肠癌和直肠癌的筛查、诊断、分期、综合治疗和随访。","diagnosis":["临床表现：排便习惯改变（腹泻/便秘/交替）、便血（鲜红或暗红）、腹痛、腹部肿块、肠梗阻、贫血、体重下降","筛查：45岁以上粪便隐血试验（每年）、结肠镜（每10年），高危人群提前","影像学：结肠镜+活检（确诊）、腹部CT（分期）、直肠MRI（直肠癌局部分期）、胸部CT（排查肺转移）、PET-CT（疑难转移）","肿瘤标志物：CEA、CA19-9（辅助诊断和监测复发）","分子检测：RAS（KRAS/NRAS）、BRAF V600E、MMR/MSI（指导靶向和免疫）","分期：TNM分期（第8版），I-IV期，Dukes分期A-D","鉴别：痔疮、炎症性肠病、肠息肉、肠结核、阑尾炎、肠梗阻"],"staging":["I期：肿瘤侵犯黏膜下层或固有肌层，无淋巴结转移","II期：肿瘤穿透浆膜层，无淋巴结转移","III期：区域淋巴结转移","IV期：远处转移（肝、肺、腹膜、骨等）","按部位：结肠癌（盲肠、升结肠、横结肠、降结肠、乙状结肠）、直肠癌（距肛缘<15cm）","按分子：RAS野生型、RAS突变型、BRAF突变、MSI-H/dMMR"],"key_points":["I期：内镜下切除（T1）或手术切除，不需辅助化疗","II期结肠癌：手术为主，高危（T4、淋巴结取样<12枚、脉管侵犯、肠梗阻、穿孔）辅助化疗（卡培他滨单药或XELOX）","III期结肠癌：手术+辅助化疗6个月（XELOX或FOLFOX，低危可3个月）","直肠癌：T3-4或N+新辅助放化疗（长程放化疗或短程放疗），后手术，辅助化疗","IV期：多学科综合治疗，可切除转移灶手术+围手术期化疗，不可切除全身治疗","RAS野生型左半结肠癌：西妥昔单抗+化疗一线，右半或RAS突变贝伐珠单抗+化疗","MSI-H/dMMR：免疫治疗（帕博利珠单抗）一线，疗效显著","BRAF V600E突变：康奈非尼+西妥昔单抗（三药+贝伐也可）","肝转移：可切除者手术切除，不可切除者转化治疗后评估，射频消融","腹膜转移：肿瘤细胞减灭术+腹腔热灌注化疗（HIPEC），系统化疗"],"drug_recommendations":["卡培他滨：1000mg/m2 bid口服d1-14，q3w，单药或联合","奥沙利铂：130mg/m2 d1静滴，联合卡培他滨（XELOX）或5-FU（FOLFOX）","伊立替康：180mg/m2 d1静滴，联合5-FU（FOLFIRI）","西妥昔单抗：首剂400mg/m2后250mg/m2 qw静滴，RAS野生型左半","贝伐珠单抗：5mg/kg q2w或7.5mg/kg q3w静滴，抗血管生成","帕博利珠单抗：200mg q3w静滴，MSI-H/dMMR","康奈非尼：300mg qd口服，联合西妥昔单抗，BRAF V600E","5-FU：400mg/m2推注后1200mg/m2/d×2持续泵入，FOLFOX/FOLFIRI基础","亚叶酸钙：400mg/m2 d1静滴，5-FU增效"],"non_pharmacological":["结肠癌手术：右半结肠切除、横结肠切除、左半结肠切除、乙状结肠切除，D2/D3淋巴结清扫","直肠癌手术：低位前切除（LAR，保肛）、腹会阴联合切除（Miles，距肛<5cm）、Hartmann手术","新辅助放化疗：直肠癌T3-4或N+，长程放化疗（50Gy/25次+卡培他滨）后6-8周手术","肝转移切除：可切除肝转移灶手术，围手术期化疗","射频消融：不可切除小转移灶（<3cm）","支架置入：结肠癌致肠梗阻，解除梗阻作为桥梁或姑息","造口护理：直肠癌Miles术后永久性结肠造口，护理指导"],"complications":["术后并发症：吻合口瘘（直肠癌多见）、出血、感染、肠粘连梗阻","化疗不良反应：奥沙利铂神经毒性（冷刺激加重）、伊立替康迟发性腹泻、手足综合征（卡培他滨）","靶向治疗：西妥昔单抗皮疹、低镁血症；贝伐珠单抗高血压、蛋白尿、出血、肠穿孔","免疫治疗：免疫相关不良反应（结肠炎、肝炎、皮炎、内分泌）","造口并发症：造口狭窄、脱垂、旁疝、皮肤刺激","复发转移：局部复发、肝转移、肺转移、腹膜转移"],"monitoring":["治疗期间：每2-3周期复查CT、CEA/CA19-9","术后随访：前2年每3个月（CEA、体检、超声），3-5年每6个月（加CT、肠镜），5年后每年","肠镜：术后1年复查，之后每3-5年","化疗：每周期前血常规、肝肾功能","靶向治疗：血压（贝伐）、皮疹（西妥昔）、电解质","症状评估：排便情况、疼痛、体重"],"special_populations":["老年：PS评分差，单药化疗（卡培他滨），避免高强度联合","遗传性结直肠癌：Lynch综合征（MSI-H），免疫治疗，家族筛查；FAP（APC突变），预防性结肠切除","年轻患者（<50岁）：发病率上升，症状不典型，预后较差","妊娠相关：罕见，治疗需平衡母胎，孕中期可手术化疗"]},{"name":"肿瘤化疗止吐临床实践指南（2024）","category":"肿瘤科","scope":"肿瘤化疗所致恶心呕吐（CINV）的预防和治疗，按致吐风险分级处理。","diagnosis":["分类：急性呕吐（化疗后24h内）、延迟性呕吐（化疗后24h-7d）、预期性呕吐（化疗前）、爆发性呕吐（预防后仍发生）、难治性呕吐","致吐风险分级：高度（>90%）、中度（30-90%）、低度（10-30%）、轻微（<10%）","高致吐药：顺铂、AC方案（阿霉素+环磷酰胺）、氮芥、卡莫司汀>250mg/m2","中致吐药：卡铂、奥沙利铂、伊立替康、多柔比星、表柔比星、环磷酰胺<1500mg/m2","低致吐药：紫杉醇、多西他赛、吉西他滨、培美曲塞、依托泊苷、甲氨蝶呤","轻微致吐：长春新碱、博来霉素、氟尿嘧啶、贝伐珠单抗","危险因素：女性、年龄<50岁、晕动病史、焦虑、既往CINV、酒精摄入少"],"staging":["按时间：急性（0-24h）、延迟性（24h-120h）、预期性（化疗前）","按严重程度：轻度（1-2次/天）、中度（3-5次/天）、重度（≥6次/天）","按致吐风险：高、中、低、轻微四级"],"key_points":["预防为主：化疗前根据致吐风险预防性止吐，而非治疗已发生的呕吐","高致吐：三药联合——5-HT3受体拮抗剂+地塞米松+NK1受体拮抗剂（阿瑞匹坦），化疗前30min","中致吐：5-HT3受体拮抗剂+地塞米松，化疗前","低致吐：地塞米松或5-HT3受体拮抗剂单药，化疗前","轻微致吐：不需常规预防，必要时甲氧氯普胺或丙氯拉嗪","延迟性呕吐：地塞米松（高致吐d2-4）+NK1拮抗剂（d2-3），中致吐地塞米松d2-3","爆发性呕吐：甲氧氯普胺、氟哌啶醇、奥氮平、丙氯拉嗪，按需给药，不同机制联合","预期性呕吐：苯二氮卓类（阿普唑仑、劳拉西泮），行为疗法（放松训练、催眠）","多日化疗：每天化疗前5-HT3+地塞米松，最后一天后延迟性呕吐预防","口服化疗：根据致吐风险预防性止吐，高致吐口服药同样三药联合"],"drug_recommendations":["帕洛诺司琼：0.25mg静推化疗前30min，5-HT3拮抗剂，半衰期长，急性+延迟性","昂丹司琼：8-16mg静推或口服，5-HT3拮抗剂，急性呕吐","格拉司琼：3mg静推或2mg口服，5-HT3拮抗剂","阿瑞匹坦：125mg d1口服（化疗前1h），80mg d2-3 qd，NK1受体拮抗剂","福沙匹坦：150mg静推d1，阿瑞匹坦前体药物","地塞米松：高致吐12mg d1，8mg d2-4；中致吐8mg d1，4-8mg d2-3","奥氮平：5-10mg口服d1-4，高致吐联合或爆发性呕吐","甲氧氯普胺：10-20mg静推/口服q4-6h，爆发性呕吐，注意锥体外系反应","劳拉西泮：0.5-2mg口服/静推q4-6h，预期性呕吐和焦虑"],"non_pharmacological":["饮食调整：化疗前后2小时避免进食，少量多餐，清淡易消化，避免油腻辛辣","补液：充分水化，尤其顺铂化疗，预防肾损伤和脱水","行为疗法：放松训练、音乐疗法、引导想象、催眠，预期性呕吐有效","针灸/穴位按压：内关穴，辅助止吐","姜制剂：辅助减轻恶心，证据有限","心理支持：焦虑加重呕吐，心理咨询和支持"],"complications":["脱水电解质紊乱：严重呕吐致低钾低钠低氯，补液纠正","食管贲门黏膜撕裂（Mallory-Weiss）：剧烈呕吐致上消化道出血","营养不良：长期呕吐致摄入不足，营养支持","化疗药物外渗：呕吐时躁动致针头脱出","止吐药不良反应：便秘（5-HT3）、呃逆（地塞米松）、锥体外系反应（甲氧氯普胺）、嗜睡（奥氮平）","治疗依从性下降：严重CINV致患者拒绝化疗"],"monitoring":["呕吐日记：记录呕吐次数、时间、诱因、药物效果","电解质：呕吐严重者监测钾钠氯镁","肾功能：脱水和肾毒性化疗药时监测","体重：每周监测，评估营养状况","生活质量：恶心呕吐影响评估","止吐药不良反应：便秘、嗜睡、锥体外系反应"],"special_populations":["老年：便秘风险高，5-HT3拮抗剂注意，避免甲氧氯普胺（锥体外系）","儿童：按体重计算剂量，昂丹司琼0.15mg/kg","孕妇化疗：罕见，止吐药需评估胎儿安全，甲氧氯普胺、昂丹司琼相对安全","脑转移：颅内压增高致呕吐，需降颅压（甘露醇）+止吐","肠梗阻：肿瘤致机械性肠梗阻呕吐，胃肠减压，生长抑素"]},{"name":"社区获得性肺炎诊治指南（2024）","category":"感染科","scope":"成人社区获得性肺炎（CAP）的诊断、严重程度评估、抗感染治疗和预防。","diagnosis":["临床表现：新近出现的咳嗽、咳痰或原有呼吸道症状加重，伴或不伴胸痛、发热（≥38℃）、呼吸困难","体征：肺实变体征（叩诊浊音、语颤增强、支气管呼吸音）或湿啰音","影像学：胸部X线或CT显示新出现的斑片状浸润影、叶段实变影、磨玻璃影或间质性改变","实验室：血常规白细胞>10×10^9/L或<4×10^9/L，伴或不伴核左移；CRP、PCT升高","病原学：痰培养、血培养、尿抗原（肺炎链球菌、军团菌）、呼吸道病毒核酸、非典型病原体抗体","常见病原体：肺炎链球菌（最常见）、支原体、衣原体、军团菌、流感嗜血杆菌、呼吸道病毒","鉴别：肺结核、肺癌、急性支气管炎、肺栓塞、肺水肿、非感染性间质性肺病"],"staging":["CURB-65评分：意识障碍、尿素氮>7mmol/L、呼吸≥30次/分、血压<90/60、年龄≥65岁，每项1分","0-1分：门诊治疗","2分：住院治疗","3-5分：重症监护，死亡率高","PSI评分：更详细，I-II级门诊，III级住院，IV-V级ICU","重症肺炎标准：需要有创机械通气或感染性休克需血管活性药"],"key_points":["尽早抗感染：门诊患者4小时内，住院患者8小时内，重症立即","门诊无基础病：阿莫西林1g tid或多西环素100mg bid或大环内酯类（阿奇霉素）","门诊有基础病/老年：阿莫西林克拉维酸或头孢菌素+大环内酯类，或呼吸喹诺酮（左氧氟沙星/莫西沙星）","住院非ICU：β内酰胺类（头孢曲松/头孢噻肟）+大环内酯类，或呼吸喹诺酮单药","ICU：β内酰胺类+大环内酯类，或β内酰胺类+呼吸喹诺酮","怀疑MRSA：加万古霉素或利奈唑胺","怀疑铜绿假单胞菌：抗假单胞菌β内酰胺（哌拉西林他唑巴坦、头孢吡肟、亚胺培南）+环丙沙星/左氧氟沙星","流感季节：加奥司他韦75mg bid×5天（流感病毒阳性或高度怀疑）","疗程：一般5-7天，非典型病原体10-14天，金黄色葡萄球菌/铜绿/厌氧菌14-21天","支持治疗：补液、吸氧、退热、止咳祛痰、营养支持"],"drug_recommendations":["阿莫西林：1g tid口服，青霉素类，无基础病门诊","阿莫西林克拉维酸：625mg tid或1g bid口服，有基础病","头孢曲松：1-2g qd静滴，住院非ICU","阿奇霉素：500mg d1后250mg d2-5口服/静滴，非典型病原体","左氧氟沙星：500mg qd口服/静滴，或750mg qd，呼吸喹诺酮","莫西沙星：400mg qd口服/静滴，呼吸喹诺酮","哌拉西林他唑巴坦：4.5g q6h静滴，铜绿假单胞菌","万古霉素：15mg/kg q12h静滴，MRSA","奥司他韦：75mg bid口服×5天，流感"],"non_pharmacological":["氧疗：SpO2<90%吸氧，目标≥90%","雾化吸入：生理盐水+支气管扩张剂，痰多黏稠","体位引流：卧床患者定时翻身拍背，促进排痰","补液：脱水患者静脉补液，维持水电解质平衡","营养支持：高蛋白高热量饮食，不能进食者肠内营养","预防：肺炎链球菌疫苗（65岁以上或高危人群）、流感疫苗每年接种、戒烟"],"complications":["胸腔积液/脓胸：抗炎治疗后不吸收，胸腔穿刺引流，脓胸需闭式引流","肺脓肿：坏死性肺炎，抗生素疗程延长，必要时引流或手术","呼吸衰竭：重症肺炎，无创或有创机械通气","感染性休克：液体复苏+血管活性药，ICU治疗","急性肾损伤：脱水+肾毒性抗生素，补液，调整药物","机化性肺炎：抗感染后残留，激素治疗"],"monitoring":["生命体征：体温、呼吸、心率、血压、SpO2","影像学：治疗后72小时评估，症状加重或不吸收复查CT","实验室：血常规、CRP、PCT、肝肾功能、电解质","病原学：治疗无效时重复痰培养、血培养","氧合：血气分析（重症或呼吸困难）","尿量：评估灌注和脱水程度"],"special_populations":["老年：症状不典型（可无发热），合并症多，死亡率高，尽早住院，广谱抗生素","COPD患者：流感嗜血杆菌、卡他莫拉菌多见，注意铜绿假单胞菌（反复住院/抗生素）","吸入性肺炎：厌氧菌+口腔菌群，阿莫西林克拉维酸或克林霉素","免疫抑制：机会性感染（肺孢子菌、真菌、CMV），广谱覆盖，尽早病原学检查","孕妇：避免喹诺酮和四环素，青霉素/头孢/大环内酯相对安全"]},{"name":"泌尿系感染诊治指南（2024）","category":"感染科","scope":"成人泌尿系感染（膀胱炎、肾盂肾炎、复杂性尿感、反复发作尿感）的诊断和治疗。","diagnosis":["临床表现：膀胱炎（尿频尿急尿痛、耻骨上不适、血尿，一般无发热）；肾盂肾炎（发热、腰痛、寒战、恶心呕吐，伴膀胱刺激征）","尿常规：白细胞酯酶阳性、亚硝酸盐阳性、白细胞>5/HP，可有红细胞、蛋白尿","尿培养：清洁中段尿菌落计数≥10^5CFU/ml（女性有症状≥10^3也可诊断），男性≥10^4","血常规：肾盂肾炎白细胞升高、中性粒比例升高、CRP/PCT升高","影像学：反复发作、复杂性尿感、怀疑梗阻/畸形时行泌尿系超声、CT或静脉肾盂造影","常见病原体：大肠埃希菌（最常见，约70-95%）、克雷伯菌、变形杆菌、肠球菌、葡萄球菌、念珠菌","鉴别：泌尿系结石、前列腺炎、阴道炎、间质性膀胱炎、膀胱过度活动症"],"staging":["按部位：下尿路感染（膀胱炎、尿道炎）、上尿路感染（肾盂肾炎）","按复杂性：单纯性尿感（健康女性，无尿路异常）、复杂性尿感（男性、孕妇、尿路梗阻/结石/留置尿管、糖尿病、免疫抑制、肾功能不全）","按发作：初发、反复发作（6个月内≥2次或1年内≥3次）","按严重程度：轻症门诊、重症住院（脓毒症、血流动力学不稳定）"],"key_points":["单纯性膀胱炎：短程疗法——呋喃妥因100mg bid×5天，或磷霉素氨丁三醇3g单剂，或复方磺胺甲恶唑bid×3天（耐药率低地区）","单纯性肾盂肾炎：轻症口服氟喹诺酮（左氧氟沙星750mg qd×5-7天）或头孢菌素；重症静脉头孢曲松或氟喹诺酮，热退后改口服，总疗程10-14天","复杂性尿感：根据尿培养和药敏选药，经验性用广谱抗生素（哌拉西林他唑巴坦、头孢吡肟、碳青霉烯），疗程7-14天","尿脓毒症：液体复苏+广谱抗生素（碳青霉烯或哌拉西林他唑巴坦+万古霉素），控制感染源（解除梗阻）","男性尿感：按复杂性处理，疗程7-14天，排查前列腺炎和尿路异常","孕妇尿感：无症状菌尿也需治疗（筛查），用青霉素/头孢/磷霉素，避免喹诺酮和四环素，疗程7天","留置尿管相关尿感：有症状才治疗，更换或拔除尿管，根据药敏选药，无症状菌尿不治疗（除非孕妇或尿路操作前）","反复发作尿感：急性发作按常规治疗，预防用低剂量抗生素持续6个月（呋喃妥因50mg qn或甲氧苄啶100mg qn）","念珠菌尿：无症状不需治疗（除非孕妇、尿路操作前、中性粒细胞缺乏），有症状用氟康唑","支持治疗：多饮水、勤排尿，注意会阴部清洁"],"drug_recommendations":["呋喃妥因：100mg bid口服×5天，单纯性膀胱炎，肾功能eGFR≥30","磷霉素氨丁三醇：3g单剂口服，单纯性膀胱炎","左氧氟沙星：750mg qd口服/静滴×5-7天，肾盂肾炎","环丙沙星：500mg bid口服×7天，肾盂肾炎","头孢曲松：1-2g qd静滴，肾盂肾炎或复杂性","头孢克肟：400mg bid口服，序贯治疗","哌拉西林他唑巴坦：4.5g q6h静滴，复杂性或脓毒症","亚胺培南：0.5g q6h静滴，重症或耐药菌","氟康唑：200-400mg qd口服/静滴，念珠菌尿感"],"non_pharmacological":["多饮水：每日2000ml以上，增加尿量冲洗尿道","勤排尿：每2-3小时排尿一次，避免憋尿","会阴部清洁：便后从前向后擦拭，性生活后排尿","解除梗阻：结石、前列腺增生、肿瘤等导致的梗阻需处理","更换尿管：留置尿管相关感染，尽量拔除或更换","预防：绝经后女性阴道用雌激素，反复发作预防性抗生素"],"complications":["急性肾损伤：肾盂肾炎或梗阻致肾实质损害，解除梗阻+抗感染","肾乳头坏死：糖尿病或梗阻患者，血尿、腰痛，影像学检查","肾周脓肿：发热持续，腰痛加重，CT诊断，穿刺引流","脓毒症/感染性休克：重症尿感，液体复苏+广谱抗生素+ICU","慢性肾盂肾炎：反复发作致肾瘢痕、高血压、肾功能不全","感染性结石：变形杆菌等产脲酶细菌致磷酸镁铵结石"],"monitoring":["尿常规：治疗后复查，白细胞转阴","尿培养：复杂性尿感治疗后复查培养，确认转阴","血常规、CRP、PCT：肾盂肾炎评估疗效","肾功能：肌酐、尿素氮，评估肾损害","影像学：反复发作或复杂性尿感排查结构异常","体温：肾盂肾炎监测退热情况"],"special_populations":["孕妇：无症状菌尿需筛查治疗（2-4%可发展为肾盂肾炎），用安全抗生素，疗程7天","老年：症状不典型，可仅表现为意识模糊或乏力，复杂性多见，广谱抗生素","糖尿病：易发生肾乳头坏死、气肿性肾盂肾炎，影像学检查，严格控糖","男性：均按复杂性处理，排查前列腺炎和前列腺增生","免疫抑制：念珠菌和耐药菌多见，积极病原学检查，广谱覆盖"]},{"name":"感染性心内膜炎诊治指南（2024）","category":"感染科","scope":"成人感染性心内膜炎（IE）的诊断、抗感染治疗、手术指征和预防。","diagnosis":["临床表现：发热（最常见，可呈弛张热）、心脏杂音（新出现或改变）、周围体征（瘀点、Osler结节、Janeway损害、Roth斑、杵状指）、栓塞表现（脑、脾、肾、肺栓塞）","血培养：诊断关键，寒战或高热时采血，3套（每套需氧+厌氧），间隔≥30分钟，抗生素使用前","超声心动图：经胸超声（TTE）初筛，经食管超声（TEE）更敏感（诊断人工瓣膜或并发症），可见赘生物、瓣周脓肿、瓣膜穿孔","实验室：贫血、白细胞升高、血沉增快、CRP升高、类风湿因子阳性、镜下血尿","Duke诊断标准：主要标准（血培养阳性、心内膜受累证据）+次要标准（易感因素、发热、血管现象、免疫现象、微生物学证据）","常见病原体：链球菌（草绿色链球菌最常见）、葡萄球菌（金黄色葡萄球菌，人工瓣膜和静脉药瘾者）、肠球菌、HACEK菌、真菌","鉴别：风湿热、心房黏液瘤、非细菌性血栓性心内膜炎、败血症"],"staging":["按瓣膜类型：自体瓣膜心内膜炎（NVE）、人工瓣膜心内膜炎（PVE）、静脉药瘾者心内膜炎","按部位：左心心内膜炎（二尖瓣、主动脉瓣）、右心心内膜炎（三尖瓣，静脉药瘾者）","按病程：急性（金黄色葡萄球菌，进展快）、亚急性（草绿色链球菌，数周数月）","按并发症：单纯性（无并发症）、复杂性（心力衰竭、栓塞、脓肿、耐药菌）"],"key_points":["尽早血培养：疑似IE立即采血3套，不需等待发热","经验性抗感染：自体瓣膜急性——万古霉素+头孢曲松；亚急性——氨苄西林+庆大霉素；人工瓣膜——万古霉素+庆大霉素+利福平","链球菌（青霉素敏感MIC≤0.125）：青霉素G 1200-1800万U/d持续泵入或头孢曲松2g qd，疗程4周","链球菌（青霉素耐药）：头孢曲松+庆大霉素，或万古霉素，疗程4-6周","肠球菌：氨苄西林2g q4h+庆大霉素1mg/kg q8h，或万古霉素+庆大霉素，疗程4-6周","金黄色葡萄球菌（甲氧西林敏感）：萘夫西林2g q4h或苯唑西林，疗程4-6周；MRSA：万古霉素15mg/kg q12h","人工瓣膜心内膜炎：疗程6周，葡萄球菌加用利福平300mg q8h×6周+庆大霉素2周","手术指征：心力衰竭（最常见手术原因）、感染无法控制（耐药菌、真菌、脓肿）、栓塞风险大（赘生物>10mm、活动度大、既往栓塞）、人工瓣膜功能障碍","抗凝：不常规抗凝（增加出血），机械瓣患者维持原抗凝","预防：高危人群（人工瓣膜、既往IE、先天性心脏病）牙科操作前预防性抗生素（阿莫西林2g术前30-60min）"],"drug_recommendations":["青霉素G：1200-1800万U/d分4-6次静滴或持续泵入，链球菌敏感","头孢曲松：2g qd静滴，链球菌或经验性","氨苄西林：2g q4h静滴，肠球菌","万古霉素：15mg/kg q12h静滴，MRSA或青霉素过敏","萘夫西林：2g q4h静滴，甲氧西林敏感金葡菌","庆大霉素：1mg/kg q8h静滴，联合用药（监测血药浓度和肾功能）","利福平：300mg q8h口服，人工瓣膜金葡菌","氟康唑/两性霉素B：真菌性心内膜炎，疗程长，需手术","阿莫西林：2g口服术前30-60min，IE预防"],"non_pharmacological":["经食管超声（TEE）：诊断和随访，评估赘生物、脓肿、瓣膜功能","心脏手术：瓣膜修复或置换，脓肿清除，赘生物切除","栓塞处理：脑栓塞抗凝需谨慎（出血转化风险），脾栓塞保守或手术","营养支持：长期发热消耗，高蛋白高热量","卧床休息：急性期减少活动，避免赘生物脱落栓塞","口腔卫生：治疗牙源性感染，预防复发"],"complications":["心力衰竭：瓣膜穿孔或腱索断裂致急性返流，最常见死亡原因，紧急手术","栓塞：脑栓塞（最常见，可致卒中）、脾栓塞、肾栓塞、肺栓塞（右心IE），赘生物>10mm风险高","瓣周脓肿：感染蔓延至瓣周，持续发热，需手术清除","传导阻滞：脓肿累及传导系统，房室传导阻滞，需临时起搏","肾功能不全：免疫复合物肾炎或抗生素肾毒性","败血症/感染性休克：重症，液体复苏+广谱抗生素"],"monitoring":["血培养：治疗后持续阳性提示治疗失败，复查至转阴","超声心动图：治疗中复查（1周、4周、结束时），评估赘生物和瓣膜功能","血常规、CRP、血沉：评估炎症控制","肝肾功能、电解质：抗生素毒性监测","庆大霉素血药浓度：峰浓度3-5μg/ml，谷浓度<1μg/ml","神经系统体征：警惕脑栓塞"],"special_populations":["人工瓣膜患者：PVE死亡率高，疗程6周，常需手术，葡萄球菌加利福平","静脉药瘾者：右心IE多见（三尖瓣），金葡菌，治疗2周（单纯右心），需戒毒","老年：症状不典型，合并症多，手术风险高，死亡率高","先天性心脏病：易感，术前术后预防，注意肺动脉高压","起搏器/ICD相关感染：装置感染，需拔除装置+抗生素"]}];
